  AvgCommunicate_100438_Content_1 = {
    Text = "Custode, voglio aprire uno studio d'arte al Mythag, con ammissione gratuita!"
  },
  AvgCommunicate_100438_Content_10 = {
    Text = "Suppongo sia accettabile, ma..."
