  AvgCommunicate_100438_Content_13 = {Text = "!?"},
  AvgCommunicate_100438_Content_14 = {
    Text = "Per favoreee? Ti pregoooo?"
  },
  AvgCommunicate_100438_Content_15 = {
    Text = "Un modello gratuito, dedicato ad aiutarti a realizzare l'arte più perfetta! Dove troverai mai un modello così collaborativo?"
  },
  AvgCommunicate_100438_Content_16 = {
    Text = "...Ha senso."
  },
  AvgCommunicate_100438_Content_17 = {
    Text = "Ci vediamo allo studio domani!"
  },
  AvgCommunicate_100438_Content_2 = {
    Text = "Un corso magistrale di pittura tenuto personalmente da me, e tutti i miei migliori materiali artistici saranno a tua disposizione. Non sei entusiasta?"
  },
  AvgCommunicate_100438_Content_3 = {
    Text = "Esiste davvero un'offerta così vantaggiosa?"
  },
  AvgCommunicate_100438_Content_4 = {
    Text = "Non vedo l'ora!"
  },
  AvgCommunicate_100438_Content_5 = {
    Text = "In quanto grande pittrice e educatrice esperta, l'altruismo è sempre stato il mio tratto più prominente. Tuttavia, devi capire che la creazione di qualsiasi opera d'arte magnifica richiede una certa scintilla d'ispirazione..."
  },
  AvgCommunicate_100438_Content_6 = {
    Text = "Come piccola ricompensa per il mio insegnamento, potrei chiederti di posare come modello per le mie opere?"
  },
  AvgCommunicate_100438_Content_7 = {
    Text = "Lo sapevo..."
  },
  AvgCommunicate_100438_Content_8 = {
    Text = "Per favoreee? Ti pregoooo?"
  },
  AvgCommunicate_100438_Content_9 = {
    Text = "Corso magistrale gratuito, studio gratuito, materiali artistici gratuiti... tutto è gratis!"
  },
  AvgCommunicate_100438_Option_3 = {
    Text = "Esiste davvero un'offerta così vantaggiosa?"
  },
  AvgCommunicate_100438_Option_4 = {
