  AvgCommunicate_100440_Option_9 = {Text = "..."},
  AvgCommunicate_121371_Content_1 = {
    Text = "L'ho vista. Così spensierata, è sconcertante."
  },
  AvgCommunicate_121371_Content_2 = {
    Text = "Anche il suo affetto per le cose banali è incredibilmente ingenuo e assurdo."
  },
  AvgCommunicate_121371_Content_3 = {
    Text = "...Murphy mi ha detto che non è riuscita a ottenere nemmeno una delle nuove bambole e dei vestiti per cui voleva partecipare alla lotteria di questo trimestre."
  },
  AvgCommunicate_121371_Content_4 = {
    Text = "Tutti i numeri dell'estrazione sono stati acquistati in anticipo. Chi sarà mai stato? È un tale mistero."
  },
  AvgCommunicate_121371_Content_5 = {
    Text = "In quanto colei che ha sopportato per un tempo significativamente più lungo, ricevere un piccolo risarcimento è solo giusto."
  },
  AvgCommunicate_121371_Content_6 = {
    Text = "...Un risarcimento che ti permette di spendere a piacimento, forse perché hai ricevuto un'enorme eredità dal culto?"
  },
  AvgCommunicate_121371_Content_7 = {Text = "Heh."},
  AvgCommunicate_121371_Content_8 = {
    Text = "Concedo che le sue scelte passate e la sua fortuna possano essere state marginalmente migliori delle mie."
  },
  AvgCommunicate_121371_Content_9 = {
    Text = "Ma dovrebbe rendersi conto che sfidare il destino non garantisce il successo ogni volta."
  },
  AvgCommunicate_121372_Content_1 = {
    Text = "Oltraggioso! Irrispettoso! Imperdonabile!"
