  AvgCommunicate_121372_Content_10 = {Text = "Tu..."},
  AvgCommunicate_121372_Content_11 = {
    Text = "Quindi cosa farai?"
  },
  AvgCommunicate_121372_Content_12 = {
    Text = "Gli studenti che si fermano ad accarezzare i gatti stanno per causare un ingorgo fenomenale nell'edificio scolastico. Un talento davvero sorprendente."
  },
  AvgCommunicate_121372_Content_13 = {
    Text = "Sto venendo a salvarti adesso."
