  AvgCommunicate_121372_Content_2 = {
    Text = "Che succede?"
  },
  AvgCommunicate_121372_Content_3 = {
    Text = "È del tutto irragionevole! Perché Mythag dovrebbe permettere a creature simili di entrare nei dormitori!"
  },
  AvgCommunicate_121372_Content_4 = {
    Text = "Aspetta, sento qualcuno urlare nell'edificio del dormitorio. Eri tu?"
  },
  AvgCommunicate_121372_Content_5 = {
    Text = "Perché ci sono così tanti gatti radunati alla porta!?"
  },
  AvgCommunicate_121372_Content_6 = {
    Text = "Queste piccole creature malvagie e traditrici mi seguono da quando sono apparsa! Dev'essere una cospirazione—vogliono assassinare la Madre Divina!"
  },
  AvgCommunicate_121372_Content_7 = {
    Text = "...Non credo che una creatura malvagia intenzionata a fare del male a qualcuno starebbe sdraiata sulla schiena, mostrando la pancia."
  },
  AvgCommunicate_121372_Content_8 = {
    Text = "I gatti sembrano avere un'affinità insolitamente forte per te."
  },
  AvgCommunicate_121372_Content_9 = {
    Text = "Sciocchezze! In quanto Principessa, ti ordino di portarli via immediatamente, o io... io..."
  },
  AvgCommunicate_121372_Option_10 = {Text = "Tu...?"},
  AvgCommunicate_121372_Option_11 = {Text = "Quindi?"},
  AvgCommunicate_121375_Content_1 = {
    Text = "So cosa stai per dire. Si sono offerti volontari."
  },
  AvgCommunicate_121375_Content_10 = {
