  },
  AvgCommunicate_121375_Content_2 = {
    Text = "Non so come tu sia riuscita a metterti in contatto con loro, ma non puoi assolutamente permettere che quei Navigatori si presentino al Mythag per fare le tue commissioni, tenerti il posto in fila o fare i tuoi compiti!"
  },
  AvgCommunicate_121375_Content_3 = {
    Text = "Sai quanti insegnanti e studenti si lamentano che i loro quaderni diventano appiccicosi?"
  },
  AvgCommunicate_121375_Content_4 = {
