  },
  AvgCommunicate_123720_Content_5 = {
    Text = "Hai incluso i piani di reinserimento per quei cultisti?"
  },
  AvgCommunicate_123720_Content_6 = {
    Text = "Tutto pronto. Il Santuario della Vita ha preso in carico la situazione. Gli \"Innocenti\" saranno affidati ad agenzie che li aiuteranno a reintegrarsi gradualmente nella società."
  },
  AvgCommunicate_123720_Content_7 = {
    Text = "Quanto ai \"Colpevoli\", svolgeranno servizi comunitari presso la chiesa, cercando di lavare i propri peccati attraverso le buone azioni."
  },
  AvgCommunicate_123720_Content_8 = {
    Text = "In realtà questo finale non mi dispiace. Dopotutto, sono solo povere anime rese folli da questo mondo terrificante."
  },
  AvgCommunicate_123720_Content_9 = {
