  },
  AvgCommunicate_123721_Content_12 = {
    Text = "Va bene. Lo considererò un \"benefit aziendale\"."
  },
  AvgCommunicate_123721_Content_13 = {
    Text = "Ma visto che è durante l'orario di lavoro, non puoi segnalarmi per assenteismo... e non puoi assolutamente farmi fare straordinari!"
  },
  AvgCommunicate_123721_Content_14 = {
    Text = "Promesso. Vai pure a fare il check-up!"
  },
  AvgCommunicate_123721_Content_2 = {
    Text = "Rispondi appena vedi questo messaggio, o tratterò questo \"dottore\" come un intruso ostile."
  },
  AvgCommunicate_123721_Content_3 = {
    Text = "Aspetta! Fermati! Quello è davvero il dottore che ho trovato per il tuo controllo medico!"
  },
  AvgCommunicate_123721_Content_4 = {
    Text = "Eh? Sto benissimo. Non ho bisogno di vedere nessun dottore."
