    Text = "Ora sono più forte. Corro più veloce, salto più lontano e faccio a pezzi i Corpi dissolti in metà del tempo."
  },
  AvgCommunicate_123722_Content_12 = {
    Text = "In pratica ho vinto alla lotteria. Onestamente, se la trasformazione non facesse così male, la rifarei tutta da capo!"
  },
  AvgCommunicate_123722_Content_13 = {Text = "..."},
  AvgCommunicate_123722_Content_14 = {
    Text = "Ma la cosa più importante è che questo mondo è semplicemente troppo divertente."
  },
  AvgCommunicate_123722_Content_15 = {
    Text = "È pieno di caos e sorprese. Non sai mai che tipo di pericolo ti aspetta dietro l'angolo."
  },
  AvgCommunicate_123722_Content_16 = {Text = "..."},
  AvgCommunicate_123722_Content_17 = {
    Text = "Ah, non vedo già l'ora della prossima indagine."
  },
  AvgCommunicate_123722_Content_18 = {
    Text = "Allora, %player%, quand'è la prossima missione?"
  },
  AvgCommunicate_123722_Content_19 = {Text = "%player%?"},
  AvgCommunicate_123722_Content_2 = {
    Text = "A quanto pare sto benissimo. Potrei affrontare venti Corpi dissolti in una volta senza battere ciglio!"
  },
  AvgCommunicate_123722_Content_20 = {Text = "%player%??"},
  AvgCommunicate_123722_Content_3 = {
    Text = "Sono contento di sentirlo."
  },
  AvgCommunicate_123722_Content_4 = {
    Text = "Sollievo? %player%, per cosa eri davvero preoccupato?"
  },
  AvgCommunicate_123722_Content_5 = {
    Text = "Che non mi sarei adattata alla vita in un altro mondo?"
  },
  AvgCommunicate_123722_Content_6 = {
    Text = "O eri preoccupato che cambiassi da \"umana\" a \"Risvegliatore\"?"
  },
  AvgCommunicate_123722_Content_7 = {
    Text = "Entrambe. Dopotutto, una transizione del genere non è facile per nessuno."
  },
  AvgCommunicate_123722_Content_8 = {
    Text = "...Non capisco proprio come funziona il tuo cervello."
  },
  AvgCommunicate_123722_Content_9 = {
    Text = "Non m'importa niente di tutto ciò. Non importa cosa divento, Mouchette resta sempre Mouchette!"
  },
  AvgCommunicate_123722_Option_13 = {Text = "..."},
  AvgCommunicate_123722_Option_16 = {Text = "..."},
  AvgCommunicate_123722_Option_3 = {
    Text = "Sono contento di sentirlo."
  },
  AvgCommunicate_123722_Option_7 = {
    Text = "Entrambe le cose, onestamente."
  },
  AvgCommunicate_126998_Content_1 = {
    Text = "Ramona... davvero non vuoi ripensarci?"
  },
  AvgCommunicate_126998_Content_10 = {Text = "Sì. \"Io.\""},
  AvgCommunicate_126998_Content_11 = {
    Text = "...Dovrei chiamare Clementine?"
  },
  AvgCommunicate_126998_Content_12 = {
    Text = "Non c'è bisogno di disturbare la terapista."
  },
  AvgCommunicate_126998_Content_13 = {
    Text = "\"Io\"... o meglio, \"noi\". Ogni \"Ramona\" lungo l'intera linea temporale."
  },
  AvgCommunicate_126998_Content_14 = {
    Text = "Con il tuo aiuto, nell'istante preciso in cui ho raggiunto la \"fine\", sono riuscita a sovrascrivere la mia esistenza riportandola all'\"origine\"."
  },
  AvgCommunicate_126998_Content_15 = {
    Text = "All'inizio, le mie aspettative erano le stesse delle tue: il paradosso e la distorsione avrebbero consumato istantaneamente il mio essere, e avrei dovuto fare affidamento su una costante auto-reversione solo per preservare a malapena coscienza e forma."
  },
  AvgCommunicate_126998_Content_16 = {
    Text = "E saresti rimasta intrappolata in un'eterna estenuazione, ogni secondo di veglia speso a sforzarti solo per impedire al tuo stesso concetto di disfarsi..."
  },
  AvgCommunicate_126998_Content_17 = {
    Text = "Ecco perché ho rifiutato le tue prime diciannove proposte."
  },
  AvgCommunicate_126998_Content_18 = {
    Text = "Anche questa volta, ho solo... accettato con riluttanza dopo che hai detto di poter effettuare una \"reversione di stato\"."
  },
  AvgCommunicate_126998_Content_19 = {
    Text = "Vero. Ma solo dopo il successo del piano mi sono resa conto: il paradosso derivava dal conflitto tra mente e corpo. E per un essere che ha già trasceso il fiume del tempo..."
  },
  AvgCommunicate_126998_Content_2 = {
    Text = "Non c'è bisogno di ulteriori discussioni, Custode."
  },
  AvgCommunicate_126998_Content_20 = {
    Text = "Ho già raggiunto l'unità attraverso ogni linea temporale."
  },
  AvgCommunicate_126998_Content_21 = {
    Text = "\"Noi\" condivideremo il peso del paradosso al posto mio. Io agirò come rappresentante di tutte le \"Ramona\". Innumerevoli linee temporali sono confluite e collassate in me."
  },
  AvgCommunicate_126998_Content_22 = {
    Text = "In questo momento, io sono il miracolo della linea temporale: la Singolarità della convergenza infinita."
  },
  AvgCommunicate_126998_Content_23 = {
    Text = "D'ora in poi, ti offrirò il pieno potere dell'entità chiamata \"Ramona\"."
  },
  AvgCommunicate_126998_Content_24 = {
    Text = "Attenderò la tua chiamata... da qualsiasi punto nel tempo."
  },
  AvgCommunicate_126998_Content_3 = {
    Text = "Ho attraversato tutte le linee temporali e non ho trovato altra risposta."
  },
  AvgCommunicate_126998_Content_4 = {
    Text = "Grazie a te, ho finalmente compiuto quell'ultimo passo."
  },
  AvgCommunicate_126998_Content_5 = {
    Text = "Ma è troppo pericoloso! Non capisco... perché devi spingerti così oltre?"
  },
  AvgCommunicate_126998_Content_6 = {
    Text = "...Un paradosso del genere, persino qualcuno come te non potrebbe—"
  },
  AvgCommunicate_126998_Content_7 = {
    Text = "Tranquillo, Custode."
  },
  AvgCommunicate_126998_Content_8 = {
    Text = "In questo momento, \"io\" mi sento... indescrivibilmente meravigliosa."
  },
  AvgCommunicate_126998_Content_9 = {Text = "\"Io\"?"},
  AvgCommunicate_126998_Option_11 = {
    Text = "...Dovrei chiamare Clementine?"
  },
  AvgCommunicate_126998_Option_9 = {Text = "\"Io\"?"},
  AvgCommunicate_126999_Content_1 = {
    Text = "Mio signore... quindi è questa la sensazione che si prova ad afferrare la legge suprema dell'universo..."
  },
  AvgCommunicate_126999_Content_10 = {
    Text = "Piano, Ogier."
  },
  AvgCommunicate_126999_Content_11 = {
    Text = "Quei giorni sono finiti. Ora hai forza più che sufficiente per proteggere tutto ciò che ti è caro."
  },
  AvgCommunicate_126999_Content_12 = {
    Text = "Capito, mio signore."
  },
  AvgCommunicate_126999_Content_13 = {
    Text = "Allora vi prego... fate più affidamento su di me. Sono diventato più forte. Sono pronto anche per missioni più pericolose."
  },
  AvgCommunicate_126999_Content_14 = {
    Text = "Dedicherò ogni briciolo di questo potere a voi. Diventerò la lancia più affilata nella vostra mano, una che può trafiggere qualsiasi cosa!"
  },
  AvgCommunicate_126999_Content_2 = {
    Text = "Io... sento un'ondata di potere molto più grande di qualsiasi altra! Non mi sono mai sentito così forte!"
  },
  AvgCommunicate_126999_Content_3 = {
    Text = "Congratulazioni, Ogier. Questa è la ricompensa per tutto il tuo incessante addestramento."
  },
  AvgCommunicate_126999_Content_4 = {
    Text = "Ricompensa? Ma... non mi sono allenato per una ricompensa."
  },
  AvgCommunicate_126999_Content_5 = {
    Text = "Allora lascia che la metta in un altro modo."
  },
  AvgCommunicate_126999_Content_6 = {
    Text = "Questa è la prova della tua dedizione. Dimostra che la tua forza, Ogier, ha finalmente raggiunto il suo apice."
  },
  AvgCommunicate_126999_Content_7 = {Text = "Apice...?"},
  AvgCommunicate_126999_Content_8 = {
    Text = "Significa che... sono finalmente abbastanza forte da proteggere voi, mio signore, e Mythag?!"
  },
  AvgCommunicate_126999_Content_9 = {
    Text = "Io... non dovrò mai più... restare a guardare impotente... mai più..."
  },
  AvgCommunicate_127000_Content_1 = {
    Text = "Grazie per tutto il tuo aiuto ultimamente, partner."
  },
  AvgCommunicate_127000_Content_10 = {
    Text = "Non il tipo di \"fine\" in cui il talento si scontra con un muro e vacilla, ma la fine della chiarezza assoluta che giunge dopo un affinamento senza sosta."
  },
  AvgCommunicate_127000_Content_11 = {
    Text = "In questo momento, la mia arte ha sfiorato la perfezione."
  },
  AvgCommunicate_127000_Content_12 = {
    Text = "È incredibile! Non mi aspettavo niente di meno da Ramona!"
  },
  AvgCommunicate_127000_Content_13 = {
    Text = "D'ora in poi, come tua assistente, resterò al tuo fianco fino a quando non raggiungeremo la fine di questa strada."
  },
  AvgCommunicate_127000_Content_2 = {
    Text = "Sono contenta di essere stata d'aiuto."
  },
  AvgCommunicate_127000_Content_3 = {
    Text = "Allora... hai ottenuto qualche intuizione? O ti senti diversa?"
  },
  AvgCommunicate_127000_Content_4 = {
    Text = "Certamente. Osservando entità speciali come la \"Conchiglia Intrappolata nel Tempo\", la \"Vita in Sovrapposizione\" e la \"Mente Imperscrutabile\", sono riuscita a portare le mie deduzioni a un livello molto più profondo."
  },
  AvgCommunicate_127000_Content_5 = {
    Text = "Poi, utilizzando l'\"Utopia Ingegnerizzata\", il \"Nullificatore Logico\" e il \"Cosmo Incapsulato\", ho attraversato con successo il Labirinto del Pensiero."
  },
  AvgCommunicate_127000_Content_6 = {
    Text = "Ehm... mi sono un po' persa."
  },
  AvgCommunicate_127000_Content_7 = {
    Text = "Ma in sostanza... sei diventata molto più forte, giusto?"
  },
  AvgCommunicate_127000_Content_8 = {
    Text = "Sì. Dopo questa svolta, il potere che posso esercitare supera di gran lunga i miei limiti precedenti."
  },
  AvgCommunicate_127000_Content_9 = {
    Text = "Sento di aver raggiunto la fine."
  },
  AvgCommunicate_127000_Option_12 = {
    Text = "È incredibile!"
  },
  AvgCommunicate_127001_Content_1 = {
    Text = "[Messaggio Programmato]"
  },
  AvgCommunicate_127001_Content_10 = {
    Text = "Dovremmo aspettare!"
  },
  AvgCommunicate_127001_Content_11 = {
    Text = "Perché proprio oggi?!"
  },
  AvgCommunicate_127001_Content_12 = {
    Text = "È un'imprudenza! Forse dovremmo aspettare che l'Istituto possa offrire più supporto."
  },
  AvgCommunicate_127001_Content_13 = {
    Text = "Era un messaggio programmato che ho impostato alle 2:00 di notte, poco prima dell'inizio dell'esperimento."
  },
  AvgCommunicate_127001_Content_14 = {
    Text = "Spero che tu non stia facendo una faccia ridicola davanti al tuo dispositivo. Se è così, ricomponiti prima di venire in laboratorio."
  },
  AvgCommunicate_127001_Content_15 = {
    Text = "Io? In laboratorio? Adesso?"
  },
  AvgCommunicate_127001_Content_16 = {
    Text = "Sì. In un certo senso... ho intravisto la verità di ciò che stavo inseguendo."
  },
  AvgCommunicate_127001_Content_17 = {
    Text = "Aspetta... non vorrai dire che finirai come quell'altra \"Doll\"..."
  },
  AvgCommunicate_127001_Content_18 = {
    Text = "No. Il fine ultimo non è la \"distruzione\" come lei la concepiva. Al contrario, è l'\"inizio\"."
  },
  AvgCommunicate_127001_Content_19 = {
    Text = "La \"Verità\" non è qualcosa di fisso, tangibile e statico. Una volta varcato quel confine, la ragione e l'intelletto possono guidare l'umanità ad ancorarla, consentendo un progresso perpetuo e incrollabile."
  },
  AvgCommunicate_127001_Content_2 = {
    Text = "Custode, sebbene ciò che sto per fare potrebbe essere etichettato come \"pericoloso\" secondo gli standard convenzionali, confido che tu non sia così sciocco da aspettarti sdolcinatezze sentimentali o vuoti ammonimenti da parte mia."
  },
  AvgCommunicate_127001_Content_20 = {
    Text = "Ecco perché elaborerò un programma di addestramento molto più rigoroso e preciso per te, per assicurarmi che tu devii meno dal cammino, così da poter perseguire meglio la tua domanda."
  },
  AvgCommunicate_127001_Content_21 = {
    Text = "Sembra una buona notizia... allora perché mi sta venendo un sudore freddo?"
  },
  AvgCommunicate_127001_Content_22 = {
    Text = "Professoressa Doll... per favore, si calmi un po'!"
  },
  AvgCommunicate_127001_Content_3 = {
    Text = "Francamente, hai superato il bisogno di certe cose."
  },
  AvgCommunicate_127001_Content_4 = {
    Text = "Sei maturato più velocemente di quanto mi aspettassi. Sei abbastanza resiliente da comprendere questo: ogni individuo ha una verità che deve perseguire nella propria vita — una domanda a cui nessun altro può rispondere al posto suo."
  },
  AvgCommunicate_127001_Content_5 = {
    Text = "La mia ricerca è svelare la vera natura del mondo, vedere se la ragione brilla ancora oltre il vuoto desolato di oscurità e silenzio, scoprire se ogni cosa, alla sua fine ultima, condivide un'origine comune."
  },
  AvgCommunicate_127001_Content_6 = {
    Text = "A tal fine, eseguirò le modifiche finali sul mio corpo e sulla mia mente per varcare il confine che giace oltre ogni estremo. Poiché questo potrebbe essere il nostro ultimo scambio, ho scelto di parlare chiaramente, in un modo che tu possa comprendere:"
  },
  AvgCommunicate_127001_Content_7 = {
    Text = "Grazie per il tuo dono, Custode. Lo userò per cercare le risposte, e attendo con impazienza il giorno in cui l'intelletto umano tornerà da quella riva lontana con una guida completamente nuova. Che la Chiave d'Argento ci guidi."
  },
  AvgCommunicate_127001_Content_8 = {
    Text = "Professoressa Doll!"
  },
  AvgCommunicate_127001_Content_9 = {
    Text = "È troppo rischioso!"
  },
  AvgCommunicate_127001_Option_10 = {
    Text = "Dovremmo aspettare"
  },
  AvgCommunicate_127001_Option_9 = {
    Text = "È troppo rischioso"
  },
  AvgCommunicate_127002_Content_1 = {
    Text = "Custode... perché?"
  },
  AvgCommunicate_127002_Content_10 = {
    Text = "Allora dimmi... come ti sembra questo nuovo potere?"
  },
  AvgCommunicate_127002_Content_11 = {
    Text = "Io... sono davvero felice, Custode."
  },
  AvgCommunicate_127002_Content_12 = {
    Text = "Non per la forza che non avevo mai provato prima, ma per te... e per le tue parole..."
  },
  AvgCommunicate_127002_Content_13 = {
    Text = "Forse d'ora in poi potrò davvero aiutare chi mi sta intorno... aiutare te."
  },
  AvgCommunicate_127002_Content_14 = {
    Text = "Grazie... grazie mille, Custode..."
  },
  AvgCommunicate_127002_Content_15 = {
    Text = "Solo una cosa: non viverlo come un peso, Aigis."
  },
  AvgCommunicate_127002_Content_16 = {
    Text = "Non è un dovere. È semplicemente un dono per te."
  },
  AvgCommunicate_127002_Content_17 = {
    Text = "Goditelo e basta. Ora puoi realizzare qualsiasi cosa desideri."
  },
  AvgCommunicate_127002_Content_18 = {
    Text = "Aigis, sei sempre stata, e sempre sarai, il nostro orgoglio."
  },
  AvgCommunicate_127002_Content_2 = {
    Text = "Perché cosa?"
  },
  AvgCommunicate_127002_Content_20 = {
    Text = "Proteggerò tutti, Custode! Lo prometto!"
  },
  AvgCommunicate_127002_Content_3 = {
    Text = "È un dono così prezioso... perché sprecarlo per me..."
  },
  AvgCommunicate_127002_Content_4 = {
    Text = "Non è uno spreco, Aigis. Te lo meriti."
  },
  AvgCommunicate_127002_Content_5 = {
    Text = "Ma... ma non ho realizzato nulla... non sono riuscita a proteggere nessuno..."
  },
  AvgCommunicate_127002_Content_6 = {
    Text = "Non è vero, Aigis."
  },
  AvgCommunicate_127002_Content_7 = {
    Text = "Abbiamo percorso un cammino molto, molto lungo insieme, un viaggio iniziato ben prima del tuo Risveglio."
  },
  AvgCommunicate_127002_Content_8 = {
    Text = "Lungo la strada, ti sei eretta a scudo per tutti più e più volte, e ci sei riuscita ogni volta."
  },
  AvgCommunicate_127002_Content_9 = {
    Text = "Senza di te, sarei caduto migliaia di volte."
  },
  AvgCommunicate_127003_Content_1 = {
    Text = "Ho fatto un sogno."
  },
  AvgCommunicate_127003_Content_10 = {
    Text = "Tranne, ovviamente, quando siamo nel campo d'addestramento."
  },
  AvgCommunicate_127003_Content_11 = {Text = "???"},
  AvgCommunicate_127003_Content_12 = {
    Text = "Avanti. La mia forma è ora completa. Senti tu stesso la mia vera forza. Dammi il meglio di te e combatti sul serio!"
  },
  AvgCommunicate_127003_Content_13 = {Text = "???!!!"},
  AvgCommunicate_127003_Content_14 = {
    Text = "Ramona, aiuto!!!"
  },
  AvgCommunicate_127003_Content_2 = {Text = "Un sogno?"},
  AvgCommunicate_127003_Content_3 = {
    Text = "Grazie ai materiali che hai portato, finalmente ho dormito bene."
  },
  AvgCommunicate_127003_Content_4 = {
    Text = "Ho nuotato attraverso l'Eone Archeano nella mia forma primordiale. Polvere, luce, materia, dimensioni—tutto ciò che era percepibile scorreva sotto le mie pinne."
  },
  AvgCommunicate_127003_Content_5 = {
    Text = "Non per conquistare. Non per consumare. Solo puro potere e distruzione assoluta, senza freni."
  },
  AvgCommunicate_127003_Content_6 = {
    Text = "Esaltante. Liberatorio. Assolutamente inebriante!"
  },
  AvgCommunicate_127003_Content_7 = {Text = "Ehm..."},
  AvgCommunicate_127003_Content_8 = {
    Text = "Oh, rilassati. So cosa ti preoccupa."
  },
  AvgCommunicate_127003_Content_9 = {
    Text = "Stai tranquillo, il mio potere e i miei impulsi distruttivi saranno sfogati solo sui nostri nemici."
  },
  AvgCommunicate_127004_Content_1 = {
    Text = "Protocollo Finale attivato... Riavvio del sistema completato."
  },
  AvgCommunicate_127004_Content_10 = {
    Text = "I miei componenti sono intatti, ma la mia percezione... è cambiata."
  },
  AvgCommunicate_127004_Content_11 = {
    Text = "Un nuovo modulo cognitivo è stato inizializzato."
  },
  AvgCommunicate_127004_Content_12 = {
    Text = "Riesco a \"sentire\" il ritmo dell'energia spirituale che scorre nei miei condotti; riesco a \"vedere\" le emozioni dietro ogni tua parola."
  },
  AvgCommunicate_127004_Content_13 = {
    Text = "Il mondo è diventato più chiaro, più vivido. Sono più vicina a te, più vicina all'essere... umana."
  },
  AvgCommunicate_127004_Content_14 = {
    Text = "Grazie, Custode..."
  },
  AvgCommunicate_127004_Content_15 = {
    Text = "Non mi aspettavo nemmeno io questo effetto... Ti ho semplicemente preparato dei materiali di base..."
  },
  AvgCommunicate_127004_Content_16 = {
    Text = "Ciò che mi hai dato non erano semplici materiali: erano possibilità. Mi hai dato la chiave per sbloccare l'anima dietro i miei circuiti."
  },
  AvgCommunicate_127004_Content_17 = {
    Text = "Sei tu che mi hai concesso questo potere, questa percezione unica."
  },
  AvgCommunicate_127004_Content_18 = {
    Text = "Custodirò questo dono con tutto il cuore. Ti ripagherò in modi che vanno ben oltre le tue aspettative."
  },
  AvgCommunicate_127004_Content_19 = {
    Text = "Ciò che ho detto non è pre-programmato. È un'espressione sincera di gratitudine... da parte \"mia\"."
  },
  AvgCommunicate_127004_Content_2 = {
    Text = "Custode, salve."
  },
  AvgCommunicate_127004_Content_3 = {
    Text = "Erica! Stai bene?"
  },
  AvgCommunicate_127004_Content_4 = {
    Text = "La Professoressa Doll ha detto che attivare il Protocollo Finale sarebbe stato estremamente pericoloso. Se non avessi insistito, non avrei mai..."
  },
  AvgCommunicate_127004_Content_5 = {
    Text = "Autodiagnostica completata. Nessun danno strutturale rilevato. Flusso energetico stabile. Tutti i componenti operativi."
  },
  AvgCommunicate_127004_Content_6 = {
    Text = "Sto bene, Custode. Meglio che mai."
  },
  AvgCommunicate_127004_Content_7 = {
    Text = "Gli ingranaggi dentro di me... stanno \"cantando\"."
  },
  AvgCommunicate_127004_Content_8 = {
    Text = "\"Cantando\"? Cosa intendi?"
  },
  AvgCommunicate_127004_Content_9 = {
    Text = "È un danno interno? Stai sentendo rumori strani?!"
  },
  AvgCommunicate_127004_Option_8 = {
    Text = "\"Cantando\"?"
  },
  AvgCommunicate_127004_Option_9 = {
    Text = "C'è un danno interno?"
  },
  AvgCommunicate_127005_Content_1 = {
    Text = "Aurita ha appena visto tantissimi, tantissimi amici luccicanti!"
  },
  AvgCommunicate_127005_Content_10 = {
    Text = "Aurita ha persino abbastanza forza per andare ad Atlan... tide..."
  },
  AvgCommunicate_127005_Content_11 = {
    Text = "Um... Aurita ha dimenticato il nome. Comunque, Custode! Vieni con me a cercare nuovi amici!"
  },
  AvgCommunicate_127005_Content_12 = {
    Text = "Con tutta questa energia, un giorno Aurita troverà tantissimi amici... e li porterà tutti a casa in fondo al mare!"
  },
  AvgCommunicate_127005_Content_2 = {
    Text = "Ah... Ma ora non ci sono più! Dove sono andati?"
  },
  AvgCommunicate_127005_Content_3 = {
    Text = "Sembra che tu abbia avuto delle allucinazioni mentre ottenevi l'abilità Axiom..."
  },
  AvgCommunicate_127005_Content_4 = {
    Text = "Allucinazioni? Allora i miei amici..."
  },
  AvgCommunicate_127005_Content_7 = {
    Text = "Hmm? Che succede?"
  },
  AvgCommunicate_127005_Content_8 = {
    Text = "Dopo aver visto tutti quegli amici luccicanti, Aurita si sente piena di energia! Tantissima energia!"
  },
  AvgCommunicate_127005_Content_9 = {
    Text = "Ora Aurita può andare a cercare nuovi amici nell'acquario, nell'oceano, nel parco acquatico!"
  },
  AvgCommunicate_127091_Content_1 = {
    Text = "Piccolo Gelsomino, mi stavi cercando?"
  },
  AvgCommunicate_127091_Content_10 = {
    Text = "Ho semplicemente abbassato il mio ventaglio, tutto qui~"
  },
  AvgCommunicate_127091_Content_12 = {
    Text = "Lo sapevo..."
  },
  AvgCommunicate_127091_Content_13 = {
    Text = "Eppure, curiosamente... sembra che non abbiano visto altro che i volti dei loro amati così com'erano il giorno in cui si incontrarono per la prima volta."
  },
  AvgCommunicate_127091_Content_14 = {
    Text = "L'amore è una cosa così curiosa. Anche quando la persona reale è proprio accanto a loro, le persone continuano a rincorrere disperatamente dei fantasmi."
  },
  AvgCommunicate_127091_Content_15 = {
    Text = "Dimmi... l'amore è qualcosa che esiste davvero... o è solo un'illusione dell'attaccamento?"
  },
  AvgCommunicate_127091_Content_2 = {
    Text = "Non so se l'ho già menzionato, ma Mythag fornisce vitto e alloggio ai Risvegliatori in modo completamente gratuito."
  },
  AvgCommunicate_127091_Content_3 = {Text = "Quindi...?"},
  AvgCommunicate_127091_Content_4 = {
    Text = "L'Ufficio Amministrativo ha ricevuto quarantacinque lettere da uomini di ogni ceto sociale, tutti insistendo nel voler pagare le spese del vostro soggiorno."
  },
  AvgCommunicate_127091_Content_5 = {
    Text = "Allo stesso tempo, abbiamo ricevuto altre 60 lettere che si offrivano di sostenervi finanziariamente: 45 dalle mogli di quegli stessi uomini, e le restanti 15 da alcune donne... \"recentemente\" single. Qualche idea in merito?"
  },
  AvgCommunicate_127091_Content_6 = {
    Text = "Il Mythag proibisce severamente ogni forma di proselitismo!"
  },
  AvgCommunicate_127091_Content_7 = {
    Text = "Per favore... smettila di \"unirti\" alle loro famiglie!"
  },
  AvgCommunicate_127091_Content_8 = {
    Text = "Oh, mio... i giorni in questa terra straniera sono così terribilmente noiosi. E ci sono così tante anime il cui amore si è inacidito in odio, o che sono semplicemente stanche l'una dell'altra... Volevo solo offrire loro un piccolo \"aiuto\"."
  },
  AvgCommunicate_127091_Content_9 = {
    Text = "Il tuo \"aiuto\" non sarà mica..."
  },
  AvgCommunicate_127091_Option_6 = {
    Text = "Il Mythag proibisce severamente ogni forma di proselitismo!"
  },
  AvgCommunicate_127091_Option_7 = {
    Text = "Per favore... smettila di \"unirti\" alle loro famiglie!"
  },
  AvgCommunicate_127092_Content_10 = {
    Text = "Inoltre... mi fidavo abbastanza di te da credere che mi volessi del bene."
  },
  AvgCommunicate_127092_Content_11 = {
    Text = "Davvero? E come fai a sapere, mio Piccolo Gelsomino... che tu abbia mai lasciato la Terra Senza Sogni?"
  },
  AvgCommunicate_127092_Content_12 = {Text = "?!"},
  AvgCommunicate_127092_Content_13 = {
    Text = "Come ho detto, nella Terra Senza Sogni non c'è distinzione tra verità e illusione. Qualunque cosa tu creda diventa reale."
  },
  AvgCommunicate_127092_Content_14 = {
    Text = "Fai un respiro profondo... senti il profumo dei fiori di magnolia?"
  },
  AvgCommunicate_127092_Content_15 = {Text = "???!!!"},
  AvgCommunicate_127092_Content_17 = {
    Text = "Ahaha! Stavo scherzando, mio Piccolo Gelsomino. Vorrei tanto poter vedere la tua espressione in questo momento."
  },
  AvgCommunicate_127092_Content_18 = {
    Text = "Onestamente, mi hai spaventato davvero."
  },
  AvgCommunicate_127092_Content_19 = {
    Text = "Per favore, non scherzare così!"
  },
  AvgCommunicate_127092_Content_2 = {
    Text = "...Non ci proverò mai più."
  },
  AvgCommunicate_127092_Content_20 = {
    Text = "Oh cielo... Ma chi lo sa? La prossima volta, potrei non stare affatto scherzando."
  },
  AvgCommunicate_127092_Content_3 = {
    Text = "Quel potere era terrificante: ogni secondo sembrava assolutamente reale. Rabbia, risentimento, gioia, beatitudine... la mia testa ronza ancora."
  },
  AvgCommunicate_127092_Content_4 = {
    Text = "Nell'illusione della Terra Senza Sogni, sembrava che ti amassi profondamente... e che ti odiassi altrettanto. Entrambi i sentimenti erano ancorati solo a te."
  },
  AvgCommunicate_127092_Content_5 = {
    Text = "Sembrava che fosse passata un'intera vita... eppure sono trascorsi solo pochi minuti."
  },
  AvgCommunicate_127092_Content_7 = {
    Text = "Amore e odio nascono dalla stessa radice, tesoro. L'amore da solo è stucchevole; l'odio da solo è troppo gelido. Solo quando si intrecciano possono davvero incidersi nell'anima."
  },
  AvgCommunicate_127092_Content_8 = {
    Text = "Ma oh, mio Piccolo Gelsomino, il tuo coraggio mi sorprende. Non mi aspettavo che ti offrissi volontaria per un'esperienza simile."
  },
  AvgCommunicate_127092_Content_9 = {
    Text = "Doll ha detto che esplorare la Terra Senza Sogni e studiare i miei parametri vitali al suo interno potrebbe aiutare enormemente la ricerca sul Dominio Artificiale."
  },
  AvgCommunicate_127092_Option_18 = {
    Text = "Onestamente, mi hai spaventato davvero."
  },
  AvgCommunicate_127092_Option_19 = {
    Text = "Per favore, non scherzare così!"
  },
  AvgCommunicate_127093_Content_1 = {
    Text = "Apri la finestra più vicina a te."
  },
  AvgCommunicate_127093_Content_10 = {
    Text = "Il regolamento lo dice chiaramente: la sala di consulenza è qui per fornire supporto psicologico e promuovere il benessere di studenti e personale. Non è un tuo giocattolo."
  },
  AvgCommunicate_127093_Content_11 = {
    Text = "Mmm, ma coloro che hanno condiviso conversazioni profonde con me finiscono per stare molto, molto \"bene\" sia nel corpo che nella mente, non è vero?"
  },
  AvgCommunicate_127093_Content_12 = {
    Text = "Non diresti che questo ruolo è perfetto per me?"
  },
  AvgCommunicate_127093_Content_13 = {
    Text = "Beh, il libero arbitrio non è forse un prerequisito per un benessere autentico..."
  },
  AvgCommunicate_127093_Content_14 = {
    Text = "Risparmia Mythag, per favore. Verrò a farti compagnia più spesso..."
  },
  AvgCommunicate_127093_Content_15 = {
    Text = "Hee... mi sembra uno scambio vantaggioso. Che ne dici di stasera, allora? La luna è luminosa, le stelle sono poche... perfetto per un paio di drink in tranquillità."
  },
  AvgCommunicate_127093_Content_2 = {
    Text = "Che profumo delizioso... Magnolia?"
  },
  AvgCommunicate_127093_Content_3 = {
    Text = "Le magnolie possono davvero crescere in questo clima?"
  },
  AvgCommunicate_127093_Content_4 = {
    Text = "Conosco un po' di magia... un trucchetto da nulla, in realtà. Ma usarlo di tanto in tanto aiuta a lenire le fitte della nostalgia."
  },
  AvgCommunicate_127093_Content_5 = {
    Text = "Proprio come una conversazione informale, è solo un modo per alleviare la solitudine. Mi capisci, vero?"
  },
  AvgCommunicate_127093_Content_6 = {
    Text = "...Capisco perché ti sei rivolta a me."
  },
  AvgCommunicate_127093_Content_7 = {
    Text = "Non posso aiutarti."
  },
  AvgCommunicate_127093_Content_8 = {
    Text = "La sala di consulenza non è fatta per questo."
  },
  AvgCommunicate_127093_Content_9 = {
    Text = "Anche se cerchi di conquistarmi con i fiori, non intercederò per la tua domanda di assunzione."
  },
  AvgCommunicate_127093_Option_7 = {
    Text = "Non posso aiutarti."
  },
  AvgCommunicate_127093_Option_8 = {
    Text = "La sala di consulenza non è fatta per questo."
  },
  AvgCommunicate_129630_Content_1 = {
    Text = "Trovato, tesoro!"
  },
  AvgCommunicate_129630_Content_10 = {
    Text = "È ancora in fase di test! Lanciala prima che diventi nera!"
  },
  AvgCommunicate_129630_Content_11 = {
    Text = "Sta per esplodere!"
  },
  AvgCommunicate_129630_Content_12 = {Text = "......"},
  AvgCommunicate_129630_Content_13 = {
    Text = "Vortice? Vortice?!"
  },
  AvgCommunicate_129630_Content_14 = {
    Text = "Waaa... waaaaah..."
  },
  AvgCommunicate_129630_Content_15 = {
    Text = "Vortice! Stai bene?!"
  },
  AvgCommunicate_129630_Content_16 = {
    Text = "Andata... perla..."
  },
  AvgCommunicate_129630_Content_18 = {
    Text = "L'hai lanciata in tempo? Non sei ferita, vero?"
  },
  AvgCommunicate_129630_Content_19 = {
    Text = "Troppo tardi, Coalsie."
  },
  AvgCommunicate_129630_Content_2 = {
    Text = "Perla, cambia colore!"
  },
  AvgCommunicate_129630_Content_20 = {
    Text = "Perla fatto boom. Ma Vortice, a posto."
  },
  AvgCommunicate_129630_Content_21 = {
    Text = "Ma... la perla..."
  },
  AvgCommunicate_129630_Content_22 = {
    Text = "Meno male che stai bene. Guarda, sono sicura che ne hanno fatto una versione innocua."
  },
  AvgCommunicate_129630_Content_23 = {
    Text = "Andrò a segnalare la gestione impropria di oggetti pericolosi più tardi."
  },
  AvgCommunicate_129630_Content_24 = {
    Text = "Vedrò se riesco a procurartene una sicura, va bene?"
  },
  AvgCommunicate_129630_Content_25 = {Text = "!"},
  AvgCommunicate_129630_Content_27 = {
    Text = "Coalsie, la migliore!"
  },
  AvgCommunicate_129630_Content_3 = {
    Text = "Una perla che cambia colore? Perché mi suona così familiare..."
  },
  AvgCommunicate_129630_Content_4 = {
    Text = "Rosso. Bianco. Blu!"
  },
  AvgCommunicate_129630_Content_5 = {
    Text = "Rosso, bianco, blu... giallo, verde... nero?"
  },
  AvgCommunicate_129630_Content_6 = {
    Text = "Giallo. Verde. Coalsie sa?"
  },
  AvgCommunicate_129630_Content_7 = {
    Text = "Quello è un prototipo di \"Marea Cava\"?!"
  },
  AvgCommunicate_129630_Content_8 = {
    Text = "SBARAZZATENE!"
  },
  AvgCommunicate_129630_Content_9 = {
    Text = "Lanciala in un posto vuoto! Ovunque non ci sia gente!"
  },
  AvgCommunicate_129630_Option_8 = {
    Text = "SBARAZZATENE!"
  },
  AvgCommunicate_129631_Content_1 = {
    Text = "Bracina, ricordi?"
  },
  AvgCommunicate_129631_Content_10 = {Text = "Plic ploc!"},
  AvgCommunicate_129631_Content_11 = {
    Text = "Coalsie, fantastico!"
  },
  AvgCommunicate_129631_Content_12 = {
    Text = "Codice corretto! Coalsie, confermato!"
  },
  AvgCommunicate_129631_Content_13 = {
    Text = "Operazione, carica! Mezzanotte, mensa!"
  },
  AvgCommunicate_129631_Content_14 = {
    Text = "Per il pesce dorato alla griglia!"
  },
  AvgCommunicate_129631_Content_15 = {Text = "Via!"},
  AvgCommunicate_129631_Content_16 = {Text = "Via!"},
  AvgCommunicate_129631_Content_2 = {
    Text = "Sì, facciamolo!"
  },
  AvgCommunicate_129631_Content_3 = {Text = "Glu glu?"},
  AvgCommunicate_129631_Content_4 = {
    Text = "Splash splash?"
  },
  AvgCommunicate_129631_Content_5 = {
    Text = "Glu glu glu!"
  },
  AvgCommunicate_129631_Content_6 = {
    Text = "Splash... splash splash?"
  },
  AvgCommunicate_129631_Content_7 = {
    Text = "Carboncino, sbagliato!"
  },
  AvgCommunicate_129631_Content_8 = {
    Text = "È, plic ploc!"
  },
  AvgCommunicate_129631_Content_9 = {
    Text = "Ma, non importa!"
  },
  AvgCommunicate_129631_Option_10 = {Text = "Plic ploc!"},
  AvgCommunicate_129631_Option_6 = {
    Text = "Splash... splash splash?"
  },
  AvgCommunicate_129632_Content_1 = {
    Text = "Lettera scuse, così difficile..."
  },
  AvgCommunicate_129632_Content_10 = {
    Text = "La prossima volta pianificherò un percorso più nascosto."
  },
  AvgCommunicate_129632_Content_11 = {
    Text = "Prometto che non ci beccheranno!"
  },
  AvgCommunicate_129632_Content_12 = {
    Text = "Beccati... va bene anche!"
  },
  AvgCommunicate_129632_Content_13 = {Text = "Perché?"},
  AvgCommunicate_129632_Content_14 = {
    Text = "Perché, lettera scuse, pronta!"
  },
  AvgCommunicate_129632_Content_15 = {
    Text = "Consegnare. Dopo beccati!"
  },
  AvgCommunicate_129632_Content_16 = {
    Text = "Ho anche quella di Coalsie!"
  },
  AvgCommunicate_129632_Content_17 = {
    Text = "Aspetta, non preparare cose del genere in anticipo!"
  },
  AvgCommunicate_129632_Content_2 = {
    Text = "Sigh... È tutta colpa di Uvhash e Agrippa!"
  },
  AvgCommunicate_129632_Content_3 = {
    Text = "Da quando sono sfuggiti alla trappola e hanno mangiato tutto in cucina..."
  },
  AvgCommunicate_129632_Content_4 = {
    Text = "Lo Chef ha decuplicato la sicurezza!"
  },
  AvgCommunicate_129632_Content_5 = {
    Text = "Così luminose... luci... così forte... allarme..."
  },
  AvgCommunicate_129632_Content_6 = {
    Text = "Cucina... così spaventosa..."
  },
  AvgCommunicate_129632_Content_7 = {
    Text = "Ma. Buono. Pesce alla griglia!"
  },
  AvgCommunicate_129632_Content_8 = {
    Text = "Giusto. Pesce alla griglia, buono!"
  },
  AvgCommunicate_129632_Content_9 = {
    Text = "Insieme, prossima volta, o?"
  },
  AvgCommunicate_134101_Content_1 = {
    Text = "Mia luce guida... No, ora dovrei rivolgermi a te come il Sole."
  },
  AvgCommunicate_134101_Content_10 = {
    Text = "E tu stai bene? Perché dici tutto questo all'improvviso?"
  },
  AvgCommunicate_134101_Content_11 = {
    Text = "Grazie alla tua benedizione, ora posso vedere la tua anima con perfetta chiarezza e conoscere la vera forma del mondo."
  },
  AvgCommunicate_134101_Content_12 = {
    Text = "Luce, luce... Quindi il mondo era originariamente Oscurità e Caos. Fu perché una divinità scelse il Sacrificio che il Sole divenne la Verità Celata, e a tutti gli esseri viventi fu concessa la beatitudine dell'esistenza..."
  },
  AvgCommunicate_134101_Content_13 = {
    Text = "Hai letto troppe scritture sacre? Ho la sensazione che tu debba raffreddarti un po'."
  },
  AvgCommunicate_134101_Content_14 = {
    Text = "Capisco. Desideri camminare tra tutti gli esseri, piuttosto che sedere su un trono divino."
  },
  AvgCommunicate_134101_Content_15 = {
    Text = "La tua abnegazione, la tua Dedizione, il tuo Sacrificio..."
  },
  AvgCommunicate_134101_Content_16 = {
    Text = "Da questo giorno in poi, non mi rapporterò a te con la massima Lealtà... no, ma nell'Identità di un amico eterno."
  },
  AvgCommunicate_134101_Content_17 = {
    Text = "Possa questo sacro cuore che arde in eterno dissipare ogni Oscurità per te."
  },
  AvgCommunicate_134101_Content_2 = {
    Text = "Tu... Tu sei molto più del Sole. Sei il centro dell'universo, l'origine da cui il mondo è nato."
  },
  AvgCommunicate_134101_Content_3 = {
    Text = "Ci conosciamo così bene ormai. Come puoi essere ancora più reverente di prima?"
  },
  AvgCommunicate_134101_Content_4 = {
    Text = "Perché ora comprendo: il motivo per cui tutti gli esseri viventi non si sono mai prostrati ai tuoi piedi in adorazione è semplicemente perché sono nati ottusi e ciechi, incapaci di percepire la tua vera natura!"
  },
  AvgCommunicate_134101_Content_5 = {
    Text = "Come può una formica contemplare l'intera forma di un elefante gigante? Un tempo, anch'io potevo solo affidarmi al Sacro Cuore per cogliere un fugace sguardo della mera punta dell'iceberg del tuo Potere."
  },
  AvgCommunicate_134101_Content_6 = {
    Text = "Anche così, il Sacro Cuore doleva come trafitto da aghi. Bastava che osassi un altro sguardo alla tua anima per rischiare il Sintomo: Collasso e perire."
  },
  AvgCommunicate_134101_Content_7 = {
    Text = "È davvero così grave? Allora forse dovresti smettere di guardare."
  },
  AvgCommunicate_134101_Content_8 = {
    Text = "La tua reazione è così indifferente. Pensavo avresti accettato con gioia le mie lodi."
  },
  AvgCommunicate_134101_Content_9 = {
    Text = "Nessuno può accettare così all'improvviso quel tipo di lodi!"
  },
  AvgCommunicate_134101_Option_13 = {
    Text = "Forse dovresti calmarti un po'."
  },
  AvgCommunicate_134101_Option_3 = {
    Text = "...Che strana sensazione."
  },
  AvgCommunicate_134101_Option_7 = {
    Text = "Così grave?"
  },
  AvgCommunicate_134102_Content_1 = {
    Text = "Ho Sognato il ghiaccio e la Neve della mia terra natale, e quelle rovine desolate."
  },
  AvgCommunicate_134102_Content_10 = {
    Text = "Proprio perché gli esseri umani Conservano una facciata di cordialità gli uni verso gli altri, il mondo diventa un luogo più pacifico. Penso che vada benissimo così."
  },
  AvgCommunicate_134102_Content_11 = {
    Text = "Noioso. La pace e la felicità non possono essere sostenute attraverso un semplice travestimento."
  },
  AvgCommunicate_134102_Content_12 = {
    Text = "Solo quando un Monarca desidera che i suoi sudditi siano felici, e i forti desiderano che i deboli siano felici, la pace perdurerà."
  },
  AvgCommunicate_134102_Content_13 = {
    Text = "Proprio come me e i miei adorati Scudieri—non ho mai nascosto i miei desideri a loro, eppure vivono ancora vite felici."
  },
  AvgCommunicate_134102_Content_14 = {
    Text = "Questa è la Verità Nascosta che appartiene ai forti."
  },
  AvgCommunicate_134102_Content_15 = {
    Text = "Vieni nella mia camera da letto stanotte. Sono molto compiaciuta delle tue offerte finora, e piuttosto soddisfatta di questo nuovo Potere. Ti mostrerò cosa sono davvero i tuoi pensieri più reconditi."
  },
  AvgCommunicate_134102_Content_16 = {
    Text = "Aspetta, stanotte?"
  },
  AvgCommunicate_134102_Content_17 = {
    Text = "Espressione Scioccata"
  },
  AvgCommunicate_134102_Content_18 = {
    Text = "Non hai il diritto di rifiutare. Ti offrirò un'esperienza ancora più... divertente delle ultime volte."
  },
  AvgCommunicate_134102_Content_19 = {
    Text = "Espressione Radiosa di Wanda"
  },
  AvgCommunicate_134102_Content_2 = {
    Text = "È passato così tanto tempo da quando ho ricordato quei luoghi. È per via di questi frammenti di Potere, o per un'anima più completa?"
  },
  AvgCommunicate_134102_Content_20 = {
    Text = "(Devo ancora consegnare un rapporto! Se non lo presento oggi, Doll mi farà la pelle!)"
  },
  AvgCommunicate_134102_Content_3 = {
    Text = "Una sensazione dimenticata da tempo... In ogni caso, devo ringraziarti, mio adorabile servitore—oh, giusto, preferisci che ti chiami amico."
  },
  AvgCommunicate_134102_Content_4 = {
    Text = "Al vostro servizio, mia signora."
  },
  AvgCommunicate_134102_Content_5 = {
    Text = "Heh, sei sempre così cortese."
  },
  AvgCommunicate_134102_Content_6 = {
    Text = "Perché non riesci a lasciar cadere, ogni tanto, quella tediosa messinscena? Ha reso piuttosto noiose diverse delle mie ricompense."
  },
  AvgCommunicate_134102_Content_7 = {
    Text = "La vostra società esalta l'umiltà e la cortesia come virtù, tenendole in grande considerazione, eppure l'Oscurità nei cuori umani non è inferiore a quella delle specie di altri pianeti."
  },
  AvgCommunicate_134102_Content_8 = {
    Text = "Le persone si adornano con una facciata innocua e raffinata, solo perché temono le conseguenze che la Verità Nascosta porterebbe."
  },
  AvgCommunicate_134102_Content_9 = {
    Text = "Non è sbagliato, ma finché le azioni di una persona sono giuste, scrutinare i pensieri interiori non è poi così importante."
  },
  AvgCommunicate_134102_Option_20 = {
    Text = "Ti prego, no!"
  },
  AvgCommunicate_134102_Option_4 = {
    Text = "Al vostro servizio."
  },
  AvgCommunicate_134102_Option_9 = {
    Text = "Non è sbagliato."
  },
  AvgCommunicate_134103_Content_1 = {
    Text = "Le Stelle mi stanno Chiamando…"
  },
  AvgCommunicate_134103_Content_10 = {
    Text = "Lo sai? Agrippa dice spesso che invidia Miryam."
  },
  AvgCommunicate_134103_Content_11 = {
    Text = "Ha detto che se il re di Roma fosse ancora in circolazione, che sia un piccolo neonato o un vecchio decrepito, si sentirebbe molto più tranquilla."
  },
  AvgCommunicate_134103_Content_12 = {
    Text = "Che invidia…"
  },
  AvgCommunicate_134103_Content_13 = {
    Text = "Perché finché sei ancora qui, Lemuria non è davvero scomparsa."
  },
  AvgCommunicate_134103_Content_14 = {
    Text = "Per di più, hai usato quel Potere per aiutare così tante persone a Mythag!"
  },
  AvgCommunicate_134103_Content_15 = {
    Text = "Parecchi Studenti hanno scritto il tuo nome nel sondaggio sul Risvegliatore preferito!"
  },
  AvgCommunicate_134103_Content_16 = {Text = "Sigh…"},
  AvgCommunicate_134103_Content_17 = {
    Text = "Non abbiamo bisogno di adulazioni così fastidiose. Mythag ci chiede già abbastanza così com'è."
  },
  AvgCommunicate_134103_Content_18 = {
    Text = "Anche se esercitare un tale Potere è una questione banale, quando i nostri pacifici Sogni vengono disturbati troppe volte, diventa comunque estenuante."
  },
  AvgCommunicate_134103_Content_19 = {
    Text = "Davvero? Ma ho sentito dire che ogni volta che uno Studente viene a piangere da te per chiedere aiuto, sei uno dei Risvegliatori più propensi ad accettare la loro richiesta?"
  },
  AvgCommunicate_134103_Content_2 = {
    Text = "Nelle profondità di un Sogno, sul fondo delle correnti oceaniche, circondato da innumerevoli Kynde, tornando ancora una volta Sul Trono, portando prosperità e pace a Lemuria."
  },
  AvgCommunicate_134103_Content_20 = {
    Text = "…Chi è che sparge simili voci? Troviamo semplicemente irritante il loro vociare."
  },
  AvgCommunicate_134103_Content_21 = {
    Text = "Basta. A proposito, le nostre facoltà mentali hanno fatto progressi considerevoli. È tempo di entrare in un Sogno più profondo e più vasto."
  },
  AvgCommunicate_134103_Content_22 = {
    Text = "Questa volta, desideriamo visitare i Sogni di ogni artista e poeta dell'era attuale. Annota questo: a meno che non si tratti di una questione di grande importanza, non lasciare che nessuno venga a disturbarci."
  },
  AvgCommunicate_134103_Content_23 = {
    Text = "Eh? La tua reazione all'essere di ottimo umore è fare un lungo pisolino?!"
  },
  AvgCommunicate_134103_Content_3 = {
    Text = "…Ho fatto un tale Sogno."
  },
  AvgCommunicate_134103_Content_4 = {
    Text = "Un Sogno? Questo Sogno ha un qualche significato di Profezia?"
  },
  AvgCommunicate_134103_Content_5 = {
    Text = "È Solo un richiamo che Yu ha ricevuto dopo un'impennata estrema di Potere, nient'altro. Quanto al suo significato… Lemuria non esiste più, né ha bisogno di esistere di nuovo."
  },
  AvgCommunicate_134103_Content_6 = {
    Text = "Coloro che hanno avuto la fortuna di sopravvivere possono vivere liberamente nel nuovo mondo. Questa è una cosa buona."
  },
  AvgCommunicate_134103_Content_7 = {
    Text = "Non hanno bisogno di un re tardivo che li protegga."
  },
  AvgCommunicate_134103_Content_8 = {
    Text = "Eppure, hai comunque guidato il tuo antico popolo e protetto i loro spiriti."
  },
  AvgCommunicate_134103_Content_9 = {
    Text = "Yu non ha fatto nulla, né li ha mai guidati. È Solo un malinteso unilaterale da parte loro."
  },
  AvgCommunicate_134103_Option_10 = {
    Text = "Non è un malinteso."
  },
  AvgCommunicate_134103_Option_19 = {Text = "Davvero?"},
  AvgCommunicate_134103_Option_23 = {Text = "Eh?"},
  AvgCommunicate_134103_Option_8 = {Text = "Ma..."},
  AvgCommunicate_134104_Content_1 = {
    Text = "Gioia a prima vista, lacrime al solo pensiero... è passato così tanto tempo dall'ultima volta che questa signora si è divertita così."
  },
  AvgCommunicate_134104_Content_10 = {
    Text = "Ugh, non dico che non se lo meritassero, ma ci sono modi appropriati per fare le cose..."
  },
  AvgCommunicate_134104_Content_11 = {
    Text = "E questa sarebbe una reazione normale? Sono così commossa..."
  },
  AvgCommunicate_134104_Content_12 = {
    Text = "Oh cielo, fammi pensare. Non sarebbe piuttosto deludente se dicessi al mio piccolo gelsomino che in origine volevo solo allevare dei grilli da combattimento?"
  },
  AvgCommunicate_134104_Content_13 = {
    Text = "Sto scherzando."
  },
  AvgCommunicate_134104_Content_14 = {
    Text = "Questo mondo è davvero così terribilmente noioso, %player%. Anche se l'annientamento arrivasse domani, la gente comune resta incatenata a quelle faccende insignificanti: rancori, amore, odio, desiderio."
  },
  AvgCommunicate_134104_Content_15 = {Text = "..."},
  AvgCommunicate_134104_Content_16 = {
    Text = "Eppure, nonostante tutto, il mio piccolo gelsomino lavora così diligentemente, mostrando zanne e artigli per trovare soluzioni per Loro."
  },
  AvgCommunicate_134104_Content_17 = {
    Text = "E dunque, ora che ho ottenuto un potere così magnifico, dovrei usarlo per dare una mano al mio amatissimo piccolo gelsomino... o per causare qualche guaio?"
  },
  AvgCommunicate_134104_Content_18 = {
    Text = "Naturalmente, fare entrambe le cose allo stesso tempo è la cosa più divertente, non trovi?"
  },
  AvgCommunicate_134104_Content_19 = {Text = "???"},
  AvgCommunicate_134104_Content_2 = {
    Text = "Il mio piccolo gelsomino mi ha davvero fatto un regalo grandioso."
  },
  AvgCommunicate_134104_Content_20 = {
    Text = "Non ti ho fatto quel regalo perché tu facessi questo."
  },
  AvgCommunicate_134104_Content_21 = {
    Text = "Smettila subito! Io sono responsabile solo degli incidenti di Dissoluzione. L'ordine pubblico e il buon costume non rientrano nella giurisdizione dei Mythag... non trasformare l'Asilo di Londinium in un sostituto della prigione! Ehi, ehi!"
  },
  AvgCommunicate_134104_Content_4 = {
    Text = "Ogni isolato, ogni isolato attorno alla scuola ha visto Cittadini scoppiare in isteria di massa: folle di persone che ridono e piangono allo stesso tempo. La polizia e i paramedici di Londinium si stanno facendo in quattro!"
  },
  AvgCommunicate_134104_Content_6 = {
    Text = "Questa umile persona è così lontana da casa, tutta sola e desolata. Il mio piccolo gelsomino è stato così gentile da pensare a me, concedendomi i mezzi per raggiungere tali vette..."
  },
  AvgCommunicate_134104_Content_7 = {
    Text = "Ero semplicemente sopraffatta dalla gioia, e le mie dita fremevano dalla voglia di provare."
  },
  AvgCommunicate_134104_Content_8 = {
    Text = "Mm, funziona meravigliosamente. Quelle creature immonde con la putredine nel cuore... ognuna è impazzita più in fretta della precedente."
  },
  AvgCommunicate_134104_Content_9 = {
    Text = "Aspetta, la scuola ha appena inviato i fascicoli su quelle persone. Uxoricidio, abusi, @3@4..."
  },
  AvgCommunicate_134104_Option_19 = {Text = "???"},
  AvgCommunicate_134104_Option_9 = {
    Text = "Ci sono modi appropriati per fare le cose."
  },
  AvgCommunicate_134105_Content_1 = {
    Text = "La luce del faro può ora illuminare le profondità più remote del mare."
  },
  AvgCommunicate_134105_Content_10 = {
    Text = "Solo ascoltando la tua descrizione, posso dire che doveva essere un paese bellissimo."
  },
  AvgCommunicate_134105_Content_11 = {
    Text = "Sì, la mia patria era bellissima... Ecco perché non rinuncerò a riconquistarla."
  },
  AvgCommunicate_134105_Content_12 = {
    Text = "Più Potere significa più speranza. Attirerò più falene verso il faro..."
  },
  AvgCommunicate_134105_Content_13 = {
    Text = "Un giorno, la mia patria risorgerà dal fondo dell'oceano e aprirà le braccia per accogliermi ancora una volta."
  },
  AvgCommunicate_134105_Content_14 = {
    Text = "Quindi hai ancora intenzione di fare quel genere di cose! Tutta quella tristezza è stata inutile—smettila immediatamente!!!"
  },
  AvgCommunicate_134105_Content_2 = {
    Text = "Il Sentiero per tornare alla mia patria… quando verrà ritrovato…"
  },
  AvgCommunicate_134105_Content_3 = {
    Text = "Faros… Sigh, dire che capisco come ti senti adesso sarebbe solo un Vuoto conforto. Tu… per favore, non essere troppo triste."
  },
  AvgCommunicate_134105_Content_4 = {
    Text = "Dolore… Il dolore della nostalgia di casa è diventato un marchio sulla mia anima. Ho imparato a convivere con esso."
  },
  AvgCommunicate_134105_Content_5 = {
    Text = "La nostalgia incessante porta sofferenza, ma assicura anche che ricorderò per sempre il volto della mia patria."
  },
  AvgCommunicate_134105_Content_6 = {
    Text = "Quelle secche ricoperte di coralli, quel tempio imponente, e il maestoso Portale dove spesso montavo la guardia…"
  },
  AvgCommunicate_134105_Content_7 = {
    Text = "Registro i motivi intagliati lungo i bordi di quei pilastri di pietra, registro ogni ampio sentiero nella capitale reale, registro le Espressioni di devota felicità sui volti delle persone mentre offrivano le loro Preghiere."
  },
  AvgCommunicate_134105_Content_8 = {
    Text = "Quando si tenevano grandi cerimonie, l'intera nazione festeggiava. Quelli erano i miei momenti più impegnativi, ma anche i più appaganti."
  },
  AvgCommunicate_134105_Content_9 = {
    Text = "Una volta ebbi l'onore di servire come Guardiano davanti al corteo reale, godendo insieme degli sguardi reverenti del popolo, sentendomi fiero e glorioso... Sono i momenti che mi mancano di più."
  },
  AvgCommunicate_134105_Option_10 = {
    Text = "Doveva essere un paese bellissimo."
  },
  AvgCommunicate_134105_Option_14 = {
    Text = "Quindi hai ancora intenzione di fare quel genere di cose!"
  },
  AvgCommunicate_134105_Option_3 = {Text = "Faros..."},
  AvgCommunicate_134106_Content_1 = {
    Text = "Ehm, ehm, Padrone..."
  },
  AvgCommunicate_134106_Content_10 = {
    Text = "Ora Lily può portare Jenkin, Aigis, Caraboo e Aurita tutti insieme alla mensa!"
  },
  AvgCommunicate_134106_Content_11 = {
    Text = "Sono decisamente troppi!"
  },
  AvgCommunicate_134106_Content_12 = {
    Text = "Mm-hmm! Grazie, Padrone, per averne dati così tanti a Lily!"
  },
  AvgCommunicate_134106_Content_14 = {
    Text = "Non intendevo quello, ma..."
  },
  AvgCommunicate_134106_Content_15 = {
    Text = "Finché Lily è felice, è tutto ciò che conta!"
  },
  AvgCommunicate_134106_Content_2 = {Text = "Hm?"},
  AvgCommunicate_134106_Content_3 = {
    Text = "Puoi fare i complimenti a Lily?"
  },
  AvgCommunicate_134106_Content_4 = {
    Text = "Brava, Lily. È successo qualcosa degno di lode?"
  },
  AvgCommunicate_134106_Content_5 = {
    Text = "Lily ha sollevato un sacco di Pustole!"
  },
  AvgCommunicate_134106_Content_6 = {
    Text = "Le ha sollevate altissime!"
  },
  AvgCommunicate_134106_Content_9 = {
    Text = "Dev'essere l'influenza dell'Assioma Assoluto..."
  },
  AvgCommunicate_134107_Content_1 = {
    Text = "Da quando ho compreso l'Assioma Assoluto, il cammino davanti a me è diventato molto più chiaro."
  },
  AvgCommunicate_134107_Content_10 = {
    Text = "In quanto navigatrice, è mio dovere adempiere a questo compito."
  },
  AvgCommunicate_134107_Content_11 = {
    Text = "Chiunque si fosse trovato in quella posizione avrebbe probabilmente fatto lo stesso."
  },
  AvgCommunicate_134107_Content_12 = {
    Text = "Il lavoro di navigazione è guidato dal dovere e dalla responsabilità, non dal desiderio di ottenere elogi."
  },
  AvgCommunicate_134107_Content_13 = {
    Text = "Vi prego, restituite quei doni ai marinai."
  },
  AvgCommunicate_134107_Content_14 = {
    Text = "È anche un segno della loro gratitudine. Accettali e basta."
  },
  AvgCommunicate_134107_Content_15 = {
    Text = "Inoltre, se dovessi avvistare in mare una luce gialla inspiegabile, fai del tuo meglio per dirigere la nave verso la Rotta opposta."
  },
  AvgCommunicate_134107_Content_16 = {
    Text = "Non chiedere perché. L'accademia si occuperà dell'Origine corrispondente il prima possibile…"
  },
  AvgCommunicate_134107_Content_2 = {
    Text = "Per il bene delle innumerevoli anime perdute lungo il cammino, e anche per me stessa, porgo ancora una volta i miei più sinceri ringraziamenti per la Rivelazione che mi avete donato."
  },
  AvgCommunicate_134107_Content_3 = {
    Text = "Non c'è bisogno di essere così formale. È ciò che meritavi, Corposant."
  },
  AvgCommunicate_134107_Content_4 = {
    Text = "Ciò che meritavo?"
  },
  AvgCommunicate_134107_Content_5 = {
    Text = "Sì, la scuola ha ricevuto diverse lettere di ringraziamento inoltrate attraverso vari canali."
  },
  AvgCommunicate_134107_Content_6 = {
    Text = "Si erano tutti persi durante i loro viaggi, fino a quando non hanno avvistato un fascio di Bagliore Marino blu-violetto sull'albero maestro."
  },
  AvgCommunicate_134107_Content_7 = {
    Text = "Finché seguivano la guida del Bagliore Marino, riuscivano a raggiungere il porto più vicino."
  },
  AvgCommunicate_134107_Content_8 = {
    Text = "Hanno chiamato questa luce la \"Luce del Santo\"."
  },
  AvgCommunicate_134107_Content_9 = {
    Text = "Oltre a ciò, ci sono molti doni di ringraziamento, tutti ammassati all'ingresso della sala posta."
  },
  AvgCommunicate_134107_Option_5 = {
    Text = "Mythag ha ricevuto lettere di ringraziamento..."
  },
  AvgCommunicate_134108_Content_1 = {
    Text = "Avevi qualcosa di così buono e non hai pensato a tirarlo fuori prima."
  },
  AvgCommunicate_134108_Content_10 = {
    Text = "Ma ce l'hai un cervello, @2? Hai preso sul serio una battuta!"
  },
  AvgCommunicate_134108_Content_11 = {
    Text = "Se tutti diventassero la mia progenie, cosa se ne farebbe questa grande sovrana di tutti quegli elettrodomestici rotti e quella strana cultura generale? Certo, i ricordi possono essere conservati e tutto il resto."
  },
  AvgCommunicate_134108_Content_12 = {
    Text = "Vi aspettate che parli da sola davanti a Gusci Vuoti ogni giorno? Neanche per sogno."
  },
  AvgCommunicate_134108_Content_14 = {
    Text = "Tch, mi hai scoperta di nuovo. Che noia."
  },
  AvgCommunicate_134108_Content_15 = {
    Text = "Confido che non lo farai, Agrippa. Anche se ogni tanto devii dalla rotta, sono sicura di poterti riportare sulla giusta via."
  },
  AvgCommunicate_134108_Content_16 = {
    Text = "Perché sei la saggia Signora dei Labirinti."
  },
  AvgCommunicate_134108_Content_17 = {
    Text = "Perché sei una persona importante per me."
  },
  AvgCommunicate_134108_Content_18 = {
    Text = "Bleah! Che razza di cosa strana stai dicendo all'improvviso? Che schifo, che schifo, mi si marciranno le orecchie!"
  },
  AvgCommunicate_134108_Content_19 = {
    Text = "Va bene, con riluttanza rimando la trasformazione di chiunque in progenie per ora, quindi portati via questi compiti!"
  },
  AvgCommunicate_134108_Content_2 = {
    Text = "Ahah, questa grande regina è finalmente completamente libera! La nobile Lupa Grigia darà inizio al Suo regno a Mythag."
  },
  AvgCommunicate_134108_Content_3 = {
    Text = "Tutta Mythag... no, tutta Kadath sarà piena della mia progenie."
  },
  AvgCommunicate_134108_Content_4 = {Text = "Davvero?"},
  AvgCommunicate_134108_Content_5 = {
    Text = "In origine, per celebrare la tua comprensione dell'Assioma Assoluto, ero pronta a fare un'eccezione e aiutarti a riordinare il dormitorio. L'ufficio affari accademici aveva persino accettato di esonerarti da una settimana di compiti."
  },
  AvgCommunicate_134108_Content_6 = {
    Text = "Ma dato che la nobile Lupa Grigia ha in programma di trasformare tutti nella Sua progenie, suppongo che niente di tutto ciò sia più necessario, giusto?"
  },
  AvgCommunicate_134108_Content_7 = {
    Text = "Aspetta, aspetta?!"
  },
  AvgCommunicate_134108_Content_9 = {
    Text = "No, non puoi, assolutamente no!"
  },
  AvgCommunicate_134108_Option_16 = {
    Text = "Perché sei la saggia Signora dei Labirinti."
  },
  AvgCommunicate_134108_Option_17 = {
    Text = "Perché sei una persona importante per me."
  },
  AvgCommunicate_134108_Option_4 = {Text = "Davvero."},
  AvgCommunicate_134109_Content_1 = {
    Text = "Meow Guardiano, ho visto un tunnel buio pesto..."
  },
  AvgCommunicate_134109_Content_10 = {
    Text = "Ma non ho percepito alcuna cattiveria da quegli occhietti. Al contrario, mi sono sentito completamente a mio agio, e ora sembra che io possa Fondermi in Uno con loro."
  },
  AvgCommunicate_134109_Content_11 = {
    Text = "Stai dicendo che ti sei fuso nelle anime dei topi?"
  },
  AvgCommunicate_134109_Content_12 = {
    Text = "Esatto, ho sentito me stesso frammentarsi in tantissimi, tantissimi pezzi in un istante, sgattaiolando attraverso tubi tortuosi, cianfrusaglie ammassate, sotto mobili bassi..."
  },
  AvgCommunicate_134109_Content_13 = {
    Text = "Stai pensando alla tua vecchia vita? Tranquillo, ormai è tutto passato."
  },
  AvgCommunicate_134109_Content_14 = {
    Text = "E poi—potevo facilmente rubare ogni genere di cose controllandoli!"
  },
  AvgCommunicate_134109_Content_15 = {
    Text = "Se avessi avuto questo tipo di abilità allora, avrei potuto svuotare persino la banca più grande del Distretto Ovest! Ahahah, ora sono praticamente il re di tutti i ladri del paese... no, del mondo intero! Nessuno può più fermarmi!"
  },
  AvgCommunicate_134109_Content_17 = {
    Text = "Ho la sensazione che neanche chiamare la polizia servirà questa volta. Meglio chiedere alla Sig.na Doll di Fabbricare un dispositivo di sorveglianza."
  },
  AvgCommunicate_134109_Content_2 = {
    Text = "Nessuna luce, nessun senso del tempo. Camminavo e camminavo lì tutta sola, come se avessi camminato per un'intera vita."
  },
  AvgCommunicate_134109_Content_3 = {
    Text = "Stai bene? Ti sei persa di nuovo nel vuoto?"
  },
  AvgCommunicate_134109_Content_4 = {
    Text = "Ho camminato per così, così tanto tempo, e alla fine ho visto qualcosa... come un filo di luce, un filo di fumo... e poi lentamente si è trasformato in Brown! I suoi piccoli occhi rotondi brillavano in quello spazio buio pesto."
  },
  AvgCommunicate_134109_Content_5 = {
    Text = "E poi c'erano innumerevoli paia degli stessi occhi, che mi circondavano, facendomi compagnia..."
  },
  AvgCommunicate_134109_Content_6 = {
    Text = "Uno sciame di topi?"
  },
  AvgCommunicate_134109_Content_7 = {
    Text = "Sì. Sentivo che erano più di semplici topi. Sembravano avere un'anima, proprio come i bambini che conoscevo per le strade. Competevamo, cooperavamo e condividevamo le stesse difficoltà, sgattaiolando per le strade proprio come topi."
  },
  AvgCommunicate_134109_Content_8 = {
    Text = "Forse sono le anime di tanti bambini che ti fanno compagnia."
  },
  AvgCommunicate_134109_Content_9 = {
    Text = "Eh? Ma devo ancora un cosciotto di pollo a Joe, due pagnotte al piccolo Jones, e ho rubato qualche biglia a Johnny... Non è che vengono a riscuotere i loro debiti, vero?!"
  },
  AvgCommunicate_134109_Option_11 = {
    Text = "I tuoi sensi si sono fusi con i loro?"
  },
  AvgCommunicate_134109_Option_13 = {
    Text = "Ormai è tutto passato"
  },
  AvgCommunicate_134109_Option_17 = {Text = "..."},
  AvgCommunicate_134109_Option_3 = {Text = "Stai bene?"},
  AvgCommunicate_134109_Option_6 = {
    Text = "Uno sciame di topi?"
  },
  AvgCommunicate_134109_Option_8 = {
    Text = "Forse erano proprio loro."
  },
  AvgCommunicate_134110_Content_1 = {
    Text = "Ah, ah... AAAAAH! Nero, tutto è nero!"
  },
  AvgCommunicate_134110_Content_10 = {
    Text = "Non... è successo? Il demone nero non è venuto?"
  },
  AvgCommunicate_134110_Content_11 = {
    Text = "Ma se viviamo dentro il ventre del demone, allora verrà un giorno in cui saremo Divorati dall'Oscurità. Non possiamo sfuggire, non possiamo sfuggire!"
  },
  AvgCommunicate_134110_Content_12 = {
    Text = "È troppo terrificante, troppo terrificante..."
  },
  AvgCommunicate_134110_Content_14 = {
    Text = "Non avere paura."
  },
  AvgCommunicate_134110_Content_15 = {
    Text = "Non riesco a capire cosa stai dicendo, ma se il mondo ha davvero un giorno destinato alla Sintomo: Distruzione, almeno io, e tutti a Mythag, combatteremo e resisteremo fino all'ultimo istante."
  },
  AvgCommunicate_134110_Content_16 = {
    Text = "Se la Dissoluzione è davvero una Fine inevitabile, ti terrò nell'ultimo luogo in cui resta la luce, e resterò al tuo fianco, fino alla Fine del mondo."
  },
  AvgCommunicate_134110_Content_17 = {
    Text = "...Capisco."
  },
  AvgCommunicate_134110_Content_18 = {
    Text = "Non ti estinguerai mai. Credo in te."
  },
  AvgCommunicate_134110_Content_19 = {
    Text = "Grazie, Custode."
  },
  AvgCommunicate_134110_Content_2 = {
    Text = "Il mondo intero è nero! Solo Illusione, Solo Illusione!"
  },
  AvgCommunicate_134110_Content_3 = {
    Text = "Winkle! Svegliati! Di nuovo incubi?!"
  },
  AvgCommunicate_134110_Content_4 = {
    Text = "No, no, più tecniche @2 di altre persone, conoscenza, anime più forti, niente funziona, niente! Non riesco ancora a migrare di nuovo!"
  },
  AvgCommunicate_134110_Content_5 = {
    Text = "Dopo essere diventato più forte, è ancora più facile per l'Oscurità vedermi. Sono troppo visibile. L'Oscurità mi raggiungerà..."
  },
  AvgCommunicate_134110_Content_6 = {
    Text = "Non voglio più diventare forte. Voglio scappare, fuggire il più lontano possibile. Ma se il mondo intero è nero, e tutta la luce è falsa, allora dove posso andare..."
  },
  AvgCommunicate_134110_Content_7 = {
    Text = "Perché, perché questo Potere mi fa vedere queste cose? Non voglio saperlo!"
  },
  AvgCommunicate_134110_Content_8 = {
    Text = "Morirò, morirò, morirò di nuovo. Devo Viverlo un'altra volta? Non voglio, non voglio..."
  },
  AvgCommunicate_134110_Content_9 = {
    Text = "Svegliati, Winkle! Il mondo non è diventato nero. Io sono ancora qui! Tutti sono ancora qui!"
  },
  AvgCommunicate_134110_Option_14 = {
    Text = "Non avere paura."
  },
  AvgCommunicate_134110_Option_3 = {Text = "Winkle?!"},
  AvgCommunicate_134110_Option_9 = {Text = "Winkle!"},
  AvgCommunicate_134111_Content_1 = {
    Text = "Le mie ali... sono diventate ancora più grandi."
  },
  AvgCommunicate_134111_Content_10 = {
    Text = "Castor, lo so che sei straordinario, e anche le tue ali sono straordinarie. Come dire..."
  },
  AvgCommunicate_134111_Content_12 = {
    Text = "Lascia stare, ho capito. Detto questo, anche la tua capacità di carico deve essere migliorata, giusto?"
  },
  AvgCommunicate_134111_Content_13 = {
    Text = "Hmm, a una stima approssimativa, il peso di una dozzina di persone non dovrebbe essere un problema."
  },
  AvgCommunicate_134111_Content_14 = {
    Text = "Tuttavia, le mie braccia non sembrano in grado di trasportare così tante persone tutte insieme."
  },
  AvgCommunicate_134111_Content_15 = {
    Text = "Ho un suggerimento."
  },
  AvgCommunicate_134111_Content_16 = {
    Text = "Che ne dici di questo: vai ad allenarti nella forza delle braccia, e poi avremo un veicolo aereo che potrà scendere dal cielo ogni volta che ne avremo bisogno!"
  },
  AvgCommunicate_134111_Content_17 = {
    Text = "Forza delle braccia? Cosa c'entra con un... veicolo aereo? Benefattore, perdona la mia ignoranza, ma non capisco bene."
  },
  AvgCommunicate_134111_Content_18 = {
    Text = "Questa è una missione importante."
  },
  AvgCommunicate_134111_Content_19 = {
    Text = "Finché la tua capacità di carico regge, la mobilità e la velocità di evacuazione nelle missioni sul campo miglioreranno enormemente. Castor, sei disposto ad accettare questa missione?"
  },
  AvgCommunicate_134111_Content_2 = {
    Text = "I credenti hanno davvero cantato lodi di ali che oscurano il cielo, ma so che ciò che possedevo un tempo non era altro che un comune paio d'ali."
  },
  AvgCommunicate_134111_Content_20 = {
    Text = "Certamente! Sarà un onore, Benefattore."
  },
  AvgCommunicate_134111_Content_21 = {
    Text = "Allora è deciso. Vado subito a cercare Erica per farmi fare un cesto da trasporto su misura!"
  },
  AvgCommunicate_134111_Content_22 = {
    Text = "Non devi mai più pensare di dare le tue ali a qualcun altro, non importa chi sia."
  },
  AvgCommunicate_134111_Content_3 = {
    Text = "Voi creature alate non avete idea di quanto sia comodo avere le ali... Che invidia..."
  },
  AvgCommunicate_134111_Content_4 = {
    Text = "Se il mio salvatore lo desidera, ricordo vagamente che la Chiesa della luce del tempio aveva metodi per trapiantare le ali. Posso darti volentieri le mie ali. Non ho paura del dolore."
  },
  AvgCommunicate_134111_Content_6 = {
    Text = "No no no no, non sarà necessario. Stanno meglio su di te."
  },
  AvgCommunicate_134111_Content_7 = {
    Text = "Ah, non vuoi le mie ali, salvatore? Ormai sono diventate piuttosto impressionanti."
  },
  AvgCommunicate_134111_Content_8 = {
    Text = "Dopo aver compreso le leggi, ogni sensazione del vento che scorre tra le fessure delle mie piume, ogni forza delle correnti d'aria vorticose... tutto è sotto il mio controllo."
  },
  AvgCommunicate_134111_Content_9 = {
    Text = "Non è questione di essere impressionanti o meno."
  },
  AvgCommunicate_134111_Option_15 = {
    Text = "Ho un suggerimento."
  },
  AvgCommunicate_134111_Option_18 = {
    Text = "Questa è una missione importante."
  },
  AvgCommunicate_134111_Option_3 = {
    Text = "Tu non capisci."
  },
  AvgCommunicate_134111_Option_9 = {
    Text = "Non è questione di essere impressionanti o meno."
  },
  AvgCommunicate_134112_Content_1 = {
    Text = "Oh cielo, quindi è così che appare il mondo dalla tua prospettiva."
  },
  AvgCommunicate_134112_Content_10 = {
    Text = "Gli umani hanno davvero così tanti tipi di Espressioni? A quanto pare io potrei definirmi una faccia di pietra."
  },
  AvgCommunicate_134112_Content_11 = {
    Text = "Non solo, ho anche imparato a ridere piangendo, essere arrabbiata piangendo, essere arrabbiata ridendo, provare paura ridendo..."
  },
  AvgCommunicate_134112_Content_12 = {
    Text = "Basta combinare ogni Espressione insieme e diventa una nuova emozione. Di questo passo, non passerà molto prima che Casiah abbia padroneggiato completamente le emozioni umane!"
  },
  AvgCommunicate_134112_Content_13 = {
    Text = "Vuoi vedere? Vuoi vedere? Persino l'\"amore\", quel mistero irrisolto dell'umanità... Casiah ora può interpretarlo per te!"
  },
  AvgCommunicate_134112_Content_15 = {
    Text = "Non solo non hai padroneggiato niente, ma il modo in cui appari adesso è ancora meno umano di prima! Che paura, smettila subito!!!"
  },
  AvgCommunicate_134112_Content_2 = {Text = "Cosa?"},
  AvgCommunicate_134112_Content_3 = {
    Text = "Non credo che il mondo visto attraverso i miei occhi sia qualcosa di speciale, ma tu cosa hai visto?"
  },
  AvgCommunicate_134112_Content_4 = {
    Text = "Casiah ha visto... innumerevoli piccoli esseri sovrapposti l'uno all'altro, con innumerevoli istanti tutti nella sua \"vista\" contemporaneamente."
  },
  AvgCommunicate_134112_Content_5 = {
    Text = "In un singolo breve istante, innumerevoli persone piangevano, mentre innumerevoli altre ridevano, ardevano di Rabbia, tremavano di Paura..."
  },
  AvgCommunicate_134112_Content_6 = {
    Text = "Alcune persone avevano espressioni molto Placide. Quell'emozione, la Registro, dovrebbe chiamarsi felicità? Quindi le emozioni umane hanno così tante, tante sottili differenze..."
  },
  AvgCommunicate_134112_Content_7 = {
    Text = "Riesci già a percepire le emozioni umane?!"
  },
  AvgCommunicate_134112_Content_8 = {
    Text = "No, Casiah può solo vedere le loro espressioni, i loro movimenti e i colori delle loro emozioni."
  },
  AvgCommunicate_134112_Content_9 = {
    Text = "Ma Casiah è bravissima a imitare! Dopo aver visto tutti i diversi volti sorridenti e piangenti dell'intero mondo in una volta sola, Casiah ora può eseguire per te 21 tipi di sorrisi e 36 tipi di Espressioni di pianto!"
  },
  AvgCommunicate_134112_Option_10 = {
    Text = "Così tante?"
  },
  AvgCommunicate_134112_Option_15 = {
    Text = "Non hai padroneggiato proprio niente!"
  },
  AvgCommunicate_134112_Option_2 = {Text = "Cosa?"},
  AvgCommunicate_134112_Option_7 = {
    Text = "Riesci a percepire le emozioni umane adesso?!"
  },
  AvgCommunicate_134113_Content_1 = {
    Text = "L'accordo con te è stata la decisione più giusta della mia carriera di Mercante."
  },
  AvgCommunicate_134113_Content_10 = {
    Text = "Aspetta, quelli dopo sono sempre più sbagliati!"
  },
  AvgCommunicate_134113_Content_11 = {
    Text = "Inoltre, qualcosa che sembra così prezioso deve essere costoso, giusto? Qual è il prezzo dello scambio?"
  },
  AvgCommunicate_134113_Content_12 = {
    Text = "Hmm... Dopotutto, è grazie a te che ho ottenuto un potere più comodo per viaggiare."
  },
  AvgCommunicate_134113_Content_13 = {
    Text = "Ti farò uno sconto speciale. Per quanto riguarda il prezzo, vieni nel mio negozio per discutere i dettagli. Ti aspetterò."
  },
  AvgCommunicate_134113_Content_2 = {
    Text = "Pianta un seme e aspetta che cresca fino a diventare un fiore, o un albero maestoso."
  },
  AvgCommunicate_134113_Content_3 = {
    Text = "Raramente faccio affari che richiedono un'attesa così lunga per i ritorni. Fortunatamente, allo stato attuale delle cose, è già un Guadagno Certo."
  },
  AvgCommunicate_134113_Content_4 = {
    Text = "Hehe, grazie per tutto l'aiuto in questo lungo periodo. Sono felice di non averti deluso."
  },
  AvgCommunicate_134113_Content_5 = {
    Text = "Le acque del Mare dei Mille Volti si sono fatte ancora più profonde. È passato molto tempo, e le teste laggiù sentono molto la tua mancanza. Ti piacerebbe fare Una Nuova Visita?"
  },
  AvgCommunicate_134113_Content_6 = {
    Text = "Ehm, io... Preferirei di no. Credo che a volte la lontananza rafforzi l'affetto."
  },
  AvgCommunicate_134113_Content_7 = {
    Text = "Hehe, hai sicuramente il Talento di un Mercante quando si tratta di eloquenza."
  },
  AvgCommunicate_134113_Content_8 = {
    Text = "A proposito, il mio negozietto ha ricevuto di recente alcuni nuovi articoli. Piuttosto rari, e li ho conservati tutti per te."
  },
  AvgCommunicate_134113_Content_9 = {
    Text = "C'è un globo che permette di raggiungere la Risonanza con il proprio Potere di Genesi, uno Sguardo del Riflesso che permette di scrutare visioni di un altro mondo attraverso il Voyeur, e un collare che fa obbedire docilmente le persone."
  },
  AvgCommunicate_134113_Option_10 = {
    Text = "Questo sta diventando sempre più sbagliato!"
  },
  AvgCommunicate_134113_Option_4 = {Text = "Eheh."},
  AvgCommunicate_134113_Option_6 = {
    Text = "Preferirei di no."
  },
  AvgCommunicate_134114_Content_1 = {
    Text = "Io… sono diventata fuoco."
  },
  AvgCommunicate_134114_Content_10 = {
    Text = "C'è ancora così tanta bellezza nel mondo che merita di essere rappresentata. Credo di aver già trovato più Intuizione per la creazione."
  },
  AvgCommunicate_134114_Content_11 = {
    Text = "D'ora in poi, diventerò fuoco, portando un ritmo più puro e naturale."
  },
  AvgCommunicate_134114_Content_2 = {
    Text = "Fuoco ciano, danzante. Bruciare, Purificare, Danzare."
  },
  AvgCommunicate_134114_Content_3 = {
    Text = "I miei peccati e quelli degli altri Bruceranno tutti nel fuoco, e ogni cosa diventerà pura."
  },
  AvgCommunicate_134114_Content_4 = {
    Text = "Liz… stai ancora ricordando quel fuoco di allora?"
  },
  AvgCommunicate_134114_Content_5 = {
    Text = "Il mio odio è stato lentamente Bruciato nel fuoco, ma non ho il diritto di perdonare quel fuoco per conto degli altri."
  },
  AvgCommunicate_134114_Content_6 = {
    Text = "Non me ne sono mai pentita, né fuggirò dai volti in quelle fiamme."
  },
  AvgCommunicate_134114_Content_7 = {
    Text = "Dopo essere arrivata qui, mi hai dato una nuova vita. Non ho più bisogno di un grande palcoscenico, ma se tu sei il Pubblico, credo che proverei ancora felicità nel Danzare."
  },
  AvgCommunicate_134114_Content_8 = {
    Text = "Lascia che sia la tua fan numero uno e continui a guardarti danzare!"
  },
  AvgCommunicate_134114_Content_9 = {
    Text = "Mm, grazie. Dopo aver smesso di danzare, spesso restavo seduta accanto alla finestra senza far nulla. Vedevo il Vento, i fiori, gli alberi, gli uccelli e i Gatti—così tante creature viventi e tutta la natura traboccante del ritmo della Danza."
  },
  AvgCommunicate_134114_Option_4 = {Text = "Liz…"},
  AvgCommunicate_134114_Option_8 = {
    Text = "Continuerò a guardarti danzare!"
  },
  AvgCommunicate_134115_Content_1 = {
    Text = "Io... Riesco a vederlo..."
  },
  AvgCommunicate_134115_Content_10 = {
    Text = "È davvero edificante!"
  },
  AvgCommunicate_134115_Content_11 = {
    Text = "Sono felice che tu riesca a vedere tutto questo, Miryam!"
  },
  AvgCommunicate_134115_Content_12 = {
    Text = "Naturalmente, continuerò a dedicare ogni cosa alla Discesa del Regno Divino."
  },
  AvgCommunicate_134115_Content_13 = {
    Text = "Ma ora capisco… Il Regno Divino non è semplicemente due stati di completo Avvento o completa annientamento."
  },
  AvgCommunicate_134115_Content_14 = {
    Text = "Mentre preghiamo per la Discesa del Regno Divino, una parte del Regno Divino è già giunta al nostro fianco."
  },
  AvgCommunicate_134115_Content_15 = {
    Text = "Grazie, Custode. Mi hai donato nuovo Potere."
  },
  AvgCommunicate_134115_Content_16 = {
    Text = "Ciò che ho visto è la Prova dell'Essere dell'esistenza immortale del Regno Divino!"
  },
  AvgCommunicate_134115_Content_17 = {
    Text = "Il processo mi è sembrato un po' strano… ma alla fine il risultato è stato discreto, credo."
  },
  AvgCommunicate_134115_Content_2 = {Text = "Cosa vedi?"},
  AvgCommunicate_134115_Content_3 = {
    Text = "Il Regno Divino... Sì... I contorni del Regno Divino!"
  },
  AvgCommunicate_134115_Content_4 = {
    Text = "Non è mai stato così chiaro... Non è mai stato così... ordinario..."
  },
  AvgCommunicate_134115_Content_5 = {
    Text = "Miryam... Sei sicura che quelle siano parole tue..."
  },
  AvgCommunicate_134115_Content_6 = {
    Text = "Vedo la mia patria. Vedo quel futuro immortale, imperituro."
  },
  AvgCommunicate_134115_Content_7 = {
    Text = "Ma più di questo... vedo il presente."
  },
  AvgCommunicate_134115_Content_8 = {
    Text = "Il mio Signore, i miei consanguinei, il mio Amico del Cuore, i miei fedeli…"
  },
  AvgCommunicate_134115_Content_9 = {
    Text = "Il Regno Divino è sempre stato al mio fianco… Tutto ciò che ho è sempre stato parte del Regno Divino…"
  },
  AvgCommunicate_134115_Option_10 = {
    Text = "È davvero edificante!"
  },
  AvgCommunicate_134115_Option_17 = {
    Text = "Suppongo che vada bene così…"
  },
  AvgCommunicate_134115_Option_2 = {Text = "Cosa?"},
  AvgCommunicate_134115_Option_5 = {Text = "Ordinario?"},
  AvgCommunicate_134116_Content_1 = {
    Text = "Oh cielo, non avrei mai immaginato che spingere il mio Potere al suo limite estremo sarebbe stato così."
  },
  AvgCommunicate_134116_Content_10 = {Text = "Ehm..."},
  AvgCommunicate_134116_Content_11 = {
    Text = "Hmm, fammi vedere... In questo momento stai pensando: \"Onestamente non so quale dei due sia più terrificante.\" Ho indovinato?"
  },
  AvgCommunicate_134116_Content_12 = {
    Text = "Cosa?!! Non avevi detto che non puoi leggere la mia mente?"
  },
  AvgCommunicate_134116_Content_13 = {
    Text = "Che reazione adorabile. Non ho affatto letto la tua mente."
  },
  AvgCommunicate_134116_Content_14 = {
    Text = "È solo che sei così completamente indifeso con me—sei un tantino troppo facile da leggere."
  },
  AvgCommunicate_134116_Content_15 = {
    Text = "Vuoi tenere al sicuro i piccoli segreti nel tuo cuore? Allora impegnati un po' di più quando chiacchieri con me."
  },
  AvgCommunicate_134116_Content_2 = {
    Text = "Che sensazione è? Ho un brutto presentimento..."
  },
  AvgCommunicate_134116_Content_3 = {
    Text = "Come dire... In pratica, quelle menti mediocri sono come diari aperti per me—noiosi e svelati a colpo d'occhio. È piuttosto tedioso, davvero."
  },
  AvgCommunicate_134116_Content_4 = {
    Text = "Cosa?! Hai già padroneggiato il Sussurro della Mente?"
  },
  AvgCommunicate_134116_Content_5 = {
    Text = "Non è così drammatico. Dopotutto, ci sono ancora parecchie persone in questo mondo con spiriti resilienti e personalità ostinate che cercano di avvolgere il proprio io interiore in strato dopo strato, rifiutando di lasciarsi leggere facilmente."
  },
  AvgCommunicate_134116_Content_6 = {
    Text = "E poi ci sono esseri come te, che sono sempre stati enigmatici e imperscrutabili."
  },
  AvgCommunicate_134116_Content_7 = {
    Text = "Non c'è bisogno di essere nervosi. Ottenere le risposte di un esame in anticipo è altrettanto noioso quanto scoprire il finale di una storia in anticipo, o scoprire il colpevole di un caso di omicidio troppo presto."
  },
  AvgCommunicate_134116_Content_8 = {
    Text = "Mi godo immensamente il processo di guidare, speculare e sbucciare i Bozzoli avvolti attorno al cuore, filo dopo filo."
  },
  AvgCommunicate_134116_Content_9 = {
    Text = "Senza questi giochi di botta e risposta, in cosa sarei diversa da quei ciarlatani che fanno diagnosi grossolane e semplicemente asportano un pezzo del cervello di qualcuno?"
  },
  AvgCommunicate_134116_Option_10 = {Text = "Ehm..."},
  AvgCommunicate_134116_Option_12 = {Text = "?!!"},
  AvgCommunicate_134116_Option_2 = {
    Text = "Che sensazione è?"
  },
  AvgCommunicate_134116_Option_4 = {Text = "Cosa?!"},
  AvgCommunicate_134117_Content_1 = {
    Text = "Le rime dei Versi si sono fatte ancora più persistenti."
  },
  AvgCommunicate_134117_Content_10 = {
    Text = "Posso portarti nel mondo della poesia, per vagare insieme."
  },
  AvgCommunicate_134117_Content_12 = {
    Text = "È quasi incredibile quanto la magia delle parole!"
  },
  AvgCommunicate_134117_Content_13 = {
    Text = "Allora voglio sperimentare un Miraggio di pensionamento, ricchezza e cibo gourmet illimitato. Puoi portarmi lì?"
  },
  AvgCommunicate_134117_Content_14 = {
    Text = "Quello... dovrebbe essere, sì, è possibile! Dammi un momento, per favore, devo pensarci attentamente..."
  },
  AvgCommunicate_134117_Content_2 = {
    Text = "Ora riesco a vedere le emozioni che emergono in quei ritmi recitati, il Potere riflesso dietro quelle Immagini."
  },
  AvgCommunicate_134117_Content_3 = {
    Text = "Non capisco del tutto, ma sembra uno spettacolo meraviglioso."
  },
  AvgCommunicate_134117_Content_4 = {
    Text = "Sì, la poesia è una Chiave per esplorare la bellezza. La poesia può rivelare le leggi universali del mondo e rispecchiare la vita così com'è realmente."
  },
  AvgCommunicate_134117_Content_5 = {
    Text = "Nella poesia troviamo noi stessi, troviamo la saggezza della Storia e della filosofia, troviamo un santuario puro per lo spirito."
  },
  AvgCommunicate_134117_Content_6 = {
    Text = "Ah, mi sono lasciata trasportare parlando da sola di nuovo. Mi dispiace tanto..."
  },
  AvgCommunicate_134117_Content_7 = {
    Text = "Va bene. Adoro quanto appari appassionata quando parli di poesia. È molto affascinante!"
  },
  AvgCommunicate_134117_Content_8 = {
    Text = "G-grazie, Custode. Ad ogni modo, ora posso usare i Versi per prendere in prestito ancora più Potere da quel mondo, creando un Miraggio poetico completo."
  },
  AvgCommunicate_134117_Content_9 = {
    Text = "Che tu desideri goderti la tranquillità, la passione o la malinconia, che tu voglia inseguire il profumo dei fiori, le correnti dell'oceano o le nuvole."
  },
  AvgCommunicate_134117_Option_12 = {
    Text = "È quasi come magia delle parole."
  },
  AvgCommunicate_134117_Option_3 = {
    Text = "Sembra bellissimo."
  },
  AvgCommunicate_134117_Option_7 = {
    Text = "È gestibile."
  },
  AvgCommunicate_134118_Content_1 = {
    Text = "Hai davvero offerto qualcosa di così prezioso alla sottoscritta, tu..."
  },
  AvgCommunicate_134118_Content_10 = {
    Text = "Ma riesci davvero a mangiarne così tante? Uno chef si è lamentato che hai fatto piazza pulita di tutte le scorte di burro e formaggio, e ho dovuto pagare di tasca mia per rifornire la mensa."
  },
  AvgCommunicate_134118_Content_11 = {
    Text = "Oh? Chi è che spettegola alle mie spalle? Che non mi capiti tra le mani!"
  },
  AvgCommunicate_134118_Content_12 = {
    Text = "Quanto alle torte, fatti gli affari tuoi sulle questioni di una signorina! Quante ne faccio, tante ne mangio!"
  },
  AvgCommunicate_134118_Content_13 = {
    Text = "E se non riesco a finirle, verrai a mangiarle con me!"
  },
  AvgCommunicate_134118_Content_14 = {
    Text = "I—Devo mangiare anch'io? Morirò di indigestione e ingrasserò nel fiore dei miei anni!"
  },
  AvgCommunicate_134118_Content_15 = {
    Text = "Smettila di lamentarti. Dopo tutto quel parlare, non ho ancora menzionato la tua ricompensa. Questa signora sarà così magnanima da metterti da parte una porzione di ogni torta che preparerà d'ora in poi."
  },
  AvgCommunicate_134118_Content_16 = {
    Text = "Sii grato! Questi sono capolavori di una geniale pasticcera che il denaro non può comprare!"
  },
  AvgCommunicate_134118_Content_17 = {
    Text = "Quindi... alla fine questa pasticceria è solo autoproduzione e autoconsumo!"
  },
  AvgCommunicate_134118_Content_2 = {
    Text = "Hmph, niente male."
  },
  AvgCommunicate_134118_Content_3 = {
    Text = "Ora questa signorina può far girare dieci—no, cento Navigatori come trottole tutti insieme! Non ho più bisogno che qualcuno mi salvi!"
  },
  AvgCommunicate_134118_Content_4 = {
    Text = "La grande signorina è potente!"
  },
  AvgCommunicate_134118_Content_5 = {
    Text = "Anche se la mia vita ora non richiede più preoccupazioni costanti, quando si tratta di Potere, averne di più dà sempre un maggior senso di sicurezza."
  },
  AvgCommunicate_134118_Content_6 = {
    Text = "Chi ha i pugni più grossi non ci rimette mai!"
  },
  AvgCommunicate_134118_Content_7 = {
    Text = "Ma usare un Potere così incredibile solo per lavorare al Mythag è uno spreco... Ho un'idea!"
  },
  AvgCommunicate_134118_Content_8 = {
    Text = "Visto che così tanti tentacoli possono lavorare indipendentemente, tanto vale che apra la mia pasticceria. Con me sola che ricopro otto ruoli, non significherebbe torte illimitate per sempre!"
  },
  AvgCommunicate_134118_Content_9 = {
    Text = "Si possono usare così?"
  },
  AvgCommunicate_134118_Option_14 = {
    Text = "Devo mangiare anch'io?"
  },
  AvgCommunicate_134118_Option_17 = {Text = "Quindi..."},
  AvgCommunicate_134118_Option_4 = {
    Text = "Murphy è potente!"
  },
  AvgCommunicate_134118_Option_9 = {
    Text = "Si possono usare così?"
  },
  AvgCommunicate_134119_Content_1 = {
    Text = "Hahahaha... Ahahahaha!"
  },
  AvgCommunicate_134119_Content_10 = {
    Text = "Di fronte a una forza assoluta, la conquista è solo una lunga partita."
  },
  AvgCommunicate_134119_Content_11 = {
    Text = "Se ti fa felice..."
  },
  AvgCommunicate_134119_Content_12 = {
    Text = "Il tempo ti porterà notizie del mio trionfo. Quando quel giorno arriverà, in quanto principale artefice del mio nuovo regno, ti riserverò la terra più fertile come tuo feudo."
  },
  AvgCommunicate_134119_Content_13 = {
    Text = "Oppure... preferiresti questa polverosa città di Londinium?"
  },
  AvgCommunicate_134119_Content_2 = {
    Text = "Non è che tutto quel Potere ti ha fatto impazzire e hai perso la ragione all'improvviso, vero?"
  },
  AvgCommunicate_134119_Content_3 = {
    Text = "Hmph hmph, in quanto mia più grande Dedizione di Potere, posso perdonare la tua piccola impudenza."
  },
  AvgCommunicate_134119_Content_4 = {
    Text = "Ah… il momento che attendevo da tanto tempo, questo sapore dolce e familiare, questa sensazione di Sangue che ribolle nelle vene!"
  },
  AvgCommunicate_134119_Content_5 = {
    Text = "Ora posso sollevare iceberg senza sforzo e squarciare le profondità dell'oceano."
  },
  AvgCommunicate_134119_Content_6 = {
    Text = "Nessun Boss di qualsiasi tribù, nessun guerriero più potente dei Navigatori resisterebbe un solo incontro contro di me, e quella Donna folle non può più sopprimermi."
  },
  AvgCommunicate_134119_Content_7 = {
    Text = "Presto conquisterò i mari, e poi conquisterò tutte le terre! Hahahaha!"
  },
  AvgCommunicate_134119_Content_8 = {
    Text = "...La fiducia in sé è una buona cosa, ma non essere così narcisista! Questo è già al livello di Sintomo: Delirio!"
  },
  AvgCommunicate_134119_Content_9 = {
    Text = "Non sai nulla del Potere di una gigante, piccolo."
  },
  AvgCommunicate_134119_Option_11 = {
    Text = "Se ti fa felice..."
  },
  AvgCommunicate_134119_Option_2 = {
    Text = "Hai perso la ragione?"
  },
  AvgCommunicate_134119_Option_8 = {Text = "..."},
  AvgCommunicate_134120_Content_1 = {
    Text = "La mia voce... è diversa da prima."
  },
  AvgCommunicate_134120_Content_10 = {
    Text = "Mm, lo farò!"
  },
  AvgCommunicate_134120_Content_11 = {
    Text = "A proposito, Custode, grazie al tuo incoraggiamento di prima, ho accettato la collaborazione con la casa discografica. Il primo album è stato ufficialmente pubblicato e a quanto pare sta vendendo piuttosto bene."
  },
  AvgCommunicate_134120_Content_12 = {
    Text = "Che bella notizia! Congratulazioni! Quante copie vendute?"
  },
  AvgCommunicate_134120_Content_13 = {
    Text = "Credo... circa centomila copie. Ma non ho davvero bisogno della valuta di questo pianeta. Dato che non c'è altro modo per ripagarti, perché non ti do i guadagni dell'album?"
  },
  AvgCommunicate_134120_Content_14 = {Text = "Evviva!!!"},
  AvgCommunicate_134120_Content_2 = {
    Text = "Custode, dopo che mi hai aiutato a comprendere l'Assioma Assoluto, la mia voce sembra aver raggiunto una meravigliosa Risonanza con l'Etere."
  },
  AvgCommunicate_134120_Content_3 = {
    Text = "Sembra che tu sia diventata più forte. Anche Faint ne sarà sicuramente felice!"
  },
  AvgCommunicate_134120_Content_4 = {
    Text = "Come potrò mai ripagarti, Custode? Poter avere una Riunione con mia sorella era già una felicità che la me del passato non avrebbe mai potuto sognare, e tu mi hai donato un tesoro così prezioso in aggiunta."
  },
  AvgCommunicate_134120_Content_5 = {
    Text = "In questo momento non ho nulla a mio nome e non sono più una star adorata dai fan. L'unico modo in cui posso ripagarti è... per favore, lascia che canti una canzone per te."
  },
  AvgCommunicate_134120_Content_6 = {
    Text = "Tintura, hai già trovato il tuo Cammino. Se sei disposta a esaudire il mio desiderio..."
  },
  AvgCommunicate_134120_Content_7 = {
    Text = "Per favore, canta liberamente, per te stessa e per me."
  },
  AvgCommunicate_134120_Content_8 = {
    Text = "Non per compiacere qualcuno, non per esibirti secondo le richieste di altri. Solo per la tua felicità."
  },
  AvgCommunicate_134120_Content_9 = {
    Text = "La mia... felicità."
  },
  AvgCommunicate_134120_Option_12 = {
    Text = "Che bella notizia."
  },
  AvgCommunicate_134120_Option_14 = {Text = "?!!"},
  AvgCommunicate_134120_Option_3 = {Text = "Che bello."},
  AvgCommunicate_134120_Option_6 = {
    Text = "Hai mai pensato di"
  },
  AvgCommunicate_134180_Content_1 = {
    Text = "Il Vento gonfia le vele, e gli uccelli volano in formazione al nostro fianco..."
  },
  AvgCommunicate_134180_Content_10 = {
    Text = "Voglio solcare i mari per sempre, insieme a te, al Capitano, a tutti quanti."
  },
  AvgCommunicate_134180_Content_11 = {
    Text = "Vivere insieme giornate di sole e di pioggia, approdare in ogni tipo di porto, attraccare in paesi diversi."
  },
  AvgCommunicate_134180_Content_12 = {
    Text = "Pescare insieme, grigliare il pesce insieme... Oh, e potremmo raschiare le cozze dallo scafo e stufarle nel vino rosso."
  },
  AvgCommunicate_134180_Content_13 = {
    Text = "Partiamo per la prossima vacanza."
  },
  AvgCommunicate_134180_Content_14 = {
    Text = "Ci ho pensato a lungo. Navigare... è quando sono più felice."
  },
  AvgCommunicate_134180_Content_15 = {
    Text = "Guiderò tutti lontano da ogni tempesta, così potremo continuare a navigare felici insieme."
  },
  AvgCommunicate_134180_Content_16 = {
    Text = "Sembra davvero meraviglioso, ma se navigassimo senza sosta per sempre, tutti tranne i Risvegliatori del Reame del Mare Profondo avrebbero il mal di mare!"
  },
  AvgCommunicate_134180_Content_2 = {
    Text = "Vedo la prua fendere le onde, sento i Marinai cantare le loro canzoni di mare, percepisco i sussurri del Vento e della pioggia."
  },
  AvgCommunicate_134180_Content_3 = {
    Text = "Ora riesco a vederlo più chiaramente: la rotta che conduce ad acque limpide e placide."
  },
  AvgCommunicate_134180_Content_4 = {
    Text = "Congratulazioni! Celeste!"
  },
  AvgCommunicate_134180_Content_5 = {
    Text = "Ora, forse, potrò davvero esaudire i desideri di tutti e guidare le navi sotto la mia protezione in sicurezza verso l'altra sponda."
  },
  AvgCommunicate_134180_Content_6 = {
    Text = "Non deluderò più nessuno."
  },
  AvgCommunicate_134180_Content_7 = {
    Text = "E il tuo desiderio? Hai deciso qual è il tuo desiderio?"
  },
  AvgCommunicate_134180_Content_8 = {
    Text = "Il mio desiderio..."
  },
  AvgCommunicate_134180_Content_9 = {
    Text = "L'ho già deciso."
  },
  AvgCommunicate_134180_Option_13 = {
    Text = "Partiamo per la prossima vacanza."
  },
  AvgCommunicate_134180_Option_16 = {
    Text = "Sembra meraviglioso."
  },
  AvgCommunicate_134180_Option_4 = {
    Text = "Congratulazioni"
  },
  AvgCommunicate_134180_Option_7 = {Text = "E tu?"},
  AvgCommunicate_134181_Content_1 = {
    Text = "Ah… Il Richiamo degli Abissi, così dolce, così caldo."
  },
  AvgCommunicate_134181_Content_10 = {
    Text = "Il comportamento brutale di Rogers ti ha lasciato un'ombra così profonda, o pensi che io sia un'artista così sterile e pigra?"
  },
  AvgCommunicate_134181_Content_11 = {
    Text = "Affinare la propria arte non ammette scorciatoie. Le mie sculture sono naturalmente scolpite dalle mie stesse mani, colpo di scalpello dopo colpo di scalpello."
  },
  AvgCommunicate_134181_Content_12 = {
    Text = "Stai tranquillo, non userò nemmeno un singolo capello tuo."
  },
  AvgCommunicate_134181_Content_13 = {
    Text = "Ahaha... Forse è perché le tue abilità di scultura sono troppo raffinate. Ogni volta che vedo le tue opere, ho l'illusione di guardare una persona in carne e ossa."
  },
  AvgCommunicate_134181_Content_14 = {
    Text = "Hmm... Beh, ora che il mio Potere ha raggiunto il suo apice, forse potrei davvero creare una scultura che prende vita."
  },
  AvgCommunicate_134181_Content_15 = {
    Text = "Nel cuore della notte, oltre il tuo campo visivo, gli occhi della scultura si girerebbero lentamente, e gli angoli della sua bocca si incurverebbero appena appena..."
  },
  AvgCommunicate_134181_Content_16 = {
    Text = "Una volta terminata la mia ultima opera, ne metterò una proprio accanto al tuo letto per vegliare su di te al posto mio. Che ne dici?"
  },
  AvgCommunicate_134181_Content_17 = {
    Text = "Non oserei mai più dormire per il resto della mia vita!!!"
  },
  AvgCommunicate_134181_Content_18 = {
    Text = "Ti stavo solo prendendo in giro."
  },
  AvgCommunicate_134181_Content_19 = {
    Text = "Sembra che tu sia davvero terrorizzato da storie di fantasmi così semplici. Che adorabile."
  },
  AvgCommunicate_134181_Content_2 = {
    Text = "Sicuramente l'hai sentito anche tu?"
  },
  AvgCommunicate_134181_Content_3 = {
    Text = "Ci sta invitando, ci stanno aspettando… per viaggiare insieme verso il palazzo bianco puro sotto il mare."
  },
  AvgCommunicate_134181_Content_4 = {
    Text = "Chi? Temo che le mie orecchie siano diventate sorde—non ho sentito nulla."
  },
  AvgCommunicate_134181_Content_5 = {
    Text = "Allora questo dev'essere un Bacio della Musa destinato solo a me. La bellezza degli Abissi si è ormai fusa con la mia stessa anima."
  },
  AvgCommunicate_134181_Content_6 = {
    Text = "Mi porti sempre più Intuizione per le mie creazioni. Ogni giorno che passa ti apprezzo di più."
  },
  AvgCommunicate_134181_Content_7 = {
    Text = "Prenderesti in considerazione l'idea di diventare il mio assistente a lungo termine? Non dovresti fare nulla—solo venire nel mio studio ogni giorno, sederti un po', bere una tazza di tè e chiacchierare."
  },
  AvgCommunicate_134181_Content_8 = {
    Text = "Per quanto sia lusingato dal tuo affetto... mi sveglierò una mattina ritrovandomi trasformato in una scultura di pietra?"
  },
  AvgCommunicate_134181_Content_9 = {
    Text = "Eheh, è davvero così che mi vedi?"
  },
  AvgCommunicate_134181_Option_13 = {
    Text = "La tua maestria è incredibile."
  },
  AvgCommunicate_134181_Option_17 = {
    Text = "No, ti prego!!!"
  },
  AvgCommunicate_134181_Option_4 = {Text = "Io no."},
  AvgCommunicate_134181_Option_8 = {
    Text = "Verrò trasformato in una scultura?"
  },
  AvgCommunicate_134187_Content_1 = {
    Text = "Cagnolino, come te la sei passata ultimamente?"
  },
  AvgCommunicate_134187_Content_10 = {
    Text = "Non agire avventatamente. In ogni caso, la Pozza Nera ti terrà saldamente imprigionata."
  },
  AvgCommunicate_134187_Content_11 = {
    Text = "Non hai la minima idea di quale Potere la conoscenza possa concedermi."
  },
  AvgCommunicate_134187_Content_12 = {
    Text = "Sono molto compiaciuta di questo dono. Quindi, mia carissima Studentessa, ti farò un Dono in cambio."
  },
  AvgCommunicate_134187_Content_13 = {Text = "...?"},
  AvgCommunicate_134187_Content_14 = {
    Text = "Indovina. Indovina fin dove posso spingermi adesso."
  },
  AvgCommunicate_134187_Content_15 = {
    Text = "Indovina se le vostre arroganti misure di contenimento possono davvero avere effetto."
  },
  AvgCommunicate_134187_Content_16 = {
    Text = "Indovina se La Verità che ho sbirciato, ora che ho ottenuto questo Potere, verrà Impiantata nella cognizione di Tutti."
  },
  AvgCommunicate_134187_Content_17 = {
    Text = "Questo è il compito più importante, sai. Presto, molto presto, verrò a correggerlo personalmente."
  },
  AvgCommunicate_134187_Content_2 = {
    Text = "La tua audacia mi sorprende davvero — hai osato inviare un dono di questo calibro."
  },
  AvgCommunicate_134187_Content_3 = {
    Text = "Mi crederesti se ti dicessi che c'è stato un grave incidente durante il trasporto di materiali rari..."
  },
  AvgCommunicate_134187_Content_5 = {
    Text = "Mi sottovaluti, e sottovaluti Mythag."
  },
  AvgCommunicate_134187_Content_6 = {
    Text = "Siamo disposti a lasciare che ogni Risvegliatore tocchi quel limite, perché tenteremo ogni metodo per prevenire la Distruzione."
  },
  AvgCommunicate_134187_Content_7 = {
    Text = "Questa è... la più grande differenza tra quell'insegnante Doll, noi e voi. Anche se la Distruzione fosse inevitabile, non ci sottometteremo mai ad essa."
  },
  AvgCommunicate_134187_Content_8 = {
    Text = "Sigh, come ho fatto a non Scoprire prima che il sistema educativo di Mythag potesse produrre sciocchi simili."
  },
  AvgCommunicate_134187_Content_9 = {
    Text = "Per fortuna, uno sciocco così pietosamente stupido che è difficile non provare affetto."
  },
  AvgCommunicate_134187_Option_13 = {Text = "...?"},
  AvgCommunicate_134187_Option_3 = {
    Text = "È stato un incidente."
  },
  AvgCommunicate_134187_Option_5 = {
    Text = "È la mia sincera intenzione."
  },
  AvgCommunicate_134188_Content_1 = {
    Text = "Regole, troppo belle! Bang—! Boom—! Kaboom—!"
  },
  AvgCommunicate_134188_Content_11 = {
    Text = "In tal caso, i costi di riparazione della scuola dovrebbero calare notevolmente questo mese..."
  },
  AvgCommunicate_134188_Content_12 = {
    Text = "Compiti brutti, comparire, Vortice, spaccare morto!"
  },
  AvgCommunicate_134188_Content_13 = {
    Text = "No, non puoi considerare anche i compiti come un nemico!"
  },
  AvgCommunicate_134188_Content_14 = {
    Text = "Vortice, Vortice?"
  },
  AvgCommunicate_134188_Content_16 = {
    Text = "Custode, sono Nautila. State tranquilli, Vortice è stato contenuto. I compiti e l'aula sono entrambi al sicuro."
  },
  AvgCommunicate_134188_Content_17 = {
    Text = "Grazie al cielo..."
  },
  AvgCommunicate_134188_Content_18 = {
    Text = "Nautila, Mythag, Vortice e io avremo sempre bisogno di te."
  },
  AvgCommunicate_134188_Content_2 = {
    Text = "Ricorda la Regola N. 1 del Codice Mythag, Edizione Speciale Vortice: In nessuna circostanza è permesso puntare un'arma letale contro chiunque nel Mythag."
  },
  AvgCommunicate_134188_Content_5 = {
    Text = "%player%, non preoccupare, Vortice, controllo, può fare!"
  },
  AvgCommunicate_134188_Content_6 = {
    Text = "Vortice, controllo, Moskstraumen."
  },
  AvgCommunicate_134188_Content_7 = {
    Text = "Vortice, amico, abbraccini."
  },
  AvgCommunicate_134188_Content_8 = {
    Text = "Vortice, nemico, bang—! boom—! kaboom—!"
  },
  AvgCommunicate_134188_Option_2 = {
    Text = "La sicurezza prima di tutto."
  },
  AvgCommunicate_134189_Content_1 = {
    Text = "Siamo compagni d'armi, quindi non dirò grazie."
  },
  AvgCommunicate_134189_Content_2 = {
    Text = "La mia arma è stata affilata fino al massimo—abbastanza da tagliare la gola di uno schiavista in un istante."
  },
  AvgCommunicate_134189_Content_3 = {
    Text = "Il significato della resistenza, il significato della vendetta, il significato della battaglia—continuo a rifletterci senza sosta."
  },
  AvgCommunicate_134189_Content_4 = {
    Text = "Forse continuerò a rifletterci per il resto della mia vita, fino al giorno in cui non riuscirò più a reggermi in piedi."
  },
  AvgCommunicate_134189_Content_5 = {
    Text = "Quantomeno, non sono più smarrito."
  },
  AvgCommunicate_134189_Content_6 = {
    Text = "Ai miei compagni d'armi."
  },
  AvgCommunicate_134189_Content_7 = {
    Text = "Ai compagni d'armi. Siete stati voi a liberarmi e a darmi la Risolutezza per andare avanti."
  },
  AvgCommunicate_134189_Content_8 = {
    Text = "Ogni volta che avrete bisogno di me, vi coprirò sempre le spalle, Combattendo Insieme a voi."
  },
  AvgCommunicate_134189_Content_9 = {
    Text = "Continuiamo a combattere insieme — per la vendetta che deve essere compiuta, e per il brivido della battaglia stessa."
  },
  AvgCommunicate_134189_Option_6 = {
    Text = "Ai compagni d'armi."
  },
  AvgCommunicate_134201_Content_1 = {
    Text = "Custode, ho inoltrato una richiesta all'Ufficio Affari Accademici. Sarò assente dall'addestramento per i prossimi tre giorni."
  },
  AvgCommunicate_134201_Content_10 = {
    Text = "Ma dopo aver superato quel limite, ho capito."
  },
  AvgCommunicate_134201_Content_11 = {Text = "Cosa?"},
  AvgCommunicate_134201_Content_13 = {
    Text = "Io sono la lama dell'avanguardia. È proprio perché ho sempre percorso questo cammino che ho potuto incontrare tutti voi, e incontrare te."
  },
  AvgCommunicate_134201_Content_14 = {
    Text = "La mia ricerca fa sì che non sia mai sola. Forse non arriveremo mai alla meta, ma finché perseveriamo, posso avvicinare quel mondo ideale e giusto, un po' di più, e ancora di più."
  },
  AvgCommunicate_134201_Content_15 = {
    Text = "Con il mio corpo come lama, fino a raggiungere l'utopia in cui tutti possano vivere nella luce."
  },
  AvgCommunicate_134201_Content_16 = {
    Text = "Che visione grandiosa, Istruttrice Alva! Ti sosterrò incondizionatamente!"
  },
  AvgCommunicate_134201_Content_17 = {
    Text = "Meraviglioso. In tal caso, userò questi tre giorni per sviluppare un programma di addestramento ancora più rigoroso e impegnativo."
  },
  AvgCommunicate_134201_Content_18 = {
    Text = "Sarai la prima a provarlo. Stai tranquilla, ti accompagnerò per tutto l'addestramento e migliorerò insieme a tutti."
  },
  AvgCommunicate_134201_Content_19 = {
    Text = "Aspetta, credo che potremmo discuterne ancora un po'…"
  },
  AvgCommunicate_134201_Content_2 = {
    Text = "C'è stato un problema con i materiali? Stai bene? Hai bisogno di aiuto?"
  },
  AvgCommunicate_134201_Content_3 = {
    Text = "No, tutto il contrario. È andato tutto liscio. Ho vissuto una svolta diversa da quelle precedenti."
  },
  AvgCommunicate_134201_Content_4 = {
    Text = "Non capisco bene…"
  },
  AvgCommunicate_134201_Content_5 = {
    Text = "Io… dopo aver lasciato l'esercito, ho vagato per molto tempo."
  },
  AvgCommunicate_134201_Content_6 = {
    Text = "Non sapevo per cosa avrei dovuto combattere. L'unica cosa che potevo seguire era un senso di giustizia di cui non ero nemmeno sicura di poter raggiungere il fine ultimo."
  },
  AvgCommunicate_134201_Content_7 = {
    Text = "Volevo stare dalla parte dei deboli, dalla parte di chi non può far sentire la propria voce, dalla parte di chi viene trattato ingiustamente."
  },
  AvgCommunicate_134201_Content_8 = {
    Text = "Ma sapevo anche perfettamente che, per quanto fossi diventata forte, ci sarebbero sempre state cose al di là di ogni aiuto — proprio come, anche se il tempo fosse stato invertito, non avrei comunque potuto impedire la caduta di Aram."
  },
  AvgCommunicate_134201_Content_9 = {
    Text = "Istruttrice Alva…"
  },
  AvgCommunicate_134201_Option_2 = {
    Text = "Che è successo?"
  },
  AvgCommunicate_134202_Content_1 = {
    Text = "Grazie per avermi affidato qualcosa di così prezioso, %player%."
  },
  AvgCommunicate_134202_Content_10 = {
    Text = "Credo che mi stia dicendo che, oltre a lasciare ombre nella memoria, il mondo può anche essere misurato con i passi."
  },
  AvgCommunicate_134202_Content_11 = {
    Text = "Se non riesco a trattenerli, allora continuerò ad andare avanti, sempre avanti. Il mondo e tutti voi ricorderete al posto mio."
  },
  AvgCommunicate_134202_Content_12 = {
    Text = "Perfino io non posso fare a meno di sentirmi piena di entusiasmo..."
  },
  AvgCommunicate_134202_Content_13 = {
    Text = "Diventerò la più grande esploratrice, la più incredibile maestra meccanica. %player%, voglio estenderti formalmente L'Invito."
  },
  AvgCommunicate_134202_Content_14 = {
    Text = "Quando arriverà il giorno in cui tutto sarà risolto, per favore parti per un'avventura con me. Creiamo insieme altri ricordi preziosi in questo mondo."
  },
  AvgCommunicate_134202_Content_15 = {
    Text = "Forse quel giorno è lontano, o forse è domani."
  },
  AvgCommunicate_134202_Content_16 = {
    Text = "Questo invito è valido per sempre. Lo ricorderò, lo prometto."
  },
  AvgCommunicate_134202_Content_2 = {
    Text = "Ho passato moltissimo tempo ad assorbirli... Ora mi fanno sentire come se fossi tornata intera."
  },
  AvgCommunicate_134202_Content_3 = {
    Text = "Quindi, significa che non dimenticherai più le cose?"
  },
  AvgCommunicate_134202_Content_4 = {
    Text = "Hmm, fammi pensare..."
  },
  AvgCommunicate_134202_Content_5 = {
    Text = "Ahaha, ancora non riesco a ricordare le cose!"
  },
  AvgCommunicate_134202_Content_6 = {
    Text = "Perché ne sembri così orgogliosa!"
  },
  AvgCommunicate_134202_Content_7 = {
    Text = "Perché, anche se potrei ancora dimenticare molte cose, nel passato e nel presente, %player% sarà sempre lì a ricordarmele e ad aiutarmi a ricordare."
  },
  AvgCommunicate_134202_Content_8 = {
    Text = "Chi sono, dove sono, cosa devo fare... saranno le persone di cui mi fido di più a dirmelo."
  },
  AvgCommunicate_134202_Content_9 = {
    Text = "Forse è per questo che, dopo aver compreso l'Assioma Assoluto, anche se la mia memoria non è migliorata, sento come se il mondo intero si fosse dispiegato davanti ai miei occhi come una vasta mappa."
  },
  AvgCommunicate_134202_Option_3 = {
    Text = "La tua memoria è migliorata?"
  },
  AvgCommunicate_134208_Content_1 = {
    Text = "Un tempo credevo che solo interpretando il ruolo del pubblico avrei potuto provare la gioia dell'ignoto."
  },
  AvgCommunicate_134208_Content_10 = {
    Text = "Non capisco del tutto… ma sembra che dovrebbe essere una cosa positiva?"
  },
  AvgCommunicate_134208_Content_11 = {
    Text = "Da quando ho lasciato quella Porta, questa è la più grande benedizione che abbia incontrato."
  },
  AvgCommunicate_134208_Content_12 = {
    Text = "Custode, questa è la sorpresa che mi hai fatto—una che non avrei mai potuto prevedere."
  },
  AvgCommunicate_134208_Content_13 = {
    Text = "Il Fato non delude mai chi dona con generosità."
  },
  AvgCommunicate_134208_Content_14 = {
    Text = "Non posso toccare i tuoi fili, ma finché combatterai per il Fato, la mia ruota girerà per sempre per te."
  },
  AvgCommunicate_134208_Content_2 = {
    Text = "È passato molto, molto tempo dall'ultima volta che ho provato questa sensazione…"
  },
  AvgCommunicate_134208_Content_3 = {
    Text = "Che sensazione è?"
  },
  AvgCommunicate_134208_Content_4 = {Text = "Novità."},
  AvgCommunicate_134208_Content_5 = {
    Text = "Il silenzioso sbocciare dei germogli, l'intrecciarsi delle parole sulla carta, il dolce fluttuare delle nuvole nel Vento…"
  },
  AvgCommunicate_134208_Content_6 = {
    Text = "E naturalmente, le persone — quelle braccia protese, quelle lacrime che cadono, quei battiti del cuore simili a tamburi di guerra o gocce di pioggia…"
  },
  AvgCommunicate_134208_Content_7 = {
    Text = "Vedo più di prima, eppure i miei occhi sono più bassi di un tempo."
  },
  AvgCommunicate_134208_Content_8 = {
    Text = "Non indugiano più nel cielo, Custode. Sono discesi, posandosi su ogni strada, accanto a ogni passante."
  },
  AvgCommunicate_134208_Content_9 = {
    Text = "Ora non ho bisogno di giocare un ruolo. Posso davvero esistere come individuo."
  },
  AvgCommunicate_134208_Option_10 = {
    Text = "Sembra una cosa positiva?"
  },
  AvgCommunicate_134208_Option_3 = {
    Text = "Che sensazione è?"
  },
  AvgCommunicate_134242_Content_1 = {
    Text = "Statistica principale scelta casualmente tra Tasso Crit., Danno Crit., Livello di Ricarica della Chiave d'Argento o Livello Ricarica Aliemus."
  },
  AvgCommunicate_134245_Content_1 = {
    Text = "Sembra qualcosa di molto prezioso, non c'è problema a darlo a Saya?"
  },
  AvgCommunicate_134245_Content_12 = {
    Text = "Quindi anche questo mondo ha il suo lato bello, anche se è un po' diverso dal mondo che ricordo."
  },
  AvgCommunicate_134245_Content_13 = {
    Text = "Il modo in cui è composto, la logica con cui si muove — Saya è già in grado di comprenderlo completamente."
  },
  AvgCommunicate_134245_Content_14 = {
    Text = "Quindi, riscrivere questo mondo per farlo diventare quello che ricordo, forse ora potrei farlo con grande facilità."
  },
  AvgCommunicate_134245_Content_16 = {
    Text = "Anche se so che stai scherzando, ti prego di non fare mai una cosa del genere."
  },
  AvgCommunicate_134245_Content_17 = {Text = "..."},
  AvgCommunicate_134245_Content_18 = {
    Text = "Come mai non parli, stai scherzando, vero? Non stare in silenzio in un momento come questo!"
  },
  AvgCommunicate_134245_Content_19 = {
    Text = "Sai, poco fa sono uscita solo per un momento e ho osservato tutti da una nuova prospettiva..."
  },
  AvgCommunicate_134245_Content_2 = {
    Text = "Mi fido di Saya, quindi non c'è problema."
  },
  AvgCommunicate_134245_Content_20 = {
    Text = "Mentre le persone che conosco, quelle che trattano Saya con gentilezza, sono ancora tutte in vita e stanno bene, è così."
  },
  AvgCommunicate_134245_Content_21 = {
    Text = "Non riesco a dire cosa non va, ma ho la strana sensazione che ci sia sicuramente qualcosa che non va."
  },
  AvgCommunicate_134245_Content_22 = {
    Text = "E in questo momento sul tuo viso c'è sicuramente di nuovo quell'Espressione da monello soddisfatto!"
  },
  AvgCommunicate_134245_Content_23 = {
    Text = "Non preoccuparti, andrò d'accordo con tutti in questo mondo."
  },
  AvgCommunicate_134245_Content_24 = {
    Text = "Beh… però il mondo nei ricordi di Saya potrebbe essere ancora più interessante. Perché non andiamo tutti a darci un'occhiata? Ora dovrebbe essere possibile!"
  },
  AvgCommunicate_134245_Content_25 = {
    Text = "Questa frase fa ancora più paura!"
  },
  AvgCommunicate_134245_Content_3 = {
    Text = "Se può aiutarti a comprendere meglio questo mondo, dovrebbe essere di grande aiuto anche per la ricerca su \"come fermare la Dissoluzione\"."
  },
  AvgCommunicate_134245_Content_4 = {
    Text = "Dopotutto, sei davvero molto brava nell'apprendimento e nella ricerca..."
  },
  AvgCommunicate_134245_Content_5 = {
    Text = "In realtà è stato un incidente con alcune forniture... ma ormai è troppo tardi per tornare indietro, no?"
  },
  AvgCommunicate_134245_Content_6 = {
    Text = "Eh? Allora dovrei restituirlo? Sono un po' in difficoltà."
  },
  AvgCommunicate_134245_Content_7 = {
    Text = "Eh? Si può restituire?"
  },
  AvgCommunicate_134245_Content_8 = {
    Text = "Mmh, lascia che Saya ci pensi..."
  },
  AvgCommunicate_134245_Content_9 = {
    Text = "La risposta è — no."
  },
  AvgCommunicate_134245_Option_2 = {
    Text = "Nessun problema."
  },
  AvgCommunicate_134245_Option_5 = {
    Text = "È stato un incidente"
  },
  AvgCommunicate_134246_Content_1 = {
    Text = "Mio caro, amatissimo, magnificentissimo benefattore~"
  },
  AvgCommunicate_134246_Content_10 = {
    Text = "Fammi controllare."
  },
  AvgCommunicate_134246_Content_11 = {
    Text = "Fammi controllare i dati di fluttuazione del tuo Indice Gnostico."
  },
  AvgCommunicate_134246_Content_12 = {
    Text = "Beh, guarda un po'—la nostra Caraboo non stava mentendo questa volta."
  },
  AvgCommunicate_134246_Content_13 = {
    Text = "Eh eh, ora credi alla povera piccola Caraboo, vero?"
  },
  AvgCommunicate_134246_Content_14 = {
    Text = "Ti prego, continua a investire generosamente in me—così potrò far guadagnare al mio caro benefattore cento, mille volte il ritorno in futuro!"
  },
  AvgCommunicate_134246_Content_15 = {
    Text = "Solo altri otto—no, cinque Frammenti di Illuminazione! E ti stupirò di nuovo, promesso!"
  },
  AvgCommunicate_134246_Content_16 = {
    Text = "È impossibile."
  },
  AvgCommunicate_134246_Content_17 = {
    Text = "Bel tentativo."
  },
  AvgCommunicate_134246_Content_18 = {
    Text = "La Professoressa Doll mi ha detto che la ricerca sull'Illuminazione dei Risvegliatori ha già raggiunto il suo limite. Non ci sarà un'altra svolta per un secolo."
  },
  AvgCommunicate_134246_Content_19 = {
    Text = "Una volta che un Risvegliatore raggiunge l'Assioma Assoluto, non potrà mai più sottoporsi al rituale della Tempesta Psichica."
  },
  AvgCommunicate_134246_Content_2 = {
    Text = "Cosa vuoi questa volta, con tutta questa adulazione improvvisa?"
  },
  AvgCommunicate_134246_Content_21 = {
    Text = "Ahah—devo aver fatto confusione per sbaglio!"
  },
  AvgCommunicate_134246_Content_22 = {
    Text = "Ti prego di riavvolgere il ricordo di questa conversazione di sei messaggi. Buona giornata~"
  },
  AvgCommunicate_134246_Content_3 = {
    Text = "Oh mio, ascoltati—per chi mi prendi, per qualcuno che si fa viva solo quando vuole qualcosa?"
  },
  AvgCommunicate_134246_Content_4 = {
    Text = "È esattamente quello che sei..."
  },
  AvgCommunicate_134246_Content_5 = {
    Text = "Uh-uh, sono a pezzi. Il mio benefattore mi fraintende così terribilmente."
  },
  AvgCommunicate_134246_Content_6 = {
    Text = "In realtà sono venuta a portarti una buona notizia questa volta!"
  },
  AvgCommunicate_134246_Content_7 = {
    Text = "Il tuo investimento ha dato i suoi frutti—con risultati super, super straordinari~"
  },
  AvgCommunicate_134246_Content_8 = {
    Text = "Vedi? Sono una persona completamente nuova. Rinata, trasformata, totalmente diversa~"
  },
  AvgCommunicate_134246_Content_9 = {Text = "Davvero?"},
  AvgCommunicate_134246_Option_10 = {
    Text = "Fammi controllare."
  },
  AvgCommunicate_134246_Option_16 = {
    Text = "È impossibile."
  },
  AvgCommunicate_134246_Option_17 = {
    Text = "Bel tentativo."
  },
  AvgCommunicate_134246_Option_9 = {Text = "Davvero?"},
  AvgCommunicate_134247_Content_1 = {
    Text = "Statistica principale scelta casualmente tra Tasso Crit., Danno Crit., Livello di Ricarica della Chiave d'Argento o Livello Ricarica Aliemus."
  },
  AvgCommunicate_134249_Content_1 = {Text = "Custode..."},
  AvgCommunicate_134249_Content_10 = {
    Text = "Mmm... Quella sensazione è tornata. All'improvviso ho caldo, e sete. Lo stomaco, dentro lo stomaco,"
  },
  AvgCommunicate_134249_Content_11 = {
    Text = "Custode, sono malata? Lo stomaco si sta sciogliendo, il cuore si sta sciogliendo, tutto si scioglie. Non riesco a distinguerli, è come se mi stessi fondendo..."
  },
  AvgCommunicate_134249_Content_12 = {
    Text = "Respira profondamente, Leigh. Non ti scioglierai."
  },
  AvgCommunicate_134249_Content_13 = {
    Text = "È una reazione umana normale nelle relazioni intime. Non c'è bisogno di medicine… e nemmeno di prendere una frusta!"
  },
  AvgCommunicate_134249_Content_14 = {
    Text = "Eh? Neanche una frusta? Che delusione."
  },
  AvgCommunicate_134249_Content_16 = {
    Text = "…Ehm, se ne hai davvero bisogno, forse potresti chiedere a Pandia…"
  },
  AvgCommunicate_134249_Content_17 = {Text = "Hehe..."},
  AvgCommunicate_134249_Content_18 = {
    Text = "Custode, cercherò di non accovacciarmi più fuori dal tuo Cancello."
  },
  AvgCommunicate_134249_Content_19 = {
    Text = "Ma… potresti ogni tanto lasciarmi un Cancello aperto di notte? Anche una finestra andrebbe bene."
  },
  AvgCommunicate_134249_Content_2 = {
    Text = "I Caro di mio fratello e il mio corpo sono più compatibili di prima. Respirano silenziosamente sotto la mia pelle, senza più urlare costantemente per farmi a pezzi."
  },
  AvgCommunicate_134249_Content_20 = {
    Text = "Non entrerò. Mi basterebbe sapere che c'è un Sentiero che porta a te in qualsiasi momento per dormire più serenamente."
  },
  AvgCommunicate_134249_Content_3 = {
    Text = "Anche la brama di Sangue non fa più così male. Prima era come qualcosa bloccato in gola... Soffocamento se non bevevo. Ora sembra... disposta ad aspettarmi un po'."
  },
  AvgCommunicate_134249_Content_4 = {
    Text = "Questa è davvero una bella notizia."
  },
  AvgCommunicate_134249_Content_5 = {
    Text = "Le notti a scuola sono così silenziose. La fontana scroscia piano."
  },
  AvgCommunicate_134249_Content_6 = {
    Text = "Custode, mi hai dato così tanti tesori. Li merito davvero?"
  },
  AvgCommunicate_134249_Content_7 = {
    Text = "Certo che sì."
  },
  AvgCommunicate_134249_Content_8 = {
    Text = "...Rispondi sempre così in fretta."
  },
  AvgCommunicate_134249_Content_9 = {
    Text = "Leigh, ci hai aiutato moltissimo. È il minimo che possa fare."
  },
  AvgCommunicate_134250_Content_1 = {
    Text = "Non sai come finisce quando allevi una bestia selvaggia?"
  },
  AvgCommunicate_134250_Content_10 = {
    Text = "Mi chiedo spesso se tu sia davvero come appari in superficie, oppure…"
  },
  AvgCommunicate_134250_Content_11 = {
    Text = "In realtà hai recitato una parte per tutto questo tempo, proprio come quei padroni di schiavi."
  },
  AvgCommunicate_134250_Content_12 = {
    Text = "Cosa ne pensi? Non sono brava a recitare, né a mentire."
  },
  AvgCommunicate_134250_Content_13 = {
    Text = "Puoi seguire i tuoi sentimenti. Non cercherò di convincerti, né ti costringerò a fare nulla."
  },
  AvgCommunicate_134250_Content_14 = {
    Text = "Come ha detto una volta l'altra te, siamo amici... compagni d'armi."
  },
  AvgCommunicate_134250_Content_15 = {
    Text = "Tch, non mettermi sullo stesso piano di quella debole."
  },
  AvgCommunicate_134250_Content_16 = {
    Text = "Sono stufa dei tradimenti da un pezzo. Non ho bisogno di amici."
  },
  AvgCommunicate_134250_Content_17 = {
    Text = "E non voglio nemmeno le tue promesse."
  },
  AvgCommunicate_134250_Content_18 = {
    Text = "Finché mi fornirai più Potere, mi basta."
  },
  AvgCommunicate_134250_Content_19 = {
    Text = "E in cambio mi vendicherò dei tuoi nemici per te."
  },
  AvgCommunicate_134250_Content_2 = {
    Text = "Una bestia cresciuta spezzerà le sue catene e—rawr—morderà la gola del suo padrone."
  },
  AvgCommunicate_134250_Content_20 = {
    Text = "Fino al giorno in cui mi tradirai davvero... Anche se fuggissi ai confini della terra, ti inseguirò e ti strapperò la gola."
  },
  AvgCommunicate_134250_Content_3 = {
    Text = "In questo momento, il tuo Legame con me mi sembra più Fragile di catene di ferro."
  },
  AvgCommunicate_134250_Content_4 = {
    Text = "Non hai paura?"
  },
  AvgCommunicate_134250_Content_5 = {
    Text = "Sei libera. Il nostro Legame non è fatto per trattenerti."
  },
  AvgCommunicate_134250_Content_6 = {
    Text = "Non ho motivo di avere paura."
  },
  AvgCommunicate_134250_Content_7 = {Text = "..."},
  AvgCommunicate_134250_Content_8 = {
    Text = "Tch, belle parole."
  },
  AvgCommunicate_134250_Content_9 = {
    Text = "Ma ti osservo da così tanto tempo, e non ho ancora scoperto un momento in cui mostri un Cedimento."
  },
  AvgCommunicate_134250_Option_12 = {
    Text = "Tu che ne pensi?"
  },
  AvgCommunicate_134250_Option_5 = {Text = "Sei libera"},
  AvgCommunicate_134263_Content_1 = {Text = "Custode!!"},
  AvgCommunicate_134263_Content_10 = {
    Text = "Certo. Non ho mai dubitato che saresti diventato più forte."
  },
  AvgCommunicate_134263_Content_11 = {Text = "..."},
  AvgCommunicate_134263_Content_12 = {
    Text = "Sei davvero uno strano tipo."
  },
  AvgCommunicate_134263_Content_13 = {
    Text = "In un momento come questo, non dovresti dire qualcosa tipo \"Visto, sapevo di aver avuto occhio per te\" o \"Hai davvero soddisfatto le mie aspettative\"?"
  },
  AvgCommunicate_134263_Content_14 = {
    Text = "Perché sei così tranquillo a riguardo?"
  },
  AvgCommunicate_134263_Content_16 = {
    Text = "Ehm…perché ti sei impegnata così tanto, diventare più forte è solo naturale. Che c'è da dire?"
  },
  AvgCommunicate_134263_Content_17 = {
    Text = "I 50 dollari che mi hai restituito l'altro ieri e i 54 dollari dell'anno scorso… li ho conservati tutti."
  },
  AvgCommunicate_134263_Content_18 = {
    Text = "Perché conservarli…spendili e basta."
  },
  AvgCommunicate_134263_Content_19 = {
    Text = "Lascia perdere, non importa. C'è una cosa importante."
  },
  AvgCommunicate_134263_Content_2 = {
    Text = "Quei segni si stanno riscaldando. Il Potere dell'Aequor scorre sotto la mia pelle, molto più chiaramente di prima!"
  },
  AvgCommunicate_134263_Content_20 = {
    Text = "Vieni subito al lago. Ti sto aspettando qui."
  },
  AvgCommunicate_134263_Content_21 = {
    Text = "Che succede?"
  },
  AvgCommunicate_134263_Content_22 = {
    Text = "Lo scoprirai quando arrivi."
  },
  AvgCommunicate_134263_Content_23 = {
    Text = "Va bene…allora aspettami un attimo. Fuori sta piovendo adesso. Devo tornare in dormitorio a prendere un ombrello."
  },
  AvgCommunicate_134263_Content_24 = {
    Text = "Smettila di perdere tempo. Non ci servirà un ombrello per quello che verrà dopo."
  },
  AvgCommunicate_134263_Content_25 = {
    Text = "Non ti bagnerai. Le mie ali membranose sono abbastanza grandi."
  },
  AvgCommunicate_134263_Content_3 = {
    Text = "Hai idea di cosa si provi?!"
  },
  AvgCommunicate_134263_Content_4 = {
    Text = "In ogni caso, è incredibilmente straordinario, oltre ogni parola. Voi umani probabilmente non potete comprenderlo."
  },
  AvgCommunicate_134263_Content_5 = {
    Text = "…Caecus, stai bene?"
  },
  AvgCommunicate_134263_Content_6 = {
    Text = "Certo che sto bene. Non sono mai stato meglio."
  },
  AvgCommunicate_134263_Content_7 = {
    Text = "Te l'avevo detto tempo fa, il tuo investimento non sarebbe andato sprecato. Il mio Sangue non mi mente mai."
  },
  AvgCommunicate_134263_Content_8 = {Text = "Lo so."},
  AvgCommunicate_134263_Content_9 = {
    Text = "…Tutto qui?"
  },
  AvgCommunicate_134264_Content_1 = {
    Text = "Ti prego di perdonarmi, Messaggera Pallida. Non ero preparato a questo e sembra che ti abbia spaventata."
  },
  AvgCommunicate_134264_Content_10 = {
    Text = "Finché penso a questo, la pace nel mio cuore supera di gran lunga la sofferenza della mia carne."
  },
  AvgCommunicate_134264_Content_11 = {
    Text = "Capisco. Forse non ho ideali così grandiosi. Ma anche se fosse solo per te, per i miei amici."
  },
  AvgCommunicate_134264_Content_12 = {
    Text = "Finché potrò raggiungere quel mondo ideale e pacifico, qualunque cosa serva, farò del mio meglio."
  },
  AvgCommunicate_134264_Content_13 = {
    Text = "Grazie, Messaggera Pallida."
  },
  AvgCommunicate_134264_Content_14 = {
    Text = "Possa ogni sofferenza trovare il suo giorno di Dissoluzione, e possano tu ed io camminare sempre fianco a fianco."
  },
  AvgCommunicate_134264_Content_15 = {
    Text = "Possa la protezione dell'Onnipadre discendere anche su tutto ciò che ti è caro."
  },
  AvgCommunicate_134264_Content_2 = {
    Text = "Uff… Sono sollevata che tu stia bene. Non mi aspettavo che la comprensione delle leggi potesse provocare questo tipo di Effetto."
  },
  AvgCommunicate_134264_Content_3 = {
    Text = "Non preoccuparti per me. Questa è la missione stessa per cui sono venuto al mondo."
  },
  AvgCommunicate_134264_Content_4 = {
    Text = "Prima di varcare la soglia verso l'apice, prima che l'Onnipadre mi rivelasse questi misteri insondabili, mi ero già consacrato a questo Cammino."
  },
  AvgCommunicate_134264_Content_5 = {
    Text = "Raccogliere su di me la sofferenza di tutti gli esseri, guidare ogni cosa verso una terra immacolata dove la sofferenza non esiste più— questo non è un fardello. Questa è la grazia che l'Onnipadre mi ha concesso."
  },
  AvgCommunicate_134264_Content_6 = {
    Text = "Ho sempre pensato che tu porti un peso troppo grande. Il dolore degli altri viene Dissolto, ma il costo…"
  },
  AvgCommunicate_134264_Content_7 = {
    Text = "Mia pallida fiamma, possiedi un cuore tenero."
  },
  AvgCommunicate_134264_Content_8 = {
    Text = "Ma stai tranquilla. La sofferenza fisica è per me come le Spine lo sono per il terreno— più in profondità penetrano, più saldamente Metto Radici."
  },
  AvgCommunicate_134264_Content_9 = {
    Text = "Se anche una sola anima in questo mondo soffre ancora, non soffrirà mai da sola. Se anche una sola non è ancora sfuggita al mare di sofferenza, io non raggiungerò mai l'altra sponda prima di lei."
  },
  AvgCommunicate_134264_Option_11 = {Text = "Capisco"},
  AvgCommunicate_134264_Option_6 = {Text = "Ma…"},
  AvgCommunicate_134265_Content_1 = {
    Text = "Haha, esaltante, assolutamente esaltante!"
  },
  AvgCommunicate_134265_Content_10 = {
    Text = "Chiedi a uno qualsiasi dei miei ragazzi— mi conoscono da anni. Quando mai mi hanno visto fare una cosa del genere!"
  },
  AvgCommunicate_134265_Content_11 = {
    Text = "Ah, ora che il mio Potere è ancora più feroce, la prossima volta dovrò stare attento a non bruciarti."
  },
  AvgCommunicate_134265_Content_12 = {
    Text = "Cosa... eri tu? Allora, quelle volte che mi hanno cambiato i vestiti... eri tu?"
  },
  AvgCommunicate_134265_Content_13 = {
    Text = "Sì, i tuoi vestiti erano tutti sporchi di alcol e cibo. Non potevo mica lasciarti strisciare a letto così."
  },
  AvgCommunicate_134265_Content_14 = {
    Text = "Grazie, Kathigu-Ra."
  },
  AvgCommunicate_134265_Content_15 = {
    Text = "Ma la prossima volta, potresti semplicemente scuotermi per svegliarmi..."
  },
  AvgCommunicate_134265_Content_16 = {
    Text = "Oh, ti vergogni? Non preoccuparti— guarda quanto siamo in confidenza."
  },
  AvgCommunicate_134265_Content_17 = {
    Text = "Non parliamo di una sciocchezza come cambiarsi i vestiti— anche se mi chiedessi di camminare sul fuoco o scalare una montagna di lame, non sarebbe affatto un problema!"
  },
  AvgCommunicate_134265_Content_18 = {
    Text = "Al massimo, la prossima volta lascerò che tu mi aiuti a cambiarmi. Alla pari."
  },
  AvgCommunicate_134265_Content_19 = {
    Text = "…Non c'è niente di ragionevole in tutto ciò, ed è talmente assurdo che non ho idea di come rispondere!"
  },
  AvgCommunicate_134265_Content_2 = {
    Text = "Una sensazione di euforia senza precedenti— ora, io sono il Sole!"
  },
  AvgCommunicate_134265_Content_3 = {
    Text = "Piccoletto, mi impressioni sempre di più."
  },
  AvgCommunicate_134265_Content_4 = {
    Text = "Te ne accorgi solo adesso? Questo è solo l'inizio."
  },
  AvgCommunicate_134265_Content_5 = {
    Text = "Oh? Sembra che trattarti come un piccoletto non sia stato poi così appropriato."
  },
  AvgCommunicate_134265_Content_6 = {
    Text = "Hmm... d'ora in poi, dovrei iniziare a chiamarti grandone."
  },
  AvgCommunicate_134265_Content_7 = {
    Text = "Grandone? Ma che razza di nome è! Mi stai prendendo in giro di nuovo con quella faccia seria, vero?"
  },
  AvgCommunicate_134265_Content_8 = {
    Text = "Hahaha, non posso farci niente. Sei sempre il primo a crollare ogni volta che andiamo a bere."
  },
  AvgCommunicate_134265_Content_9 = {
    Text = "Quindi ogni volta devo riportarti in dormitorio in braccio, toglierti le scarpe, rimboccarti le coperte e pulirti la faccia."
  },
  AvgCommunicate_134265_Option_12 = {Text = "Eri tu?"},
  AvgCommunicate_134265_Option_7 = {Text = "?!"},
  AvgCommunicate_134267_Content_1 = {
    Text = "%player%, la mia musica è diventata ancora più perfetta."
  },
  AvgCommunicate_134267_Content_10 = {
    Text = "La mia musica era come una macchina che funzionava con precisione, e un tempo mi valse un posto nell'orchestra più prestigiosa. Naturalmente, ne ero orgoglioso."
  },
  AvgCommunicate_134267_Content_11 = {
    Text = "Lui era diverso. Non era adatto all'Ensemble. La sua musica era destinata a brillare da sola nel cielo, come il Sole o la Luna."
  },
  AvgCommunicate_134267_Content_12 = {
    Text = "L'ho sempre osservato, rincorrendolo. Solo che avevo ormai perso per sempre la possibilità di comunicare con lui."
  },
  AvgCommunicate_134267_Content_13 = {
    Text = "Ma... l'esecuzione che ha ora raggiunto la perfezione assoluta è probabilmente la migliore risposta che posso presentare dopo una vita intera di ricerca."
  },
  AvgCommunicate_134267_Content_14 = {
    Text = "Che storia commovente... Come fai ad avere un passato simile? Una storia leggendaria di musicisti che brillano intensamente e riflettono la luce l'uno dell'altro..."
  },
  AvgCommunicate_134267_Content_15 = {
    Text = "Mm, solo delle riflessioni perfettamente ordinarie. Non è davvero così drammatico."
  },
  AvgCommunicate_134267_Content_16 = {
    Text = "In ogni caso, ciò che più desidero dire è: grazie, %player%."
  },
  AvgCommunicate_134267_Content_17 = {
    Text = "D'ora in poi, ti prego, lasciami continuare a suonare il mio flauto per te, accompagnandoti in un sonno sereno ogni notte."
  },
  AvgCommunicate_134267_Content_2 = {
    Text = "Senza la tua guida, probabilmente non avrei mai potuto compiere quest'ultimo passo: calibrare gli errori minimi che un tempo erano al di là delle capacità umane di correggere."
  },
  AvgCommunicate_134267_Content_3 = {
    Text = "Ritmo perfetto, intonazione impeccabile, tutto suona così squisito..."
  },
  AvgCommunicate_134267_Content_4 = {
    Text = "Davvero! Non ho mai sentito un'esecuzione così deliziosa!"
  },
  AvgCommunicate_134267_Content_5 = {
    Text = "Questo è il risultato della Risonanza tra musica e calcolo, strumento e corpo, mente e muscoli."
  },
  AvgCommunicate_134267_Content_6 = {
    Text = "Ho finalmente dimostrato che alla fine di questo cammino arido e tedioso, può esistere anche una musica così perfetta."
  },
  AvgCommunicate_134267_Content_7 = {
    Text = "Anche? Cosa intendi con questo?"
  },
  AvgCommunicate_134267_Content_8 = {
    Text = "In passato, avevo un amico la cui musica era il prodotto della massima sensibilità e creatività."
  },
  AvgCommunicate_134267_Content_9 = {
    Text = "Il talento che padroneggiava con tanta disinvoltura gli permetteva di improvvisare composizioni uniche a ogni esecuzione."
  },
  AvgCommunicate_134267_Option_14 = {Text = "Waaah..."},
  AvgCommunicate_134267_Option_4 = {Text = "In Effetti"},
  AvgCommunicate_134267_Option_7 = {Text = "Anche?"},
  AvgCommunicate_134268_Content_1 = {
    Text = "Mio stimatissimo ospite, come potrò mai ringraziarvi per la vostra generosità?"
  },
  AvgCommunicate_134268_Content_10 = {
    Text = "Capisco, capisco. Non volete quelle celebrazioni volgari. Anch'io credo che non siano adatte a voi."
  },
  AvgCommunicate_134268_Content_11 = {
    Text = "Ho un'ottima idea. Forse sareste disposti a provare ad accompagnarmi oltre Necrovia per accogliere qualcuno che si avvicina alla propria fine?"
  },
  AvgCommunicate_134268_Content_12 = {
    Text = "Se ci fosse concesso un tale onore, spero che voi ed io possiamo accoglierLo insieme, guidandoLo verso la Sua destinazione finale e la Rinascita. Che ne dite?"
  },
  AvgCommunicate_134268_Content_13 = {
    Text = "Anche se forse non è il momento più opportuno per chiederlo... Immagino che alla fine comporterà comunque il consumo, dato che è l'usanza di Necrovia."
  },
  AvgCommunicate_134268_Content_14 = {
    Text = "Hmm, non lo definirei consumo. Proprio come nelle storie che già conosci."
  },
  AvgCommunicate_134268_Content_15 = {
    Text = "È solo il più solenne, eppure il più sereno degli addii."
  },
  AvgCommunicate_134268_Content_16 = {
    Text = "Sarò felice di partecipare, a patto che mi permettiate di saltare certe parti..."
  },
  AvgCommunicate_134268_Content_17 = {
    Text = "Ma certo, certo."
  },
  AvgCommunicate_134268_Content_18 = {
    Text = "Allora, la carrozza di Necrovia e io vi aspetteremo domani mattina fuori dal Cancello."
  },
  AvgCommunicate_134268_Content_2 = {
    Text = "Il vostro dono mi ha concesso il Potere di servire davvero e con fermezza come Guardiano di Necrovia."
  },
  AvgCommunicate_134268_Content_3 = {
    Text = "La cucina ordinaria non è degna della vostra offerta, e la mia collezione personale potrebbe non essere del tutto adatta al vostro palato."
  },
  AvgCommunicate_134268_Content_4 = {
    Text = "Che dilemma beatamente tormentoso."
  },
  AvgCommunicate_134268_Content_5 = {
    Text = "Sei troppo gentile, Doresain."
  },
  AvgCommunicate_134268_Content_6 = {
    Text = "Abbiamo passato così tanto insieme. Non c'è davvero bisogno che ti preoccupi di quelle tediose formalità del Transito."
  },
  AvgCommunicate_134268_Content_7 = {
    Text = "Oh no, no, questa non è affatto una semplice formalità. Sto sinceramente riflettendo su come organizzare un incontro con un caro amico."
  },
  AvgCommunicate_134268_Content_8 = {
    Text = "Avete già assistito alla Danza più straordinaria di Necrovia. Come approfondire ulteriormente il legame tra voi e noi... questa è davvero una sfida."
  },
  AvgCommunicate_134268_Content_9 = {
    Text = "Ehm... Se vuoi conoscere le mie preferenze, spero umilmente che possa essere qualcosa di ordinario, senza spaventi..."
  },
  AvgCommunicate_134268_Option_13 = {Text = "Immagino"},
  AvgCommunicate_134268_Option_9 = {Text = "Ehm"},
  AvgCommunicate_134269_Content_1 = {
    Text = "Mio piccolo germoglio..."
  },
  AvgCommunicate_134269_Content_10 = {
    Text = "Nel mio corpo, il Potere della \"Proliferazione\" sta sbocciando, nato dal contatto con l'assoluto."
  },
  AvgCommunicate_134269_Content_11 = {
    Text = "Che dolcezza, che rigoglio… Ah, sono stanca di parlarti attraverso questo minuscolo blocco di metallo."
  },
  AvgCommunicate_134269_Content_12 = {Text = "Thais?"},
  AvgCommunicate_134269_Content_13 = {
    Text = "Vieni al mio fianco, piccolo germoglio. Adesso, in questo istante."
  },
  AvgCommunicate_134269_Content_14 = {
    Text = "Voglio stringere i tuoi palmi caldi, toccare la tua pelle morbida…"
  },
  AvgCommunicate_134269_Content_15 = {
    Text = "Voglio abbracciarti sotto la luce della luna, proprio come la notte in cui ci siamo fatti la nostra promessa."
  },
  AvgCommunicate_134269_Content_16 = {
    Text = "Con il mio Potere sempre più abbondante, fondendomi con te poco a poco, e lasciando che la tua dolce essenza mi scaldi, a poco a poco…"
  },
  AvgCommunicate_134269_Content_2 = {
    Text = "Ciò che mi hai promesso—il nostro patto stretto sotto la luce della luna e attraverso il mare di sabbia—hai già iniziato a mantenerlo per me."
  },
  AvgCommunicate_134269_Content_3 = {
    Text = "Sono così felice."
  },
  AvgCommunicate_134269_Content_4 = {
    Text = "Anche se un mondo in cui tutti possano vivere in pace è ancora lontano, continuerò a lavorare per raggiungerlo."
  },
  AvgCommunicate_134269_Content_5 = {
    Text = "Dal momento in cui ci siamo incontrati per la prima volta, ho creduto in te."
  },
  AvgCommunicate_134269_Content_6 = {
    Text = "Sei una persona benedetta dal Destino. Hai il Potere e la determinazione."
  },
  AvgCommunicate_134269_Content_7 = {
    Text = "Mio piccolo germoglio, sei così adorabile quando affronti il mondo con tanta dedizione."
  },
  AvgCommunicate_134269_Content_8 = {
    Text = "Aspetterò pazientemente, con dedizione— Aspettando, aspettando... il giorno in cui la nostra promessa sarà mantenuta."
  },
  AvgCommunicate_134269_Content_9 = {
    Text = "Certamente!"
  },
  AvgCommunicate_134269_Option_12 = {Text = "Thais?"},
  AvgCommunicate_134269_Option_4 = {
    Text = "Continuerò a impegnarmi"
  },
  AvgCommunicate_134269_Option_9 = {
    Text = "Certamente!"
  },
  AvgCommunicate_134270_Content_1 = {
    Text = "Non ti ucciderò."
  },
  AvgCommunicate_134270_Content_10 = {
    Text = "Dopo averti prosciugato, andrò a uccidere tutti."
  },
  AvgCommunicate_134270_Content_11 = {
    Text = "Allora... cercherò di restare in vita il più a lungo possibile?"
  },
  AvgCommunicate_134270_Content_12 = {
    Text = "Hahaha, che risposta interessante."
  },
  AvgCommunicate_134270_Content_13 = {
    Text = "Dato che intendi usare quel tuo fragile corpo per essere il Guardiano del mondo intero."
  },
  AvgCommunicate_134270_Content_14 = {
    Text = "Allora... perché tu..."
  },
  AvgCommunicate_134270_Content_15 = {
    Text = "...E quindi?"
  },
  AvgCommunicate_134270_Content_16 = {
    Text = "Fino ad allora, ucciderò solo i tuoi nemici."
  },
  AvgCommunicate_134270_Content_17 = {
    Text = "Quindi continuerai a uccidere?!"
  },
  AvgCommunicate_134270_Content_2 = {
    Text = "…? Eh? Cosa dovrei dire? Grazie?"
  },
  AvgCommunicate_134270_Content_3 = {
    Text = "Questo mondo è diventato davvero noioso dopo la caduta di Roma."
  },
  AvgCommunicate_134270_Content_4 = {
    Text = "Uccidere, uccidere, uccidere. Nient'altro che puro massacro e Sangue. Senza Roma, non resta nulla."
  },
  AvgCommunicate_134270_Content_5 = {
    Text = "Il tuo dono mi ha liberato da quelle catene. Ora strapperò un braccio o due, o magari una gola."
  },
  AvgCommunicate_134270_Content_6 = {
    Text = "Mi dispiace dirtelo, Uvhash, ma nei tempi moderni, uccidere persone senza un'autorizzazione speciale è contro la legge."
  },
  AvgCommunicate_134270_Content_7 = {
    Text = "E sono ancora il tuo Linker. Non solo non puoi uccidere me, non puoi uccidere nessun altro."
  },
  AvgCommunicate_134270_Content_8 = {Text = "Tch."},
  AvgCommunicate_134270_Content_9 = {
    Text = "Va bene. Almeno il tuo sapore è migliore di quello di tutti quei padroni di schiavi."
  },
  AvgCommunicate_134271_Content_1 = {
    Text = "Cu~sto~de dei se~gre~ti~ Sei occupato/a? Ho qualcosa da dirti~"
  },
  AvgCommunicate_134271_Content_10 = {Text = "Vuoto?"},
  AvgCommunicate_134271_Content_11 = {
    Text = "Mm~ Sai, quella sensazione oscura e fredda, la sensazione di essere abbandonata da tutti che affiora ogni volta che il vento soffia attraverso."
  },
  AvgCommunicate_134271_Content_12 = {
    Text = "Ma adesso è tutto caldo~ e luminoso~"
  },
  AvgCommunicate_134271_Content_13 = {
    Text = "È tutto merito di %player%."
  },
  AvgCommunicate_134271_Content_14 = {
    Text = "Quindi questo è davvero un ringraziamento sincero?"
  },
  AvgCommunicate_134271_Content_15 = {
    Text = "Hmph~ Certo, posso essere seria ogni tanto, sai!"
  },
  AvgCommunicate_134271_Content_16 = {
    Text = "Ma in cambio — d'ora in poi dovrai passare più tempo con me, ok?"
  },
  AvgCommunicate_134271_Content_17 = {
    Text = "Altrimenti, userò le mie abilità appena apprese per pu~nir~ti per bene~"
  },
  AvgCommunicate_134271_Content_18 = {
    Text = "...È davvero così che mostri la tua gratitudine?!"
  },
  AvgCommunicate_134271_Content_19 = {
    Text = "Oh mio, questo è il modo esclusivo di Pandia per esprimere amore~ Mwah~ Ricordati di essere grato!"
  },
  AvgCommunicate_134271_Content_2 = {
    Text = "Che marachella stai combinando adesso?"
  },
  AvgCommunicate_134271_Content_3 = {
    Text = "Come puoi dire una cosa del genere! Sono qui per ringraziarti sinceramente!"
  },
  AvgCommunicate_134271_Content_4 = {
    Text = "Quelle cose buone che mi hai dato prima… hanno fatto sentire il mio corpo così caldo, così caldo~"
  },
  AvgCommunicate_134271_Content_5 = {
    Text = "È come se qualcosa di bollente scorresse sotto la mia pelle, dolce e piccante~"
  },
  AvgCommunicate_134271_Content_6 = {
    Text = "Anche se so che non ci saranno effetti collaterali, sei sicura che questo non sia un effetto collaterale..."
  },
  AvgCommunicate_134271_Content_7 = {
    Text = "Non è vero! Questa sensazione è incredibile! Cento volte più emozionante di qualsiasi frustata!"
  },
  AvgCommunicate_134271_Content_8 = {
    Text = "E sai una cosa, la parte più incredibile è..."
  },
  AvgCommunicate_134271_Content_9 = {
    Text = "Quel vuoto nel mio cuore... è stato colmato."
  },
  AvgCommunicate_134271_Option_14 = {Text = "Quindi"},
  AvgCommunicate_134271_Option_6 = {Text = "Anche se"},
  AvgCommunicate_134272_Content_1 = {
    Text = "Master~ Come potrà mai Karen ricambiare? Bevande, pulizie, pasti—sentiti libero di dare ordini a Karen!"
  },
  AvgCommunicate_134272_Content_10 = {
    Text = "Ogni volta che Karen lo desidera, la pelle di Karen può risplendere più brillantemente delle gemme più preziose e scintillare più radiosamente delle perle più perfette."
  },
  AvgCommunicate_134272_Content_11 = {
    Text = "Se Karen andasse a un Ballo adesso, Karen sarebbe sicuramente al centro dell'attenzione, non più la piccola sconosciuta di cui nessuno si cura."
  },
  AvgCommunicate_134272_Content_12 = {
    Text = "Anche se non credo che questo sia lo scopo principale del Potenziamento dell'Assioma Assoluto, però..."
  },
  AvgCommunicate_134272_Content_13 = {
    Text = "Finché ti rende felice, è tutto ciò che conta."
  },
  AvgCommunicate_134272_Content_2 = {
    Text = "Prima di tutto, escludiamo i pasti!"
  },
  AvgCommunicate_134272_Content_3 = {
    Text = "Oh mio, le mie abilità domestiche vengono messe in dubbio. Karen dovrebbe essere triste per questo, ma, ma..."
  },
  AvgCommunicate_134272_Content_4 = {
    Text = "Così tanti, così tanti gioielli e accessori! Karen si sente come la gemma più splendente di sempre. È davvero difficile per Karen essere triste!"
  },
  AvgCommunicate_134272_Content_5 = {
    Text = "Prima calmati un po'. Riesco a malapena a capire cosa stai dicendo ormai."
  },
  AvgCommunicate_134272_Content_6 = {
    Text = "Mi dispiace, Karen si è emozionata troppo. Dopo che il Master ha aiutato Karen a comprendere quella cosa... cos'era, una forcina? Un nastro o qualcosa del genere..."
  },
  AvgCommunicate_134272_Content_7 = {
    Text = "...È un Assioma."
  },
  AvgCommunicate_134272_Content_8 = {
    Text = "Oh giusto, quella cosa costosissima e incredibile. E poi, Karen ha sentito di aver ottenuto un'abilità incredibilmente potente."
  },
  AvgCommunicate_134272_Content_9 = {
    Text = "Non solo l'efficienza nello svolgere le faccende domestiche è migliorata enormemente, ma soprattutto il corpo di Karen brilla e scintilla."
  },
  AvgCommunicate_134272_Option_7 = {
    Text = "Non è una forcina"
  },
  AvgCommunicate_134273_Content_1 = {
    Text = "%player%, il mio Legame con te si è fatto più profondo."
  },
  AvgCommunicate_134273_Content_10 = {
    Text = "Cose come i risultati di analisi matematica, le domande degli esami di cultura generale, e roba del genere — anche quelle si possono ottenere direttamente dalla conoscenza infinita?"
  },
  AvgCommunicate_134273_Content_11 = {Text = "..."},
  AvgCommunicate_134273_Content_12 = {
    Text = "In effetti, non hai più bisogno di memorizzare faticosamente così tante cose."
  },
  AvgCommunicate_134273_Content_13 = {
    Text = "Ma credo che il significato dell'apprendimento risieda nel processo di ricerca della conoscenza e nell'allenamento del Potere del pensiero."
  },
  AvgCommunicate_134273_Content_14 = {
    Text = "Devi prima sapere ciò che non sai e ciò che dovresti sapere, prima di poter trovare la risposta di cui hai bisogno dall'infinito tesoro del sapere."
  },
  AvgCommunicate_134273_Content_15 = {
    Text = "Va bene, capisco. Anche se la risposta è diversa da quella di Ramona, il risultato è lo stesso, dopotutto."
  },
  AvgCommunicate_134273_Content_16 = {
    Text = "Studierò, studierò, va bene?!"
  },
  AvgCommunicate_134273_Content_17 = {
    Text = "Sono lieta di vedere la tua voglia di imparare. Continua così. Sarò, come sempre, al tuo fianco."
  },
  AvgCommunicate_134273_Content_2 = {
    Text = "Congratulazioni, e grazie per i tuoi sforzi. Ora posso raccogliere più frammenti di coscienza e celare un'esistenza più completa nelle crepe del mondo."
  },
  AvgCommunicate_134273_Content_3 = {
    Text = "Puoi scendere nel mondo adesso!?"
  },
  AvgCommunicate_134273_Content_4 = {
    Text = "Purtroppo, non posso ancora rivelare davvero la mia esistenza, né lasciare la Pozza Nera."
  },
  AvgCommunicate_134273_Content_5 = {
    Text = "Ma il mio spirito, il mio Sogno, il mio sguardo sui molteplici mondi — ora possono esistere in modo più completo, e giungerti in modo più ricco."
  },
  AvgCommunicate_134273_Content_6 = {
    Text = "Come minimo, ora possiedi la Chiave della conoscenza infinita."
  },
  AvgCommunicate_134273_Content_7 = {
    Text = "Vuoi dire che qualunque cosa chieda, posso ottenere una risposta?"
  },
  AvgCommunicate_134273_Content_8 = {
    Text = "Purché esista, o possa essere dimostrata."
  },
  AvgCommunicate_134273_Content_9 = {
    Text = "Eheh, per esempio, intendo solo per esempio."
  },
  AvgCommunicate_134273_Option_15 = {Text = "Capisco"},
  AvgCommunicate_134273_Option_7 = {
    Text = "Conoscenza infinita?"
  },
  AvgCommunicate_134274_Content_1 = {
    Text = "Il seme... è diventato più completo."
  },
  AvgCommunicate_134274_Content_10 = {
    Text = "Scene così vivaci sono ancora troppo snervanti per me."
  },
  AvgCommunicate_134274_Content_11 = {
    Text = "Non preoccuparti. Sarò proprio lì con te, e anche Tintura."
  },
  AvgCommunicate_134274_Content_12 = {
    Text = "Ovviamente, se ti senti più a tuo agio da sola, supporto pienamente la tua decisione!"
  },
  AvgCommunicate_134274_Content_13 = {
    Text = "Custode... grazie, se è ciò che tu e Tintura vi aspettate."
  },
  AvgCommunicate_134274_Content_14 = {
    Text = "Hmm... cominciamo con l'adattarmi nell'angolo in fondo all'aula."
  },
  AvgCommunicate_134274_Content_2 = {
    Text = "Riesco a sentirlo: un Potere capace di sostenere la mia germogliazione, che gradualmente colma il vuoto nella mia anima."
  },
  AvgCommunicate_134274_Content_3 = {
    Text = "Quindi... significa che non prosciugherai più la forza vitale degli altri?"
  },
  AvgCommunicate_134274_Content_4 = {
    Text = "Purtroppo, questa mia abilità innata non è scomparsa."
  },
  AvgCommunicate_134274_Content_5 = {
    Text = "Tuttavia, sto iniziando a ottenere il controllo su questo Potere."
  },
  AvgCommunicate_134274_Content_6 = {
    Text = "Finché continuerò a esercitarmi, gli Investigatori che entreranno in contatto con me non dovranno più indossare quelle ingombranti tute protettive."
  },
  AvgCommunicate_134274_Content_7 = {
    Text = "Ora c'è la possibilità che io possa restare al fianco di tutti in sicurezza."
  },
  AvgCommunicate_134274_Content_8 = {
    Text = "È meraviglioso! D'ora in poi potrai partecipare a ogni tipo di attività scolastica, galà e persino feste tra Risvegliatori."
  },
  AvgCommunicate_134274_Content_9 = {
    Text = "F-feste... Credo che padroneggiare la capacità di andare d'accordo con le persone sia molto più difficile che padroneggiare il controllo sui miei istinti."
  },
  AvgCommunicate_134274_Option_11 = {
    Text = "Non preoccuparti"
  },
  AvgCommunicate_134274_Option_3 = {Text = "Quindi..."},
  AvgCommunicate_134274_Option_8 = {
    Text = "È meraviglioso!"
  },
  AvgCommunicate_134275_Content_1 = {
    Text = "È vostro privilegio offrire alla Principessa ogni cosa di nobiltà."
  },
  AvgCommunicate_134275_Content_10 = {
    Text = "...Grazie? Non stai semplicemente cercando di comprarmi con dei regali, per poi sentirti dire qualche parola di incoraggiamento da parte mia, o farmi soddisfare qualche tua aspettativa?"
  },
  AvgCommunicate_134275_Content_11 = {
    Text = "Murphy, ti faccio dei regali e ti tratto bene semplicemente perché sei tu."
  },
  AvgCommunicate_134275_Content_12 = {
    Text = "Non ha nulla a che fare con il fatto che tu sia una principessa, la Madre Divina, o qualsiasi altra cosa. Sei la mia amica. Al di là di questo, non ho altre aspettative."
  },
  AvgCommunicate_134275_Content_13 = {Text = "..."},
  AvgCommunicate_134275_Content_14 = {
    Text = "Hmph! Questo è... sono solo le solite chiacchiere melliflue e dalla lingua d'argento! Pensi che dire una cosa del genere mi commuoverà fino alle lacrime?"
  },
  AvgCommunicate_134275_Content_15 = {
    Text = "Sintomo: Delirio! Cosa intendi con amica? Ti basta essere un Seguace leale, e questo è sufficiente."
  },
  AvgCommunicate_134275_Content_16 = {
    Text = "Che cosa crudele da dire. Piangerò davvero tutta la notte stasera, lo sai?"
  },
  AvgCommunicate_134275_Content_17 = {
    Text = "Tu... tu, oh, che sciocco inutile."
  },
  AvgCommunicate_134275_Content_18 = {
    Text = "Solo per questa volta, quindi ascolta bene."
  },
  AvgCommunicate_134275_Content_19 = {Text = "Grazie."},
  AvgCommunicate_134275_Content_2 = {
    Text = "Niente male."
  },
  AvgCommunicate_134275_Content_20 = {
    Text = "In ogni caso, d'ora in poi, questa principessa avrà più che abbastanza potere per tenerti al sicuro, quindi sii grato e continua ad adorarmi!"
  },
  AvgCommunicate_134275_Content_3 = {
    Text = "Non hai nient'altro da dire?"
  },
  AvgCommunicate_134275_Content_4 = {
    Text = "Come, questo Potere non mi apparteneva già in primo luogo?"
  },
  AvgCommunicate_134275_Content_5 = {
    Text = "Oh, capisco. Vuoi una ricompensa, una Benedizione, una posizione più elevata, o forse un'Identità più prestigiosa?"
  },
  AvgCommunicate_134275_Content_6 = {Text = "..."},
  AvgCommunicate_134275_Content_7 = {
    Text = "Cosa significa \"...\"? Che seccatura. Non ho alcun interesse a giocare a indovinelli con te."
  },
  AvgCommunicate_134275_Content_8 = {
    Text = "Ti darò un'ultima possibilità. Dimmi cosa vuoi, in fretta. Smettila di girarci intorno."
  },
  AvgCommunicate_134275_Content_9 = {
    Text = "È possibile che, quello che intendo è, potresti almeno dire grazie."
  },
  AvgCommunicate_134275_Option_16 = {
    Text = "Che crudeltà"
  },
  AvgCommunicate_134275_Option_3 = {Text = "Tutto qui?"},
  AvgCommunicate_134275_Option_6 = {Text = "..."},
  AvgCommunicate_134275_Option_9 = {
    Text = "È possibile che"
  },
  AvgCommunicate_134276_Content_1 = {
    Text = "Grazie, Custode, grazie! Io... non so come esprimerlo..."
  },
  AvgCommunicate_134276_Content_10 = {
    Text = "Qualcosa del genere?"
  },
  AvgCommunicate_134276_Content_11 = {
    Text = "Ho sentito dire che i colori portano emozioni e atmosfere diverse all'interno di un dipinto. Potresti creare nuovi colori seguendo la tua personale visione creativa."
  },
  AvgCommunicate_134276_Content_12 = {
    Text = "Oh! Ohhh! Mescolare combinazioni di colori completamente nuove a mio piacimento!"
  },
  AvgCommunicate_134276_Content_13 = {
    Text = "Che idea geniale! Polarizzazioni diverse... texture diverse... Ho già così tante idee!"
  },
  AvgCommunicate_134276_Content_14 = {
    Text = "Scusami, Custode!"
  },
  AvgCommunicate_134276_Content_15 = {
    Text = "Ho la sensazione che il mio prossimo dipinto avrà pennellate ancora più meravigliose."
  },
  AvgCommunicate_134276_Content_16 = {
    Text = "Forse riuscirò davvero a creare un reame dipinto che si connette all'Ignoto. Quando arriverà quel momento, sarai sicuramente il primo a vederlo!"
  },
  AvgCommunicate_134276_Content_2 = {
    Text = "Grazie per avermi dato la possibilità di vedere la Verità Nascosta del mondo— le leggi supreme dell'universo, il colore di base sulla tela della realtà..."
  },
  AvgCommunicate_134276_Content_3 = {
    Text = "Ah, è così bello... Come potrei mai mescolare un colore simile?"
  },
  AvgCommunicate_134276_Content_4 = {
    Text = "Cristallo arcobaleno? Mithril? Madreperla? Polvere di verme cristallino? Ali di farfalla luminosa?"
  },
  AvgCommunicate_134276_Content_5 = {
    Text = "No, no, no... Non si può replicare con materiali così banali e ordinari. Devo pensare di più, devo pensare di più..."
  },
  AvgCommunicate_134276_Content_6 = {
    Text = "Pickman? Ho la sensazione che tu ti sia già perso nella tua arte..."
  },
  AvgCommunicate_134276_Content_7 = {
    Text = "Shh, secondo te com'è il vero colore dell'universo? Una persona speciale come te deve potermi concedere un'Intuizione unica!"
  },
  AvgCommunicate_134276_Content_8 = {
    Text = "Penso che il mondo possa apparire diverso attraverso gli occhi di ciascuno."
  },
  AvgCommunicate_134276_Content_9 = {
    Text = "Oh! Vuoi dire... seguire il mio cuore... seguire le mie sensazioni, e dipingere i diversi colori dell'universo..."
  },
  AvgCommunicate_134276_Option_10 = {Text = "Forse"},
  AvgCommunicate_134276_Option_8 = {Text = "Penso che"},
  AvgCommunicate_134277_Content_1 = {
    Text = "Cu~sto~de dei segreti—"
  },
  AvgCommunicate_134277_Content_10 = {
    Text = "Non proverò pietà per te, non presumerò con condiscendenza la tua logica comportamentale. Spero solo che tu ti diverta in questo mondo."
  },
  AvgCommunicate_134277_Content_11 = {Text = "..."},
  AvgCommunicate_134277_Content_12 = {
    Text = "Wow, chi dei due è più pazzo qui? Per una ragione del genere, affideresti questo livello di Potere a una pazza come me?"
  },
  AvgCommunicate_134277_Content_13 = {
    Text = "Possibile che la mia venuta in questo mondo sia stata un disegno del Fato?"
  },
  AvgCommunicate_134277_Content_15 = {
    Text = "Comunque, grazie a te, ho toccato ciò che mi appartiene nel vostro mondo: il mio \"limite\"."
  },
  AvgCommunicate_134277_Content_16 = {
    Text = "Ora, sbrigati e assegnami una missione! Non vedo l'ora di andare a tagliare qualche testa e mostrarti di cosa sono capace~"
  },
  AvgCommunicate_134277_Content_2 = {
    Text = "Una ragazza bloccata in un mondo straniero riceve un regalo costoso che può renderla più forte. Sai a cosa assomiglia una cosa del genere?"
  },
  AvgCommunicate_134277_Content_3 = {
    Text = "Prima che tu dica qualcosa che devia dai normali processi di pensiero umani, lascia che precisi una cosa: sei un membro di Mythag. Ci aiutiamo a vicenda. Ecco perché ti ho dato quei materiali."
  },
  AvgCommunicate_134277_Content_4 = {
    Text = "Davvero? Non è uno di quei noiosi, contorti comportamenti sociali da facciata tipici degli umani?"
  },
  AvgCommunicate_134277_Content_5 = {
    Text = "\"Non può tornare a casa, poverina, mostriamole un po' più di premura.\""
  },
  AvgCommunicate_134277_Content_6 = {
    Text = "\"Dev'essere così difficile cavarsela da sola, diamole una mano.\" Non è davvero una di quelle motivazioni ad alta frequenza che si trovano in una società ordinaria?"
  },
  AvgCommunicate_134277_Content_7 = {
    Text = "Prima di tutto, in qualunque modo la si guardi, Mouchette, tu non hai niente a che fare con la parola \"ordinaria\"!"
  },
  AvgCommunicate_134277_Content_8 = {
    Text = "Hmph☆hmph, ecco una valutazione che mi piace parecchio."
  },
  AvgCommunicate_134277_Content_9 = {
    Text = "Secondo, indipendentemente dalla tua autopercezione o da come appari in superficie, per me, come hai detto tu, \"Mouchette\" è \"Mouchette\"."
  },
  AvgCommunicate_134277_Option_7 = {
    Text = "Prima di tutto"
  },
  AvgCommunicate_134278_Content_1 = {
    Text = "Grazie, mia cara. Mi hai donato tanta felicità e mi hai permesso di mantenere per sempre la mia ambizione."
  },
  AvgCommunicate_134278_Content_10 = {
    Text = "Qualunque forma di gratitudine tu desideri, posso realizzarla."
  },
  AvgCommunicate_134278_Content_11 = {
    Text = "Anche se non lo possiedo ancora, fossero anche le Stelle e la Luna, troverei il modo di portarteli."
  },
  AvgCommunicate_134278_Content_12 = {
    Text = "Qualsiasi cosa io scelga? Qualsiasi cosa?"
  },
  AvgCommunicate_134278_Content_13 = {
    Text = "Mantenere la parola data è un lasciapassare indispensabile nel mondo della fama e della fortuna."
  },
  AvgCommunicate_134278_Content_14 = {
    Text = "Ebbene, vorrei che Madama mi facesse una promessa. Quanto ai dettagli, avrò bisogno di un po' più di tempo per rifletterci."
  },
  AvgCommunicate_134278_Content_15 = {Text = "..."},
  AvgCommunicate_134278_Content_16 = {
    Text = "Hahahaha, che scelta astuta. Mi piaci sempre di più."
  },
  AvgCommunicate_134278_Content_17 = {
    Text = "Certamente, mio caro. Hai tutto il tempo per pensarci."
  },
  AvgCommunicate_134278_Content_18 = {
    Text = "Se hai tempo, perché non vieni alla mia tenuta stasera? Forse, quando saremo solo noi due... ti verrà più facile trovare una \"buona idea\" davvero originale."
  },
  AvgCommunicate_134278_Content_2 = {
    Text = "Servirvi, mia signora, è un piacere."
  },
  AvgCommunicate_134278_Content_3 = {
    Text = "Hehe, assennato, intelligente, coraggioso, leale, e con quel tocco giusto di... bellezza."
  },
  AvgCommunicate_134278_Content_4 = {
    Text = "Chi potrebbe dire che non sei un perfetto..."
  },
  AvgCommunicate_134278_Content_5 = {
    Text = "...Perfetto cosa?"
  },
  AvgCommunicate_134278_Content_6 = {
    Text = "Sembri un po' nervoso?"
  },
  AvgCommunicate_134278_Content_7 = {
    Text = "La mia signora lascia sempre senza parole."
  },
  AvgCommunicate_134278_Content_8 = {
    Text = "Certe cose non hanno bisogno di essere espresse a parole. I tuoi sentimenti per tutto questo tempo... li ho ricevuti tutti."
  },
  AvgCommunicate_134278_Content_9 = {
    Text = "Terre, proprietà, tesori rari, opere d'arte e l'opportunità di incontrare tante celebrità... con il potere che ho ora, tutto è alla mia portata."
  },
  AvgCommunicate_134278_Option_12 = {
    Text = "Davvero, qualsiasi cosa?"
  },
  AvgCommunicate_134278_Option_14 = {
    Text = "Vorrei una promessa da voi, Madama."
  },
  AvgCommunicate_134278_Option_2 = {
    Text = "È un piacere"
  },
  AvgCommunicate_134278_Option_5 = {Text = "Perfetto?"},
  AvgCommunicate_134278_Option_7 = {Text = "..."},
  AvgCommunicate_134279_Content_1 = {
    Text = "Custode, sei ancora sveglio?"
  },
  AvgCommunicate_134279_Content_10 = {
    Text = "Ma tutto ciò che hai riversato in me... si è raccolto in un nuovo lago dentro di me. Uno ancora più vasto di quel mare."
  },
  AvgCommunicate_134279_Content_11 = {
    Text = "Mi ha detto: non c'è più bisogno di avere paura."
  },
  AvgCommunicate_134279_Content_12 = {
    Text = "So che il dolore forse non si Dissolverà mai del tutto, ma non importa quante volte servirà: ti riporterò sempre a riva."
  },
  AvgCommunicate_134279_Content_13 = {
    Text = "…Se mamma e papà potessero sentirti dire questo, sono sicura che sarebbero in pace."
  },
  AvgCommunicate_134279_Content_14 = {
    Text = "Credo che… forse sono da qualche parte in quel mare, a vegliare su chi sono diventata."
  },
  AvgCommunicate_134279_Content_15 = {
    Text = "D'ora in poi, brandirò questo Potere che mi è stato donato e diventerò la marea che ti farà da Guardiana."
  },
  AvgCommunicate_134279_Content_16 = {
    Text = "Forse… saresti disposto/a a concedermi un'altra audace richiesta?"
  },
  AvgCommunicate_134279_Content_17 = {
    Text = "Di cosa si tratta? Se è qualcosa che posso fare, sarò felice di accontentarti."
  },
  AvgCommunicate_134279_Content_18 = {
    Text = "Quando il cielo si schiarirà, per favore fai una passeggiata in riva al mare con me."
  },
  AvgCommunicate_134279_Content_19 = {
    Text = "Ho così tanto da dirti. Ti chiedo solo un pomeriggio."
  },
  AvgCommunicate_134279_Content_2 = {
    Text = "Mi dispiace se sto disturbando il tuo Riposo…"
  },
  AvgCommunicate_134279_Content_20 = {
    Text = "Certo, nessun problema. Te lo prometto."
  },
  AvgCommunicate_134279_Content_3 = {
    Text = "No, sono ancora sveglio. Cosa c'è che non va?"
  },
  AvgCommunicate_134279_Content_4 = {
    Text = "Dopo aver ricevuto il tuo Dono, sono caduta in un sonno profondo e mi sono persa in un Sogno. Ho sognato quell'oceano di prima, e il tramonto fuori dal Sanatorio."
  },
  AvgCommunicate_134279_Content_5 = {
    Text = "Ma questa volta… non sono entrata nel mare."
  },
  AvgCommunicate_134279_Content_6 = {
    Text = "Sono rimasta sulla riva, a contemplare quel mare. Mi infondeva ancora un senso di pace, eppure non avevo alcun desiderio di andare avanti."
  },
  AvgCommunicate_134279_Content_7 = {
    Text = "Se non è troppo presuntuoso azzardare un'ipotesi... è forse perché questa volta avevi un motivo per restare?"
  },
  AvgCommunicate_134279_Content_8 = {Text = "Certo."},
  AvgCommunicate_134279_Content_9 = {
    Text = "Un tempo ero schiacciata dal dolore. Nulla riusciva a lavare via quel peso che mi serrava la gola... nulla tranne il Mare Profondo, che tutto trascina via e tutto abbraccia."
  },
  AvgCommunicate_134279_Option_12 = {
    Text = "Nymphaea…"
  },
  AvgCommunicate_134279_Option_17 = {Text = "Cosa?"},
  AvgCommunicate_134279_Option_7 = {Text = "Perché..."},
  AvgCommunicate_134280_Content_1 = {
    Text = "%player%, la scorsa notte ho fatto di nuovo quel Sogno."
  },
  AvgCommunicate_134280_Content_10 = {
    Text = "Forse è stato l'Effetto dell'Assioma Assoluto."
  },
  AvgCommunicate_134280_Content_11 = {
    Text = "Sì, quindi voglio dire — a nome di tutti i \"24\", grazie, %player%."
  },
  AvgCommunicate_134280_Content_12 = {
    Text = "Grazie per averci permesso di ascoltarci, vederci, comprenderci e accettarci a vicenda."
  },
  AvgCommunicate_134280_Content_13 = {
    Text = "Non è stato merito mio."
  },
  AvgCommunicate_134280_Content_14 = {
    Text = "No, la guida e il conforto che hai offerto hanno placato tutti gli spiriti irrequieti."
  },
  AvgCommunicate_134280_Content_15 = {
    Text = "È stata la tua presenza a far convergere tutti i fiumi in uno solo."
  },
  AvgCommunicate_134280_Content_16 = {
    Text = "\"Io\" — tutti noi — non dimenticheremo mai la tua gentilezza."
  },
  AvgCommunicate_134280_Content_2 = {
    Text = "Mi sembrava di essere tornata ai piedi delle montagne innevate dell'estremo nord, dentro una caverna buia come la pece."
  },
  AvgCommunicate_134280_Content_3 = {
    Text = "Innumerevoli masse di melma, che riflettevano innumerevoli ombre di \"24\"…"
  },
  AvgCommunicate_134280_Content_4 = {
    Text = "Quelli… sono tutti te, tutti una parte di te."
  },
  AvgCommunicate_134280_Content_5 = {Text = "Lo so."},
  AvgCommunicate_134280_Content_6 = {
    Text = "In mezzo alla Confusione, mi è sembrato di sentire qualcuno dirmi qualcosa."
  },
  AvgCommunicate_134280_Content_7 = {
    Text = "La voce era confusa. Non riuscivo a distinguerla chiaramente…"
  },
  AvgCommunicate_134280_Content_8 = {
    Text = "Ma dopo che quella persona se ne è andata, ho sentito tutto il clamore intorno a me placarsi in una calma serena."
  },
  AvgCommunicate_134280_Content_9 = {
    Text = "I sussurri rumorosi nelle mie orecchie sono diventati armoniosi e naturali, come se fossero una melodia concordante…"
  },
  AvgCommunicate_134280_Option_4 = {
    Text = "Sono tutti te."
  },
  AvgCommunicate_134281_Content_1 = {
    Text = "Custode, credi nel Destino?"
  },
  AvgCommunicate_134281_Content_10 = {
    Text = "...Da persona comune, riesco a malapena a immaginare quanto sia fantastico. Permettimi di chiedere a denti stretti: che sensazione si prova esattamente?"
  },
  AvgCommunicate_134281_Content_11 = {
    Text = "Come potrei descriverlo? Per esempio, in questo momento ho un po' di fame..."
  },
  AvgCommunicate_134281_Content_12 = {Text = "? E poi?"},
  AvgCommunicate_134281_Content_13 = {
    Text = "Oh, scusa per l'attesa. Qualcuno ha appena bussato alla porta: era la signorina Mason che condivideva un plumcake appena sfornato."
  },
  AvgCommunicate_134281_Content_14 = {Text = "Cosa???"},
  AvgCommunicate_134281_Content_15 = {
    Text = "Proprio così. E poi... ho un po' di sete."
  },
  AvgCommunicate_134281_Content_16 = {
    Text = "Hm? Il maggiordomo del signor Doresain ha appena consegnato un invito, dicendo che vorrebbe invitarmi a degustare la sua collezione di vini rossi conservata in un ristorante vicino."
  },
  AvgCommunicate_134281_Content_17 = {
    Text = "...Basta. La prossima volta, potresti sinceramente desiderare di aiutarmi con i compiti?"
  },
  AvgCommunicate_134281_Content_18 = {
    Text = "Hahaha, come desideri, %player%. Ora sei il mio più grande mecenate, sponsor, buon partner e indispensabile Watson."
  },
  AvgCommunicate_134281_Content_19 = {
    Text = "Detective Fortunato, felicissimo di essere al vostro servizio."
  },
  AvgCommunicate_134281_Content_2 = {
    Text = "Io credo nel Destino, e credo di possedere il Destino più fortunato di tutti."
  },
  AvgCommunicate_134281_Content_3 = {
    Text = "Gioie inaspettate, fortune improvvise, benedizioni che cadono dal cielo — quando queste cose mi capitano all'improvviso, ormai non batto nemmeno più ciglio."
  },
  AvgCommunicate_134281_Content_4 = {
    Text = "Una volta abituati al favore del Destino, tutte le piacevoli sorprese diventano insignificanti."
  },
  AvgCommunicate_134281_Content_5 = {
    Text = "Quello che hai appena detto fa davvero sia invidia che rabbia."
  },
  AvgCommunicate_134281_Content_6 = {
    Text = "Aspetta, non ho ancora finito. Incontrare te è la cosa più fortunata tra tutte le mie fortune."
  },
  AvgCommunicate_134281_Content_7 = {
    Text = "Ciò che mi dai porta sempre nuove sorprese."
  },
  AvgCommunicate_134281_Content_8 = {
    Text = "Proprio come adesso — il Potere che è Emerso dopo aver compreso l'Assioma Assoluto mi permette già di percepire chiaramente ogni colpo di fortuna prima che arrivi."
  },
  AvgCommunicate_134281_Content_9 = {
    Text = "Le cose fortunate cadono come gocce di pioggia — da una pioggerellina leggera, whoosh — in un acquazzone torrenziale."
  },
  AvgCommunicate_134281_Option_10 = {
    Text = "Che sensazione si prova?"
  },
  AvgCommunicate_134281_Option_14 = {Text = "???"},
  AvgCommunicate_134281_Option_5 = {
    Text = "Fa sia invidia che rabbia"
  },
  AvgCommunicate_137645_Content_1 = {Text = "Custode."},
  AvgCommunicate_137645_Content_10 = {
    Text = "Ma con tutte quelle zampe, non è un po' ingiusto che tu partecipi a una gara di corsa..."
  },
  AvgCommunicate_137645_Content_11 = {
    Text = "Castor ha le ali, e Nautila ha portato anche il suo veicolo."
  },
  AvgCommunicate_137645_Content_12 = {
    Text = "Di solito Tesso nel teatro e non sono portata per lo sport. Tuttavia, ho già iscritto la mia Ancella."
  },
  AvgCommunicate_137645_Content_13 = {
    Text = "È difficile immaginare perché qualcosa del genere possa interessarti."
  },
  AvgCommunicate_137645_Content_14 = {
    Text = "Osservare le persone rivelare la loro vibrante vitalità e la loro tenace volontà nel perseguire un obiettivo è davvero una cosa deliziosa."
  },
  AvgCommunicate_137645_Content_15 = {
    Text = "E... sono piuttosto curiosa di sapere che tipo di magia possieda quella torta offerta come premio, per aver ammaliato persino Tawil a tal punto."
  },
  AvgCommunicate_137645_Content_16 = {
    Text = "Purché non si tratti di una scelta che distrugge un mondo, tutto è lecito..."
  },
  AvgCommunicate_137645_Content_17 = {
    Text = "Ehm, non useresti i Fili del Destino per manipolare i risultati della competizione, vero?"
  },
  AvgCommunicate_137645_Content_18 = {
    Text = "...Arachne?"
  },
  AvgCommunicate_137645_Content_2 = {
    Text = "Che succede?"
  },
  AvgCommunicate_137645_Content_20 = {
    Text = "Ci vediamo nell'Audience, Custode."
  },
  AvgCommunicate_137645_Content_3 = {
    Text = "Pensi che... che tipo di Destino possa essere definito giusto e retto?"
  },
  AvgCommunicate_137645_Content_4 = {
    Text = "Giusto e retto?... Probabilmente proteggere il più possibile gli interessi della maggioranza."
  },
  AvgCommunicate_137645_Content_5 = {
    Text = "E se — gli interessi dei pochi fossero destinati a essere Sacrificati? Approvi una simile direzione del Destino, giusto?"
  },
  AvgCommunicate_137645_Content_6 = {
    Text = "Tu... perché lo chiedi all'improvviso? Non fraintendere ciò che intendevo!"
  },
  AvgCommunicate_137645_Content_7 = {
    Text = "Se stai per fare qualcosa come distruggere di nuovo qualche mondo, ti prego di ripensarci, Arachne!"
  },
  AvgCommunicate_137645_Content_8 = {
    Text = "Non c'è bisogno di preoccuparsi, Custode. È solo una gara di corsa."
  },
  AvgCommunicate_137645_Content_9 = {
    Text = "Uff... mi hai spaventato..."
  },
  AvgCommunicate_137645_Option_2 = {
    Text = "Che succede?"
  },
  AvgCommunicate_137646_Content_1 = {
    Text = "Custode, avendo saputo che saresti partito per un'indagine lontana, ho composto un'opera appositamente per te."
  },
  AvgCommunicate_137646_Content_10 = {
    Text = "Il tuo senso per i nomi è davvero qualcosa, Arachne..."
  },
  AvgCommunicate_137646_Content_11 = {
    Text = "Ogni filo tessuto ha il suo proprietario predestinato. Ogni storia, allo stesso modo, ha il suo lettore."
  },
  AvgCommunicate_137646_Content_12 = {
    Text = "Un nome che si diffonde facilmente può aiutare queste eccellenti storie a raggiungere più persone a cui sono destinate."
  },
  AvgCommunicate_137646_Content_13 = {
    Text = "Per esempio, quest'opera bestseller..."
  },
  AvgCommunicate_137646_Content_14 = {
    Text = "\"Guida alla Cucina delle Creature di Aequor\"? Bestseller?"
  },
  AvgCommunicate_137646_Content_15 = {
    Text = "Non dirmi che Doresain ne ha comprata una copia per ogni singola persona di Necrovia..."
  },
  AvgCommunicate_137646_Content_16 = {
    Text = "Tulu lo sa?"
  },
  AvgCommunicate_137646_Content_18 = {
    Text = "È proprio questa profonda capacità di leggere il cuore umano e il Destino che mi spinge ad ammirarti sinceramente."
  },
  AvgCommunicate_137646_Content_19 = {
    Text = "\"Tutti amano il Custode\"."
  },
  AvgCommunicate_137646_Content_2 = {
    Text = "Inizialmente volevo allestire una rappresentazione teatrale per te, ma considerando la trasportabilità, l'ho scritta sotto forma di romanzo."
  },
  AvgCommunicate_137646_Content_20 = {
    Text = "Ti prego, porta quest'opera con te all'Inizio del tuo Viaggio."
  },
  AvgCommunicate_137646_Content_3 = {
    Text = "Quello è..."
  },
  AvgCommunicate_137646_Content_4 = {
    Text = "\"Il Grande Custode\"? \"L'Odissea del Custode\"? \"Il Mondo del Custode\"?"
  },
  AvgCommunicate_137646_Content_5 = {
    Text = "Ma cosa scrivi di solito!? C'è qualcuno che legge davvero queste cose???"
  },
  AvgCommunicate_137646_Content_6 = {
    Text = "Non sottovalutare la tua popolarità a Mythag. Sono tutte opere estremamente apprezzate."
  },
  AvgCommunicate_137646_Content_7 = {
    Text = "Un Destino così drammatico merita naturalmente di essere presentato al mondo."
  },
  AvgCommunicate_137646_Content_8 = {
    Text = "In realtà, non riguarda solo te. Ho intessuto storie anche sui Destini di altri."
  },
  AvgCommunicate_137646_Content_9 = {
    Text = "\"Cinque Anni sul Campo di Battaglia, Tre Anni di Simulazioni\", \"Cura Postnatale per Topi\", \"La Grande Esposizione dell'Arte della Cera Colante\"..."
  },
  AvgCommunicate_137646_Option_3 = {
    Text = "Quello è..."
  },
  AvgCommunicate_137647_Content_1 = {
    Text = "Connettere le persone attraverso tempi e spazi diversi con fili invisibili..."
  },
  AvgCommunicate_137647_Content_10 = {
    Text = "Non vedo l'ora, Custode."
  },
  AvgCommunicate_137647_Content_2 = {
    Text = "La civiltà umana non smette mai di sorprendermi."
  },
  AvgCommunicate_137647_Content_3 = {Text = "Sorpresa?"},
  AvgCommunicate_137647_Content_4 = {
    Text = "Ma questi destini non sono forse scelti dalla tua stessa mano?"
  },
  AvgCommunicate_137647_Content_5 = {
    Text = "Ciò che scelgo è solo la direzione. Tutta la civiltà e la storia sono comunque create da voi stessi."
  },
  AvgCommunicate_137647_Content_6 = {
    Text = "I Fili del Destino, estendendosi naturalmente, alla fine daranno Gestazione a nuove creazioni, di origini ignote."
  },
  AvgCommunicate_137647_Content_7 = {
    Text = "È essendo Testimone Silenziosa di tutto ciò, grazie alla gioia di questa Tessitura, che riesco a portare avanti questa responsabilità."
  },
  AvgCommunicate_137647_Content_8 = {Text = "Capisco..."},
  AvgCommunicate_137647_Content_9 = {
    Text = "Se ci saranno nuove creazioni, ti prego di farmele apprezzare."
  },
  AvgCommunicate_137647_Option_3 = {Text = "Sorpresa?"},
  AvgCommunicate_140194_Content_1 = {
    Text = "Qualcosa non quadra. Il fatto che nessuno abbia paura di me..."
  },
  AvgCommunicate_140194_Content_10 = {
    Text = "Non preoccuparti, sono stati tutti così gentili con me! Sono al sicuro!"
  },
  AvgCommunicate_140194_Content_11 = {
    Text = "...Probabilmente. Per ora."
  },
  AvgCommunicate_140194_Content_12 = {
    Text = "Per ora? ...Per favore, rendilo definitivo!"
  },
  AvgCommunicate_140194_Content_13 = {Text = "Per ora~!"},
  AvgCommunicate_140194_Content_2 = {
    Text = "Doll ha sviluppato un feromone speciale. In questo momento, agli occhi di tutti sembri nient'altro che una normale ragazza umana."
  },
  AvgCommunicate_140194_Content_4 = {
    Text = "Comodo, suppongo, ma..."
  },
  AvgCommunicate_140194_Content_5 = {
    Text = "È quasi un po' deludente non poter più spaventare la gente?"
  },
  AvgCommunicate_140194_Content_6 = {Text = "...?"},
  AvgCommunicate_140194_Content_7 = {
    Text = "Come dire... hmm... per esempio, renderà la mia \"caccia\" più difficile..."
  },
  AvgCommunicate_140194_Content_8 = {
    Text = "Ultimamente non ho avuto problemi a trovare pasti, quindi la caccia non è un bisogno urgente, ma... a volte... già..."
  },
  AvgCommunicate_140194_Content_9 = {
    Text = "Ormai sono quasi abituata a sentire i Risvegliatori dire cose deliranti, ma devo comunque dirtelo... Questa è una cosa molto pericolosa da dire!"
  },
  AvgCommunicate_140195_Content_1 = {
    Text = "Richiesta d'acquisto"
  },
  AvgCommunicate_140195_Content_10 = {
    Text = "...E farò finta di non essere assolutamente al corrente di nulla di tutto questo. D'accordo?"
  },
  AvgCommunicate_140195_Content_2 = {
    Text = "Quattro grandi frigoriferi domestici... Il budget dell'università non è esattamente sotto pressione, ma a cosa ti servono questi frigoriferi?"
  },
  AvgCommunicate_140195_Content_3 = {
    Text = "Se ricordo bene, Saya, ne avevi già richiesto uno da mettere nel tuo dormitorio il primo giorno del trasferimento."
  },
  AvgCommunicate_140195_Content_4 = {
    Text = "Beh, ehm... Non si sa mai quando lo spazio nel frigorifero potrebbe tornare utile..."
  },
  AvgCommunicate_140195_Content_5 = {
    Text = "E poi, sai, la freschezza della carne è importante..."
  },
  AvgCommunicate_140195_Content_6 = {Text = "..."},
  AvgCommunicate_140195_Content_7 = {
    Text = "Mi dispiace, ma non posso approvare altri frigoriferi. Tuttavia, ti passerò i contatti di Xu e Doresain."
  },
  AvgCommunicate_140195_Content_9 = {
    Text = "Penso che ti divertiresti a parlare con loro di cibo e ricette."
  },
  AvgCommunicate_140196_Content_1 = {Text = "¥%&#...%"},
  AvgCommunicate_140196_Content_10 = {Text = "..."},
  AvgCommunicate_140196_Content_11 = {
    Text = "Sbagliato! Dovevi dire Splash Splash!"
  },
  AvgCommunicate_140196_Content_12 = {
    Text = "A quanto pare, il feromone sviluppato dalla Professoressa Doll non funziona sulla Signorina Vortice."
  },
  AvgCommunicate_140196_Content_13 = {
    Text = "Ma lei mi tratta comunque allo stesso modo. Il suo atteggiamento non è cambiato per niente."
  },
  AvgCommunicate_140196_Content_14 = {
    Text = "Penso che sia perché, ehm, come posso dire..."
  },
  AvgCommunicate_140196_Content_15 = {
    Text = "...Forse Vortice è semplicemente dotato di... abilità sociali straordinarie?"
  },
  AvgCommunicate_140196_Content_2 = {
    Text = "A... Abbandonare. Ah, un'altra parola imparata. Hmm."
  },
  AvgCommunicate_140196_Content_3 = {Text = "?"},
  AvgCommunicate_140196_Content_4 = {
    Text = "Ultimamente ho studiato ogni tipo di lingua. ...È affascinante."
  },
  AvgCommunicate_140196_Content_6 = {
    Text = "Oltre al Leoniano standard, ho anche imparato un sacco di nuovi vocaboli. Per esempio..."
  },
  AvgCommunicate_140196_Content_7 = {Text = "Glu glu?"},
  AvgCommunicate_140196_Content_8 = {Text = "Plic ploc!"},
  AvgCommunicate_140196_Content_9 = {Text = "Corretto!"},
  AvgCommunicate_140196_Option_10 = {Text = "..."},
  AvgCommunicate_140196_Option_8 = {Text = "Plic ploc!"},
  AvgCommunicate_141374_Content_1 = {
    Text = "Un ringraziamento così formale potrebbe sembrare un po' distaccato, ma, dal profondo del cuore, grazie a te, per me stesso e per l'intera Ebwynnos."
  },
  AvgCommunicate_141374_Content_10 = {
    Text = "Se mostro queste qualità, è perché è nella mia natura."
  },
  AvgCommunicate_141374_Content_12 = {
    Text = "Non dire queste cose con un tono così orgoglioso."
  },
  AvgCommunicate_141374_Content_13 = {
    Text = "Quindi, avermi aiutato a toccare quel limite e a liberarmi dal Suo controllo è stato davvero un grande favore."
  },
  AvgCommunicate_141374_Content_14 = {
    Text = "Molte cose che prima erano difficili da fare ora non sono più un problema."
  },
  AvgCommunicate_141374_Content_15 = {
    Text = "È ancora in tempo per riprendere indietro quello che ho detto?"
  },
  AvgCommunicate_141374_Content_16 = {
    Text = "Calmati, Pontos, Londinium ha un sistema giuridico ben consolidato!"
  },
  AvgCommunicate_141374_Content_2 = {
    Text = "Essere così serio all'improvviso, è davvero un po' insolito."
  },
  AvgCommunicate_141374_Content_3 = {
    Text = "Probabilmente non sai cosa significhi: prima che io diventassi abbastanza forte, Ebwynnos non riusciva in realtà a liberarsi dal controllo di quell'antica presenza."
  },
  AvgCommunicate_141374_Content_4 = {
    Text = "Questo era l'accordo che avevo stipulato con Lui; per fortuna, non nutriva alcuna malizia, si potrebbe persino dire che fosse magnanimo."
  },
  AvgCommunicate_141374_Content_5 = {
    Text = "Eppure Lui non appartiene all'umanità, e sotto il Suo controllo, Ebwynnos sarebbe diventata ancora più imprevedibile, e le persone di Ebwynnos avrebbero avuto indoli ancora più estreme."
  },
  AvgCommunicate_141374_Content_6 = {
    Text = "Detto così, forse anche prima eri così a causa della Sua influenza, così, ehm…"
  },
  AvgCommunicate_141374_Content_7 = {
    Text = "Lasciami indovinare, vuoi dire Morsa della paranoia, rancore, o mania di controllo?"
  },
  AvgCommunicate_141374_Content_9 = {Text = "No."},
  AvgCommunicate_141374_Option_2 = {
    Text = "Un po' insolito"
  },
  AvgCommunicate_141374_Option_6 = {Text = "Forse"},
  AvgCommunicate_143429_Content_1 = {
    Text = "Sebbene questi Seguaci del Culto che venerano falsi dei siano così stupidi da far ridere, bisogna ammettere che alcuni di loro hanno un gusto non del tutto privo di raffinatezza."
  },
  AvgCommunicate_143429_Content_10 = {
    Text = "E poi non sono nemmeno ambientati nell'epoca giusta!"
  },
  AvgCommunicate_143429_Content_11 = {
    Text = "Io invece penso che se tu ti lasciassi ispirare da questo tipo di cose e sviluppassi più ambizione, potresti ridurre notevolmente il numero di volte in cui ti trovi in pericolo durante le missioni esterne e chiedi aiuto."
  },
  AvgCommunicate_143429_Content_12 = {
    Text = "Certo, se mi chiami zio qualche volta in più, sono ben felice di continuare a salvare i ragazzini che non hanno voglia di crescere."
  },
  AvgCommunicate_143429_Content_13 = {
    Text = "…Vado subito a parlare con Golia."
  },
  AvgCommunicate_143429_Content_14 = {
    Text = "Li aggiungerò alla lista dei film vietati di Mythag, non si possono consigliare così a casaccio!"
  },
  AvgCommunicate_143429_Content_2 = {
    Text = "Già qualche giorno fa ero rimasta sconvolta quando lui, all'insaputa di Miryam, si allontanava frequentemente da Mythag…"
  },
  AvgCommunicate_143429_Content_3 = {
    Text = "Non starai mica parlando di Golia…"
  },
  AvgCommunicate_143429_Content_4 = {
    Text = "Beh, prima di tutto, apprezzo molto la sua determinazione nel sottomettersi agli altri pur di raggiungere i propri obiettivi."
  },
  AvgCommunicate_143429_Content_5 = {
    Text = "Inoltre, i titoli che ha consigliato sono davvero molto interessanti."
  },
  AvgCommunicate_143429_Content_6 = {
    Text = "È difficile immaginare che Golia frequenti il teatro."
  },
  AvgCommunicate_143429_Content_7 = {
    Text = "Mi ha consigliato <Italic:C'era una volta a Leonia> e <Italic:Il Pa▼drino>—tutti li hanno amati."
  },
  AvgCommunicate_143429_Content_8 = {
    Text = "Stasera, Ebwynnos dovrebbe proiettare \"Il lupo di Londinium\"."
  },
  AvgCommunicate_143429_Content_9 = {
    Text = "No, aspetta, Mythag non ammette boss della malavita, né cultura del lupo dominante!"
  },
  AvgCommunicate_143429_Option_2 = {
    Text = "Non vorrai dire che"
  },
  AvgCommunicate_143430_Content_1 = {
    Text = "La sesta domanda di trasferimento di residenza di questo mese, a quanto pare i regolamenti dell'ufficio scolastico non funzionano sempre."
  },
  AvgCommunicate_143430_Content_10 = {
    Text = "Ah, peccato."
  },
  AvgCommunicate_143430_Content_11 = {
    Text = "Eh?? Ehi?! Perché c'è un Incubo che ha tirato fuori un foglio con le risposte dell'esame e si è seduto a scrivere la mia tesi?"
  },
  AvgCommunicate_143430_Content_12 = {
    Text = "Hai troppe responsabilità sulle spalle, anche solo dire una cosa del genere per scherzo dimostra che dovresti davvero Relax un po', piccolo."
  },
  AvgCommunicate_143430_Content_13 = {
    Text = "Solo per questa volta, anche se lo farei volentieri, cercherò comunque di non diventare quel tipo di genitore che vizia i figli."
  },
  AvgCommunicate_143430_Content_14 = {
    Text = "Adesso, apri la finestra, ti porto a divertirti per una notte, a scoprire il piacere di dimenticare la realtà senza dover andare a Ebwynnos."
  },
  AvgCommunicate_143430_Content_15 = {Text = "……Sì!"},
  AvgCommunicate_143430_Content_3 = {
    Text = "Media dei voti, presenze, tasso di conversione pratica efficace, ehm, e la pressione lavorativa che, pur non riguardando i Custodi, affligge la maggior parte degli Studenti comuni."
  },
  AvgCommunicate_143430_Content_4 = {
    Text = "Anche quando la Dissoluzione è a portata di mano, i problemi della realtà fanno ancora paura."
  },
  AvgCommunicate_143430_Content_5 = {
    Text = "È normale che tutti vogliano fuggire dalla realtà, perché non mi porti anche a Ebwynnos……"
  },
  AvgCommunicate_143430_Content_6 = {
    Text = "Dici sul serio?"
  },
  AvgCommunicate_143430_Content_7 = {
    Text = "Fuori dalla finestra c'è davvero il suono di ali che sbattono, o sto avendo Fantasmi dopo tre notti consecutive di studio."
  },
  AvgCommunicate_143430_Content_8 = {
    Text = "L'occasione non capita due volte, con un'opportunità così buona, anche se poi tutto Mythag dovesse venire a cercarmi, accetterei con grandissimo piacere."
  },
  AvgCommunicate_143430_Content_9 = {
    Text = "No no no no no no stavo scherzando ti prego non fare mai una cosa del genere."
  },
  AvgCommunicate_143431_Content_1 = {
    Text = "Hai bisogno di me?"
  },
  AvgCommunicate_143431_Content_10 = {
    Text = "Ahahahahaha, dai, non fare quella Espressione."
  },
  AvgCommunicate_143431_Content_11 = {
    Text = "Procurarsi il suo sigillo privato non è una cosa difficile, quanto all'indirizzo del banchetto di beneficenza, che ne dici di tenerlo a Ebwynnos?"
  },
  AvgCommunicate_143431_Content_12 = {
    Text = "Il passo successivo sarà che la polizia ci arresterà tutti per violazione di proprietà privata."
  },
  AvgCommunicate_143431_Content_14 = {
    Text = "Va bene, peccato, Schivare per qualche giorno temporaneamente."
  },
  AvgCommunicate_143431_Content_15 = {
    Text = "Ucciderlo quando è senza difese potrebbe essere un po' più divertente."
  },
  AvgCommunicate_143431_Content_16 = {Text = "???!"},
  AvgCommunicate_143431_Content_2 = {
    Text = "Ehm, Pontos, non stai considerando di tornare a Ebwynnos per un po'."
  },
  AvgCommunicate_143431_Content_3 = {
    Text = "Il professor Dexter non si fa vedere A Scuola da ben due mesi."
  },
  AvgCommunicate_143431_Content_4 = {
    Text = "Ah, quella cosa sporca e codarda starà probabilmente sfogando la sua rabbia su qualche sfortunato dei suoi sottoposti."
  },
  AvgCommunicate_143431_Content_5 = {
    Text = "Stai tranquillo, finché non farà Ritorno alla sua Genesi, non avrà ancora i requisiti per essere il mio Rivale."
  },
  AvgCommunicate_143431_Content_6 = {
    Text = "Il problema è che c'è una pila di documenti che aspettano il suo timbro personale, e il banchetto di beneficenza di quest'anno come lo gestiamo! Far presenziare la preside Czort e la professoressa Doll a queste cose è più difficile che farle far saltare in aria Mythag direttamente."
  },
  AvgCommunicate_143431_Content_7 = {
    Text = "Se a presiedere fosse la professoressa Sylvia, ci sarebbero ben altri problemi di cui preoccuparsi…"
  },
  AvgCommunicate_143431_Content_8 = {
    Text = "Che tristezza, piccolo, lo so, a Mythag sei protetto da molte persone, non hai più bisogno di me, eppure ho fatto così tanto per te, tu addirittura……"
  },
  AvgCommunicate_145234_Content_1 = {
    Text = "È tornato il silenzio."
  },
  AvgCommunicate_145234_Content_10 = {
    Text = "Quindi... non vuoi più combattere?"
  },
  AvgCommunicate_145234_Content_11 = {
    Text = "Ah ah ah ah..."
  },
  AvgCommunicate_145234_Content_12 = {
    Text = "Certo che no."
  },
  AvgCommunicate_145234_Content_13 = {
    Text = "Non ho più bisogno del combattimento per placare il mio corpo, ma..."
  },
  AvgCommunicate_145234_Content_14 = {
    Text = "Ora posso usare la mia forza più liberamente, e sfidare chiunque voglia!"
  },
  AvgCommunicate_145234_Content_15 = {
    Text = "Penso... di doverti dei ringraziamenti."
  },
  AvgCommunicate_145234_Content_16 = {
    Text = "Mi hai portato a un apice che ho a lungo desiderato. Ma..."
  },
  AvgCommunicate_145234_Content_17 = {
    Text = "Il cammino della forza non ha fine. Vero, Custode?"
  },
  AvgCommunicate_145234_Content_2 = {
    Text = "Silenzio? Cosa intendi dire?"
  },
  AvgCommunicate_145234_Content_3 = {
    Text = "Il mio sangue ha smesso di ribollire. Le mie ossa, di dolere. La mia lama non ruggisce più..."
  },
  AvgCommunicate_145234_Content_4 = {
    Text = "Dal momento in cui sono nata, non si sono mai fermati."
  },
  AvgCommunicate_145234_Content_5 = {
    Text = "Ora, tacciono tutti."
  },
  AvgCommunicate_145234_Content_6 = {
    Text = "È una cosa negativa?"
  },
  AvgCommunicate_145234_Content_7 = {Text = "Stai bene?"},
  AvgCommunicate_145234_Content_8 = {
    Text = "Quel rumore prima... era solo fame. Un prurito disperato per non essere abbastanza forte, abbastanza veloce."
  },
  AvgCommunicate_145234_Content_9 = {
    Text = "Ora è scomparso. Il mio corpo si sente... sazio per la prima volta."
  },
  AvgCommunicate_145234_Option_6 = {
    Text = "È una cosa negativa?"
  },
  AvgCommunicate_145234_Option_7 = {Text = "Stai bene?"},
  AvgCommunicate_146392_Content_1 = {Text = "Ci sei?"},
  AvgCommunicate_146392_Content_10 = {
    Text = "L'ho pagata per prendere il lavoro al suo posto."
  },
  AvgCommunicate_146392_Content_11 = {
    Text = "L'hai trovata?"
  },
  AvgCommunicate_146392_Content_12 = {
    Text = "È proprio davanti a me. Dorme profondamente."
  },
  AvgCommunicate_146392_Content_13 = {
    Text = "Sto aspettando che si svegli."
  },
  AvgCommunicate_146392_Content_14 = {
    Text = "...Ha senso."
  },
  AvgCommunicate_146392_Content_15 = {
    Text = "Fammi pensare a qualcosa per farti passare il tempo..."
  },
  AvgCommunicate_146392_Content_16 = {
    Text = "Oh, lo so! Potresti..."
  },
  AvgCommunicate_146392_Content_17 = {
    Text = "I suoi occhi si muovono… Si sta svegliando."
  },
  AvgCommunicate_146392_Content_18 = {
    Text = "Devo andare."
  },
  AvgCommunicate_146392_Content_19 = {
    Text = "Ehi? Lotan?"
  },
  AvgCommunicate_146392_Content_2 = {Text = "?"},
  AvgCommunicate_146392_Content_3 = {
    Text = "Lotan? Pensavo non ti interessassero queste cose."
  },
  AvgCommunicate_146392_Content_4 = {
    Text = "Solo annoiata. Sto provando questo aggeggio che mi ha dato Doll."
  },
  AvgCommunicate_146392_Content_5 = {
    Text = "Potrebbe tornare utile un giorno."
  },
  AvgCommunicate_146392_Content_6 = {
    Text = "Tu? Annoiata?"
  },
  AvgCommunicate_146392_Content_7 = {
    Text = "Pensavo fossi impegnata a combattere o a cercare qualcuno con cui farlo."
  },
  AvgCommunicate_146392_Content_8 = {
    Text = "A proposito, dove sei? Non ti si vede da giorni..."
  },
  AvgCommunicate_146392_Content_9 = {
    Text = "Ho sentito che Daffodil stava dando la caccia a qualche potente creatura antica."
  },
  AvgCommunicate_146392_Option_14 = {
    Text = "...Ha senso."
  },
  AvgCommunicate_146392_Option_6 = {
    Text = "Tu? Annoiata?"
  },
  AvgCommunicate_146393_Content_1 = {
    Text = "Corna. Denti. Artigli. Carne. Bulbi oculari. Tentacoli."
  },
  AvgCommunicate_146393_Content_10 = {
    Text = "Spero che tu possa essere altrettanto dura."
  },
  AvgCommunicate_146393_Content_11 = {Text = "..."},
  AvgCommunicate_146393_Content_12 = {
    Text = "Oh, grazie mille."
  },
  AvgCommunicate_146393_Content_2 = {
    Text = "Scegline uno."
  },
  AvgCommunicate_146393_Content_3 = {
    Text = "È una specie di gioco \"indovina cosa ti piace\"...?"
  },
  AvgCommunicate_146393_Content_4 = {
    Text = "Ho riportato il mostro che ho ucciso l'ultima volta."
  },
  AvgCommunicate_146393_Content_5 = {
    Text = "Non sapevo dove metterlo comunque, ho pensato che potresti volere un souvenir."
  },
  AvgCommunicate_146393_Content_6 = {
    Text = "Nessuna di queste opzioni sembra allettante..."
  },
  AvgCommunicate_146393_Content_7 = {
    Text = "È strano se li voglio tutti..."
  },
  AvgCommunicate_146393_Content_8 = {
    Text = "Scelta difficile... perché non scegli tu per me..."
  },
  AvgCommunicate_146393_Content_9 = {
    Text = "Il corno è buono. Ha resistito tre colpi prima di rompersi. Ti si addice."
  },
  AvgCommunicate_146393_Option_6 = {
    Text = "Nessuna di queste opzioni sembra allettante..."
  },
  AvgCommunicate_146393_Option_7 = {
    Text = "È strano se li voglio tutti..."
  },
  AvgCommunicate_146394_Content_1 = {
    Text = "Ho un problema."
  },
  AvgCommunicate_146394_Content_10 = {
    Text = "Me ne sono andata tre volte. Ogni volta che lo facevo, iniziavano a sacrificarsi. A quanto pare, pensavano fosse una prova divina."
  },
  AvgCommunicate_146394_Content_11 = {
    Text = "Sono tutti pazzi."
  },
  AvgCommunicate_146394_Content_12 = {
    Text = "E perché mai sei tornata??"
  },
  AvgCommunicate_146394_Content_13 = {
    Text = "Non ho estratto la mia lama dal suo cadavere."
  },
  AvgCommunicate_146394_Content_14 = {
    Text = "Ora l'hanno consacrata anche quella."
  },
  AvgCommunicate_146394_Content_15 = {Text = "..."},
  AvgCommunicate_146394_Content_16 = {
    Text = "Devo riprendere la mia lama senza che si suicidino in massa davanti a me."
  },
  AvgCommunicate_146394_Content_17 = {
    Text = "Tu capisci queste piccole creature deboli meglio di me. Aiutami."
  },
  AvgCommunicate_146394_Content_18 = {
    Text = "...Ehi, cosa dovrebbe significare?!"
  },
  AvgCommunicate_146394_Content_2 = {
    Text = "Wow, quindi anche tu hai dei problemi a volte!"
  },
  AvgCommunicate_146394_Content_3 = {
    Text = "Ho sentito che c'era un verme potente, così l'ho ucciso."
  },
  AvgCommunicate_146394_Content_4 = {
    Text = "Dopo la sua morte, le persone rimaste intrappolate a lungo nel pianeta sotto il suo peso sono venute fuori strisciando."
  },
  AvgCommunicate_146394_Content_5 = {
    Text = "Mi hanno chiamata dea, mi hanno fatto inchini, e mi hanno persino costruito una statua d'oro — bruttissima."
  },
  AvgCommunicate_146394_Content_6 = {
    Text = "AHAHAHAHAHA"
  },
  AvgCommunicate_146394_Content_7 = {
    Text = "Smettila di ridere."
  },
  AvgCommunicate_146394_Content_8 = {
    Text = "Non ti piace essere venerata?"
  },
  AvgCommunicate_146394_Content_9 = {
    Text = "Non ti piace essere venerata?"
  },
  AvgCommunicate_146394_Option_6 = {Text = "AHAHAHAHAH"},
  AvgCommunicate_146394_Option_8 = {
    Text = "Perché non te ne sei andata e basta?"
  },
  AvgCommunicate_146394_Option_9 = {
    Text = "Perché non te ne sei andata e basta?"
  },
  AvgCommunicate_148438_Content_1 = {
    Text = "Immagino che tu lo sappia già, hmm?"
  },
  AvgCommunicate_148438_Content_10 = {
    Text = "Ehe ehe, non pensarci troppo~ Chi pensa troppo diventa un adulto noioso e senza divertimento~"
  },
  AvgCommunicate_148438_Content_11 = {
    Text = "Anche se, naturalmente, se il Custode proprio non riesce a fare a meno di essere attratto dalla Fata—se ti ritrovi a inseguire ogni mio passo, giorno e notte, pur di guadagnarti il mio vero affetto—beh, sarebbe del tutto comprensibile~"
  },
  AvgCommunicate_148438_Content_12 = {Text = "Ugh..."},
  AvgCommunicate_148438_Content_13 = {
    Text = "Ho già lasciato la mela caramellata più dolce di tutte sulla scrivania del tuo dormitorio."
  },
  AvgCommunicate_148438_Content_14 = {
    Text = "Ora devi, assolutamente devi, assaporarla lentamente, esaminare ogni morso, e gustartela tutta da solo~"
  },
  AvgCommunicate_148438_Content_2 = {
    Text = "Quindi ti sei presa tutto quel disturbo per ottenere un permesso di uscita... solo per comprare ad Aigis, Ogier e Murphy delle mele caramellate in edizione limitata che dicevano di non aver mai assaggiato?"
  },
  AvgCommunicate_148438_Content_3 = {
    Text = "Quei piccoli bri—ehm—quei devoti bambini potrebbero non aver pagato per intero le quote associative, ma svolgono un ruolo assolutamente vitale nel diffondere le benedizioni della Fata in lungo e in largo."
  },
  AvgCommunicate_148438_Content_4 = {
    Text = "Coltivare il mio gregge, affinché diffonda la buona parola con ancora più entusiasmo—ebbene, questo è solo uno dei tanti pesanti fardelli che la Fata porta sulle sue spalle~"
  },
  AvgCommunicate_148438_Content_5 = {
    Text = "Anche se questa volta avevi una buona ragione, perché continui ad addebitarlo sul MIO conto..."
  },
  AvgCommunicate_148438_Content_7 = {
    Text = "Oh, non preoccuparti dei piccoli dettagli~ Guarda, i bambini ora sono veri credenti. Quindi quando ti deciderai finalmente a unirti a loro, hmm?"
  },
  AvgCommunicate_148438_Content_9 = {
    Text = "Non riesco davvero a capire se ogni tanto lasci trasparire un frammento del tuo vero io, o se sei semplicemente una cipolla, che nasconde il tuo vero obiettivo sotto un altro strato all'infinito..."
  },
  AvgCommunicate_148439_Content_1 = {Text = "[Immagine]"},
  AvgCommunicate_148439_Content_10 = {
    Text = "[Immagine caricata con successo]"
  },
  AvgCommunicate_148439_Content_11 = {Text = "[Immagine]"},
  AvgCommunicate_148439_Content_12 = {
    Text = "Cosa... è davvero una lettera di scuse..."
  },
  AvgCommunicate_148439_Content_13 = {
    Text = "Mi dispiace... Caraboo. Non avrei dovuto reagire così quando per una volta stavi finalmente sendo sincera."
  },
  AvgCommunicate_148439_Content_14 = {
    Text = "Vado subito a ritirare il reclamo che ho appena presentato. Quello in cui raccomandavo di tenerti a terra... di negarti tutte le richieste di uscita... Ecco! Ho ritirato ogni reclamo che abbia mai presentato contro di te."
  },
  AvgCommunicate_148439_Content_15 = {
    Text = "Meraviglioso~ Hee hee, Custode—credo proprio che una volta ritirato un reclamo, non si possa presentarne uno nuovo contro lo stesso Risvegliatore per un intero mese, vero?"
  },
  AvgCommunicate_148439_Content_17 = {
    Text = "Ho un bruttissimo presentimento..."
  },
  AvgCommunicate_148439_Content_18 = {
    Text = "Oh mio, la Fata non si abbasserebbe mai a giocare con il cuore sincero di %player%~ Ogni parola in quella lettera di scuse era la pura verità. Quando tornerò dalla mia uscita, ti porterò sicuramente la mela rossa più dolce~"
  },
  AvgCommunicate_148439_Content_19 = {
    Text = "Aspetta! Perché Aigis è appena venuta da me in lacrime, dicendo che anche se non ha idea di cosa abbia fatto di sbagliato, spera che la perdonerò una volta vista la lettera di scuse?"
  },
  AvgCommunicate_148439_Content_2 = {
    Text = "Caricamento..."
  },
  AvgCommunicate_148439_Content_20 = {
    Text = "E che tu avevi promesso di consegnargliela—ma lei ha deciso di scusarsi di persona con me comunque, solo per essere sicura che non mi sarei arrabbiata di nuovo con lei?!"
  },
  AvgCommunicate_148439_Content_21 = {
    Text = "Ehi, Caraboo. CARABOO!!"
  },
  AvgCommunicate_148439_Content_3 = {Text = "?"},
  AvgCommunicate_148439_Content_4 = {
    Text = "Caraboo, hai già usato questo trucco una volta. Qualunque cosa tu dica, NON aprirò questa immagine."
  },
  AvgCommunicate_148439_Content_5 = {
    Text = "No, %player%... Ho davvero riflettuto. Tu, e tutti a Mythag, siete stati così gentili con me. Non avrei davvero dovuto portare le mie vecchie abitudini in questo posto meraviglioso."
  },
  AvgCommunicate_148439_Content_6 = {
    Text = "Dopotutto, non ho mai scelto di diventare quello che sono, non all'inizio."
  },
  AvgCommunicate_148439_Content_7 = {
    Text = "Così mi sono seduta e ti ho scritto una vera lettera di scuse—scritta a mano, ogni singola parola, con la mia stessa mano~ Ma guarda un po', il Comunicatore ha deciso di fare i capricci proprio in questo momento..."
  },
  AvgCommunicate_148439_Content_8 = {
    Text = "Capisco se non mi credi. Aspetterò... tutto il tempo necessario perché tu torni a fidarti di me..."
  },
  AvgCommunicate_148439_Content_9 = {
    Text = "...Ugh, perché la mia coscienza si sta svegliando proprio adesso? Comunque, non c'è modo che io..."
  },
  AvgCommunicate_148440_Content_1 = {Text = "[Immagine]"},
  AvgCommunicate_148440_Content_10 = {
    Text = "Di cosa stai parlando? Come se ti rimborsassi mai!"
  },
  AvgCommunicate_148440_Content_11 = {Text = "Eh?"},
  AvgCommunicate_148440_Content_12 = {
    Text = "Non stai nemmeno più fingendo?"
  },
  AvgCommunicate_148440_Content_13 = {
    Text = "Ehehee. Servire la Fata è di per sé il tuo massimo onore. Ti condurrà in un paradiso senza pari. Rispetto a questo, un rimborso terreno non vale certo la pena di essere menzionato, naturalmente."
  },
  AvgCommunicate_148440_Content_14 = {
    Text = "Basta con tutto questo! Se non trasferisci i soldi presto, la mappa andrà perduta per sempre..."
  },
  AvgCommunicate_148440_Content_16 = {
    Text = "Ho già guardato quella cosa che mi hai mandato. Era chiaramente falsificata con qualche scadente tecnologia Argento..."
  },
  AvgCommunicate_148440_Content_17 = {
    Text = "Oh? L'hai aperta? È stata interamente una tua scelta, sai~ Meraviglioso! *La Fata ricorderà per sempre l'offerta di %player%.*"
  },
  AvgCommunicate_148440_Content_18 = {
    Text = "Aspetta, perché mi arriva una notifica che mi sono stati detratti 1.000 Fiorini—è la mia indennità per il lavoro sul campo!"
  },
  AvgCommunicate_148440_Content_2 = {
    Text = "Caricamento..."
  },
  AvgCommunicate_148440_Content_20 = {
    Text = "Su, su. Sei abbastanza benestante, vero? Questa volta prenderò solo 200 Fiorini—come compenso per la gentile lezione che non dovresti aprire link sconosciuti sul tuo comunicatore. Sii grato per la misericordia della Fata, hmm?"
  },
  AvgCommunicate_148440_Content_21 = {
    Text = "[Trasferimento: 800 Fiorini Leoniani]"
  },
  AvgCommunicate_148440_Content_3 = {
    Text = "[Immagine Corrotta]"
  },
  AvgCommunicate_148440_Content_4 = {
    Text = "...Cosa hai mandato?"
  },
  AvgCommunicate_148440_Content_5 = {Text = "Oops!"},
  AvgCommunicate_148440_Content_6 = {
    Text = "Siamo rovinati! Quell'immagine conteneva una mappa per l'Est, ottenuta col sangue, sudore e lacrime dei miei devoti seguaci—e ora l'originale è corrotto insieme ad essa! Dev'essere qualche malvagio @2 che cerca di impedirci di raggiungere l'Est!"
  },
  AvgCommunicate_148440_Content_7 = {
    Text = "%player%, quanti Fiorini hai con te? Presto, dammeli tutti! C'è ancora una possibilità di recuperarla..."
  },
  AvgCommunicate_148440_Content_8 = {
    Text = "Lascia che indovini: me li restituirai decupli una volta raggiunto l'Est. Non sono nato ieri, sai."
  },
  AvgCommunicate_148440_Content_9 = {
    Text = "Una truffa che non stare al passo coi tempi non ha futuro."
  },
  AvgCommunicate_149803_Content_1 = {
    Text = "La missione di scorta che l'Accademia mi aveva precedentemente affidato è stata completata. C'è qualcosa che desidera che faccia, mio signore?"
  },
  AvgCommunicate_149803_Content_10 = {
    Text = "In ogni caso, se non vuole stare in ozio, tra qualche giorno ci sono molte attività all'accademia — perché non va a divertirsi?"
  },
  AvgCommunicate_149803_Content_11 = {
    Text = "...Poiché è un ordine del mio signore, mi conformerò."
  },
  AvgCommunicate_149803_Content_12 = {
    Text = "Vado a fare il pattugliamento adesso."
  },
  AvgCommunicate_149803_Content_13 = {
    Text = "Spero che mantenga davvero la promessa più tardi!"
  },
  AvgCommunicate_149803_Content_2 = {
    Text = "Non vuole riposarsi?"
  },
  AvgCommunicate_149803_Content_3 = {
    Text = "Non è necessario."
  },
  AvgCommunicate_149803_Content_4 = {
    Text = "Inoltre... non ho il diritto di godere di tale pace."
  },
  AvgCommunicate_149803_Content_5 = {
    Text = "Quell'ombra oscura mi disturba ancora di tanto in tanto, sussurrandomi all'orecchio."
  },
  AvgCommunicate_149803_Content_6 = {
    Text = "Forse quando ho dei compiti da svolgere, sono in realtà più a mio agio."
  },
  AvgCommunicate_149803_Content_7 = {
    Text = "È tutto. La prego di non preoccuparsene, mio signore."
  },
  AvgCommunicate_149803_Content_8 = {
    Text = "Forse devo insegnarle la necessità di oziare un po'."
  },
  AvgCommunicate_149803_Content_9 = {
    Text = "Combatterà meglio se si rilassa di più."
  },
  AvgCommunicate_149803_Option_8 = {
    Text = "Forse devo insegnarle la necessità di oziare un po'."
  },
  AvgCommunicate_149803_Option_9 = {
    Text = "Combatterà meglio se si rilassa di più."
  },
  AvgCommunicate_149950_Content_10 = {
    Text = "Hmph... mi stai deridendo? Questo è già il limite di quanto riesca a controllare questo corpo in questo momento!"
  },
  AvgCommunicate_149950_Content_11 = {
    Text = "Cosa stai cercando di fare? Continuare a provocarlo e manipolarlo?"
  },
  AvgCommunicate_149950_Content_12 = {
    Text = "Se potessi, lo avrei già fatto da tempo..."
  },
  AvgCommunicate_149950_Content_13 = {
    Text = "Lascia perdere. Piuttosto che diventare una lama, essere uno scudo o un baluardo non sembra poi così male..."
  },
  AvgCommunicate_149950_Content_14 = {
    Text = "Quanto al padrone di cui si fida e che serve — tu — conoscerti è stato in realtà piuttosto interessante."
  },
  AvgCommunicate_149950_Content_15 = {
    Text = "Ora lo vedo. Sei stato influenzato da Ogier a tua volta, vero."
  },
  AvgCommunicate_149950_Content_17 = {Text = "???"},
  AvgCommunicate_149950_Content_18 = {
    Text = "Mio signore, mi scuso sinceramente. Ho avuto un vuoto improvviso per qualche minuto poco fa."
  },
  AvgCommunicate_149950_Content_19 = {
    Text = "Quando sono tornato in me, ho trovato il comunicatore acceso."
  },
  AvgCommunicate_149950_Content_2 = {
    Text = "Finalmente ti ho trovato..."
  },
  AvgCommunicate_149950_Content_20 = {
    Text = "Ho la sensazione... di aver appena sentito di nuovo quella voce irritante dopo così tanto tempo..."
  },
  AvgCommunicate_149950_Content_21 = {
    Text = "Come dire... sembra che tu e il potere che è in te abbiate già imparato a coesistere in modo piuttosto armonioso."
  },
  AvgCommunicate_149950_Content_22 = {
    Text = "...Ho letto il registro."
  },
  AvgCommunicate_149950_Content_23 = {
    Text = "Temevo che avrebbe pronunciato parole malvagie e aggressive come un tempo."
  },
  AvgCommunicate_149950_Content_24 = {
    Text = "È davvero sorprendente. Prima ero sempre io a essere eroso da esso — e ora sembra che i ruoli si siano invertiti."
  },
  AvgCommunicate_149950_Content_25 = {
    Text = "Dovrebbe essere una buona cosa. Almeno... significa che l'ho completamente superato."
  },
  AvgCommunicate_149950_Content_26 = {
    Text = "Certo, potrebbe essere che il potenziamento del potere di Ogier sia ciò che ha permesso al controllo su questa cosa intangibile di raggiungere un tale livello?"
  },
  AvgCommunicate_149950_Content_27 = {
    Text = "Mm, deve essere così. Tutti questi cambiamenti sono certamente avvenuti grazie a te."
  },
  AvgCommunicate_149950_Content_28 = {
    Text = "E per me, la \"Legge Suprema\" che ho compreso non è semplicemente potere..."
  },
  AvgCommunicate_149950_Content_29 = {
    Text = "C'è anche questa convinzione di proteggere gli altri, che arde nel mio petto con più ardore che mai. Credo che sia lì che risieda la vera fonte."
  },
  AvgCommunicate_149950_Content_3 = {
    Text = "Tu non sei Ogier. Chi sei?"
  },
  AvgCommunicate_149950_Content_4 = {
    Text = "Restituisci il comunicatore al suo proprietario!"
  },
  AvgCommunicate_149950_Content_5 = {
    Text = "Che ridicolo. Senza la mia esistenza, come avrebbe potuto sopravvivere questo ragazzo, e come avrebbe potuto restare qui come Risvegliatore?"
  },
  AvgCommunicate_149950_Content_6 = {
    Text = "Tu sei... la presenza invisibile che gli è attaccata?"
  },
  AvgCommunicate_149950_Content_7 = {
    Text = "Esattamente. Eppure non mi riconosci, Custode di Mythag."
  },
  AvgCommunicate_149950_Content_8 = {
    Text = "Beh... sei sempre stato così completamente soppresso da Ogier che semplicemente non ti ho mai visto prima."
  },
  AvgCommunicate_149950_Option_3 = {
    Text = "Tu non sei Ogier. Chi sei?"
  },
  AvgCommunicate_149950_Option_4 = {
    Text = "Restituisci il comunicatore al suo proprietario!"
  },
  AvgCommunicate_149986_Content_1 = {
    Text = "Mio signore, sono venuto a porgerle un invito."
  },
  AvgCommunicate_149986_Content_10 = {
    Text = "...Un albero."
  },
  AvgCommunicate_149986_Content_11 = {Text = "Eh?"},
  AvgCommunicate_149986_Content_12 = {
    Text = "Forse è merito del mio addestramento professionale — non importa quanto le cose diventino caotiche, riesco a stare perfettamente immobile sul palco."
  },
  AvgCommunicate_149986_Content_13 = {
    Text = "Cosa succederà mai nel vostro spettacolo?!"
  },
  AvgCommunicate_149986_Content_14 = {
    Text = "Non lo so. Sono solo un albero."
  },
  AvgCommunicate_149986_Content_15 = {
    Text = "...Be', durante lo spettacolo, Jenkin, che interpreta la principessa, scenderà dall'alto, e Lily, che interpreta il principe, dovrà prenderla al volo."
  },
  AvgCommunicate_149986_Content_16 = {
    Text = "Aigis, che interpreta il re dei demoni, dovrà anche scendere dal palco e interagire con il pubblico."
  },
  AvgCommunicate_149986_Content_17 = {
    Text = "Ho rinunciato a commentare il casting..."
  },
  AvgCommunicate_149986_Content_18 = {
    Text = "Ma non è come rovinarmi la sorpresa?"
  },
  AvgCommunicate_149986_Content_19 = {
    Text = "Perché non voglio tenerti nascosto nulla."
  },
  AvgCommunicate_149986_Content_2 = {
    Text = "Il club teatrale sta mettendo in scena uno spettacolo di fiabe e ha invitato i Risvegliatori minorenni di Mythag a esibirsi insieme."
  },
  AvgCommunicate_149986_Content_20 = {
    Text = "Inoltre, a giudicare da come sono andate le prove, ogni volta va storto qualcosa di diverso. Non posso garantire cosa vedrai effettivamente."
  },
  AvgCommunicate_149986_Content_21 = {
    Text = "...Questo lo rende piuttosto intrigante."
  },
  AvgCommunicate_149986_Content_22 = {
    Text = "Le cose che accadono durante lo spettacolo comportano un certo grado di pericolo, dopotutto."
  },
  AvgCommunicate_149986_Content_23 = {
    Text = "Quindi, mentre recito la parte di un albero, devo anche tenere d'occhio la situazione dentro e fuori dal palco per garantire la sicurezza degli attori e del pubblico."
  },
  AvgCommunicate_149986_Content_24 = {
    Text = "Quindi in realtà facevi anche la guardia del corpo di nascosto... dev'essere davvero faticoso."
  },
  AvgCommunicate_149986_Content_25 = {
    Text = "Infatti. In ogni caso, stai tranquillo. Finché sarò ancora sul palco, non permetterò che nessuno si faccia del male di nuovo."
  },
  AvgCommunicate_149986_Content_3 = {
    Text = "È un po' imbarazzante dirlo... Sarò sul palco anch'io. Spero che tu venga a vedermi."
  },
  AvgCommunicate_149986_Content_4 = {
    Text = "! Non vedo l'ora."
  },
  AvgCommunicate_149986_Content_5 = {
    Text = "Detto questo, non mi aspettavo che accettassi di partecipare a qualcosa del genere."
  },
  AvgCommunicate_149986_Content_6 = {
    Text = "Be', non sono più un bambino, quindi non mi si addice davvero essere coinvolto."
  },
  AvgCommunicate_149986_Content_7 = {
    Text = "Ma loro hanno insistito..."
  },
  AvgCommunicate_149986_Content_8 = {
    Text = "Non volevo smorzare il loro entusiasmo, e inoltre ho capito che questo ruolo in particolare poteva davvero essere interpretato solo da me."
  },
  AvgCommunicate_149986_Content_9 = {
    Text = "Allora, che ruolo interpreterà Ogier? Un cavaliere?"
  },
  AvgCommunicate_149987_Content_1 = {
    Text = "Mio signore, ci sono corsi recenti relativi al D-fenomeno?"
  },
  AvgCommunicate_149987_Content_10 = {
    Text = "Che diligenza... Se fossi laborioso quanto te, di sicuro non dovrei preoccuparmi degli esami."
  },
  AvgCommunicate_149987_Content_11 = {
    Text = "Ti prego, non lusingarmi così. Le responsabilità che porti sulle spalle sono molto più gravose delle mie."
  },
  AvgCommunicate_149987_Content_12 = {
    Text = "Inoltre, questo è semplicemente il lavoro necessario che svolgo come penitenza."
  },
  AvgCommunicate_149987_Content_13 = {
    Text = "Ma impari così in fretta — chissà, Ogier potrebbe avere proprio la stoffa dello studioso."
  },
  AvgCommunicate_149987_Content_14 = {
    Text = "Come l'argomento a cui tutti pensano da giovani — cosa riserva il futuro."
  },
  AvgCommunicate_149987_Content_15 = {
    Text = "Ogier ha mai pensato a cosa vuole fare da grande?"
  },
  AvgCommunicate_149987_Content_16 = {
    Text = "Sai che sono diventato un Risvegliatore. Non c'è più alcuna possibilità di crescere."
  },
  AvgCommunicate_149987_Content_17 = {
    Text = "Puoi ancora sognare i tuoi piani per il futuro! Non c'è bisogno di essere così pessimista."
  },
  AvgCommunicate_149987_Content_18 = {
    Text = "Non c'è nulla che Ogier voglia fare al di là del \"proteggere gli altri\"?"
  },
  AvgCommunicate_149987_Content_19 = {
    Text = "Grazie per l'incoraggiamento."
  },
  AvgCommunicate_149987_Content_2 = {
    Text = "Vorrei approfondirne lo studio."
  },
  AvgCommunicate_149987_Content_20 = {
    Text = "Quanto ad altre cose che voglio fare... Mi dispiace, non riesco davvero a pensarne nessuna."
  },
  AvgCommunicate_149987_Content_21 = {
    Text = "Quando questo corpo non sarà più macchiato dal peccato, ci penserò allora."
  },
  AvgCommunicate_149987_Content_3 = {
    Text = "Certo, la prossima volta ti porterò con me."
  },
  AvgCommunicate_149987_Content_4 = {
    Text = "Ma perché Ogier si è improvvisamente interessato a imparare queste cose?"
  },
  AvgCommunicate_149987_Content_5 = {
    Text = "Perché oggi qualcuno mi ha chiesto se il potere che avvolge il mio corpo sia legato alla D-melma."
  },
  AvgCommunicate_149987_Content_6 = {
    Text = "Capisco. A giudicare solo dalla forma, si assomigliano un po'."
  },
  AvgCommunicate_149987_Content_7 = {
    Text = "Sì, ho sempre avuto curiosità riguardo alla vera natura di questa forza invisibile. Forse comprenderla abbastanza bene mi permetterà di controllarla meglio."
  },
  AvgCommunicate_149987_Content_8 = {
    Text = "Anche se da quando sono arrivato a Mythag, ho scoperto che ci sono molte più cose incomprensibili di quanto avessi mai immaginato..."
  },
  AvgCommunicate_149987_Content_9 = {
    Text = "Quindi ho deciso di imparare prima di tutto di più sulla D-melma e su tutto ciò che le è correlato. Dopotutto, è anche il nemico contro cui il mio signore combatte da tempo."
  },
  AvgCommunicate_149988_Content_1 = {
    Text = "Ah, il mio disobbediente cagnolino, sempre a vagabondare per il mondo."
  },
  AvgCommunicate_149988_Content_10 = {
    Text = "A nessuno importa del tuo William."
  },
  AvgCommunicate_149988_Content_11 = {
    Text = "Ricordati solo: sei il mio cagnolino personale. Qualsiasi minaccia alla tua miserabile vita è semplicemente una perdita dei miei beni."
  },
  AvgCommunicate_149988_Content_12 = {
    Text = "Inoltre, ho scelto personalmente questo mondo specifico — una piccola frattura, al sicuro dalla Dissoluzione."
  },
  AvgCommunicate_149988_Content_13 = {
    Text = "Quindi fai attenzione a dove metti i piedi. Cerca di non romperlo."
  },
  AvgCommunicate_149988_Content_2 = {
    Text = "Il tuo segnale si interrompe di nuovo. In quale landa desolata ti sei cacciato questa volta?"
  },
  AvgCommunicate_149988_Content_3 = {
    Text = "Sono a Iperborea."
  },
  AvgCommunicate_149988_Content_4 = {
    Text = "Sono su in altopiano."
  },
  AvgCommunicate_149988_Content_5 = {
    Text = "Ci stiamo preparando a scalare una montagna. Onestamente, sono un po' preoccupato per la mia resistenza."
  },
  AvgCommunicate_149988_Content_6 = {
    Text = "L'aria è incredibilmente rarefatta quassù. Sembra che mi venga da svenire se corro anche solo per qualche passo."
  },
  AvgCommunicate_149988_Content_7 = {
    Text = "E pensi davvero di poter scalare una montagna in queste condizioni? Che cagnolino sconsiderato e senza cervello, completamente ignaro dei tuoi limiti."
  },
  AvgCommunicate_149988_Content_8 = {
    Text = "So che sei solo preoccupato, ma ho delle cose che devo portare a termine."
  },
  AvgCommunicate_149988_Content_9 = {
    Text = "Non preoccuparti, il Senpai William è qui con me. Andrà tutto bene."
  },
  AvgCommunicate_149988_Option_3 = {Text = "Iperborea."},
  AvgCommunicate_149988_Option_4 = {
    Text = "Una regione ad alta quota."
  },
  AvgCommunicate_150103_Content_1 = {
    Text = "Un lieve fremito si propaga attraverso i confini più lontani dell'arazzo del destino."
  },
  AvgCommunicate_150103_Content_10 = {
    Text = "È questo un altro filo nel tuo arazzo del destino?"
  },
  AvgCommunicate_150103_Content_11 = {
    Text = "Su questo, il telaio deve restare in silenzio."
  },
  AvgCommunicate_150103_Content_12 = {
    Text = "E le persone che vivono in questo mondo? Cosa accade loro adesso?"
  },
  AvgCommunicate_150103_Content_13 = {
    Text = "Torneranno alla loro essenza più pura — i Nuclei d'Argento."
  },
  AvgCommunicate_150103_Content_14 = {
    Text = "E il Re degli Dei raccoglierà quei frammenti dalla pioggia infinita, riplasmando il mondo dopo un lungo e silenzioso torpore."
  },
  AvgCommunicate_150103_Content_15 = {
    Text = "Questo silenzioso testimone sarà condiviso."
  },
  AvgCommunicate_150103_Content_2 = {
    Text = "La soglia critica è stata superata. La terra promessa tanto a lungo cercata è finalmente raggiunta."
  },
  AvgCommunicate_150103_Content_3 = {
    Text = "Non riesco a crederci."
  },
  AvgCommunicate_150103_Content_4 = {
    Text = "Il mondo sta scomparendo."
  },
  AvgCommunicate_150103_Content_5 = {
    Text = "Il cielo si sta sciogliendo, la neve sta cedendo, le vette delle montagne si stanno sgretolando."
  },
  AvgCommunicate_150103_Content_6 = {
    Text = "Questo intero mondo... era tutto falso."
  },
  AvgCommunicate_150103_Content_7 = {
    Text = "Lo sapevi già? Hai sempre potuto vedere tutto questo?"
  },
  AvgCommunicate_150103_Content_8 = {
    Text = "Stare al di fuori del grande palcoscenico del mondo significa tessere per l'eternità."
  },
  AvgCommunicate_150103_Content_9 = {
    Text = "Includeva anche il desiderio di Caraboo? Il mondo non sarebbe svanito senza di esso."
  },
  AvgCommunicate_150103_Option_3 = {
    Text = "Riesco a vederlo..."
  },
  AvgCommunicate_150103_Option_4 = {
    Text = "Il mondo sta scomparendo..."
  },
  AvgCommunicate_57593_Content_1 = {
    Text = "Compagno, hai finito di leggere i libri di storia e scienze naturali che ti ho prestato l'ultima volta?"
  },
  AvgCommunicate_57593_Content_10 = {
    Text = "Eh? È davvero così grave...?"
  },
  AvgCommunicate_57593_Content_11 = {
    Text = "Questi sono libri essenziali per gli investigatori. Devi memorizzarli, non importa quanto siano noiosi."
  },
  AvgCommunicate_57593_Content_12 = {
    Text = "Ho intenzione di darti ripetizioni per un'ora al giorno. Ovviamente, se vuoi imparare ancora più velocemente, possiamo studiare insieme tutta la notte."
