  },
  AvgCommunicate_57593_Content_15 = {
    Text = "Ricordati di portare il quaderno degli appunti. Controllerò i tuoi progressi."
  },
  AvgCommunicate_57593_Content_17 = {
    Text = "Perché l'ho detto..."
  },
  AvgCommunicate_57593_Content_2 = {
