  },
  AvgCommunicate_57594_Content_6 = {
    Text = "Oh davvero? A proposito, ho dimenticato di dirti una cosa. L'insegnante Doll è proprio accanto a me e sta guardando."
  },
  AvgCommunicate_57594_Content_7 = {
