  AvgCommunicate_57595_Content_1 = {
    Text = "Custode, hai detto..."
  },
  AvgCommunicate_57595_Content_10 = {
    Text = "Scriverò delle sfide a duello e le invierò ai dormitori di tutti; dovrebbe essere abbastanza cortese."
  },
  AvgCommunicate_57595_Content_11 = {
