  AvgCommunicate_57595_Content_13 = {
    Text = "Non capisci. Ho sentito Dexter dire che in passato, sfidare le persone a duello tramite una lettera di sfida era considerato un gesto da gentiluomo. Dovresti imparare dai tuoi antenati, giovanotto!"
