  },
  AvgCommunicate_57897_Content_10 = {
    Text = "Non preoccuparti, non è affatto un problema. Ci vediamo domani~."
  },
  AvgCommunicate_57897_Content_11 = {
    Text = "Ho già altri allenamenti programmati durante il tempo libero—"
  },
  AvgCommunicate_57897_Content_12 = {
    Text = "Sto scherzando."
  },
  AvgCommunicate_57897_Content_13 = {
    Text = "Ho modificato il tuo programma di addestramento. Vai a goderti la pausa nei prossimi giorni."
  },
  AvgCommunicate_57897_Content_14 = {
    Text = "Davvero? Meraviglioso, grazie!"
  },
  AvgCommunicate_57897_Content_2 = {
    Text = "Vuoi provare a indovinare com'è andata?"
  },
  AvgCommunicate_57897_Content_3 = {
    Text = "...M-mi stai mettendo ansia..."
  },
  AvgCommunicate_57897_Content_4 = {
    Text = "Non preoccuparti, sono qui per farti i complimenti. Nonostante tutti gli \"incidenti\" che hai avuto questo semestre, hai fatto un lavoro FANTASTICO in questo esame."
  },
  AvgCommunicate_57897_Content_5 = {
    Text = "Anzi, sei andato/a così bene che meriti una ricompensa. Ho personalmente modificato il tuo prossimo programma di addestramento. Goditi il tempo libero~."
