  },
  AvgCommunicate_57897_Content_7 = {
    Text = "Non preoccuparti, sono qui per congratularmi con te. Nonostante tutti gli \"incidenti\" che hai avuto questo trimestre, te la sei cavata COSÌ bene in questo esame."
  },
  AvgCommunicate_57897_Content_8 = {
