  AvgCommunicate_57898_Content_1 = {
    Text = "Ti ho trovato."
  },
  AvgCommunicate_57898_Content_10 = {
    Text = "...Segnalerò questa falla che hai trovato alle autorità scolastiche."
  },
  AvgCommunicate_57898_Content_11 = {
    Text = "Oh, che bambino dispettoso. Non crederai davvero che questo aggeggio possa trattenermi per sempre, vero?"
  },
  AvgCommunicate_57898_Content_12 = {
    Text = "Ti terrò SEMPRE d'occhio."
  },
  AvgCommunicate_57898_Content_2 = {
    Text = "Chi sei? Perché non hai un account ufficiale?"
  },
  AvgCommunicate_57898_Content_3 = {
    Text = "Sei in gamba. Perché non provi a indovinare e vedi se ci arrivi?"
  },
  AvgCommunicate_57898_Content_4 = {
    Text = "Beh, conosci il comunicatore. Sei uno studente?"
  },
  AvgCommunicate_57898_Content_5 = {
    Text = "Certo, perché no? È quello che dicono tutti comunque."
  },
  AvgCommunicate_57898_Content_6 = {
    Text = "Aspetta... tu sei quella Doll, vero?!"
  },
  AvgCommunicate_57898_Content_7 = {
    Text = "Esatto~! Un cagnolino sveglio come te merita una ricompensa."
  },
  AvgCommunicate_57898_Content_8 = {
    Text = "...Una ricompensa?"
