  AvgCommunicate_57899_Content_10 = {
    Text = "Grazie, %player%."
  },
  AvgCommunicate_57899_Content_2 = {
    Text = "Stamattina ha detto qualcosa riguardo a dei \"cioccolatini croccanti\" ed è uscita. Ora non riesco a trovarla."
  },
  AvgCommunicate_57899_Content_3 = {
    Text = "Sono un po' preoccupato."
