  AvgCommunicate_57899_Content_4 = {
    Text = "Hannah ha detto che Jenkin è con lei."
  },
  AvgCommunicate_57899_Content_5 = {
    Text = "Credo volesse comprare del cioccolato come dono per voi."
  },
  AvgCommunicate_57899_Content_6 = {Text = "Un regalo?"},
  AvgCommunicate_57899_Content_7 = {
    Text = "Ma non è nemmeno una festa... giusto?"
  },
  AvgCommunicate_57899_Content_8 = {
