  AvgCommunicate_57900_Content_1 = {
    Text = "Mio signore?"
  },
  AvgCommunicate_57900_Content_10 = {
    Text = "Incredibile! Come hai fatto?"
  },
  AvgCommunicate_57900_Content_11 = {
    Text = "Aspetta. Vengo lì e te lo mostro."
  },
  AvgCommunicate_57900_Content_2 = {
    Text = "Che succede, Ogier?"
  },
  AvgCommunicate_57900_Content_3 = {
    Text = "Wow, funziona davvero..."
  },
  AvgCommunicate_57900_Content_4 = {
    Text = "Mi perdoni, Mio Signore. Ho perso la calma poco fa."
  },
  AvgCommunicate_57900_Content_5 = {
    Text = "La signorina Doll mi ha appena inviato un comunicatore migliorato da testare. Non mi aspettavo che funzionasse così bene."
  },
  AvgCommunicate_57900_Content_6 = {
    Text = "Mi chiedo cos'altro si possa inviare."
  },
  AvgCommunicate_57900_Content_7 = {
    Text = "Si possono inviare anche immagini!"
  },
  AvgCommunicate_57900_Option_2 = {
    Text = "Che succede?"
  },
  AvgCommunicate_57901_Content_1 = {Text = "?!#¥%&*()"},
  AvgCommunicate_57901_Content_10 = {
    Text = "Ah! Scusa, Custode!"
  },
  AvgCommunicate_57901_Content_11 = {
    Text = "La prossima volta non dimenticherò di sicuro! Di sicuro!"
  },
  AvgCommunicate_57901_Content_2 = {Text = "??"},
  AvgCommunicate_57901_Content_3 = {
    Text = "Scusa. Mi sto ancora abituando a usare una tastiera."
  },
  AvgCommunicate_57901_Content_4 = {
    Text = "Non preoccuparti. Anch'io facevo errori all'inizio. Continua a esercitarti e alla fine ci prenderai la mano."
  },
  AvgCommunicate_57901_Content_5 = {
    Text = "Sì, ma... ho paura di dimenticare tutto quello che ho imparato entro domani."
  },
  AvgCommunicate_57901_Content_6 = {
    Text = "Allora esercitati ancora di più! Andrà tutto bene!"
