  AvgCommunicate_57901_Content_7 = {
    Text = "Hai ragione! Grazie, Alva!"
  },
  AvgCommunicate_57901_Content_8 = {
    Text = "Ehm... Non sono Alva."
  },
  AvgCommunicate_57901_Content_9 = {
    Text = "In realtà, sono il Custode."
  },
  AvgCommunicate_57901_Option_2 = {Text = "??"},
  AvgCommunicate_57901_Option_4 = {
    Text = "La pratica rende perfetti. Ci prenderai la mano in un attimo."
  },
  AvgCommunicate_57901_Option_6 = {
    Text = "Allora esercitati ancora di più!"
  },
  AvgCommunicate_57901_Option_8 = {
    Text = "Non sono Alva."
  },
  AvgCommunicate_57901_Option_9 = {
    Text = "In realtà, sono il Custode."
  },
  AvgCommunicate_57903_Content_1 = {
    Text = "Buon giorno, pallido messaggero."
  },
  AvgCommunicate_57903_Content_10 = {
    Text = "Devo dire che è davvero ingegnoso."
  },
  AvgCommunicate_57903_Content_2 = {
    Text = "Salve, Vescovo Salvador."
  },
  AvgCommunicate_57903_Content_3 = {
    Text = "A quanto pare hai ricevuto l'ultimo modello di comunicatore. Come ti sembra?"
  },
  AvgCommunicate_57903_Content_4 = {
    Text = "È molto interessante e comodo. Anche se siamo a centinaia di miglia di distanza, possiamo comunque comunicare come se fossimo faccia a faccia."
  },
  AvgCommunicate_57903_Content_5 = {
    Text = "Se il mondo intero avesse dispositivi del genere, la distanza tra le persone non sarebbe così vasta come lo è ora."
  },
  AvgCommunicate_57903_Content_6 = {
    Text = "Ma comprendo l'unicità di questa tecnologia... sai che trasmette informazioni connettendo i nostri spiriti, vero?"
  },
  AvgCommunicate_57903_Content_7 = {
    Text = "So solo che all'interno c'è un Nucleo d'Argento."
  },
  AvgCommunicate_57903_Content_8 = {
    Text = "Hai scoperto come funziona?"
  },
  AvgCommunicate_57903_Content_9 = {
    Text = "Esatto. I nostri spiriti si connettono a un Nucleo d'Argento, che a sua volta è collegato ai Nuclei presenti in altri dispositivi simili."
  },
  AvgCommunicate_57903_Option_2 = {
