  },
  AvgCommunicate_57904_Content_1 = {
    Text = "Custode, grazie per aver portato quelle provviste al sanatorio ieri. Per favore, ringrazia Lord Dexter per il suo continuo supporto."
  },
  AvgCommunicate_57904_Content_10 = {
    Text = "È tutto quello che posso fare per lei..."
  },
  AvgCommunicate_57904_Content_2 = {
    Text = "Questo è ciò che dovremmo fare."
  },
  AvgCommunicate_57904_Content_3 = {
    Text = "Il sanatorio non sarebbe sopravvissuto senza di voi."
  },
  AvgCommunicate_57904_Content_4 = {
    Text = "Il rettore ti sarà sicuramente grato."
  },
  AvgCommunicate_57904_Content_5 = {
    Text = "Dev'essere difficile dover gestire il sanatorio tutta da sola."
  },
  AvgCommunicate_57904_Content_6 = {
    Text = "Non è niente, davvero."
  },
  AvgCommunicate_57904_Content_7 = {
    Text = "Spero solo che i pazienti del sanatorio possano avere un momento di pace."
  },
  AvgCommunicate_57904_Content_8 = {
    Text = "Se avete tempo, vi prego, riportate Lily più spesso."
  },
  AvgCommunicate_57904_Content_9 = {
    Text = "Pulirò l'ufficio della direttrice e vi aspetterò."
  },
  AvgCommunicate_57904_Option_2 = {
    Text = "Questo è ciò che dovremmo fare."
  },
  AvgCommunicate_57904_Option_5 = {
    Text = "Dev'essere difficile dover gestire il sanatorio tutta da sola."
  },
  AvgCommunicate_57905_Content_1 = {
    Text = "Din-din~! La tua meravigliosa Cameriera Karen ti avvisa che la colazione è alla tua porta, pronta per quando ti alzi~!"
  },
  AvgCommunicate_57905_Content_10 = {
    Text = "Oh, lasciate fare a me! Karen è una cameriera tuttofare, capace di gestire qualsiasi cosa, dal bucato al cambio serrature e tutto il resto~!"
  },
  AvgCommunicate_57905_Content_11 = {
    Text = "No! NON entrare nella mia stanza!"
  },
  AvgCommunicate_57905_Content_12 = {
    Text = "Non siate timido! Arrivo subito~!"
  },
  AvgCommunicate_57905_Content_2 = {
    Text = "Ehi! Hai preso i miei vestiti!?"
  },
  AvgCommunicate_57905_Content_3 = {
    Text = "Oh cielo, Master. Perché siete già sveglio? I vostri vestiti non si sono ancora asciugati!"
  },
  AvgCommunicate_57905_Content_4 = {
    Text = "\"Non si sono ancora asciugati\"? Stai lavando i miei vestiti?"
  },
  AvgCommunicate_57905_Content_5 = {
    Text = "Certo! Come cameriera qualificata, non potrei mai permettere al mio Master di uscire con abiti sporchi e stropicciati!"
  },
  AvgCommunicate_57905_Content_6 = {
    Text = "Quindi sono rimasta sveglia tu~tta la notte e ho lavato tutti i vostri vestiti per be~ni~no~!"
  },
  AvgCommunicate_57905_Content_7 = {
    Text = "Non puoi lavare tutto senza lasciarmi niente da indossare!"
  },
  AvgCommunicate_57905_Content_8 = {
    Text = "Beh, il Master ha ancora qualcosa addosso. Onestamente, avrei voluto lavare anche quello, ma... il Master era avvolto così comodamente nel letto che non potevo toglierglielo senza svegliarlo~."
  },
  AvgCommunicate_57905_Content_9 = {
    Text = "...Cambio il lucchetto."
  },
  AvgCommunicate_57905_Option_11 = {
    Text = "No! NON entrare nella mia stanza!"
  },
  AvgCommunicate_57905_Option_2 = {
    Text = "Hai preso i miei vestiti!?"
