  },
  AvgCommunicate_57905_Option_9 = {
    Text = "...Cambio il lucchetto."
  },
  AvgCommunicate_57906_Content_1 = {
    Text = "Mmm... vediamo se questo aggeggio funziona..."
  },
  AvgCommunicate_57906_Content_2 = {
    Text = "C'è qualcuno là fuori che si sente insoddisfatto e ha bisogno di un po' della mia frusta?"
  },
  AvgCommunicate_57906_Content_3 = {
    Text = "Non proprio..."
  },
  AvgCommunicate_57906_Content_4 = {
    Text = "Non essere timido! Non nascondere i tuoi desideri!"
  },
  AvgCommunicate_57906_Content_5 = {
    Text = "Cedi a loro! Liberali! Lasciali scatenare!"
  },
  AvgCommunicate_57906_Content_6 = {
    Text = "SCATENA I TUOI DESIDERI!"
  },
  AvgCommunicate_57906_Content_7 = {
    Text = "...Spengo il comunicatore."
  },
  AvgCommunicate_57906_Content_8 = {
    Text = "È piuttosto raro trovare un modo così comodo e privato per parlare con te. Non aver paura; è il nostro piccolo segreto."
  },
  AvgCommunicate_57906_Content_9 = {
    Text = "Se mai avessi bisogno di un servizio privato, puoi chiamarmi in qualsiasi momento!"
  },
  AvgCommunicate_57906_Option_3 = {
    Text = "Non proprio..."
  },
  AvgCommunicate_57906_Option_7 = {
    Text = "...Spengo il comunicatore."
  },
  AvgCommunicate_57907_Content_1 = {
    Text = "La signorina Doll mi ha chiesto se ci fosse qualcosa che desideravo fare."
  },
  AvgCommunicate_57907_Content_10 = {
    Text = "...Non l'avevo mai sentita questa."
  },
  AvgCommunicate_57907_Content_11 = {
    Text = "Beh, se sei ancora indeciso, perché non cominci con ciò che sai fare meglio?"
  },
  AvgCommunicate_57907_Content_12 = {
    Text = "Considerando il tuo passato, direi che sei piuttosto abile nell'addestrare soldati. Perché non parti da lì?"
  },
  AvgCommunicate_57907_Content_13 = {
    Text = "Addestramento, dici. Potrebbe... funzionare."
  },
  AvgCommunicate_57907_Content_14 = {
    Text = "Grazie, Custode."
  },
  AvgCommunicate_57907_Content_2 = {
    Text = "Sono... un po' confusa."
  },
  AvgCommunicate_57907_Content_3 = {
    Text = "Ti ha subito assegnato del lavoro?"
  },
  AvgCommunicate_57907_Content_4 = {
    Text = "Ti sta già sfruttando, eh?"
  },
  AvgCommunicate_57907_Content_5 = {
    Text = "Ahahah... non è così. Sono stata io a offrirmi di aiutare, ma... non sono sicura di cosa posso fare per essere utile..."
  },
  AvgCommunicate_57907_Content_6 = {
    Text = "Sono stata una soldatessa per tutta la vita; ho sempre seguito gli ordini degli altri. Anche quando ero a Remouahe, non ero mai davvero sicura di cosa avrei dovuto fare."
  },
  AvgCommunicate_57907_Content_7 = {
    Text = "Sentirmi dire all'improvviso di decidere da sola cosa fare... È un'esperienza nuova per me."
  },
  AvgCommunicate_57907_Content_8 = {
    Text = "La signorina Doll probabilmente me l'ha chiesto perché era preoccupata che non riuscissi ad adattarmi alla vita civile."
  },
  AvgCommunicate_57907_Content_9 = {
    Text = "Può sembrare fredda, ma in realtà è molto premurosa verso gli altri."
