  },
  AvgCommunicate_57956_Content_4 = {
    Text = "La signora che siede sempre su uno strano congegno e beve grandi quantità di liquido scuro è rimasta nella mia stanza per tre giorni."
  },
  AvgCommunicate_57956_Content_5 = {
    Text = "So che teme il buio, e comprendo il dolore di non poter mai fare Ritorno a casa pur seguendo la guida, ma..."
  },
  AvgCommunicate_57956_Content_6 = {
    Text = "Vuole persino seguirmi in bagno. È un po' imbarazzante."
  },
  AvgCommunicate_57956_Content_7 = {
