  },
  AvgCommunicate_57956_Content_8 = {
    Text = "Grazie in anticipo."
  },
  AvgCommunicate_57956_Content_9 = {
    Text = "Tuttavia, vi prego, trattatela con gentilezza. Dopotutto, non è colpa sua."
  },
  AvgCommunicate_57956_Option_2 = {
