  AvgCommunicate_57957_Content_1 = {
    Text = "Hai ricevuto il mio Dono?"
  },
  AvgCommunicate_57957_Content_2 = {
    Text = "Avrei dovuto immaginarlo. Sei l'unica persona che mi regalerebbe qualcosa del genere."
  },
  AvgCommunicate_57957_Content_3 = {
    Text = "Come ogni forma d'arte, anche la scultura è qualcosa di molto personale."
  },
  AvgCommunicate_57957_Content_4 = {
    Text = "Non tutti riescono a vedere queste creazioni di pietra come un'estensione di sé stessi; una continuazione della propria vita, come faccio io."
  },
  AvgCommunicate_57957_Content_5 = {
    Text = "Ma tu sei diverso, non è vero?"
  },
  AvgCommunicate_57957_Content_6 = {
    Text = "Mia cara \"Sig.na Coral\"?"
  },
  AvgCommunicate_57957_Option_2 = {
    Text = "Avrei dovuto immaginarlo."
  },
  AvgCommunicate_57958_Content_1 = {
    Text = "Mi scusi, {Male=sir,Female=miss}, potrei avere un momento del suo tempo?"
  },
  AvgCommunicate_57958_Content_10 = {
    Text = "Non importa. Se è per diffondere la grazia del mio Signore, non rinuncerò nemmeno con le persone più ostinate."
  },
  AvgCommunicate_57958_Content_11 = {
    Text = "Domani alle 3 del mattino, terrò una cerimonia nella Sala di Mythag per narrare le grandi gesta del mio signore."
  },
  AvgCommunicate_57958_Content_12 = {
    Text = "In quanto persona profondamente legata al mio Signore, spero che il Custode {Male=signore,Female=signora} si presenti puntuale."
  },
  AvgCommunicate_57958_Content_2 = {
    Text = "Vorrei parlarvi del nostro giovane re e salvatore: Tulu."
  },
  AvgCommunicate_57958_Content_3 = {
    Text = "Sommo Sacerdote, la prego di essere consapevole del suo ruolo. Per favore, non imiti i ciarlatani..."
  },
  AvgCommunicate_57958_Content_4 = {
    Text = "Juliette ha suggerito che, per aumentare il numero di fedeli, dobbiamo adottare un approccio più gentile e proattivo nella nostra predicazione."
  },
  AvgCommunicate_57958_Content_5 = {
    Text = "Credo che quel suggerimento abbia i suoi meriti."
  },
  AvgCommunicate_57958_Content_6 = {
    Text = "Finché può diffondere la grazia del nostro Signore, sono disposta a imitare qualsiasi metodo moderno."
  },
  AvgCommunicate_57958_Content_7 = {
    Text = "Ho dimenticato di dirtelo... in realtà preferisco Hass..."
  },
  AvgCommunicate_57958_Content_9 = {
