  },
  AvgCommunicate_57959_Content_4 = {
    Text = "I Mythag non sono gli unici ad aver padroneggiato la tecnologia del Nucleo d'Argento."
  },
  AvgCommunicate_57959_Content_5 = {
    Text = "Cosa vuoi? Dubito che mi abbia scritto solo per sfoggiare il tuo comunicatore."
  },
  AvgCommunicate_57959_Content_6 = {
    Text = "Perspicace, vero?"
  },
  AvgCommunicate_57959_Content_7 = {
    Text = "Venite subito al 38 di Via Bruciatura. Abbiamo bisogno di voi qui."
  },
  AvgCommunicate_57959_Content_8 = {
    Text = "...Perché hai bisogno di me in una stazione di polizia?"
  },
  AvgCommunicate_57959_Content_9 = {
    Text = "Sei stato arrestato o qualcosa del genere?"
  },
  AvgCommunicate_57959_Option_2 = {
    Text = "Tanto per cominciare, il mio nome non è \"Ehi.\""
  },
  AvgCommunicate_57959_Option_3 = {
    Text = "Non dire \"Ehi\" così come se niente fosse!"
  },
  AvgCommunicate_57959_Option_5 = {Text = "Cosa vuoi?"},
  AvgCommunicate_57959_Option_8 = {
    Text = "...Perché hai bisogno di me in una stazione di polizia?"
  },
  AvgCommunicate_57987_Content_1 = {
    Text = "Quindi le persone possono semplicemente inviarmi i loro desideri attraverso questa piccola scatola?"
