  AvgCommunicate_57987_Content_3 = {
    Text = "È solo uno strumento che le persone possono usare per comunicare."
  },
  AvgCommunicate_57987_Content_4 = {
    Text = "Comunicare?"
  },
  AvgCommunicate_57987_Content_5 = {
    Text = "Ebbene, comunica con me. Qual è il tuo desiderio?"
