  },
  AvgCommunicate_57987_Content_7 = {
    Text = "No, no, non ho nessun desiderio!"
  },
  AvgCommunicate_57987_Content_8 = {
    Text = "Non hai desideri?"
  },
  AvgCommunicate_57987_Content_9 = {
    Text = "Molto bene. Se mai avrai un desiderio, fammelo sapere."
