  AvgCommunicate_57988_Content_1 = {
    Text = "Ehm, Custode."
  },
  AvgCommunicate_57988_Content_10 = {
    Text = "Mi servono cinquanta per comprare il rimedio. Consideralo un investimento."
  },
  AvgCommunicate_57988_Content_11 = {
    Text = "Una volta che il mio potere si sarà risvegliato, ti ripagherò cento volte tanto."
  },
  AvgCommunicate_57988_Content_12 = {
    Text = "Quindi in realtà sei venuto a chiedere soldi in prestito!"
  },
  AvgCommunicate_57988_Content_13 = {
    Text = "Ci sono così tante cose che vorrei dirti che non so nemmeno da dove cominciare!"
  },
  AvgCommunicate_57988_Content_14 = {
    Text = "Senti, capisco che hai ancora un complesso per i tuoi poteri deboli, ma questa sembra proprio una truffa..."
  },
  AvgCommunicate_57988_Content_15 = {
    Text = "Davvero? Sembra che tu non ti fidi del mio giudizio..."
