  },
  AvgCommunicate_57988_Content_5 = {
    Text = "Sembra interessante, ma... troppo bello per essere vero..."
  },
  AvgCommunicate_57988_Content_6 = {
    Text = "Puoi anche invidiarmi, ma accetterò quei sentimenti. Vado avanti e lo prendo."
  },
  AvgCommunicate_57988_Content_7 = {
