    Text = "Che succede?"
  },
  AvgCommunicate_57990_Content_4 = {
    Text = "Ho tempo. Di cosa si tratta?"
  },
  AvgCommunicate_57990_Content_5 = {
    Text = "Ho una piccola esibizione alla Mythag Hall tra un mese e vorrei che qualcuno ascoltasse il pezzo prima che lo esegua."
  },
  AvgCommunicate_57990_Content_6 = {
    Text = "Ho pensato di chiedere a Faint, e sicuramente accetterebbe, ma... mi vergogno troppo per chiederglielo..."
  },
  AvgCommunicate_57990_Content_7 = {
    Text = "Dopo averci pensato un po', ho capito che il Custode è una persona affidabile e degna di fiducia."
  },
  AvgCommunicate_57990_Content_8 = {Text = "Quindi..."},
  AvgCommunicate_57990_Content_9 = {
    Text = "Certo. Ci vediamo all'auditorium?"
