  AvgCommunicate_57990_Option_3 = {
    Text = "Che succede?"
  },
  AvgCommunicate_57990_Option_4 = {
    Text = "Ho tempo. Di cosa si tratta?"
  },
  AvgCommunicate_57990_Option_9 = {Text = "D'accordo."},
  AvgCommunicate_57991_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} Custode, ti ricordi ancora di quel tram bruco?"
  },
  AvgCommunicate_57991_Content_10 = {
    Text = "Considerando il contesto, ho scorto una bellezza diversa nella tua opera..."
  },
  AvgCommunicate_57991_Content_11 = {
    Text = "Mi piacerebbe includere il tuo verso nella mia nuova raccolta di poesie."
  },
  AvgCommunicate_57991_Content_12 = {
    Text = "Ti va bene, Custode {Male=signore,Female=signora}?"
  },
  AvgCommunicate_57991_Content_13 = {
    Text = "Dici sul serio?"
  },
  AvgCommunicate_57991_Content_14 = {Text = "Ma certo!"},
  AvgCommunicate_57991_Content_16 = {
    Text = "...Che sia la nascita di un nuovo poeta geniale?"
  },
  AvgCommunicate_57991_Content_17 = {
    Text = "Beh, potresti essere stanco per aver scritto troppo. Fai un bel Riposo!"
  },
  AvgCommunicate_57991_Content_18 = {
