  },
  AvgCommunicate_57991_Content_5 = {
    Text = "Pensavo fosse così bello, ma quel bruco si è rifiutato di farmi sedere! Che impostore!"
  },
  AvgCommunicate_57991_Content_6 = {
    Text = "{Male=Mr.,Female=Miss} Custode, la penso anch'io così!"
  },
  AvgCommunicate_57991_Content_7 = {
    Text = "Dopo il nostro ritorno, ci ho riflettuto a lungo."
  },
  AvgCommunicate_57991_Content_8 = {
    Text = "Sebbene quel verso fosse certamente \"brutto\" visto attraverso la lente tradizionale..."
  },
  AvgCommunicate_57991_Content_9 = {
    Text = "...credo che cose come la dissonanza, l'ironia e gli errori possano anch'essi far parte della poesia!"
  },
  AvgCommunicate_57991_Option_13 = {
    Text = "Dici sul serio?"
  },
  AvgCommunicate_57991_Option_18 = {
    Text = "Non dimenticare le mie royalty!"
  },
  AvgCommunicate_57991_Option_3 = {
    Text = "Che imbarazzo..."
  },
  AvgCommunicate_57991_Option_5 = {
    Text = "Pensavo fosse così bello, ma..."
  },
  AvgCommunicate_57992_Content_1 = {
