  },
  AvgCommunicate_60943_Content_3 = {
    Text = "Ho anche requisito della Gnosi d'Emergenza aggiuntiva per te. Anche se siamo a corto di personale, farò del mio meglio per organizzare qualcun altro che ti accompagni."
  },
  AvgCommunicate_60943_Content_4 = {Text = "Ramona."},
  AvgCommunicate_60943_Content_5 = {
    Text = "So che sei preoccupata per me. Grazie per tutto quello che hai fatto."
