  AvgCommunicate_60943_Content_7 = {
    Text = "Certo che mi fido delle tue capacità, è solo che…"
  },
  AvgCommunicate_60943_Content_8 = {
    Text = "Mi dispiace, sono abituata a fare Deduzioni su tutto. Se non sono presente, non posso fare a meno di pensare alle peggiori possibilità."
  },
  AvgCommunicate_60943_Content_9 = {
