  AvgCommunicate_66973_Content_1 = {
    Text = "Custode, grazie mille per aver suggerito a me e mia sorella di andare insieme al raduno."
  },
  AvgCommunicate_66973_Content_10 = {
    Text = "Che adorabile, vedere mia sorella arrossire così."
  },
  AvgCommunicate_66973_Content_11 = {
    Text = "Mm, il legame tra voi sorelle è davvero profondo..."
  },
  AvgCommunicate_66973_Content_12 = {
    Text = "Certo. Mia sorella sarà sempre la persona più importante per me, e continuerò a prendermi cura di lei per sempre."
  },
  AvgCommunicate_66973_Content_13 = {
    Text = "Sembra che ai prossimi incontri toccherà a me guidare mia sorella."
  },
  AvgCommunicate_66973_Content_14 = {
    Text = "Se ne avrai l'occasione, Custode, dovresti venire a unirti a noi!"
  },
  AvgCommunicate_66973_Content_15 = {
    Text = "Nessun problema!"
  },
  AvgCommunicate_66973_Content_2 = {
    Text = "Di niente! Felice di essere stato d'aiuto!"
  },
  AvgCommunicate_66973_Content_3 = {
    Text = "Prima dipendevo sempre da mia sorella, e lei si mostrava sempre forte davanti a me—persino un po' dura."
  },
  AvgCommunicate_66973_Content_4 = {
    Text = "Non mi sarei mai aspettata che fosse così agitata in quel tipo di situazione. Non ho mai visto mia sorella così timida prima d'ora."
  },
  AvgCommunicate_66973_Content_5 = {
    Text = "Hm? Ho sempre pensato che Faint avesse quel tipo di personalità riservata."
  },
  AvgCommunicate_66973_Content_6 = {
    Text = "No, in realtà mia sorella ha una personalità molto determinata, ed è piuttosto decisa!"
  },
  AvgCommunicate_66973_Content_7 = {
    Text = "Ogni volta che ero persa e Fragile, era sempre mia sorella a darmi consigli. Mi accarezzava sempre la testa e calmava dolcemente le mie emozioni."
  },
  AvgCommunicate_66973_Content_8 = {
    Text = "Capisco, non me lo sarei aspettato."
  },
  AvgCommunicate_66973_Content_9 = {
    Text = "Ma ora che non dobbiamo più affrontare una crisi di sopravvivenza, mia sorella può finalmente fare amicizia davanti agli altri."
  },
  AvgCommunicate_66973_Option_11 = {
