  AvgCommunicate_66975_Content_16 = {
    Text = "Bisogna essere pazzi per pensare che con cinquecento si possa comprare roba autentica!!! Che fine hanno fatto quegli anni di riserve??"
  },
  AvgCommunicate_66975_Content_17 = {
    Text = "P-perché Karen ama così tanto le cose luccicanti, ogni volta che Karen riceve dei soldi li spende tutti in cose brillanti, quindi Karen non ha risparmiato molto..."
  },
  AvgCommunicate_66975_Content_18 = {
    Text = "Lascia stare... Comunque, se ti piacciono semplicemente le pietre luccicanti, queste pietre sono effettivamente abbastanza brillanti, e la lavorazione è sufficientemente raffinata."
  },
  AvgCommunicate_66975_Content_19 = {
    Text = "Rispetto a comprare quelle vere, in realtà hai risparmiato una fortuna. Di cosa ti lamenti?"
  },
  AvgCommunicate_66975_Content_2 = {
    Text = "?? Cos'è successo?"
  },
  AvgCommunicate_66975_Content_20 = {
    Text = "Eh, in effetti ha molto senso."
  },
  AvgCommunicate_66975_Content_21 = {
    Text = "Karen si sente subito come se ci avesse guadagnato! Grazie, Maestro!"
  },
  AvgCommunicate_66975_Content_3 = {
    Text = "Daffodil, quella Donna traditrice! Ha truffato Karen portandole via tutte le Riserve per cui ha lavorato così duramente in tutti questi anni!"
  },
  AvgCommunicate_66975_Content_4 = {
    Text = "Daffodil ti ha truffato i soldi? Cosa sei andata a comprarle?"
  },
  AvgCommunicate_66975_Content_5 = {
    Text = "È tutto perché Karen stava sospirando guardando i prezzi di gioielli e accessori su una rivista, e quella Donna malvagia l'ha beccata proprio in quel momento."
  },
  AvgCommunicate_66975_Content_6 = {
    Text = "Ha detto a Karen che aveva un lotto di gioielli con pietre preziose in offerta speciale. Nessuno li voleva perché i design erano fuori moda, ma sarebbero stati perfetti per lo stile vintage di Karen..."
  },
  AvgCommunicate_66975_Content_7 = {
