  AvgCommunicate_66976_Content_3 = {
    Text = "È troppo piccolo per appartenere a un adulto, ma non ricordo di aver visto nessun bambino indossare un cilindro del genere."
  },
  AvgCommunicate_66976_Content_4 = {
