  },
  AvgCommunicate_66977_Content_1 = {
    Text = "Custode! Ti ho appena portato dei biscotti?"
  },
  AvgCommunicate_66977_Content_10 = {
    Text = "Che devo fare? Ti ho disturbato di nuovo. Contatterò subito la Sig.ra Sylvia!"
  },
  AvgCommunicate_66977_Content_11 = {
    Text = "Aspetta, non... Credo di aver capito cosa ha aggiunto..."
  },
  AvgCommunicate_66977_Content_12 = {
    Text = "Cosa? Che succede, Custode?"
  },
  AvgCommunicate_66977_Content_13 = {
    Text = "Quello che ha aggiunto... era un lassativo. Adesso vado in bagno."
  },
  AvgCommunicate_66977_Content_14 = {
    Text = "Potrei finire la carta, quindi per favore portamene un po' dopo..."
  },
  AvgCommunicate_66977_Content_15 = {
    Text = "Lo farò, lo farò! Mi dispiace!!"
  },
  AvgCommunicate_66977_Content_2 = {
    Text = "Ehm, sì? Li ho appena finiti di mangiare, erano deliziosi. Sei diventata davvero brava a cucinare."
  },
  AvgCommunicate_66977_Content_3 = {
    Text = "Oh no! Volevo dirti di NON mangiare quei biscotti! Non li ho fatti io!"
