  },
  AvgCommunicate_66977_Content_6 = {
    Text = "Credo che abbia aggiunto qualcosa ai biscotti mentre li preparava... Stai bene?"
  },
  AvgCommunicate_66977_Content_7 = {
    Text = "Ora che lo dici, sento un'improvvisa sensazione di terrore..."
