  AvgCommunicate_66977_Content_8 = {
    Text = "Cosa ha aggiunto? Non è veleno, vero?!"
  },
  AvgCommunicate_66977_Content_9 = {
    Text = "Non credo che arriverebbe a tanto! Le piace solo fare scherzi alla gente."
