  },
  AvgCommunicate_66978_Content_1 = {
    Text = "Ehi! Aiutami! Sono intrappolata nella coperta!"
  },
  AvgCommunicate_66978_Content_10 = {
    Text = "Questa è una delle faccende più facili che si possano fare. Sei completamente fuori dal mondo reale."
  },
  AvgCommunicate_66978_Content_11 = {
    Text = "Hmph... Suppongo che tratterò meglio i miei futuri schiavi. Ora vai a trovarmene di laboriosi!"
  },
  AvgCommunicate_66978_Content_12 = {
    Text = "Quante volte te lo devo dire che Roma non esiste più!"
  },
  AvgCommunicate_66978_Content_13 = {
    Text = "Non ci sono schiavi a servirti nella società moderna!"
  },
  AvgCommunicate_66978_Content_14 = {
    Text = "Non mi importa, non mi importa, non mi importa! Preferisco morire piuttosto che essere costretta a fare queste faccende ogni giorno!"
  },
  AvgCommunicate_66978_Content_15 = {
    Text = "Sia le faccende che i compiti, eh?"
  },
  AvgCommunicate_66978_Content_16 = {
    Text = "Ti butterò nel labirinto per sfamare le mie creature!!!"
  },
  AvgCommunicate_66978_Content_2 = {
    Text = "? Scusa, cosa??"
  },
  AvgCommunicate_66978_Content_3 = {
    Text = "È tutta colpa tua per non avermi assegnato degli schiavi!! Perché diavolo è così difficile cambiare questo maledetto lenzuolo?!"
  },
  AvgCommunicate_66978_Content_4 = {
    Text = "Non riuscivo a capire come piegarlo, così ho iniziato a lottare con la coperta!"
  },
  AvgCommunicate_66978_Content_5 = {Text = "..."},
