    Text = "Allora?! Non stare lì a... sbrigati a salvarmi! Non riesco a uscire!"
  },
  AvgCommunicate_66978_Content_7 = {
    Text = "Sono sinceramente impressionato che una come te sia riuscita a sopravvivere così a lungo."
  },
  AvgCommunicate_66978_Content_8 = {
