  AvgCommunicate_66979_Content_1 = {
    Text = "Custode, la torta che hai appena mandato alla Pozza Nera — era una torta di compleanno per Quel Tale, il dipendente senior che Forgia le Chiavi d'Argento, vero?"
  },
  AvgCommunicate_66979_Content_10 = {
    Text = "Pfft, ho capito. Ti porto subito un'altra fetta!"
  },
  AvgCommunicate_66979_Content_11 = {Text = "Grazie."},
  AvgCommunicate_66979_Content_2 = {
    Text = "Esatto! Sapevamo che non ne avresti mangiata, ma tutti volevano che partecipassi al divertimento, così te l'abbiamo mandata."
  },
  AvgCommunicate_66979_Content_3 = {
    Text = "Grazie per il gentile gesto. Per favore, porgi le mie Benedizioni di compleanno a nome mio, e... sarebbe possibile avere un'altra fetta di torta?"
  },
  AvgCommunicate_66979_Content_4 = {
    Text = "Eh? L'hai mangiata davvero?!"
  },
  AvgCommunicate_66979_Content_5 = {
    Text = "Un impulso del momento. Quella persona ha lavorato con me per molti anni e non ha mai commesso un singolo errore."
  },
  AvgCommunicate_66979_Content_6 = {
    Text = "Sebbene possieda una conoscenza infinita e comprenda tutti i principi, io... in realtà non avevo mai mangiato una torta prima d'ora."
  },
  AvgCommunicate_66979_Content_7 = {
    Text = "Capisco, quindi intendi dire che conoscevi la torta solo in teoria?"
  },
  AvgCommunicate_66979_Content_8 = {
    Text = "Sì, conoscevo tutti i componenti di questa torta, e che l'esperienza gustativa avrebbe dovuto essere dolce con l'aroma di ricchi grassi animali."
  },
  AvgCommunicate_66979_Content_9 = {
    Text = "Ma non avrei mai immaginato che la torta potesse essere così dolce e fragrante…"
  },
  AvgCommunicate_66979_Option_10 = {
    Text = "Pfft, ho capito."
  },
