  },
  AvgCommunicate_66980_Content_10 = {
    Text = "Smettila di studiarlo! Non hai bisogno di sapere COSÌ tanto! È troppo costoso perché tu ci metta le mani!"
  },
  AvgCommunicate_66980_Content_11 = {
    Text = "Allora dimmi a cosa dovrebbe servire questa scatola."
  },
  AvgCommunicate_66980_Content_12 = {
    Text = "È un comunicatore che ti ha dato la scuola. Ti permetterà di comunicare con altre persone a distanza, o di chiedere aiuto se sei in pericolo."
  },
  AvgCommunicate_66980_Content_13 = {
    Text = "Capisco, che invenzione interessante. Grazie, Custode."
  },
  AvgCommunicate_66980_Content_14 = {
    Text = "Ti ricordi davvero chi sono?"
  },
  AvgCommunicate_66980_Content_15 = {
    Text = "Certo che sì. Ho promesso che non ti avrei mai dimenticato!"
  },
  AvgCommunicate_66980_Content_16 = {
    Text = "Sei il mio amico, %player%!"
  },
  AvgCommunicate_66980_Content_2 = {
    Text = "? Hai dimenticato di nuovo?"
  },
  AvgCommunicate_66980_Content_3 = {
    Text = "Dimenticato? Non ricordo da dove venga questa scatola."
  },
  AvgCommunicate_66980_Content_4 = {
    Text = "Ma ho visto i registri delle chat. Credo di averlo usato prima, ma non ricordo come si usa adesso..."
  },
  AvgCommunicate_66980_Content_5 = {
