  AvgCommunicate_66981_Content_1 = {
    Text = "Custode, cosa ne pensi delle emozioni umane?"
  },
  AvgCommunicate_66981_Content_10 = {
    Text = "E tu, allora? In quanto Corpo intellettuale, non dovresti essere assolutamente razionale?"
  },
  AvgCommunicate_66981_Content_11 = {
    Text = "Sei perspicace, Custode, ed è uno dei motivi per cui ho sempre cercato di ridurre al minimo il mio contatto con il mondo."
  },
  AvgCommunicate_66981_Content_12 = {
    Text = "Quando resto distaccato dal mondo ed evito di mantenere legami troppo stretti con gli esseri umani, riesco a mantenere i miei pensieri lucidi e indipendenti."
  },
  AvgCommunicate_66981_Content_13 = {
    Text = "È come se non avessi mai assaggiato la dolcezza di una torta: non svilupperei costantemente una preferenza per essa nei miei pensieri."
  },
  AvgCommunicate_66981_Content_14 = {
    Text = "Capisco... Quindi, adesso vorresti mangiare dei dolcetti?"
  },
  AvgCommunicate_66981_Content_15 = {
    Text = "Non è una necessità, ma se per te non è un problema, te ne sarei molto grata."
  },
  AvgCommunicate_66981_Content_2 = {
    Text = "Un argomento così profondo fin dall'inizio!"
  },
  AvgCommunicate_66981_Content_3 = {
    Text = "Le emozioni... tutti le hanno, dopotutto siamo solo esseri umani."
  },
  AvgCommunicate_66981_Content_4 = {
    Text = "Esatto. Gli esseri umani esistono facendo affidamento sulla propria carne, e le emozioni nascono da reazioni istintive."
  },
  AvgCommunicate_66981_Content_5 = {
    Text = "La maggior parte delle scelte umane è influenzata dalle emozioni piuttosto che dal pensiero razionale, che richiede disciplina e sforzo consapevole."
  },
  AvgCommunicate_66981_Content_6 = {
    Text = "In effetti, mantenere una razionalità assoluta in ogni momento sembra possibile solo per la Professoressa Doll."
  },
  AvgCommunicate_66981_Content_7 = {
    Text = "No, nemmeno Doll ci riesce. Ha ancora legami emotivi e, quando prende decisioni, è disposta a fare scommesse disperate."
  },
  AvgCommunicate_66981_Content_8 = {
    Text = "È davvero così? Tutte le persone sono fatte in questo modo, compresi quegli individui deviati e folli?"
  },
  AvgCommunicate_66981_Content_9 = {
    Text = "Sì. Le scelte estreme sono guidate dalle emozioni in modo ancora più profondo."
  },
  AvgCommunicate_66981_Option_10 = {
    Text = "E tu, allora? In quanto Corpo intellettuale, non dovresti essere assolutamente razionale?"
  },
  AvgCommunicate_66981_Option_14 = {
    Text = "Capisco... Quindi, adesso vorresti mangiare dei dolcetti?"
  },
  AvgCommunicate_66981_Option_2 = {
    Text = "Un argomento così profondo fin dall'inizio!"
  },
  AvgCommunicate_66981_Option_6 = {
    Text = "In effetti, mantenere una razionalità assoluta in ogni momento sembra possibile solo per la Professoressa Doll."
  },
  AvgCommunicate_66981_Option_8 = {
    Text = "È davvero così? Tutte le persone sono fatte in questo modo, compresi quegli individui deviati e folli?"
  },
  AvgCommunicate_66982_Content_1 = {
    Text = "Custode, ti sto dando l'opportunità di guadagnarti il mio favore."
  },
  AvgCommunicate_66982_Content_10 = {
    Text = "Perché non vendi direttamente me, già che ci sei."
  },
  AvgCommunicate_66982_Content_11 = {
    Text = "Come faccio a comprare uno di quei giocattoli dell'alta società che non si possono ottenere nemmeno con i soldi!"
  },
  AvgCommunicate_66982_Content_12 = {
    Text = "Non mi interessa! Trova un modo. Anche quel coniglietto non vede l'ora di venire da me."
  },
  AvgCommunicate_66982_Content_13 = {
    Text = "Ho già pensato a un nome per lui: Ivy!"
  },
  AvgCommunicate_66982_Content_14 = {
    Text = "Farà i tea party con me, insieme a Jenny e Oliver."
  },
  AvgCommunicate_66982_Content_15 = {
    Text = "Va bene, va bene, va bene. Andrò a supplicare Lady Sorel e te lo riporterò sicuramente per la vostra piccola riunione."
  },
  AvgCommunicate_66982_Content_16 = {
    Text = "Hehe, così mi piace!"
