  },
  AvgCommunicate_66982_Content_8 = {
    Text = "C'è praticamente il mio nome scritto dappertutto! La rivista dice che è una specie di pezzo artigianale di alta qualità. Sbrigati a comprarmelo!"
  },
  AvgCommunicate_66982_Content_9 = {
    Text = "Artigianale di alta qualità?"
  },
  AvgCommunicate_66982_Option_10 = {
    Text = "Perché non vendi direttamente me, già che ci sei."
  },
  AvgCommunicate_66982_Option_15 = {
