  },
  AvgCommunicate_66982_Option_4 = {
    Text = "Beh, cos'altro..."
  },
  AvgCommunicate_66982_Option_9 = {
    Text = "Artigianale di alta qualità?"
  },
  AvgCommunicate_66983_Content_1 = {
    Text = "Ehi, non c'è bisogno che mi porti dolci in questi giorni."
  },
  AvgCommunicate_66983_Content_10 = {
    Text = "E con quella sfolgorante varietà di ingredienti, puoi aggiungerne quanti ne vuoi... è assolutamente delizioso!"
