    Text = "Che ne sai tu? Le mie nuove creazioni hanno ricevuto lodi infinite da quegli chef!"
  },
  AvgCommunicate_66983_Content_13 = {
    Text = "La produzione è iniziata ieri ed è già sugli scaffali della mensa. C'è un sacco di gente in fila!"
  },
  AvgCommunicate_66983_Content_14 = {
    Text = "Quindi sei stata tu a fare quella nuova mini torta che è andata esaurita all'istante ieri!"
  },
  AvgCommunicate_66983_Content_15 = {
    Text = "Hahahahaha, non sono fantastica? Chiamatemi genio!"
  },
  AvgCommunicate_66983_Content_16 = {Text = "Geniale!"},
  AvgCommunicate_66983_Content_17 = {
    Text = "Ma all'improvviso ho capito che le torte fatte in casa potrebbero essere più buone. Continuare così d'ora in poi non è una cattiva idea."
  },
  AvgCommunicate_66983_Content_18 = {
    Text = "Che gioia sincera. La signorina ha finalmente scoperto la soddisfazione del lavoro."
  },
  AvgCommunicate_66983_Content_2 = {
    Text = "Cosa vedo? Che catastrofe ti ha colpito?"
  },
  AvgCommunicate_66983_Content_3 = {
    Text = "Quale catastrofe? Sto benissimo!"
  },
  AvgCommunicate_66983_Content_4 = {Text = "Chi sei?"},
  AvgCommunicate_66983_Content_5 = {
    Text = "Sigh, è solo che ultimamente mi sono completamente stufata delle tortine della mensa, e quegli chef senza cervello non hanno nessuna intenzione di introdurne di nuove!"
  },
  AvgCommunicate_66983_Content_6 = {
    Text = "In effetti, nessuno ha una voglia così smisurata di cupcake come te..."
  },
  AvgCommunicate_66983_Content_7 = {
    Text = "È tutta colpa loro per essere così incompetenti, così ho fatto irruzione in cucina e mi sono fatta insegnare come preparare una torta."
  },
  AvgCommunicate_66983_Content_8 = {
    Text = "Eh? Tu, cucinare?"
  },
  AvgCommunicate_66983_Content_9 = {
    Text = "Sorpresa! Poi ho scoperto che fare una torta non è affatto difficile! Sono semplicemente un genio naturale!"
  },
  AvgCommunicate_66983_Option_11 = {
    Text = "Non è questo il punto cruciale?! Aggiungerne troppi non la renderà disgustosamente dolce?"
  },
  AvgCommunicate_66983_Option_14 = {
    Text = "Quindi sei stata tu a fare quella nuova mini torta che è andata esaurita all'istante ieri!"
  },
