  },
  AvgCommunicate_66984_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} %player%, ho un piccolo problema, mi daresti una mano?"
  },
  AvgCommunicate_66984_Content_10 = {
    Text = "Ma gli ho detto che ho già un cavaliere per il ballo."
  },
  AvgCommunicate_66984_Content_11 = {
    Text = "In verità, solo adesso sto venendo a cercare il mio adorabile cavaliere."
  },
  AvgCommunicate_66984_Content_12 = {
    Text = "Penso che {Male=he,Female=she} non sopporterebbe di lasciarmi andare al ballo tutta sola, giusto?"
  },
  AvgCommunicate_66984_Content_13 = {
    Text = "Che ne dici?"
  },
  AvgCommunicate_66984_Content_14 = {
    Text = "L'onore è mio, mia signora."
  },
  AvgCommunicate_66984_Content_15 = {
    Text = "Sembra che farei meglio a ripassare i miei passi di danza e il galateo, per non pestare i piedi alla mia signora."
  },
  AvgCommunicate_66984_Content_16 = {
    Text = "Sei sempre così affidabile e premuroso, mio Cavaliere."
  },
  AvgCommunicate_66984_Content_2 = {
    Text = "Cosa vi mette in difficoltà, Lady Sorel?"
  },
  AvgCommunicate_66984_Content_3 = {
    Text = "Sono tutt'orecchi."
  },
  AvgCommunicate_66984_Content_4 = {
    Text = "Tra qualche giorno parteciperò a una cena danzante. Sai il tipo... un mucchio di persone pretenziose e pignole che oziano insieme."
  },
  AvgCommunicate_66984_Content_5 = {
    Text = "La cosa fastidiosa è che un tizio assolutamente maleducato mi sta importunando ultimamente. Anche lui parteciperà al ballo e mi ha invitata a gran voce come sua accompagnatrice."
  },
  AvgCommunicate_66984_Content_6 = {
    Text = "Che seccatura. Volete che me ne occupi io, mia signora?"
  },
  AvgCommunicate_66984_Content_7 = {
    Text = "Eheheh, stai diventando sempre più bravo a scherzare."
  },
  AvgCommunicate_66984_Content_8 = {
    Text = "Purtroppo, per ora non è un'opzione. Il mondo degli adulti è complicato così. Tuttavia, ho già declinato il suo invito."
  },
  AvgCommunicate_66984_Content_9 = {
    Text = "Allora la questione non è risolta?"
  },
  AvgCommunicate_66984_Option_14 = {
    Text = "L'onore è mio, mia signora."
  },
  AvgCommunicate_66984_Option_2 = {
    Text = "Cosa vi mette in difficoltà, Lady Sorel?"
  },
  AvgCommunicate_66984_Option_3 = {
    Text = "Sono tutt'orecchi."
  },
  AvgCommunicate_66984_Option_6 = {
    Text = "Che seccatura. Volete che me ne occupi io, mia signora?"
  },
  AvgCommunicate_66984_Option_9 = {
    Text = "Allora la questione non è risolta?"
  },
  AvgCommunicate_66985_Content_1 = {
    Text = "Mio piccolo Cavaliere, grazie al tuo aiuto al Ballo l'ultima volta, sono riuscita a liberarmi di quella persona orribile."
  },
  AvgCommunicate_66985_Content_10 = {
    Text = "Un desiderio? Allora desidero che la bella Lady Sorel condivida con me una sontuosa cena a lume di candela."
  },
  AvgCommunicate_66985_Content_11 = {
    Text = "Solo tu e io, senza bisogno di intrattenere nessun altro."
  },
  AvgCommunicate_66985_Content_12 = {
    Text = "Come desideri, piccolo furbetto."
  },
  AvgCommunicate_66985_Content_13 = {
    Text = "Cosa vorresti mangiare? Dimmelo, e lo assaporerò insieme a te."
  },
  AvgCommunicate_66985_Content_14 = {
    Text = "Questo mette davvero alla prova l'immaginazione di qualcuno come me che mangia in mensa tutti i giorni. Bene allora, lasciatemi provare... qualunque cosa la mia Lady ami mangiare di più."
  },
  AvgCommunicate_66985_Content_15 = {
    Text = "Hehe, che bambino affascinante che sei."
  },
  AvgCommunicate_66985_Content_16 = {
    Text = "Allora, attenderò la tua visita nella mia residenza."
  },
  AvgCommunicate_66985_Content_2 = {
    Text = "Per ringraziarti della tua gentilezza e generosità, vorrei fare qualcosa per te come segno della mia gratitudine."
  },
  AvgCommunicate_66985_Content_3 = {
    Text = "Siete troppo gentile, Lady Sorel. Pensavo che il nostro rapporto avesse già superato il punto in cui è necessario dire grazie."
  },
  AvgCommunicate_66985_Content_4 = {
    Text = "In effetti, non mi piace esprimere gratitudine a parole. Il più delle volte, sono solo vuote formalità."
  },
  AvgCommunicate_66985_Content_5 = {
    Text = "Tuttavia, un'opportunità di farmi qualsiasi richiesta... non ti interessa davvero?"
  },
  AvgCommunicate_66985_Content_6 = {
    Text = "Wow, qualsiasi richiesta? Se quei nobili signori lo venissero a sapere, morirebbero d'invidia."
  },
  AvgCommunicate_66985_Content_7 = {
    Text = "Tu meriti sempre un trattamento speciale da parte mia."
  },
  AvgCommunicate_66985_Content_8 = {
    Text = "Adesso mi hai messo davvero in difficoltà. È così difficile decidere… Se esagerassi e chiedessi una villa, la scuola lo scoprirebbe…"
  },
  AvgCommunicate_66985_Content_9 = {
    Text = "Non preoccuparti, mi occuperò di tutto. Sentiti libero di esprimere il tuo desiderio."
  },
  AvgCommunicate_66985_Option_10 = {
    Text = "Un desiderio?"
  },
  AvgCommunicate_66985_Option_14 = {
    Text = "Allora lasciatemi provare... qualunque cosa la mia Lady ami mangiare di più."
  },
  AvgCommunicate_66985_Option_3 = {
    Text = "Siete troppo gentile, Lady Sorel."
  },
  AvgCommunicate_66985_Option_6 = {
    Text = "Wow, qualsiasi richiesta?"
  },
  AvgCommunicate_66985_Option_8 = {
    Text = "Adesso mi hai messo davvero in difficoltà…"
  },
  AvgCommunicate_66986_Content_1 = {
    Text = "Lotan e io abbiamo appena avuto un incontro. È finito in parità."
  },
  AvgCommunicate_66986_Content_10 = {
    Text = "Ahaha… Non credo di avere così tanti pensieri che mi distraggono, quindi per ora passo…"
  },
  AvgCommunicate_66986_Content_11 = {
    Text = "Allora sei forte anche tu."
  },
  AvgCommunicate_66986_Content_12 = {
    Text = "Purtroppo, c'è sempre qualcuno che pesca accanto a quella cascata. È un po' rumoroso."
  },
  AvgCommunicate_66986_Content_13 = {
    Text = "Una volta sono uscita dalla cascata e ho provato a chiedergli di fare meno rumore. Si è spaventato così tanto che mi ha lanciato il pesce in faccia ed è scappato via."
  },
  AvgCommunicate_66986_Content_14 = {
    Text = "Chissà se tornerà la prossima volta."
  },
  AvgCommunicate_66986_Content_15 = {
    Text = "Hmm… Non credo che lo farà…"
  },
  AvgCommunicate_66986_Content_2 = {
    Text = "Cos'è successo tra voi due?"
  },
  AvgCommunicate_66986_Content_3 = {
    Text = "Non avete litigato, vero?"
  },
  AvgCommunicate_66986_Content_4 = {
    Text = "No, solo un combattimento di allenamento tra guerrieri."
  },
  AvgCommunicate_66986_Content_5 = {
    Text = "Prima, lei ha detto che il mio modo di combattere non era abbastanza puro. Credo di aver capito ora."
  },
  AvgCommunicate_66986_Content_6 = {
    Text = "Ho trovato un modo per diventare più pura. La me attuale è più forte."
  },
  AvgCommunicate_66986_Content_7 = {
    Text = "È una buona cosa, ma che metodo usi per diventare più pura?"
  },
  AvgCommunicate_66986_Content_8 = {
    Text = "Stare sotto una cascata e lasciare che l'acqua lavi via i pensieri che distraggono."
  },
  AvgCommunicate_66986_Content_9 = {
    Text = "È molto efficace. Vuoi venire insieme a me?"
  },
  AvgCommunicate_66986_Option_10 = {
    Text = "Ahaha… Non credo di avere così tanti pensieri che mi distraggono, quindi per ora passo…"
  },
  AvgCommunicate_66986_Option_15 = {
    Text = "Hmm… Non credo che lo farà…"
  },
