  },
  AvgCommunicate_66987_Content_1 = {
    Text = "Custode, conosci qualche ricetta a base di pesce?"
  },
  AvgCommunicate_66987_Content_10 = {
    Text = "Che vecchietta gentile e premurosa."
  },
  AvgCommunicate_66987_Content_11 = {
    Text = "Mm. Perciò voglio imparare a cucinare il pesce anch'io. La prossima volta, sarò io a cucinare per lei."
  },
  AvgCommunicate_66987_Content_12 = {
    Text = "Che cosa commovente! Devi assolutamente farlo! Vado subito a interrogare il cuoco della mensa per te!"
  },
  AvgCommunicate_66987_Content_13 = {Text = "Grazie."},
  AvgCommunicate_66987_Content_2 = {
    Text = "Ricette?? Hai intenzione di cucinare?"
  },
  AvgCommunicate_66987_Content_3 = {
    Text = "Mm, dopo che l'ultima volta ho spaventato quel pescatore, nei pressi della cascata è rimasto tutto tranquillo per un bel po'."
  },
  AvgCommunicate_66987_Content_4 = {
    Text = "Di recente, una vecchietta ha iniziato a venire qui a pescare. Non fa mai rumore, quindi non mi sono mai fatta vedere."
  },
  AvgCommunicate_66987_Content_5 = {
    Text = "Poi, una volta, ha acceso un fuoco e ha iniziato a grigliare il pesce che aveva pescato."
  },
  AvgCommunicate_66987_Content_6 = {
    Text = "Il profumo era così buono che il mio stomaco ha fatto un piccolo rumore, e lei mi ha scoperta."
  },
  AvgCommunicate_66987_Content_7 = {
    Text = "Eh? L'hai spaventata anche lei?"
  },
  AvgCommunicate_66987_Content_8 = {
    Text = "No, mi ha invitata a mangiare il pesce grigliato insieme a lei. Era delizioso."
  },
  AvgCommunicate_66987_Content_9 = {
    Text = "In seguito ha iniziato a portare una pentolina quando veniva a pescare, poi preparava la zuppa di pesce e la condivideva con me."
  },
  AvgCommunicate_66987_Option_10 = {
    Text = "Che vecchietta gentile e premurosa."
  },
  AvgCommunicate_66987_Option_12 = {
    Text = "Che cosa commovente! Devi assolutamente farlo! Vado subito a interrogare il cuoco della mensa per te!"
  },
  AvgCommunicate_66987_Option_2 = {
    Text = "Ricette?? Hai intenzione di cucinare?"
  },
  AvgCommunicate_66987_Option_7 = {
    Text = "Eh? L'hai spaventata anche lei?"
  },
  AvgCommunicate_66988_Content_1 = {
    Text = "Di recente ho guadagnato una bella somma di denaro, ma nel processo ho quasi perso la vita. Per fortuna, la dea della fortuna mi concede sempre la sua Benedizione."
  },
  AvgCommunicate_66988_Content_10 = {
    Text = "Ma quando abbiamo iniziato a combattere, la trappola che aveva piazzato si è attivata per sbaglio e ha colpito lui."
  },
  AvgCommunicate_66988_Content_11 = {Text = "Eh?"},
  AvgCommunicate_66988_Content_12 = {
    Text = "Gli ho persino praticato un controllo d'emergenza del Sangue, ed è l'unico motivo per cui era ancora vivo quando l'ho portato alla stazione di polizia."
  },
  AvgCommunicate_66988_Content_13 = {
    Text = "La polizia mi ha dato una ricompensa. Il detenuto è tornato in prigione, e ho sentito che la sua condanna verrà cambiata in ergastolo."
  },
  AvgCommunicate_66988_Content_14 = {
    Text = "Gli mancavano solo pochi anni prima di poter uscire. Perché ha dovuto fare una cosa così sciocca... *sigh*..."
  },
  AvgCommunicate_66988_Content_15 = {
    Text = "Difficile dire chi stia peggio, tu o lui..."
  },
  AvgCommunicate_66988_Content_16 = {
    Text = "Ma aspetta, non sono venuti quelli del Fang della Scommessa proprio ieri a riscuotere un debito? Che fine ha fatto la tua ricompensa?"
  },
  AvgCommunicate_66988_Content_17 = {
    Text = "Ahaha... Beh, la mia fortuna è limitata dopotutto. Se la spendo tutta in anticipo, è inevitabile che perda qualche mano al tavolo..."
  },
  AvgCommunicate_66988_Content_18 = {
    Text = "A sentire questo, improvvisamente mi sento molto meglio riguardo alle cose."
  },
  AvgCommunicate_66988_Content_2 = {
    Text = "Cos'è successo??"
  },
  AvgCommunicate_66988_Content_3 = {
    Text = "Sai, di solito accetto incarichi da detective all'esterno. Il mio tasso di successo nella risoluzione dei casi è così alto che sono sempre molto richiesta."
  },
  AvgCommunicate_66988_Content_4 = {
    Text = "Ma d'altro canto, quei criminali che ho fatto finire in prigione mi detestano profondamente."
  },
  AvgCommunicate_66988_Content_5 = {
    Text = "Beh, dopotutto hanno perso nei modi più sconcertanti."
  },
  AvgCommunicate_66988_Content_6 = {
    Text = "Un paio di giorni fa, un detenuto è evaso di prigione e ha sorvegliato per giorni il Fang dove gioco d'azzardo abitualmente, finché non mi ha finalmente beccata."
  },
  AvgCommunicate_66988_Content_7 = {
    Text = "Era lì per vendicarsi di te?!"
  },
  AvgCommunicate_66988_Content_8 = {
    Text = "Esatto. Mi ha pedinata a lungo e alla fine mi ha messa con le spalle al muro in un vicolo."
  },
  AvgCommunicate_66988_Content_9 = {
    Text = "Aveva piazzato delle trappole nel vicolo in anticipo, con l'intenzione di uccidermi."
  },
  AvgCommunicate_66988_Option_11 = {Text = "Eh?"},
  AvgCommunicate_66988_Option_15 = {
    Text = "Difficile dire chi stia peggio, tu o lui..."
  },
  AvgCommunicate_66988_Option_18 = {
    Text = "A sentire questo, improvvisamente mi sento molto meglio riguardo alle cose."
  },
  AvgCommunicate_66988_Option_2 = {
    Text = "Cos'è successo??"
  },
  AvgCommunicate_66988_Option_5 = {
    Text = "Beh, dopotutto hanno perso nei modi più sconcertanti."
  },
  AvgCommunicate_66988_Option_7 = {
    Text = "Era lì per vendicarsi di te?!"
  },
  AvgCommunicate_66989_Content_1 = {
    Text = "Custode, ho finito di compilare i protocolli di gestione delle crisi per gli Investigatori su cui mi avevi consultata."
  },
  AvgCommunicate_66989_Content_10 = {
    Text = "Per quanto io possa essere più attenta alle tue esigenze rispetto a quella Ramona, non dimenticare— un tempo ero lei anch'io."
  },
  AvgCommunicate_66989_Content_11 = {
    Text = "Se vuoi ingannarmi, dovrai esercitarti di più."
  },
  AvgCommunicate_66989_Content_12 = {
    Text = "Sigh… La mia sincerità è stata sprecata con la persona sbagliata!"
  },
  AvgCommunicate_66989_Content_13 = {
    Text = "Quindi riguardo a quei compiti— cioè, quella domanda— almeno dammi un indizio su come affrontarla!"
  },
  AvgCommunicate_66989_Content_14 = {Text = "Ramona?"},
  AvgCommunicate_66989_Content_15 = {Text = "Ramona—"},
  AvgCommunicate_66989_Content_2 = {
    Text = "Meraviglioso! Sapevo che eri la più affidabile."
  },
  AvgCommunicate_66989_Content_3 = {
    Text = "Grazie, ma potresti tranquillamente chiedere alla Ramona del tuo mondo per questo tipo di domande. Perché venire da me?"
  },
  AvgCommunicate_66989_Content_4 = {
    Text = "Sai com'è— quella Ramona è sempre stata così seria su tutto. Se vado a chiederle direttamente, sicuramente mi farà ragionare da solo."
  },
  AvgCommunicate_66989_Content_5 = {
    Text = "Ma il punto è questo! Credo che l'apprendimento progredisca più velocemente attraverso la discussione reciproca e lo scambio di idee!"
  },
  AvgCommunicate_66989_Content_6 = {Text = "Capito."},
  AvgCommunicate_66989_Content_7 = {
    Text = "Quindi mi stai chiedendo di aiutarti a finire i compiti."
  },
  AvgCommunicate_66989_Content_8 = {Text = "?!"},
  AvgCommunicate_66989_Content_9 = {
    Text = "Q-questo assolutamente no, come potrebbe essere, ahaha…"
  },
  AvgCommunicate_66989_Option_12 = {
    Text = "Sigh… La mia sincerità è stata sprecata con la persona sbagliata!"
  },
  AvgCommunicate_66989_Option_2 = {
    Text = "Meraviglioso! Sapevo che eri la più affidabile."
  },
  AvgCommunicate_66989_Option_4 = {
    Text = "Sai com'è…"
  },
  AvgCommunicate_66989_Option_8 = {Text = "?!"},
  AvgCommunicate_66990_Content_1 = {
    Text = "Custoode, i nomi di tutti sono così difficili da scrivere. Non riesco a ricordare come si scrivono!"
  },
  AvgCommunicate_66990_Content_10 = {
    Text = "Allora, allora lo cambio! Non devi dirlo a nessuno!"
  },
  AvgCommunicate_66990_Content_11 = {
    Text = "Va bene, va bene, e i nomi di Aigis e Lily?"
  },
  AvgCommunicate_66990_Content_12 = {
    Text = "Ovviamente, i loro nomi sono Aigis e Lily. Sono amici. Gli amici non possono avere lo stesso nome!"
  },
  AvgCommunicate_66990_Content_13 = {
    Text = "E allora perché io mi chiamo il Custtode..."
  },
  AvgCommunicate_66990_Content_14 = {
    Text = "Non è più o meno lo stesso?! Non fare il lamentoso! Aiutami a inventare i nomi in codice per gli altri!"
  },
  AvgCommunicate_66990_Content_15 = {
    Text = "Credo sia più affidabile trovare prima qualcuno che ti insegni a leggere e scrivere."
  },
  AvgCommunicate_66990_Content_2 = {
    Text = "Beh, in effetti è un po' impegnativo per te. Che ne dici di farti dare una lezione di alfabetizzazione da Ramona?"
  },
  AvgCommunicate_66990_Content_3 = {
    Text = "Ma dai! E allora, Moccioso dell'Ovest? Mi stai guardando dall'alto in basso solo perché non so leggere?"
  },
  AvgCommunicate_66990_Content_4 = {
    Text = "Io non... Non sei stato tu a tirarlo fuori per primo!"
  },
  AvgCommunicate_66990_Content_5 = {
    Text = "Hmph, è troppo facile. Non potrebbe certo mettere in difficoltà una ladra provetta come me."
  },
  AvgCommunicate_66990_Content_6 = {
    Text = "Ho deciso di dare a tutti un nome in codice, così posso scriverlo."
  },
  AvgCommunicate_66990_Content_7 = {
    Text = "Per esempio?"
  },
  AvgCommunicate_66990_Content_8 = {
    Text = "Per esempio, Robot, Lumachina di Mare, Donna Rossa, Testa Rosa... Non ne ho ancora pensati molti!"
  },
  AvgCommunicate_66990_Content_9 = {
    Text = "Pfft, intendi la Dama in Rosso! E se Doll sentisse questo soprannome..."
  },
  AvgCommunicate_66990_Option_11 = {
    Text = "Va bene, va bene, e i nomi di Aigis e Lily?"
  },
  AvgCommunicate_66990_Option_13 = {
