  AvgCommunicate_66991_Content_1 = {
    Text = "Custode dei Gatti!! Brown è scomparso. L'hai visto?"
  },
  AvgCommunicate_66991_Content_10 = {
    Text = "Immagino che per ora sia tutto quello che possiamo fare... Grazie, Custode dei Gatti."
  },
  AvgCommunicate_66991_Content_11 = {
    Text = "Adesso fai la gentile con me? Lascia che mi vesta e esca... Aspetta un momento."
  },
  AvgCommunicate_66991_Content_12 = {
    Text = "Perché c'è una coda dall'aspetto familiare nel mio mucchio di vestiti..."
  },
  AvgCommunicate_66991_Content_13 = {
    Text = "Brown?! Brown è a casa tua?"
  },
  AvgCommunicate_66991_Content_14 = {
    Text = "Sì, puoi smettere di cercare. Inoltre, si è impigliato nella mia maglietta, e ha uno dei miei calzini in bocca e non lo molla. Hai idea di cosa significhi?"
  },
  AvgCommunicate_66991_Content_15 = {
    Text = "Q-quello è sicuramente solo un suo passatempo da topo. Non ha niente a che fare con me!"
  },
  AvgCommunicate_66991_Content_16 = {
    Text = "Al massimo, ti comprerò un paio di calzini nuovi."
  },
  AvgCommunicate_66991_Content_2 = {
    Text = "Brown? Non è sempre con te?"
  },
  AvgCommunicate_66991_Content_3 = {
    Text = "La maggior parte del tempo sì, ma a volte esce a rub... *ehm* a cacciare cose. Di solito torna entro mezza giornata, ma ormai è un giorno intero che non lo vedo!"
  },
  AvgCommunicate_66991_Content_4 = {
    Text = "Non farti prendere dal panico. Lascia che ti aiuti a pensare a qualcosa. Dove gli piace andare di solito?"
  },
  AvgCommunicate_66991_Content_5 = {
    Text = "Va in cucina più spesso, ma quegli sciocchi non riuscirebbero mai a catturare Brown."
  },
  AvgCommunicate_66991_Content_6 = {
    Text = "Potrebbe anche andare nei laboratori a cercare cosine luccicanti, ma ho già controllato ognuno di essi. Nessuna traccia di Brown da nessuna parte."
