  AvgCommunicate_66992_Content_1 = {
    Text = "Custode, ho già esaudito il desiderio che hai espresso l'ultima volta."
  },
  AvgCommunicate_66992_Content_10 = {
    Text = "L'ho scambiato con quello di Ramona, così il numero di compiti torna."
