  AvgCommunicate_66992_Content_12 = {
    Text = "Non preoccuparti? Se ne accorgerà sicuramente!"
  },
  AvgCommunicate_66992_Content_13 = {
    Text = "...Qualcuno sta bussando alla mia porta..."
