  AvgCommunicate_66996_Content_1 = {
    Text = "Mythag è un posto così noioso."
  },
  AvgCommunicate_66996_Content_10 = {
    Text = "Allora ti auguro di trovare ciò che cerchi. Se mai vorrai tornare, le porte di Mythag saranno sempre aperte per te."
  },
  AvgCommunicate_66996_Content_2 = {
    Text = "Un branco di sedicenti giusti che tengono rinchiuse un branco di bestie col collare."
  },
  AvgCommunicate_66996_Content_3 = {
    Text = "Non capisco proprio perché quell'altra me sia disposta a partecipare ai vostri giochetti noiosi. Ma d'altronde, pensando a quanto è debole, ha tutto senso."
  },
  AvgCommunicate_66996_Content_4 = {
    Text = "Non sei mai stata protetta con risolutezza da nessuno, quindi è naturale che tu non comprenda i sentimenti e il significato dell'essere un guardiano."
  },
  AvgCommunicate_66996_Content_5 = {
    Text = "Helot è una guerriera eccezionale. Ha semplicemente scelto di accettare il calore e l'aiuto offerti dagli altri."
  },
  AvgCommunicate_66996_Content_6 = {
    Text = "Ha, fate come vi pare. Se è disposta a portare un collare, allora che resti pure qui."
  },
  AvgCommunicate_66996_Content_7 = {
