  },
  AvgCommunicate_66996_Content_8 = {
    Text = "Va bene, immagino che non risponderesti nemmeno se ti chiedessi dove stai andando."
  },
  AvgCommunicate_66996_Content_9 = {
    Text = "Ovunque possa diventare più forte, è lì che andrò."
  },
  AvgCommunicate_66996_Option_10 = {
    Text = "Allora ti auguro di trovare ciò che cerchi."
  },
  AvgCommunicate_66996_Option_4 = {
    Text = "Non sei mai stata protetta con risolutezza da nessuno, quindi è naturale che tu non comprenda i sentimenti e il significato dell'essere un guardiano."
  },
  AvgCommunicate_66996_Option_8 = {
    Text = "Va bene, immagino che non risponderesti nemmeno se ti chiedessi dove stai andando."
  },
  AvgCommunicate_66997_Content_1 = {
    Text = "Ehi, ho sentito che Murphy non ha frequentato le lezioni di recente. Che succede?"
  },
  AvgCommunicate_66997_Content_10 = {
    Text = "Ovvio, ne sequestrerò uno e lo porterò qui."
  },
  AvgCommunicate_66997_Content_11 = {
    Text = "Pronto, è la polizia? Qualcuno sta per commettere di nuovo un crimine."
  },
  AvgCommunicate_66997_Content_12 = {
    Text = "Va bene, ne comprerò uno, d'accordo? Impiccione."
  },
  AvgCommunicate_66997_Content_13 = {
    Text = "Ricorda, ti tengo d'occhio. Se provi a fare qualcosa di strano con Murphy... Hmph."
  },
  AvgCommunicate_66997_Content_2 = {
    Text = "Ha mangiato troppe tortine e le è venuto mal di pancia. Ma perché non glielo chiedi direttamente?"
  },
  AvgCommunicate_66997_Content_3 = {
    Text = "Basta chiacchiere. Hai fatto qualcosa tu? Ti ho visto comprarle torte in continuazione."
  },
  AvgCommunicate_66997_Content_4 = {
    Text = "Cosa c'entro io? È stata solo golosa e ha mangiato la torta avanzata dal giorno prima che non aveva buttato via."
  },
  AvgCommunicate_66997_Content_5 = {
    Text = "Aspetta, ma a te cosa importa?"
  },
  AvgCommunicate_66997_Content_6 = {
    Text = "Dubito che ne avresti il coraggio."
  },
  AvgCommunicate_66997_Content_7 = {
    Text = "Hmph, cosa avranno mai di speciale qualche torta? Troverò uno chef che gliele prepari ogni singolo giorno."
  },
  AvgCommunicate_66997_Content_8 = {
    Text = "Non crederai davvero di essere suo padre, vero? Non mi sarei mai aspettato che avessi un lato così paterno."
  },
  AvgCommunicate_66997_Content_9 = {
    Text = "Aspetta, come pensi di \"trovare\" uno chef?"
  },
  AvgCommunicate_66997_Option_11 = {
    Text = "Pronto, è la polizia? Qualcuno sta per commettere di nuovo un crimine."
  },
  AvgCommunicate_66997_Option_2 = {
