  },
  AvgCommunicate_66997_Option_4 = {
    Text = "Cosa c'entro io?"
  },
  AvgCommunicate_66997_Option_8 = {
    Text = "Non mi sarei mai aspettato che mostrassi un lato così paterno."
  },
  AvgCommunicate_66998_Content_1 = {
    Text = "Il cammino del forte è davvero solitario."
  },
  AvgCommunicate_66998_Content_10 = {
    Text = "Difficile dire se hai fatto qualcosa di buono o di cattivo..."
  },
  AvgCommunicate_66998_Content_11 = {
    Text = "Hmph, ho solo fatto ciò che i forti dovrebbero fare."
  },
  AvgCommunicate_66998_Content_12 = {
    Text = "La malavita qui è diventata un po' noiosa ormai. Cosa dovrei fare adesso…"
  },
  AvgCommunicate_66998_Content_13 = {
    Text = "Qualunque cosa tu stia tramando, mi assicurerò di dire alla polizia di tenerti d'occhio."
  },
  AvgCommunicate_66998_Content_2 = {
    Text = "Cammino? Cos'hai combinato? Non dirmi che sei di nuovo alla stazione di polizia?"
  },
  AvgCommunicate_66998_Content_3 = {
    Text = "Ha, come se quegli sciocchi potessero mai trattenermi."
  },
  AvgCommunicate_66998_Content_4 = {
    Text = "Dopo quello che è successo l'ultima volta, ora ho conquistato con successo metà della malavita di Londinium."
  },
  AvgCommunicate_66998_Content_5 = {
    Text = "Peccato che le bande qui siano molto più deboli dei miei confratelli Perishita di un tempo. Non combineranno mai nulla di grande."
  },
  AvgCommunicate_66998_Content_6 = {
    Text = "Bande?? Ma che razza di cose fuorilegge hai fatto?"
  },
  AvgCommunicate_66998_Content_7 = {
    Text = "Come, se sgominare le bande conta come infrangere la legge, allora non resterebbe una sola brava persona al mondo."
  },
  AvgCommunicate_66998_Content_8 = {
    Text = "Se vuoi la mia opinione, Mythag o quell'ufficio di polizia o come si chiama mi deve ancora una medaglia al merito Nobile."
  },
  AvgCommunicate_66998_Content_9 = {
    Text = "Ora che li ho messi tutti in riga, non hai notato che la sicurezza pubblica in città è migliorata?"
  },
  AvgCommunicate_66998_Option_10 = {
    Text = "Difficile dire se hai fatto qualcosa di buono o di cattivo..."
  },
  AvgCommunicate_66998_Option_13 = {
    Text = "Qualunque cosa tu stia tramando, mi assicurerò di dire alla polizia di tenerti d'occhio."
  },
  AvgCommunicate_66998_Option_2 = {
    Text = "Cammino? Cos'hai combinato? Non dirmi che sei di nuovo alla stazione di polizia?"
  },
  AvgCommunicate_66998_Option_6 = {
    Text = "Bande?? Ma che razza di cose fuorilegge hai fatto?"
  },
  AvgCommunicate_66999_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} %player%, di recente sono stato invitato dall'Università di Mythag per aiutare a registrare la musica di transizione tra le lezioni."
  },
  AvgCommunicate_66999_Content_10 = {
    Text = "Se devo specificare cosa la rende speciale, dev'essere perché trabocca del mio bisogno di proteggerti."
  },
  AvgCommunicate_66999_Content_11 = {
    Text = "A dire il vero, ho sempre avuto un po' di difficoltà ad alzarmi. Se avessi della musica trascinante, probabilmente sarebbe più facile uscire dal letto!"
  },
  AvgCommunicate_66999_Content_12 = {
    Text = "Musica trascinante? Capito."
  },
  AvgCommunicate_66999_Content_13 = {
    Text = "Anche se penso che sia più importante dormire bene, ti fai carico di così tanti impegni che il lavoro è inevitabile."
  },
  AvgCommunicate_66999_Content_14 = {
    Text = "Possa questa marcia darti forza!"
  },
  AvgCommunicate_66999_Content_2 = {
    Text = "Durante la sessione di registrazione, la Professoressa Doll ha anche menzionato che la scuola ha sviluppato un nuovo tipo di registratore. È piccolo e portatile per le missioni, ha un audio nitido e dispone sia della funzione di registrazione che di riproduzione."
  },
  AvgCommunicate_66999_Content_3 = {
    Text = "Quando l'ho visto, ho pensato a te. Se lo desideri, posso registrare la musica che ti piace ascoltare."
  },
  AvgCommunicate_66999_Content_4 = {
    Text = "In questo modo, anche quando non sarò al tuo fianco, non dovrai preoccuparti di restare senza musica per rasserenare l'animo."
  },
  AvgCommunicate_66999_Content_5 = {
    Text = "Hameln... Sono così commosso/a!"
  },
  AvgCommunicate_66999_Content_6 = {
    Text = "Sto semplicemente adempiendo al mio dovere. Ebbene, c'è qualcosa che desideri ascoltare?"
  },
  AvgCommunicate_66999_Content_7 = {
    Text = "A proposito, dormo sempre bene ogni volta che suoni una ninna nanna."
  },
  AvgCommunicate_66999_Content_8 = {
    Text = "Cosa la rende così speciale?"
  },
  AvgCommunicate_66999_Content_9 = {
