  AvgCommunicate_67000_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} %player%. Di recente ho composto un nuovo brano e vorrei invitarti ad ascoltarlo e a darmi un parere quando hai tempo."
  },
  AvgCommunicate_67000_Content_10 = {
    Text = "Ah, richieste del genere sono piuttosto austere. Mi scuso per la mia indelicatezza."
  },
  AvgCommunicate_67000_Content_11 = {
    Text = "Che ne dici se la prossima volta suonassi accanto al tuo letto e tu mi permettessi di osservare e registrare il tuo sonno?"
  },
  AvgCommunicate_67000_Content_12 = {
    Text = "Spero che tu possa addormentarti ogni volta sotto la mia protezione."
  },
  AvgCommunicate_67000_Content_2 = {
    Text = "Sei troppo gentile Hameln, ma come può una dilettante improvvisata come me essere qualificata per criticare il tuo lavoro?"
