  AvgCommunicate_67000_Content_3 = {
    Text = "No, non sminuire la tua importanza; i tuoi suggerimenti sono la mia più grande fonte di motivazione creativa."
  },
  AvgCommunicate_67000_Content_4 = {
    Text = "Davvero? Mi vergogno ad ammetterlo, ma tendo ad addormentarmi quando ascolto le tue nuove composizioni..."
  },
  AvgCommunicate_67000_Content_5 = {
    Text = "La tua musica è di una bellezza ammaliante e l'esecuzione è impeccabile, eppure esercita su di me una sorta di magia sedativa e mi addormento all'istante. Forse mi manca davvero l'orecchio musicale."
  },
  AvgCommunicate_67000_Content_6 = {
    Text = "No, è esattamente ciò che desidero."
  },
  AvgCommunicate_67000_Content_7 = {
    Text = "Poterti donare un sonno ristoratore è la mia missione e il mio dovere."
  },
  AvgCommunicate_67000_Content_8 = {
    Text = "Piuttosto, descrivimi nel dettaglio le sensazioni che i diversi brani ti suscitano, così come la qualità del sonno dopo l'ascolto, quanto tempo impieghi ad addormentarti, la durata del tuo riposo..."
  },
  AvgCommunicate_67000_Content_9 = {Text = "Eh?"},
  AvgCommunicate_67000_Option_2 = {
    Text = "Sei troppo gentile."
  },
  AvgCommunicate_67000_Option_4 = {Text = "Davvero?"},
  AvgCommunicate_67000_Option_9 = {Text = "Eh?"},
  AvgCommunicate_67001_Content_1 = {
    Text = "Custode, queste nuove scarpe da ballo al mio Varco sono da parte tua?"
  },
  AvgCommunicate_67001_Content_10 = {
    Text = "No, assolutamente no. Le scarpe da ballo che mi hai regalato Ispirano il mio cuore e la mia anima."
  },
  AvgCommunicate_67001_Content_11 = {
    Text = "Sapere che qualcuno attende con tanta gioia la mia Danza, lo prenderò come motivazione per continuare a impegnarmi e danzare."
  },
  AvgCommunicate_67001_Content_2 = {
    Text = "Ahaha, era così ovvio? Pensavo di non aver lasciato tracce!"
  },
  AvgCommunicate_67001_Content_3 = {
    Text = "A Mythag, non ci sono davvero molte persone che si interessano a me e sono così premurosi con gli altri."
  },
  AvgCommunicate_67001_Content_4 = {
    Text = "Sono sempre stata grata per tutto quello che hai fatto per me. Grazie, Custode."
  },
  AvgCommunicate_67001_Content_5 = {
    Text = "Adesso mi fai arrossire… In realtà, ho notato che le scarpe da ballo che indossavi durante la tua ultima esibizione erano un po' consumate, così ho pensato di prenderti un paio nuovo."
  },
  AvgCommunicate_67001_Content_6 = {
    Text = "Ah, in effetti, quelle scarpe da ballo mi accompagnano da molto tempo. Ma per una Danzatrice, le scarpe nuove non sono necessariamente migliori."
  },
  AvgCommunicate_67001_Content_7 = {
