  },
  AvgCommunicate_67001_Content_8 = {
    Text = "Un paio di scarpe da ballo deve passare attraverso innumerevoli ore di rodaggio per adattarsi gradualmente ai propri piedi. L'usura delle scarpe spesso riflette le abitudini della Danzatrice stessa."
  },
  AvgCommunicate_67001_Content_9 = {
