  AvgCommunicate_67006_Content_1 = {
    Text = "Ho notato che, sebbene il progresso tecnologico e lo sviluppo commerciale restino noiosi, sono emersi molti nuovi tipi di cuscini."
  },
  AvgCommunicate_67006_Content_10 = {
    Text = "Quel commesso mi ha definita una testatrice di sonno nata e ha insistito perché provassi i cuscini per loro a lungo termine."
  },
  AvgCommunicate_67006_Content_11 = {
    Text = "Ti stanno chiedendo di lavorare? Se Miryam lo scopre, potrebbe ammazzarli."
  },
  AvgCommunicate_67006_Content_12 = {
    Text = "Inizialmente volevo rifiutare, ma ha detto che i tester del sonno potevano portare a casa tutti i nuovi prodotti gratuitamente per provarli."
  },
  AvgCommunicate_67006_Content_13 = {
    Text = "Vista la sua sincerità, ho accettato."
  },
  AvgCommunicate_67006_Content_14 = {
    Text = "Non avrei mai pensato che ti saresti fatta corrompere da un cuscino... Ah, cioè, che Re davvero gentile."
  },
  AvgCommunicate_67006_Content_2 = {
    Text = "L'altro giorno sono passata davanti ai grandi magazzini di Londinium e ho visto che promuovevano una serie di cuscini nuovi."
  },
  AvgCommunicate_67006_Content_3 = {
    Text = "Ho dato solo due occhiate, e il commesso mi ha trascinata a provare un letto campione. Che maleducazione inaudita."
