  },
  AvgCommunicate_67006_Content_5 = {
    Text = "Ma il cosiddetto cuscino Nuvola è davvero straordinariamente soffice. Non è piuma né cotone; non riesco a capire di cosa sia fatto."
  },
  AvgCommunicate_67006_Content_6 = {
