  AvgCommunicate_67007_Content_1 = {
    Text = "Padrone, oggi Aigis ha raccontato a me e a Jenkin dei giocattoli dell'Ospizio."
  },
  AvgCommunicate_67007_Content_10 = {
    Text = "No, Custode, per favore non ascoltare Jenkin. La mia bambola sta benissimo, non c'è bisogno di comprarne una nuova!"
  },
  AvgCommunicate_67007_Content_11 = {
    Text = "Va bene, va bene, va bene, compriamo tutto, tutto!"
  },
  AvgCommunicate_67007_Content_12 = {
    Text = "Padrone, il comunicatore è stato appena strappato di mano ed è caduto a terra. Sembra che alcuni pezzi si siano staccati."
  },
  AvgCommunicate_67007_Content_13 = {
    Text = "Possiamo comprarne uno nuovo anche di questo?"
