  AvgCommunicate_67007_Content_14 = {Text = "Eh???"},
  AvgCommunicate_67007_Content_2 = {
    Text = "Ha detto che c'è un giocattolo chiamato tangram, fatto di sette pezzi piatti come blocchetti che possono essere disposti in tanti disegni e anche rimessi insieme in una grande cornice quadrata."
  },
  AvgCommunicate_67007_Content_3 = {
    Text = "Jenkin ha detto che potremmo farne uno di carta, ma dopo averci pensato a lungo insieme, non siamo riusciti a capire che aspetto abbia il tangram."
  },
  AvgCommunicate_67007_Content_4 = {
