  },
  AvgCommunicate_67007_Content_7 = {
    Text = "Grazie, Padrone! Vado a dirlo a Jenkin e Aigis!"
  },
  AvgCommunicate_67007_Content_8 = {
    Text = "Ehi, Custode, Aigis ha detto che c'è anche un giocattolo chiamato Cubo di Rubik con tanti quadratini che si possono girare e ruotare! Vogliamo anche quello!"
  },
  AvgCommunicate_67007_Content_9 = {
    Text = "E anche la bambola di Aigis è vecchia, quindi devi comprargliene una nuova!"
