  },
  AvgCommunicate_67008_Content_1 = {Text = "*sigh*..."},
  AvgCommunicate_67008_Content_10 = {
    Text = "Sembra che l'unica cosa rimasta per un fallito inutile come me sia strisciare in una fossa e morire..."
  },
  AvgCommunicate_67008_Content_11 = {
    Text = "Questa è una conclusione un po' estrema!"
  },
  AvgCommunicate_67008_Content_12 = {
    Text = "Ascolta, non è colpa tua. Sei stato ingannato e sfruttato da quelli che ti hanno venduto quel rimedio; hanno approfittato della tua disperazione."
  },
  AvgCommunicate_67008_Content_13 = {
    Text = "Non è che tu non riesca a Risvegliarti; sei stato avvelenato da medicine di ciarlatani!"
  },
  AvgCommunicate_67008_Content_14 = {
