  },
  AvgCommunicate_67008_Content_19 = {
    Text = "Allora... puoi prestarmi cinquanta per andare dal dottore?"
  },
  AvgCommunicate_67008_Content_2 = {
    Text = "Che succede, sei di nuovo senza soldi?"
  },
  AvgCommunicate_67008_Content_20 = {
    Text = "Quindi alla fine si trattava sempre di prendere soldi in prestito!!!"
  },
  AvgCommunicate_67008_Content_3 = {
    Text = "Sono davvero così avida ai tuoi occhi? In verità, non mi sono mai interessata a quei Beni Terreni."
  },
  AvgCommunicate_67008_Content_4 = {
    Text = "Già, perché sei sempre al verde."
  },
  AvgCommunicate_67008_Content_5 = {
    Text = "Quindi si tratta di quel rimedio?"
  },
  AvgCommunicate_67008_Content_6 = {
    Text = "Beh, sembra che la mia ricerca di potere finisca qui..."
  },
  AvgCommunicate_67008_Content_7 = {
