  AvgCommunicate_67013_Option_6 = {Text = "..."},
  AvgCommunicate_67013_Option_7 = {Text = "..."},
  AvgCommunicate_67014_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} Custode, a volte mi chiedo se tutto ciò che ho cercato di fare per il mio Re lo abbia davvero soddisfatto."
  },
  AvgCommunicate_67014_Content_10 = {
    Text = "Ma io credo che l'unica cosa che gli dèi possano davvero percepire sia il cuore appassionato e devoto che i loro seguaci dedicano loro."
  },
  AvgCommunicate_67014_Content_11 = {
    Text = "Quindi, ciò che hai fatto forse non è la parte più importante; ciò che conta è il cuore che ci hai messo. Dopotutto, Tulu non ti ha mai fermato, vero?"
  },
  AvgCommunicate_67014_Content_12 = {
    Text = "Non mi sarei mai aspettato di essere illuminato da un miscredente come te. Le tue parole mi hanno lasciato un'impressione profonda. Grazie."
  },
  AvgCommunicate_67014_Content_2 = {
    Text = "Il sentiero che ho scelto è davvero quello giusto?"
  },
  AvgCommunicate_67014_Content_3 = {
    Text = "Non mi sarei mai aspettato che un giorno avresti riflettuto su te stesso."
  },
  AvgCommunicate_67014_Content_4 = {
    Text = "Perché anch'io mi sento confuso, stanco e scoraggiato. Se tutto ciò che faccio è giusto, perché il Re non mi ha risposto?"
  },
  AvgCommunicate_67014_Content_5 = {
    Text = "Anche se non sono devoto quanto te, credo che ciò che i seguaci fanno per un Dio non sia necessariamente ciò di cui il Dio ha bisogno."
  },
  AvgCommunicate_67014_Content_6 = {
    Text = "Cosa hai detto?"
  },
  AvgCommunicate_67014_Content_7 = {
    Text = "Ehi, ehi, non avere fretta. Non ho ancora finito di parlare."
  },
  AvgCommunicate_67014_Content_8 = {
    Text = "La differenza tra i mortali e gli dèi è simile a quella tra le formiche e gli esseri umani. Non credo che gli umani possano comprendere appieno i bisogni degli dèi."
  },
  AvgCommunicate_67014_Content_9 = {
    Text = "Efemere... Forse hai ragione."
  },
  AvgCommunicate_67014_Option_10 = {
    Text = "Ma io credo..."
  },
  AvgCommunicate_67014_Option_3 = {
    Text = "Non mi sarei mai aspettato che un giorno avresti riflettuto su te stesso."
  },
  AvgCommunicate_67014_Option_5 = {
    Text = "Sebbene la mia fede non sia devota quanto la tua..."
  },
  AvgCommunicate_67014_Option_7 = {
    Text = "Ehi, ehi, non avere fretta. Non ho ancora finito di parlare."
  },
  AvgCommunicate_67015_Content_1 = {
    Text = "Custode, le conferenze che ho tenuto nel campus e gli opuscoli promozionali che ho stampato hanno avuto un ottimo riscontro."
  },
  AvgCommunicate_67015_Content_10 = {
    Text = "La signorina Sanga? La vedo raramente. Ho sentito dire che è una scultrice eccezionale."
  },
  AvgCommunicate_67015_Content_11 = {
    Text = "Se fosse disposta a scolpire per il nostro Signore, sarebbe perfetto; il Regno divino la proteggerà."
  },
  AvgCommunicate_67015_Content_2 = {
    Text = "Hanno sviluppato sentimenti di reverenza per il mio grande Signore. Alcuni fedeli mi hanno detto che desiderano ottenere delle statuette in miniatura del Signore, così da poter esprimere la loro Preghiera e adorarlo comodamente nella loro stanza."
  },
  AvgCommunicate_67015_Content_3 = {
    Text = "Penso che abbiano ragione. Dove potrei trovare un artigiano per realizzare su misura un lotto di queste statuette?"
  },
  AvgCommunicate_67015_Content_4 = {
    Text = "Statuette in miniatura? Qualcosa non mi torna…"
  },
  AvgCommunicate_67015_Content_5 = {
    Text = "Cosa c'è che non va? Queste statuette richiedono un'artigianalità raffinata. Non ci sono davvero artigiani del genere a Mythag?"
  },
  AvgCommunicate_67015_Content_6 = {
    Text = "Non è proprio una questione di artigiani… è solo che ho la sensazione che non vogliano quelle statuette per la Preghiera e l'adorazione…"
  },
  AvgCommunicate_67015_Content_7 = {
    Text = "Impossibile. Ho assistito di persona al loro fervore per il mio Signore. Si interessano persino di ogni dettaglio delle preferenze e della vita quotidiana del Signore."
  },
  AvgCommunicate_67015_Content_8 = {
    Text = "Questo non fa che confermare la mia tesi… Lascia perdere, basta che tu sia contenta."
  },
  AvgCommunicate_67015_Content_9 = {
    Text = "Chiederò a Sanga se è disposta a realizzare questo lotto di statuette."
  },
  AvgCommunicate_67015_Option_4 = {
    Text = "Statuette in miniatura? Qualcosa non mi torna…"
  },
  AvgCommunicate_67015_Option_6 = {
    Text = "Non è proprio una questione di artigiani…"
  },
  AvgCommunicate_67015_Option_8 = {
    Text = "Questo non fa che confermare la mia tesi… Lascia perdere, basta che tu sia contenta."
  },
  AvgCommunicate_67016_Content_1 = {
    Text = "Sigh, Custode, sono venuta a confessare la mia negligenza a te e a Lord Dexter, e spero di ricevere il vostro perdono."
  },
  AvgCommunicate_67016_Content_10 = {
    Text = "Ehm, è davvero sfortunato, ma non è colpa tua. Non incolparti."
  },
  AvgCommunicate_67016_Content_11 = {
    Text = "No, è stato tutto per una mia svista. Farò un'autocritica pubblica e rafforzerò la gestione quotidiana."
  },
  AvgCommunicate_67016_Content_2 = {
    Text = "A causa di una mia cattiva gestione personale, due pazienti del Sanatorio sono stati gravemente avvelenati. Fortunatamente, ora sono fuori pericolo dopo un trattamento d'emergenza."
  },
  AvgCommunicate_67016_Content_3 = {
    Text = "Eh? Cos'è successo?"
  },
  AvgCommunicate_67016_Content_4 = {
    Text = "Beh, dietro il Sanatorio c'è un piccolo stagno che poche persone di solito visitano."
  },
  AvgCommunicate_67016_Content_5 = {
    Text = "Conosci la mia passione per l'acqua. Nelle giornate di lavoro intense, di notte mi immergevo di nascosto nello stagno per godermi un momento di placida tranquillità nel mondo sottomarino."
  },
  AvgCommunicate_67016_Content_6 = {
    Text = "Mm... È comprensibile. Il lavoro è sempre stressante, dopotutto."
  },
  AvgCommunicate_67016_Content_7 = {
    Text = "Forse perché ci sono andata troppe volte, le Tossine del mio corpo si sono gradualmente diffuse nello stagno e nei pesci che vi abitavano."
  },
  AvgCommunicate_67016_Content_8 = {
    Text = "In origine questo stagno non si trovava nell'area attività dei Pazienti, ma due giorni fa, due Pazienti golosi si sono allontanati di nascosto fino allo stagno per pescare e arrostire il pesce da mangiare."
  },
  AvgCommunicate_67016_Content_9 = {
    Text = "Quando il Personale Medico li ha scoperti, stavano già schiumando dalla bocca ed erano crollati a terra..."
  },
  AvgCommunicate_67016_Option_10 = {
    Text = "Ehm, è davvero sfortunato, ma non è colpa tua. Non incolparti."
  },
  AvgCommunicate_67016_Option_3 = {
    Text = "Eh? Cos'è successo?"
  },
  AvgCommunicate_67016_Option_6 = {
    Text = "Mm... È comprensibile. Il lavoro è sempre stressante, dopotutto."
  },
  AvgCommunicate_67017_Content_1 = {
    Text = "Custode, un ospite in visita a Mythag ha sentito per caso il mio canto durante le prove."
  },
  AvgCommunicate_67017_Content_10 = {
    Text = "Ami cantare, ami esibirti... perché non far sentire la tua voce a più persone?"
  },
  AvgCommunicate_67017_Content_11 = {
    Text = "Amarlo… ora capisco. Grazie, Custode."
  },
  AvgCommunicate_67017_Content_12 = {
    Text = "Cercherò di brillare ancora una volta su questo pianeta."
  },
  AvgCommunicate_67017_Content_2 = {
    Text = "Ora mi invitano a collaborare con la loro compagnia per pubblicare dei dischi. Dovrei accettare?"
  },
  AvgCommunicate_67017_Content_3 = {
    Text = "Penso di sì! Se ricordo bene, eri una cantante famosa, giusto?"
  },
  AvgCommunicate_67017_Content_4 = {
    Text = "Sì, le mie canzoni erano molto in voga su Desolate, il nostro pianeta natale, ma la maggior parte delle volte servivano solo come merce di scambio con la nobiltà."
  },
  AvgCommunicate_67017_Content_5 = {
    Text = "Ora che ho ritrovato mia sorella, non ho più bisogno di nient'altro."
  },
  AvgCommunicate_67017_Content_6 = {
    Text = "E tu? Ti senti ancora felice quando canti?"
  },
  AvgCommunicate_67017_Content_7 = {
    Text = "Felice… suppongo di esserlo. Dopotutto, cantare è l'unica cosa che so fare."
  },
  AvgCommunicate_67017_Content_8 = {
    Text = "No, Tintura, nessuno continuerebbe a esercitarsi nel canto ogni giorno se non lo amasse davvero."
  },
  AvgCommunicate_67017_Content_9 = {
    Text = "Aggrapparsi a ciò che si ama è solo naturale."
  },
  AvgCommunicate_67017_Option_3 = {
    Text = "Penso di sì! Se ricordo bene, eri una cantante famosa, giusto?"
  },
  AvgCommunicate_67017_Option_6 = {
    Text = "E tu? Ti senti ancora felice quando canti?"
  },
  AvgCommunicate_67017_Option_8 = {
    Text = "Nessuno continuerebbe a esercitarsi nel canto ogni giorno se non lo amasse davvero."
  },
  AvgCommunicate_67018_Content_1 = {
    Text = "Messaggero Pallido, volevo contattarti appositamente per informarti che visiterò Mythag a breve."
  },
  AvgCommunicate_67018_Content_2 = {
    Text = "La mia visita precedente sembra essere stata di qualche piccolo aiuto per tutti, e sono stato invitato a tornare per chiacchierare con tutti nell'auditorium."
  },
  AvgCommunicate_67018_Content_3 = {
    Text = "Se per caso hai un po' di tempo libero, spero che potremo incontrarci nel campus."
  },
  AvgCommunicate_67018_Content_4 = {
    Text = "Mi piacerebbe molto!"
  },
  AvgCommunicate_67018_Content_5 = {
    Text = "Meraviglioso. Metterò da parte del tempo solo per te, per ascoltare tutto ciò che vorresti raccontarmi."
  },
  AvgCommunicate_67018_Content_6 = {
    Text = "Solo noi due?"
  },
  AvgCommunicate_67018_Content_7 = {
    Text = "Sì. Dopotutto, non è una cerimonia religiosa... solo un incontro tra amici, no?"
  },
  AvgCommunicate_67018_Content_8 = {
    Text = "Nessun problema. Ti farò fare un giro tra le attrazioni di Mythag. Ti andrebbe di provare la mensa dei Risvegliatori?"
  },
  AvgCommunicate_67018_Content_9 = {
    Text = "Mi affiderò ai tuoi piani. Non vedo l'ora."
  },
  AvgCommunicate_67018_Option_4 = {
    Text = "Mi piacerebbe molto!"
  },
  AvgCommunicate_67018_Option_6 = {
    Text = "Solo noi due?"
  },
  AvgCommunicate_67018_Option_8 = {
    Text = "Nessun problema!"
  },
  AvgCommunicate_67019_Content_1 = {
    Text = "Messaggero Pallido, il distretto della Chiesa terrà presto una grande Messa."
  },
  AvgCommunicate_67019_Content_10 = {
    Text = "Il tuo cuore sincero mi riempie di calore. Allora non rifiuterò oltre."
  },
  AvgCommunicate_67019_Content_11 = {
    Text = "Vieni pure quando hai tempo libero e aiutami con qualche semplice pulizia e decorazione."
  },
  AvgCommunicate_67019_Content_12 = {
    Text = "Nessun problema, ci vediamo allora!"
  },
  AvgCommunicate_67019_Content_13 = {
    Text = "Grazie ancora, Messaggero Pallido. Che l'Onnipotente vegli sul Cammino davanti a te."
  },
  AvgCommunicate_67019_Content_2 = {
    Text = "Sarò io a presiedere la cerimonia, condividendo gli insegnamenti dell'Onnipotente."
  },
  AvgCommunicate_67019_Content_3 = {
    Text = "I fedeli di Londinium e delle zone circostanti parteciperanno tutti. Se ti interessa, sei il benvenuto a unirti a questa celebrazione eucaristica."
  },
  AvgCommunicate_67019_Content_4 = {
    Text = "Mi piacerebbe molto! Ma con così tanti fedeli da accogliere, i preparativi per questa Messa devono essere una bella sfida."
  },
  AvgCommunicate_67019_Content_5 = {
    Text = "Sei sempre così attento, gentile e premuroso verso gli altri."
  },
  AvgCommunicate_67019_Content_6 = {
    Text = "In effetti, assicurarsi che tutti siano adeguatamente accolti e possano sentire la grazia dell'Onnipotente richiede una grande preparazione."
  },
  AvgCommunicate_67019_Content_7 = {
    Text = "Ma non temere. Ho una vasta ESP nel presiedere la Messa e posso gestire bene queste questioni di poco conto."
  },
  AvgCommunicate_67019_Content_8 = {
    Text = "Nessuna quantità di ESP ti dà braccia in più. Se possibile, lasciami venire prima per darti una mano!"
  },
  AvgCommunicate_67019_Content_9 = {
    Text = "Dopotutto, per un evento così grande, più accurati sono i preparativi, meglio è."
  },
  AvgCommunicate_67019_Option_12 = {
    Text = "Nessun problema, ci vediamo allora!"
  },
  AvgCommunicate_67019_Option_4 = {
    Text = "Con piacere!"
  },
  AvgCommunicate_67019_Option_8 = {
    Text = "Se possibile, lasciami venire prima per darti una mano!"
  },
  AvgCommunicate_67020_Content_1 = {
    Text = "Sigh, da quando Mythag ha emesso quell'ordine restrittivo, nessuna bellezza viene più a farmi compagnia."
  },
  AvgCommunicate_67020_Content_10 = {
    Text = "Molto bene, allora non mi resta che pregare affinché il Sole tramonti in fretta."
  },
  AvgCommunicate_67020_Content_11 = {
    Text = "Ah, non vedo già l'ora di ammirare il chiaro di luna di stasera."
  },
  AvgCommunicate_67020_Content_2 = {
    Text = "Dicendo che senza il tuo accompagnamento, a nessun altro è permesso vedermi."
  },
  AvgCommunicate_67020_Content_3 = {
    Text = "Tu, proprio tu, dimmi... ti sei ingelosito/a e mi hai denunciato alla scuola?"
  },
  AvgCommunicate_67020_Content_4 = {
    Text = "Sei stato tu il primo ad ammaliare gli Studenti facendogli bere strane cose..."
  },
  AvgCommunicate_67020_Content_5 = {
    Text = "Quello era chiaramente un dono d'amore. Sono davvero così spregevole ai tuoi occhi?"
  },
  AvgCommunicate_67020_Content_6 = {
    Text = "Ogni giorno ti aspetto in solitudine, eppure è così che mi vedi..."
  },
  AvgCommunicate_67020_Content_7 = {
    Text = "Basta! Ho capito, verrò a trovarti più spesso."
  },
  AvgCommunicate_67020_Content_8 = {
    Text = "Che creatura premurosa. Ma voglio vederti in ogni istante—adesso—non voglio aspettare nemmeno un secondo."
  },
  AvgCommunicate_67020_Content_9 = {
    Text = "Stasera, verrò stasera, va bene!"
  },
  AvgCommunicate_67020_Option_4 = {
    Text = "Sei stato tu il primo ad ammaliare gli Studenti facendogli bere strane cose..."
  },
  AvgCommunicate_67020_Option_7 = {
    Text = "Basta! Ho capito, verrò a trovarti più spesso."
  },
  AvgCommunicate_67020_Option_9 = {
    Text = "Stasera, verrò stasera, va bene!"
  },
  AvgCommunicate_67021_Content_1 = {
    Text = "Custode, scusa il disturbo. Hai un po' di tempo libero di recente?"
  },
  AvgCommunicate_67021_Content_10 = {
    Text = "Quindi mi stai chiedendo se potrei venire con te?"
  },
  AvgCommunicate_67021_Content_11 = {
    Text = "Mm, andrebbe bene?"
  },
  AvgCommunicate_67021_Content_12 = {
    Text = "Certo! Sembra che sarà molto divertente!"
  },
  AvgCommunicate_67021_Content_13 = {
    Text = "Grazie, Custode! Averti con me mi fa sentire molto più tranquilla."
  },
  AvgCommunicate_67021_Content_14 = {
    Text = "Ho sentito che le poesie scritte sul momento hanno la possibilità di vincere un premio. Se sarò abbastanza fortunata da ottenerne uno, te lo darò come regalo di ringraziamento."
  },
  AvgCommunicate_67021_Content_2 = {
    Text = "Che succede? È raro che tu venga da me di tua iniziativa."
  },
  AvgCommunicate_67021_Content_3 = {
    Text = "Beh, sta per esserci una fiera della poesia a Londinium. Verranno venduti molti libri nuovi e usati, e tanti poeti parteciperanno per scambiarsi idee."
  },
  AvgCommunicate_67021_Content_4 = {
    Text = "Gli organizzatori mi hanno anche invitato ad allestire uno stand per condividere la mia raccolta di poesie."
  },
  AvgCommunicate_67021_Content_5 = {
    Text = "Il loro invito è stato così gentile che ho accettato senza pensarci, ma..."
  },
  AvgCommunicate_67021_Content_6 = {
    Text = "Ma andare a gestire uno stand da sola ti mette troppa ansia?"
  },
  AvgCommunicate_67021_Content_7 = {
    Text = "Mm... Mi capisci sempre."
  },
  AvgCommunicate_67021_Content_8 = {
    Text = "Ma non voglio ritrattare qualcosa che ho già accettato, e l'evento sembra davvero interessante! Ho sentito che ci sarà persino una staffetta di scrittura collaborativa dal vivo."
  },
  AvgCommunicate_67021_Content_9 = {Text = "Quindi..."},
  AvgCommunicate_67021_Option_10 = {
    Text = "Quindi mi stai chiedendo se potrei venire con te?"
  },
  AvgCommunicate_67021_Option_12 = {
    Text = "Certo! Sembra che sarà molto divertente!"
  },
  AvgCommunicate_67021_Option_2 = {
    Text = "Che succede? È raro che tu venga da me di tua iniziativa."
  },
  AvgCommunicate_67021_Option_6 = {
    Text = "Ma andare a gestire uno stand da sola ti mette troppa ansia?"
  },
  AvgCommunicate_67022_Content_1 = {
    Text = "Custode, finalmente ho trovato un buon modo per dormire tranquillamente."
  },
  AvgCommunicate_67022_Content_10 = {
    Text = "È già un enorme disturbo per gli altri!"
  },
  AvgCommunicate_67022_Content_11 = {
    Text = "Considerala come un'opera d'arte decorativa! Non russo nel sonno!"
  },
  AvgCommunicate_67022_Content_12 = {
    Text = "Aspetta, non dirmi che la persona di cui ti fidi sono io."
  },
  AvgCommunicate_67022_Content_13 = {
    Text = "Ma certo! Il Custode più gentile, più affidabile e più potente di Mythag — non c'è nessuno più adatto di te per questo compito!"
  },
  AvgCommunicate_67022_Content_14 = {
    Text = "Ho intenzione di spostare la Sfera del Sonno stanotte. Se ti va, posso anche chiacchierare con te prima di dormire~"
  },
  AvgCommunicate_67022_Content_15 = {Text = "Custode?"},
  AvgCommunicate_67022_Content_16 = {Text = "Custode??"},
  AvgCommunicate_67022_Content_2 = {
    Text = "Congratulazioni! Qual è il metodo?"
  },
  AvgCommunicate_67022_Content_3 = {
    Text = "Ho progettato una sfera per il sonno che mantiene l'interno illuminato per tutta la notte. In questo modo non servono luci potenti e si evitano angoli bui nelle vicinanze."
  },
  AvgCommunicate_67022_Content_4 = {
    Text = "Sembra fantastico. Così finalmente potrai smettere di irrompere ogni giorno nelle stanze degli altri per poi farti cacciare fuori."
  },
  AvgCommunicate_67022_Content_5 = {
    Text = "No! Per prevenire qualsiasi malfunzionamento della Sfera del Sonno e per evitare pericoli esterni, devo posizionarla in un luogo dove ci siano persone nelle vicinanze."
  },
  AvgCommunicate_67022_Content_6 = {
    Text = "? Vuoi mettere questo aggeggio nella stanza di qualcun altro?"
  },
  AvgCommunicate_67022_Content_7 = {
    Text = "Esatto! Affiderò il pulsante di riavvio d'emergenza della Sfera del Sonno a qualcuno di cui mi fido. In questo modo, nulla potrà andare storto!"
  },
  AvgCommunicate_67022_Content_8 = {
    Text = "In più, la mia abitudine di dormire con le luci accese non darà più fastidio a nessuno. È assolutamente perfetto."
  },
  AvgCommunicate_67022_Content_9 = {
    Text = "Perfetto un corno!"
  },
  AvgCommunicate_67022_Option_10 = {
    Text = "È già un enorme disturbo per gli altri!"
  },
  AvgCommunicate_67022_Option_12 = {
    Text = "Aspetta, non dirmi che la persona di cui ti fidi sono io."
  },
  AvgCommunicate_67022_Option_2 = {
    Text = "Congratulazioni! Qual è il metodo?"
  },
  AvgCommunicate_67022_Option_4 = {
    Text = "Sembra un'ottima idea."
  },
  AvgCommunicate_67022_Option_6 = {
    Text = "? Vuoi mettere questo aggeggio nella stanza di qualcun altro?"
  },
  AvgCommunicate_67022_Option_9 = {
    Text = "Perfetto un corno!"
  },
  AvgCommunicate_67023_Content_1 = {
    Text = "Custode, ultimamente continuo a vedere strane macchie davanti agli occhi, e ho sempre capogiri, palpitazioni, oppressione al petto, fischi nelle orecchie... Sto per morire?!"
  },
  AvgCommunicate_67023_Content_10 = {
    Text = "No, non capisci. Quell'oscurità è ovunque. Non importa dove mi trovi, mi troverà! Non posso dormire, non posso chiudere gli occhi…"
  },
  AvgCommunicate_67023_Content_11 = {
    Text = "Ehm… allora perché non assumi qualcuno che ti metta semplicemente KO? Così perdi conoscenza e non sentirai paura."
  },
  AvgCommunicate_67023_Content_12 = {
    Text = "Eh? Quello che hai detto in effetti ha un certo senso."
  },
  AvgCommunicate_67023_Content_13 = {
    Text = "Dato che la Sintomo: Distruzione arriverà comunque, tanto vale lasciarmi morire in pace nella beata ignoranza…"
  },
  AvgCommunicate_67023_Content_14 = {
    Text = "Si tratta solo di essere messo KO, sei ben lontano dal morire!"
  },
  AvgCommunicate_67023_Content_15 = {
    Text = "Grazie, Custode. Allora affiderò questo compito a te, la persona di cui mi fido di più."
  },
  AvgCommunicate_67023_Content_16 = {
    Text = "……dovevo proprio aprire la mia boccaccia!!"
  },
  AvgCommunicate_67023_Content_2 = {
    Text = "Ehm, considerando i tuoi orari di sonno, probabilmente sei rimasta sveglia troppo a lungo. Ti consiglierei di andare a letto prima."
  },
  AvgCommunicate_67023_Content_3 = {
    Text = "Cosa? Anche questo corpo ha già raggiunto il suo limite...?"
  },
  AvgCommunicate_67023_Content_4 = {
    Text = "Ma affrontare quell'oscurità terrificante mi ucciderebbe allo stesso modo!"
  },
  AvgCommunicate_67023_Content_5 = {
    Text = "Agh, maledizione. Sofferenza prolungata o una fine rapida, essere o non essere — come dovrei scegliere..."
  },
  AvgCommunicate_67023_Content_6 = {
    Text = "Non stai un po' esagerando! L'hai elevata a filosofia!"
  },
  AvgCommunicate_67023_Content_7 = {
    Text = "Ma non ti è mai successo niente di brutto per aver dormito. Quell'orrore è solo frutto della tua immaginazione. Penso che dovresti provare la desensibilizzazione."
  },
  AvgCommunicate_67023_Content_8 = {
    Text = "Desensibilizzazione?"
  },
  AvgCommunicate_67023_Content_9 = {
    Text = "Per esempio, magari inizia provando a fare un pisolino? Di giorno, almeno l'ambiente circostante è luminoso, quindi dovresti sentirti al sicuro."
  },
  AvgCommunicate_67023_Option_11 = {
    Text = "Ehm… allora perché non assumi qualcuno che ti metta semplicemente KO?"
  },
  AvgCommunicate_67023_Option_14 = {
    Text = "Si tratta solo di essere messo KO, sei ben lontano dal morire!"
  },
  AvgCommunicate_67023_Option_16 = {
    Text = "……dovevo proprio aprire la mia boccaccia!!"
  },
  AvgCommunicate_67023_Option_2 = {
    Text = "Considerando i tuoi orari di sonno, probabilmente sei rimasta sveglia troppo a lungo."
  },
  AvgCommunicate_67023_Option_6 = {
    Text = "Non stai un po' esagerando! L'hai elevata a filosofia!"
  },
  AvgCommunicate_67023_Option_9 = {
    Text = "Per esempio, magari inizia provando a fare un pisolino?"
  },
  AvgCommunicate_67024_Content_1 = {
    Text = "Ta-da~! La lezione di magia di Casiah è iniziata!"
  },
  AvgCommunicate_67024_Content_10 = {
    Text = "E allora perché ti sei presa la briga di elencarle?!"
  },
  AvgCommunicate_67024_Content_11 = {
    Text = "Beh, quelle sono abilità esclusive della Professoressa Casiah. Ovviamente non puoi impararle!"
  },
  AvgCommunicate_67024_Content_12 = {
    Text = "Ma quello che la Professoressa Casiah PUÒ insegnarti è come rendere le tue mani agili. Così, quando sarai legata con una corda impossibile da sciogliere o ti imbatterai in una serratura impossibile da aprire, potrai mettere in mostra la tua capacità di cogliere le opportunità!"
  },
  AvgCommunicate_67024_Content_13 = {
    Text = "Quindi insisti a insegnare cose strane!"
  },
  AvgCommunicate_67024_Content_14 = {
    Text = "Basta con questi esempi assurdi!!"
  },
  AvgCommunicate_67024_Content_15 = {
    Text = "Tsk, Doll deve avere a che fare con studenti così problematici tutto il tempo? Che seccatura! Fare l'insegnante è uno schifo!"
  },
  AvgCommunicate_67024_Content_16 = {
    Text = "Anche se la Sig.na Doll a volte ha le sue difficoltà, NON accetterò assolutamente di essere criticata da gente come te!"
  },
  AvgCommunicate_67024_Content_2 = {
    Text = "Che stai combinando adesso??"
  },
  AvgCommunicate_67024_Content_3 = {
    Text = "Come? Dico sul serio! La scuola mi ha invitata a tenere una lezione!"
  },
  AvgCommunicate_67024_Content_4 = {
    Text = "Doll mi ha detto che insegnare mi avrebbe permesso di \"sperimentare la sensazione dell'educazione e della trasmissione del sapere.\""
  },
  AvgCommunicate_67024_Content_5 = {
    Text = "Non ho capito bene, ma in ogni caso, chiamatemi Professoressa Casiah!"
  },
  AvgCommunicate_67024_Content_6 = {
    Text = "Ehm, Casi— Professoressa Casiah... Sono io che non capisco come tu possa insegnare!!"
  },
  AvgCommunicate_67024_Content_7 = {
    Text = "Come? La Professoressa Casiah può insegnare un sacco di segreti incredibili! Potrei insegnarti a fare giocoleria, a trapassare gli oggetti, o a rubare un oggetto dentro una cassaforte..."
  },
  AvgCommunicate_67024_Content_8 = {
    Text = "Queste materie diventano sempre più strane, non ti pare?!"
  },
  AvgCommunicate_67024_Content_9 = {
    Text = "...ma non lo farò!"
  },
  AvgCommunicate_67024_Option_10 = {
    Text = "E allora perché ti sei presa la briga di elencarle?!"
  },
  AvgCommunicate_67024_Option_13 = {
    Text = "Quindi insisti a insegnare cose strane!"
  },
  AvgCommunicate_67024_Option_14 = {
    Text = "Basta con questi esempi assurdi!!"
  },
  AvgCommunicate_67024_Option_16 = {
    Text = "Anche se la Sig.na Doll a volte ha le sue difficoltà, NON accetterò assolutamente di essere criticata da gente come te!"
  },
  AvgCommunicate_67024_Option_2 = {
    Text = "Che stai combinando adesso??"
  },
  AvgCommunicate_67024_Option_6 = {
    Text = "Ehm, Casi— Professoressa Casiah... Sono io che non capisco come tu possa insegnare!!"
  },
  AvgCommunicate_67024_Option_8 = {
    Text = "Queste materie diventano sempre più strane, non ti pare?!"
  },
  AvgCommunicate_67025_Content_1 = {
    Text = "Sembra che l'aggiunta dei cani militari al mio addestramento abbia superato di gran lunga le mie aspettative."
  },
  AvgCommunicate_67025_Content_10 = {
    Text = "Per favore, assicurati di tenermi un posto!!!"
  },
  AvgCommunicate_67025_Content_2 = {
    Text = "Persino gli studenti che inizialmente non partecipavano all'addestramento fisico si stanno iscrivendo ai miei corsi. Sono davvero sorpresa dall'entusiasmo di tutti."
  },
  AvgCommunicate_67025_Content_3 = {
    Text = "Nessuno potrebbe mai resistere al fascino dei cuccioli morbidosi!!!"
  },
  AvgCommunicate_67025_Content_4 = {
    Text = "Esatto. Ho scelto i cuccioli per favorire un miglior lavoro di squadra tra gli studenti."
  },
  AvgCommunicate_67025_Content_5 = {
    Text = "Per quanto adori questi piccoli tanto quanto i miei studenti, richiedono più cure e addestramento rispetto ai cani adulti."
  },
  AvgCommunicate_67025_Content_6 = {
    Text = "Con l'aumento del numero di studenti iscritti al mio corso, è aumentato anche il numero di cuccioli necessari. È diventato difficile per me gestirli tutti da sola."
  },
  AvgCommunicate_67025_Content_7 = {
    Text = "Un problema facile da risolvere! Se l'Istruttrice Alva chiede semplicemente un po' di aiuto, un sacco di persone si offriranno volontarie per prendersi cura dei cuccioli. Anzi, potrebbero esserci più volontari che cuccioli!"
  },
  AvgCommunicate_67025_Content_8 = {
    Text = "Reclutare volontari? È una buona idea."
  },
  AvgCommunicate_67025_Content_9 = {
    Text = "Farò una richiesta al Decano Czort per ottenere l'approvazione. Se tutto andrà bene, gli studenti potranno anche vedere più cuccioli."
  },
  AvgCommunicate_67025_Option_10 = {
    Text = "Per favore, assicurati di tenermi un posto!!!"
  },
  AvgCommunicate_67025_Option_3 = {
    Text = "Nessuno potrebbe mai resistere al fascino dei cuccioli morbidosi!!!"
  },
  AvgCommunicate_67025_Option_7 = {
    Text = "Un problema facile da risolvere!"
  },
  AvgCommunicate_67026_Content_1 = {
    Text = "Custode, hai qualche suggerimento per migliorare i miei recenti corsi di addestramento per investigatori?"
  },
  AvgCommunicate_67026_Content_10 = {
    Text = "Inoltre, i cani militari ben addestrati possono assistere notevolmente i soldati in vari compiti. Forse potremmo considerare di aggiungere questo alle missioni degli investigatori."
  },
  AvgCommunicate_67026_Content_11 = {
    Text = "Cani... Sarebbe bello..."
  },
  AvgCommunicate_67026_Content_12 = {
    Text = "Devo dedurne che questo ti renderebbe più disposta a venire alle lezioni di addestramento?"
  },
  AvgCommunicate_67026_Content_13 = {
    Text = "Assolutamente, Istruttrice Alva!"
  },
  AvgCommunicate_67026_Content_2 = {
    Text = "Il mio suggerimento: l'addestramento è stato ottimo! Non c'è bisogno di ulteriore addestramento..."
  },
  AvgCommunicate_67026_Content_3 = {
    Text = "L'addestramento era troppo difficile?"
  },
  AvgCommunicate_67026_Content_4 = {
    Text = "Scherzavo. È solo che trovo l'addestramento troppo noioso. Non ho nessuna motivazione per farlo..."
  },
  AvgCommunicate_67026_Content_5 = {
    Text = "Capisco. Sembra che il problema principale riguardi l'interesse."
  },
  AvgCommunicate_67026_Content_6 = {
    Text = "Pensandoci, mi è venuta un'idea. Le persone sarebbero più motivate se integrassimo dei cani militari nella routine di addestramento?"
  },
  AvgCommunicate_67026_Content_7 = {
    Text = "Cani militari? Vuoi dire che ci sono dei cani in classe con te?"
  },
  AvgCommunicate_67026_Content_8 = {
    Text = "Sì. In realtà è un metodo comunemente usato nell'esercito. I soldati tendono a sentirsi meglio quando sono accompagnati da un cane."
  },
  AvgCommunicate_67026_Content_9 = {
    Text = "Avere un cagnolone morbidoso al mio fianco mi motiverebbe sicuramente!"
