  AvgCommunicate_67027_Content_1 = {
    Text = "Custode, perché nessuno di Mythag mi chiede più di esaudire i propri desideri?"
  },
  AvgCommunicate_67027_Content_10 = {
    Text = "Invece di chiedere che vengano esauditi direttamente, le persone vogliono qualcosa da sognare, qualcosa da attendere con speranza."
  },
  AvgCommunicate_67027_Content_11 = {
    Text = "Anche se i loro desideri non si avverano subito, il semplice atto di desiderare qualcosa può portare loro conforto."
  },
  AvgCommunicate_67027_Content_12 = {
    Text = "I desideri che non possono essere esauditi subito... sono davvero così preziosi?"
  },
  AvgCommunicate_67027_Content_13 = {
    Text = "Credo di capire ora. A partire da domani, impartirò a tutti la mia benedizione alla fontana della scuola."
  },
  AvgCommunicate_67027_Content_14 = {
    Text = "Aspetta, perché alla fontana della scuola?"
  },
  AvgCommunicate_67027_Content_15 = {
    Text = "Ho sentito che i pozzi dei desideri sono popolari in molti luoghi, quindi se trasformo la fontana della scuola in un pozzo dei desideri, tutti potranno venire a cercare la Benedizione."
  },
  AvgCommunicate_67027_Content_16 = {
    Text = "La logica non fa una piega, ma è un po' strano!"
  },
  AvgCommunicate_67027_Content_2 = {
    Text = "Mm... suppongo sia perché la gente di Mythag è pragmatica."
  },
  AvgCommunicate_67027_Content_3 = {
    Text = "Avendo affrontato innumerevoli pericoli ogni giorno, il loro spirito è diventato abbastanza resiliente da non affidarsi ai desideri per salvarsi."
  },
  AvgCommunicate_67027_Content_4 = {
    Text = "...Sembra che io sia ancora troppo inutile."
  },
  AvgCommunicate_67027_Content_5 = {
    Text = "No, no! Non è che tutti abbiano completamente smesso di esprimere desideri."
  },
  AvgCommunicate_67027_Content_6 = {
    Text = "È più che altro che i loro desideri sono diventati più astratti, a lungo termine."
  },
  AvgCommunicate_67027_Content_7 = {Text = "Davvero?"},
  AvgCommunicate_67027_Content_8 = {
    Text = "Non capisco. Cosa intendi per astratti?"
