  AvgCommunicate_67028_Content_1 = {
    Text = "Salve, Custode {Male=Mr.,Female=Miss}. Scusa se ti disturbo di nuovo dopo tutto questo tempo."
  },
  AvgCommunicate_67028_Content_10 = {
    Text = "Fantastico. Passerò in un momento comodo."
  },
  AvgCommunicate_67028_Content_11 = {
    Text = "Oh, e per ora non diciamo niente a Lily. Voglio farle una sorpresa."
  },
  AvgCommunicate_67028_Content_2 = {
    Text = "Ho ottenuto inaspettatamente due bellissimi pesci rossi."
  },
  AvgCommunicate_67028_Content_3 = {
    Text = "Fortunatamente, sotto le mie cure, hanno deposto con successo molte uova. Quelle uova si sono schiuse in innumerevoli pesciolini."
  },
  AvgCommunicate_67028_Content_4 = {
    Text = "Fantastico. Se ricordo bene, ami i pesci, vero?"
  },
  AvgCommunicate_67028_Content_5 = {
    Text = "Esatto. Ho un profondo legame con il mondo sottomarino."
  },
  AvgCommunicate_67028_Content_6 = {
    Text = "I pesci, le alghe e i coralli nell'acqua sono un luogo caldo, familiare nella mia Memoria."
  },
  AvgCommunicate_67028_Content_7 = {
    Text = "Scusa, mi sono lasciata distrarre. Volevo chiederti se saresti disposto a prenderti cura di alcuni dei pesci rossi."
  },
  AvgCommunicate_67028_Content_8 = {
    Text = "Il modo in cui agitano le pinne caudali nell'acqua è così carino. Penso che a Lily piacerebbero tantissimo."
  },
  AvgCommunicate_67028_Content_9 = {
    Text = "Certo! Possiamo metterne alcuni nelle stanze di entrambi."
  },
  AvgCommunicate_67028_Option_4 = {
    Text = "Fantastico. Se ricordo bene, ami i pesci, vero?"
  },
  AvgCommunicate_67028_Option_9 = {
