  AvgCommunicate_67029_Content_1 = {
    Text = "Oh cielo, Custode, mi stavi cercando?"
  },
  AvgCommunicate_67029_Content_10 = {
    Text = "Così Casiah ha avuto un'idea geniale: studiamo gli animali! È molto più facile!"
  },
  AvgCommunicate_67029_Content_11 = {
    Text = "...E dove sono le galline adesso?"
  },
  AvgCommunicate_67029_Content_12 = {
    Text = "Nella stanza di Casiah, dove tanti pulcini appena nati ora scorrazzano liberi! La mia stanza è diventata molto vivace!"
  },
  AvgCommunicate_67029_Content_13 = {
    Text = "Riporta quelle galline in mensa immediatamente!!"
  },
  AvgCommunicate_67029_Content_14 = {
    Text = "Che crudeltà, Custode! Voler separare questi pulcini dalle loro madri! Ti sei forse dimenticato dell'amore materno?!"
  },
  AvgCommunicate_67029_Content_15 = {
    Text = "Non proverò amore materno per un mucchio di galline!"
  },
  AvgCommunicate_67029_Content_16 = {
    Text = "E non accetto di essere definito insensibile da una come te!"
  },
  AvgCommunicate_67029_Content_2 = {
    Text = "Esatto. Casiah, qualcuno ha segnalato che dopo il tuo spettacolo di magia improvvisato nella mensa della scuola ieri, tre galline e venti uova sono sparite dal magazzino."
  },
  AvgCommunicate_67029_Content_3 = {
    Text = "Cooosa~? Come può essere successo? Casiah è davvero perplessa."
  },
  AvgCommunicate_67029_Content_4 = {
    Text = "Smettila di fare la finta tonta! Tutti ti hanno vista far comparire un mucchio di galline!"
  },
  AvgCommunicate_67029_Content_5 = {
