  },
  AvgCommunicate_67030_Content_1 = {
    Text = "Sigh, Maestro, perché secondo te nessuna delle tortine preparate con cura da Karen riesce mai a vendersi?"
  },
  AvgCommunicate_67030_Content_10 = {
    Text = "Chi è che ha i gusti particolari qui!!"
  },
  AvgCommunicate_67030_Content_11 = {
    Text = "Sigh, avviare un'attività è così difficile. Devo vendere qualcos'altro. Che ne dite se questa volta preparo delle bevande?"
  },
  AvgCommunicate_67030_Content_12 = {
    Text = "Smettila, basta infliggere le tue creazioni a tutti!!!"
  },
  AvgCommunicate_67030_Content_2 = {
    Text = "L'ultima volta che abbiamo allestito un banchetto nel campus, Murphy le ha addirittura sputate per terra. Se non fossi scappata abbastanza in fretta, mi avrebbe picchiata!"
  },
  AvgCommunicate_67030_Content_3 = {
