  },
  AvgCommunicate_67031_Content_10 = {
    Text = "Non hai letto l'etichetta?"
  },
  AvgCommunicate_67031_Content_11 = {
    Text = "L'etichetta? Non riesco a leggerla."
  },
  AvgCommunicate_67031_Content_12 = {
    Text = "Non riesci a— Ma stai ignorando le lezioni base di lingua?!"
  },
  AvgCommunicate_67031_Content_13 = {
    Text = "Argh, che seccatura! Perché la padrona del labirinto deve studiare!"
  },
  AvgCommunicate_67031_Content_14 = {
    Text = "Sbrigati e trovami degli schiavi che mi servano!"
  },
  AvgCommunicate_67031_Content_15 = {
    Text = "Svegliati, principessa. Roma è caduta da un pezzo."
  },
  AvgCommunicate_67031_Content_16 = {
    Text = "La nostra società non ha più padroni e schiavi!"
  },
  AvgCommunicate_67031_Content_17 = {
    Text = "Non mi importa! Se non puoi portarmi nessuno, allora servi tu me!"
  },
  AvgCommunicate_67031_Content_18 = {
    Text = "Allora immagino che dovresti continuare a lavarti i denti col sapone."
  },
  AvgCommunicate_67031_Content_19 = {
    Text = "Ti butterò nel labirinto in pasto ai miei piccoli!!!"
  },
  AvgCommunicate_67031_Content_2 = {
    Text = "Che ti succede??"
  },
  AvgCommunicate_67031_Content_3 = {
    Text = "Non avevi detto che il dentifricio è quello nel tubetto lungo e non nella scatolina?"
  },
  AvgCommunicate_67031_Content_4 = {
    Text = "Ho usato il tubetto lungo e ora la mia bocca è in fiamme! È così piccante e amaro!!"
  },
  AvgCommunicate_67031_Content_5 = {
    Text = "Ehm... Il dentifricio non dovrebbe avere quel sapore."
  },
  AvgCommunicate_67031_Content_6 = {
    Text = "Aspetta un attimo... Di che colore è il tubetto lungo che hai usato?"
  },
  AvgCommunicate_67031_Content_7 = {
    Text = "Blu, perché?"
  },
  AvgCommunicate_67031_Content_8 = {
    Text = "...Quel tubetto è per lavare il viso. Il dentifricio è nel tubetto verde..."
  },
  AvgCommunicate_67031_Content_9 = {
