  },
  AvgCommunicate_67031_Option_8 = {
    Text = "...Quel tubetto è per lavare il viso. Il dentifricio è nel tubetto verde..."
  },
  AvgCommunicate_67032_Content_1 = {
    Text = "Oh cucciolo, fa così freddo nella Pozza Nera. Sento la mia vita che si consuma lentamente."
  },
  AvgCommunicate_67032_Content_10 = {
    Text = "Hmm... E se ti dicessi che sono riuscita ad allentare un po' il dispositivo che mi intrappola?"
  },
  AvgCommunicate_67032_Content_11 = {
    Text = "?! Arrivo subito."
  },
  AvgCommunicate_67032_Content_2 = {
    Text = "Se non vieni a trovarmi presto, potrei sciogliermi in D-melma..."
  },
  AvgCommunicate_67032_Content_3 = {
    Text = "...Non cadrò più nei tuoi tranelli."
  },
  AvgCommunicate_67032_Content_4 = {
    Text = "Come puoi trattare così la tua mentore? Non mentirei mai alla mia preziosa studentessa."
  },
  AvgCommunicate_67032_Content_5 = {
    Text = "Mi manca ancora il modo in cui ti imboscavi durante le lezioni, temendo che potessi scoprirti."
  },
  AvgCommunicate_67032_Content_6 = {
    Text = "La tua espressione retta ma ingenua era così~ carina."
  },
  AvgCommunicate_67032_Content_7 = {
    Text = "Smettila o spengo il comunicatore."
  },
  AvgCommunicate_67032_Content_8 = {
    Text = "Che freddezza. Non c'è nulla che possa dire per farti venire a trovarmi?"
  },
  AvgCommunicate_67032_Content_9 = {
    Text = "Tu che ne pensi?"
  },
  AvgCommunicate_67032_Option_11 = {
    Text = "?! Arrivo subito."
  },
  AvgCommunicate_67032_Option_3 = {
    Text = "...Non cadrò più nei tuoi tranelli."
