  AvgCommunicate_67032_Option_7 = {
    Text = "Smettila o spengo il comunicatore."
  },
  AvgCommunicate_67032_Option_9 = {
    Text = "Tu che ne pensi?"
  },
  AvgCommunicate_67033_Content_1 = {
    Text = "Ah, Watson, la vita è così noiosa."
  },
  AvgCommunicate_67033_Content_10 = {
    Text = "Non dirmi che hai davvero perso contro di lui?"
  },
  AvgCommunicate_67033_Content_11 = {
    Text = "No, non quello. Nessuno dei due era disposto a cedere. La posta in gioco continuava a salire, e avevamo entrambi gli occhi iniettati di sangue."
  },
  AvgCommunicate_67033_Content_12 = {
    Text = "Poi, nella foga, il vecchio ha avuto un Cedimento, e ho Scoperto che in realtà aveva barato per tutto il tempo."
  },
  AvgCommunicate_67033_Content_13 = {
    Text = "Quindi hai diviso vittorie e sconfitte alla pari con un baro per tutto questo tempo?"
  },
  AvgCommunicate_67033_Content_14 = {
    Text = "Già, ero così deluso. La cosa ancora più irritante è che il vecchio è andato su tutte le furie per l'umiliazione e si è lanciato su di me per fare a botte."
  },
  AvgCommunicate_67033_Content_15 = {
    Text = "In realtà sospettava che fossi un imbroglione come lui! Che insulto."
  },
  AvgCommunicate_67033_Content_16 = {
    Text = "Alla fine, siamo stati buttati fuori entrambi dal personale del Scommetti un Fang. Mi fa ancora male il sedere per la caduta. Che sfortuna maledetta."
  },
  AvgCommunicate_67033_Content_17 = {
    Text = "Non so perché, ma proprio non riesco a provare compassione..."
  },
  AvgCommunicate_67033_Content_2 = {
    Text = "? Devi essere andato a giocare d'azzardo di nuovo. Hai spennato tutti un'altra volta?"
  },
  AvgCommunicate_67033_Content_3 = {
    Text = "Non questa volta, davvero! Stavo solo andando al Fang delle Scommesse per divertirmi come al solito... ehm."
  },
  AvgCommunicate_67033_Content_4 = {
    Text = "Va bene, continua."
  },
  AvgCommunicate_67033_Content_5 = {
    Text = "Fammi sentire il resto delle tue scuse."
  },
  AvgCommunicate_67033_Content_6 = {
    Text = "Sigh, e poi oggi ho incontrato improvvisamente un Rivale che poteva tenermi testa alla pari."
  },
  AvgCommunicate_67033_Content_7 = {
    Text = "Dopo essermi seduto a quel tavolo, le vittorie e le sconfitte erano Quasi equamente divise tra me e quel vecchietto dall'aria insignificante."
  },
  AvgCommunicate_67033_Content_8 = {
    Text = "È davvero scioccante. Per riuscire a vincere contro la tua fortuna, deve essere un vero esperto."
  },
  AvgCommunicate_67033_Content_9 = {
    Text = "È esattamente quello che ho pensato! Così ho raccolto tutta la mia concentrazione e ho continuato a giocare con lui. Mi sono persino messo seduto dritto!"
  },
  AvgCommunicate_67033_Option_10 = {
    Text = "Non dirmi che hai davvero perso contro di lui?"
  },
  AvgCommunicate_67033_Option_13 = {
