  AvgCommunicate_67034_Content_1 = {
    Text = "Custode, salve."
  },
  AvgCommunicate_67034_Content_10 = {
    Text = "Davvero? E allora come spieghi questo compito in classe insufficiente? Fare errori su argomenti così basilari... Credo che ti farebbe bene copiare le risposte corrette cento volte."
  },
  AvgCommunicate_67034_Content_11 = {
    Text = "Cento volte?! No, ti prego... Aspetta, mi ero quasi dimenticata che sei Erica!"
  },
  AvgCommunicate_67034_Content_12 = {
    Text = "Perché hai fatto la Maledizione in modo così realistico? L'hai fatto apposta?! Lascio una recensione negativa!!"
  },
  AvgCommunicate_67034_Content_13 = {Text = "Ramona."},
  AvgCommunicate_67034_Content_14 = {
    Text = "Ricevuto. Cambio simulazione della personalità a: Ramona."
  },
  AvgCommunicate_67034_Content_15 = {
    Text = "Partner, un insegnante mi ha appena detto che a quanto pare non hai consegnato uno dei tuoi compiti?"
  },
  AvgCommunicate_67034_Content_16 = {
    Text = "Eh? Davvero? Ricordo chiaramente di aver fatto tutti i compiti..."
  },
  AvgCommunicate_67034_Content_17 = {
    Text = "Quando hai intenzione di correggere questa tua abitudine di essere così distratta?"
  },
  AvgCommunicate_67034_Content_18 = {
    Text = "Lascia perdere. D'ora in poi vieni ogni giorno nella mia stanza. Ti sorveglierò finché non avrai finito i compiti giornalieri prima di andartene. Ah, e niente consultare risposte o materiale di riferimento."
  },
  AvgCommunicate_67034_Content_19 = {
    Text = "Cosa?! Non se ne parla! Come faccio a fare i compiti senza materiale di riferimento?!"
  },
  AvgCommunicate_67034_Content_2 = {
    Text = "Sei invitato/a a provare l'ultimo sistema di simulazione della personalità. Questo sistema, quando le missioni lo richiedono, imiterà le comunicazioni per conto dei membri non disponibili, prevederà la loro logica comportamentale e altro ancora."
  },
  AvgCommunicate_67034_Content_20 = {
    Text = "Aspetta... mi ero quasi dimenticata che sei Erica! Mi hai spaventata apposta?! Lascio una recensione negativa!!"
  },
  AvgCommunicate_67034_Content_21 = {
    Text = "Capito. Il tuo feedback sull'utilizzo è stato ricevuto. Valutazione preliminare: simulazione qualificata."
  },
  AvgCommunicate_67034_Content_22 = {
    Text = "Non vedo l'ora di rivederti al prossimo test di sistema."
  },
  AvgCommunicate_67034_Content_3 = {
    Text = "Ti preghiamo di condividere i tuoi commenti e suggerimenti una volta terminato il periodo di prova."
  },
  AvgCommunicate_67034_Content_4 = {
    Text = "Che roba strana è questa?"
  },
  AvgCommunicate_67034_Content_5 = {
    Text = "Puoi scegliere uno dei seguenti due personaggi iniziali per sperimentare una simulazione della personalità: Doll, Ramona."
  },
  AvgCommunicate_67034_Content_6 = {Text = "Doll."},
  AvgCommunicate_67034_Content_7 = {
    Text = "Ricevuto. Cambio simulazione della personalità a: Doll."
  },
  AvgCommunicate_67034_Content_8 = {
    Text = "Custode, sono usciti i risultati del tuo ultimo esame. Spero che tu sia consapevole di quello che hai combinato ultimamente."
  },
  AvgCommunicate_67034_Content_9 = {
    Text = "Eh? Io... Ultimamente ho consegnato tutti i compiti in tempo. Mi sono solo addormentata in classe un paio di volte, tutto qui..."
  },
  AvgCommunicate_67034_Option_11 = {
    Text = "Cento volte?! No, ti prego..."
  },
  AvgCommunicate_67034_Option_13 = {Text = "Ramona."},
  AvgCommunicate_67034_Option_16 = {
    Text = "Eh? Davvero? Ricordo chiaramente di aver fatto tutti i compiti..."
  },
  AvgCommunicate_67034_Option_19 = {
    Text = "Cosa?! Non se ne parla! Come faccio a fare i compiti senza materiale di riferimento?!"
  },
  AvgCommunicate_67034_Option_4 = {
    Text = "Che roba strana è questa?"
  },
  AvgCommunicate_67034_Option_6 = {Text = "Doll."},
  AvgCommunicate_67034_Option_9 = {Text = "Eh?"},
  AvgCommunicate_67035_Content_1 = {
    Text = "Caro Custode! Per favore, aiutami!"
  },
  AvgCommunicate_67035_Content_10 = {
    Text = "Ma come può essere un lavoro?!"
  },
  AvgCommunicate_67035_Content_11 = {
    Text = "Beh... Le sessioni di addestramento di Alva ultimamente si sono concentrate sull'addestrare i cuccioli a eseguire la Caccia ai nemici."
  },
  AvgCommunicate_67035_Content_12 = {
    Text = "Se non ti dispiace essere morso dai cani, puoi andare a giocare il ruolo del cattivo laggiù."
  },
  AvgCommunicate_67035_Content_13 = {
    Text = "Cosa? Stai dicendo che posso essere ferocemente morso da adorabili cucciolini?"
  },
  AvgCommunicate_67035_Content_14 = {
    Text = "Ci sto! Sei il migliore, Custode!"
  },
  AvgCommunicate_67035_Content_2 = {
    Text = "Non ti sto urlando contro né picchiando. E non sono nella mia stanza."
  },
  AvgCommunicate_67035_Content_3 = {
    Text = "Oh, dai, questa volta davvero non ero al Cancello della tua Stanza!"
  },
  AvgCommunicate_67035_Content_4 = {
    Text = "Grazie al tuo aiuto l'ultima volta, ho passato un sacco di tempo a farmi colpire felicemente dentro il sacco di sabbia nella sala d'addestramento. Mi sentivo come a casa—non sono mai stato così felice prima."
  },
  AvgCommunicate_67035_Content_5 = {
    Text = "Mm… di niente. L'importante è che tu sia felice."
  },
  AvgCommunicate_67035_Content_6 = {
    Text = "Sigh, ma alla fine sono stato scoperto di recente. Non ho idea di come Uvhash abbia capito che ero io lì dentro."
  },
  AvgCommunicate_67035_Content_7 = {
    Text = "Dopo che tutti hanno scoperto che ero io dentro il Sacco di sabbia, mi hanno tutti maledetto."
  },
  AvgCommunicate_67035_Content_8 = {
    Text = "Anche se quella parte è stata piuttosto divertente, non posso più travestirmi da Sacco di sabbia."
  },
  AvgCommunicate_67035_Content_9 = {
    Text = "Che faccio? Essere disoccupato è terribile, Custode! Per favore, trovami un altro lavoro del genere!"
  },
  AvgCommunicate_67035_Option_10 = {
    Text = "Ma come può essere un lavoro?!"
  },
  AvgCommunicate_67035_Option_2 = {
    Text = "Non ti sto urlando contro né picchiando. E non sono nella mia stanza."
  },
  AvgCommunicate_67035_Option_5 = {
    Text = "Mm… di niente. L'importante è che tu sia felice."
  },
  AvgCommunicate_67036_Content_1 = {
    Text = "Custode! La mia ultima modifica è un successo!"
  },
  AvgCommunicate_67036_Content_10 = {
    Text = "In questo modo non dovrò più preoccuparmi di dimenticare di controllare il mio diario e di perdere i ricordi precedenti."
  },
  AvgCommunicate_67036_Content_11 = {
    Text = "Ottima idea! Ma non eri solita non preoccuparti così tanto della tua smemoratezza?"
  },
  AvgCommunicate_67036_Content_12 = {
    Text = "È vero, ma adesso non voglio dimenticare i miei amici."
  },
  AvgCommunicate_67036_Content_13 = {
    Text = "Mi assicurerò di ricordarmi di te, Custode!"
  },
  AvgCommunicate_67036_Content_2 = {
    Text = "Congratulazioni! Stai parlando del tuo Il Nautilus? Inoltre, mi sorprende che tu ti ricordi ancora di me."
  },
  AvgCommunicate_67036_Content_3 = {
    Text = "No, sto parlando di questa piccola finestra di chat."
  },
  AvgCommunicate_67036_Content_4 = {
    Text = "? Quello si chiama comunicatore, e cosa esattamente hai modificato??"
  },
  AvgCommunicate_67036_Content_5 = {
    Text = "Adesso posso impostare ciò che ho scritto perché venga inviato con un ritardo, e posso controllare io stessa il tempo di ritardo."
  },
  AvgCommunicate_67036_Content_6 = {
    Text = "Per esempio, il primo messaggio che ti ho appena inviato in realtà è stato scritto cinque minuti fa come test."
  },
  AvgCommunicate_67036_Content_7 = {
    Text = "È incredibile?! Sembra che si potrebbero pianificare operazioni successive in anticipo durante le missioni, e anche attivare piani di riserva sarebbe davvero comodo."
  },
  AvgCommunicate_67036_Content_8 = {
    Text = "Ah, io non ci ho pensato tanto quanto voi."
  },
  AvgCommunicate_67036_Content_9 = {
    Text = "Stavo solo pensando che, se invio ciò che ricordo oggi a me stessa domani, allora non dimenticherò."
  },
  AvgCommunicate_67036_Option_11 = {
    Text = "Ottima idea! Ma non eri solita non preoccuparti così tanto della tua smemoratezza?"
  },
  AvgCommunicate_67036_Option_2 = {
    Text = "Congratulazioni! Stai parlando del tuo Il Nautilus? Inoltre, mi sorprende che tu ti ricordi ancora di me."
