  },
  AvgCommunicate_67037_Content_1 = {
    Text = "Custode, di recente ho scoperto un gioco di poesia molto interessante."
  },
  AvgCommunicate_67037_Content_10 = {Text = "Freddo."},
  AvgCommunicate_67037_Content_11 = {Text = "Morte."},
  AvgCommunicate_67037_Content_12 = {Text = "Canto."},
  AvgCommunicate_67037_Content_13 = {Text = "Amore."},
  AvgCommunicate_67037_Content_14 = {
    Text = "Malinconia."
  },
  AvgCommunicate_67037_Content_15 = {Text = "Fragranza."},
  AvgCommunicate_67037_Content_16 = {
    Text = "Hmm, penso che basti così. Provo a intrecciare tutto in un verso."
  },
  AvgCommunicate_67037_Content_17 = {
    Text = "L'amore dell'usignolo per la luna fiorisce notte dopo notte nella sua gola melodiosa, eppure la luna resta sempre così fredda."
  },
  AvgCommunicate_67037_Content_18 = {
    Text = "Cantò e cantò, finché la spina della rosa gli trafisse il petto."
  },
  AvgCommunicate_67037_Content_19 = {
    Text = "Quel canto svanì con il flusso cremisi della morte, lasciando solo la rosa, solo la rosa a esalare una malinconica fragranza."
  },
  AvgCommunicate_67037_Content_2 = {
    Text = "Che tipo di gioco?"
  },
  AvgCommunicate_67037_Content_20 = {
    Text = "Bellissimo! Bravo! Non mi aspettavo di meno da te!"
  },
  AvgCommunicate_67037_Content_21 = {
    Text = "È... è solo qualcosa che ho improvvisato al momento. Niente di speciale..."
  },
  AvgCommunicate_67037_Content_22 = {
    Text = "Se questo verso è bello, allora metà della sua bellezza l'hai creata tu."
  },
  AvgCommunicate_67037_Content_3 = {
    Text = "Ognuno dice a turno un'Immagine, e dopo diversi giri, tutte le Immagini vengono combinate insieme per formare un'Offerta."
  },
  AvgCommunicate_67037_Content_4 = {
    Text = "È pieno della bellezza degli accostamenti casuali, non trovi? Ti piacerebbe provare con me?"
  },
  AvgCommunicate_67037_Content_5 = {
    Text = "Sembra davvero divertente! Giochiamo, giochiamo!"
  },
  AvgCommunicate_67037_Content_6 = {
    Text = "Allora comincio io. Rosa."
  },
