  },
  AvgCommunicate_67037_Option_7 = {Text = "Sboccia."},
  AvgCommunicate_67037_Option_9 = {Text = "Luna."},
  AvgCommunicate_67038_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} Custode, la statua di Tulu che mi hai chiesto di realizzare per Miryam è stata consegnata nella tua stanza."
  },
  AvgCommunicate_67038_Content_10 = {
    Text = "La sua comprensione di Tulu è persino inferiore alla mia comprensione di te; davvero incompetente."
  },
  AvgCommunicate_67038_Content_11 = {
    Text = "Basta! Non dirlo. Non farglielo vedere."
  },
  AvgCommunicate_67038_Content_12 = {
    Text = "Comunque, grazie per il tuo duro lavoro. Fammi pensare a come dirlo a Miryam..."
  },
  AvgCommunicate_67038_Content_2 = {
    Text = "L'ho visto, ma questa immagine... non è un po' troppo carina?"
  },
  AvgCommunicate_67038_Content_3 = {
    Text = "È questo il vero aspetto di Tulu? Miryam mi strangolerà..."
  },
  AvgCommunicate_67038_Content_4 = {
    Text = "Cosa? Anche tu sei una devota seguace del giovane Re?"
  },
  AvgCommunicate_67038_Content_5 = {
    Text = "Ai miei occhi, era solo un bambino, a cui altri avevano semplicemente imposto una corona e delle catene."
  },
  AvgCommunicate_67038_Content_6 = {
    Text = "Non trovi che il suo aspetto assonnato e pigro di ogni giorno sia adorabile? Mi ricorda il gatto a pelo lungo che avevo da bambina."
  },
  AvgCommunicate_67038_Content_7 = {
    Text = "Potresti anche avere ragione, e chi ha richiesto la statua probabilmente ne sarà soddisfatto..."
  },
  AvgCommunicate_67038_Content_8 = {
    Text = "L'unica cattiva notizia potrebbe essere la creazione di un mondo in cui solo Miryam soffre..."
  },
  AvgCommunicate_67038_Content_9 = {
    Text = "Questo dimostra solo che è una sacerdotessa cieca che non comprende il Dio che venera."
  },
  AvgCommunicate_67038_Option_11 = {
    Text = "Basta! Non dirlo. Non farglielo vedere."
  },
  AvgCommunicate_67038_Option_2 = {
    Text = "L'ho visto, ma questa immagine... non è un po' troppo carina?"
  },
  AvgCommunicate_67038_Option_7 = {
    Text = "Potresti anche avere ragione, e chi ha richiesto la statua probabilmente ne sarà soddisfatto..."
  },
  AvgCommunicate_67039_Content_1 = {
    Text = "Caro Custode, hai ricevuto la mia ultima opera?"
  },
  AvgCommunicate_67039_Content_10 = {
    Text = "Complimenti così improvvisi... mi fai arrossire..."
  },
  AvgCommunicate_67039_Content_11 = {
    Text = "Non c'è bisogno di essere timido. Sei sempre stato la mia musa. Quando hai tempo, verresti a visitare il mio studio?"
  },
  AvgCommunicate_67039_Content_12 = {
    Text = "Ho così tante opere che desidero completare. Ho bisogno di tracciare con cura i contorni della tua anima."
  },
  AvgCommunicate_67039_Content_13 = {
    Text = "Sarò qui nella La Veglia per te, in attesa che tu mi conceda altra Intuizione."
  },
  AvgCommunicate_67039_Content_2 = {
    Text = "Questo... sono io, addormentato?"
  },
  AvgCommunicate_67039_Content_3 = {
    Text = "Nella mia Intuizione, questo sei tu, che sprofondi in un bellissimo Sogno."
  },
  AvgCommunicate_67039_Content_4 = {
    Text = "Ottenere una felicità cieca e falsa, o una discesa lucida e dolorosa?"
  },
  AvgCommunicate_67039_Content_5 = {
    Text = "Una scelta impossibile è per sempre una questione di arte e filosofia."
  },
  AvgCommunicate_67039_Content_6 = {
    Text = "Non posso avere una felicità che sia al contempo lucida e reale?"
  },
  AvgCommunicate_67039_Content_7 = {
    Text = "Hehe, quanto sei avido."
  },
  AvgCommunicate_67039_Content_8 = {
    Text = "Nulla è perfetto. Forse nemmeno la scultura può catturare la perfezione."
  },
  AvgCommunicate_67039_Content_9 = {
    Text = "Ma puoi sempre percorrere il Sentiero alla ricerca di tale felicità. È lì che risiede il tuo fascino."
  },
  AvgCommunicate_67039_Option_10 = {
    Text = "Complimenti così improvvisi... mi fai arrossire..."
  },
  AvgCommunicate_67039_Option_2 = {
    Text = "Questo... sono io, addormentato?"
  },
  AvgCommunicate_67039_Option_6 = {
    Text = "Non posso avere una felicità che sia al contempo lucida e reale?"
  },
  AvgCommunicate_67040_Content_1 = {
    Text = "Oh, tesoro, come ti sei sentito riguardo al nostro dolce momento insieme l'ultima volta? L'hai assaporato ogni giorno da allora?"
  },
  AvgCommunicate_67040_Content_10 = {
    Text = "Dillo e basta, cosa stai tramando questa volta…"
  },
  AvgCommunicate_67040_Content_11 = {
    Text = "Non essere così teso, siamo già in ottimi rapporti~"
  },
  AvgCommunicate_67040_Content_12 = {
    Text = "Fidati di me, seguimi, e ti condurrò verso piaceri tutti nuovi."
  },
  AvgCommunicate_67040_Content_13 = {
    Text = "Questa volta, vorresti sperimentare di persona come si usano le candele e le piccole fruste?"
  },
  AvgCommunicate_67040_Content_14 = {
    Text = "Ti insegnerò tutto, mano a mano, passo dopo passo, tesoro."
  },
  AvgCommunicate_67040_Content_2 = {
    Text = "Quale momento insieme?"
  },
  AvgCommunicate_67040_Content_3 = {
    Text = "Non ricordo."
  },
  AvgCommunicate_67040_Content_4 = {
    Text = "Che crudeltà! E io sono stata così gentile con te l'ultima volta~"
  },
  AvgCommunicate_67040_Content_5 = {
    Text = "Ti consiglierei di fare attenzione alle parole..."
  },
  AvgCommunicate_67040_Content_6 = {
    Text = "Hmph, fare il finto tonto non ti servirà, perché ho già usato la cera per Registrare ogni contorno, ogni curva, ogni forma del tuo corpo!"
  },
  AvgCommunicate_67040_Content_7 = {
    Text = "Voglio davvero mostrarlo a Tutti~"
  },
  AvgCommunicate_67040_Content_8 = {
    Text = "?! Non oseresti?"
  },
  AvgCommunicate_67040_Content_9 = {
    Text = "Oh mio, beh dipende da come il tesorino mi tratta~ Sono molto Fragile, sai~"
  },
  AvgCommunicate_67040_Option_10 = {
    Text = "Dillo e basta, cosa stai tramando questa volta…"
  },
  AvgCommunicate_67040_Option_2 = {
