  },
  AvgCommunicate_67040_Option_8 = {
    Text = "?! Non oseresti?"
  },
  AvgCommunicate_67041_Content_1 = {
    Text = "Maestro, mi stavi facendo dei gesti poco fa. Volevi dire che desideravi contattarmi?"
  },
  AvgCommunicate_67041_Content_10 = {
    Text = "Sigh, devo insegnarti a riconoscere le Donne cattive a scuola e procurarti subito delle misure precauzionali."
  },
  AvgCommunicate_67041_Content_11 = {
    Text = "Ascoltami: lascia il suo Cancello adesso. Più lontano vai, meglio è. Dille semplicemente dopo che ti ho chiamato io!"
  },
  AvgCommunicate_67041_Content_12 = {
    Text = "M-ma ho già fatto una promessa a Lady Pandia. Non posso venire meno alla mia parola."
  },
  AvgCommunicate_67041_Content_13 = {
    Text = "Non preoccupatevi, mio signore. Ho il Potere per proteggermi!"
  },
  AvgCommunicate_67041_Content_14 = {
    Text = "Tu, io... Lascia perdere. Se insisti a restare lì, registra questo: non entrare mai nella sua Stanza."
  },
  AvgCommunicate_67041_Content_15 = {
    Text = "Certo! Non entrerei mai nella Stanza di una signora!"
  },
  AvgCommunicate_67041_Content_16 = {
    Text = "Non importa cosa dica, non entrare. Chiamami se succede qualcosa. Ah, e qualunque cosa tu faccia, non annusare le sue candele!"
  },
  AvgCommunicate_67041_Content_17 = {
    Text = "Lo terrò a mente, mio signore. Ma perché non posso annusare le candele?"
  },
  AvgCommunicate_67041_Content_18 = {
    Text = "Non chiedere... Sono lezioni duramente pagate con il mio Sangue e le mie lacrime per conto tuo..."
  },
  AvgCommunicate_67041_Content_2 = {
    Text = "Esatto. Perché sei rimasto davanti al Cancello di Pandia??"
  },
  AvgCommunicate_67041_Content_3 = {
    Text = "Ah, Pandia me l'ha chiesto. Ha detto che aveva qualcosa di molto importante di cui occuparsi e voleva che facessi da Guardiano della sua porta."
  },
  AvgCommunicate_67041_Content_4 = {
    Text = "Qualcosa di importante? Non credere alle sue sciocchezze! Le sue cosiddette faccende... Lascia perdere, ti ha sicuramente ingannato!"
  },
  AvgCommunicate_67041_Content_5 = {
    Text = "Eh? Ma la sua Espressione di poco fa era così solenne, e mi stringeva la mano con tale sincerità..."
  },
  AvgCommunicate_67041_Content_6 = {
    Text = "Lascia che indovini: ti ha preso la mano e ti ha chiamato il Cavaliere più affidabile e gentile."
  },
  AvgCommunicate_67041_Content_7 = {
    Text = "Come facevate a saperlo, mio signore?!"
  },
  AvgCommunicate_67041_Content_8 = {
    Text = "Ogier, non fidarti mai delle parole di una Donna cattiva! Ti avrà in pugno in men che non si dica!"
  },
  AvgCommunicate_67041_Content_9 = {
    Text = "Mm, è solo che sento che nessuno ha cattive intenzioni..."
  },
  AvgCommunicate_67041_Option_10 = {
    Text = "Devo insegnarti a riconoscere le Donne cattive a scuola, e in fretta..."
  },
  AvgCommunicate_67041_Option_14 = {
    Text = "Lascia perdere..."
  },
  AvgCommunicate_67041_Option_16 = {
    Text = "Non importa cosa dica, non entrare. Chiamami se succede qualcosa."
