  AvgCommunicate_67042_Content_1 = {
    Text = "Din don, c'è un adorabile regalo che ti aspetta per essere ritirato~"
  },
  AvgCommunicate_67042_Content_10 = {
    Text = "In effetti ha un buon profumo, un aroma molto particolare, ma perché mi sento un po' stordito/a..."
  },
  AvgCommunicate_67042_Content_11 = {
    Text = "Forse ti sei già innamorato/a di me. Quindi, sono sceso/a di sotto proprio come hai chiesto."
  },
  AvgCommunicate_67042_Content_12 = {
