  },
  AvgCommunicate_67043_Content_1 = {
    Text = "Dopo aver trascorso così tanto tempo a Mythag, all'improvviso mi ritrovo a sentire la mancanza della luna sopra il deserto."
  },
  AvgCommunicate_67043_Content_10 = {
    Text = "Vieni, creiamo nuovi ricordi insieme — tra i fiori, attraverso i campi aperti, per vedere il Mare Profondo e le valli, le città e la campagna."
  },
  AvgCommunicate_67043_Content_11 = {
    Text = "Voglio lasciare ricordi di noi in ogni luogo meraviglioso. Resterai al mio fianco, vero?"
  },
  AvgCommunicate_67043_Content_2 = {
    Text = "Quindi anche tu soffri di nostalgia di casa?"
  },
  AvgCommunicate_67043_Content_3 = {
    Text = "Più che nostalgia di casa, forse sto solo rievocando i ricordi che un tempo ho condiviso con le persone — quelle emozioni intense."
  },
  AvgCommunicate_67043_Content_4 = {
    Text = "Non mi aspettavo che fossi così sentimentale."
  },
  AvgCommunicate_67043_Content_5 = {
    Text = "Cosa? Pensi che io sia il tipo spensierato e senza cuore? No, ricordo ogni persona, ogni ricordo caldo e dolce."
  },
  AvgCommunicate_67043_Content_6 = {
    Text = "Compresi quelli con te."
  },
  AvgCommunicate_67043_Content_7 = {
    Text = "Dovrei sentirmi onorato o geloso?"
  },
  AvgCommunicate_67043_Content_8 = {
    Text = "Adoro vederti tutto agitato così. Che carino."
  },
  AvgCommunicate_67043_Content_9 = {
    Text = "Per quanto i giorni passati meritino di essere assaporati, la gioia di stasera è la più preziosa di tutte."
  },
  AvgCommunicate_67043_Option_2 = {
    Text = "Quindi anche tu soffri di nostalgia di casa?"
  },
  AvgCommunicate_67043_Option_4 = {
