  },
  AvgCommunicate_67044_Content_1 = {
    Text = "Ultimamente sto progettando una serie di accessori per adornare la mia collezione."
  },
  AvgCommunicate_67044_Content_10 = {
    Text = "Se ti fa piacere, accetta queste collane che ho selezionato con cura. Questa volta sono un regalo."
  },
  AvgCommunicate_67044_Content_11 = {
