  AvgCommunicate_67045_Content_1 = {
    Text = "Sigh, gli affari nel mio negozietto vanno male ultimamente. È passato molto tempo dall'ultima volta che ho trovato una testa che mi soddisfacesse."
  },
  AvgCommunicate_67045_Content_10 = {
    Text = "Se voi due collaboraste per dare la caccia a dei grandi criminali ricercati, potreste persino creare una leggenda di vigilanti urbani che puniscono il male."
  },
  AvgCommunicate_67045_Content_11 = {
    Text = "Non è una cattiva idea, ma un tipo sveglio come quello non è facile da ingannare."
  },
  AvgCommunicate_67045_Content_12 = {
    Text = "A pensarci bene, quella sua testa peculiare varrebbe davvero la pena di essere aggiunta alla mia Collezione. Peccato che non ci sia occasione per uno scambio. Che rammarico."
  },
  AvgCommunicate_67045_Content_13 = {
