    Text = "Mio signore! La cavalla Neve sta per partorire!"
  },
  AvgCommunicate_67046_Content_10 = {
    Text = "Non vedo l'ora di addestrare il puledro!"
  },
  AvgCommunicate_67046_Content_11 = {
    Text = "Si inizia ad allevare un cavallo così giovane?"
  },
  AvgCommunicate_67046_Content_12 = {
    Text = "Un cavallo è il compagno più fidato di un cavaliere! Più c'è fiducia tra loro, meglio è."
  },
  AvgCommunicate_67046_Content_13 = {
    Text = "Ho sempre desiderato possedere un cavallo allevato da me fin da puledro!"
  },
  AvgCommunicate_67046_Content_14 = {
    Text = "Si vede che non vedi davvero l'ora."
  },
  AvgCommunicate_67046_Content_15 = {
    Text = "Se avrò tempo verrò a dare una mano."
  },
  AvgCommunicate_67046_Content_16 = {
    Text = "Sono curiosa anch'io di scoprire che tipo di manto avrà il puledro."
  },
  AvgCommunicate_67046_Content_17 = {
    Text = "!! Sarò ben preparato!"
  },
  AvgCommunicate_67046_Content_2 = {
    Text = "Ricordo che lo stallone era completamente nero. Sono curioso del colore del puledro—sarà bianco e nero?"
  },
  AvgCommunicate_67046_Content_3 = {
    Text = "Forse il puledro avrà le strisce di una zebra."
  },
  AvgCommunicate_67046_Content_4 = {
    Text = "È... è davvero possibile? È incredibile..."
  },
  AvgCommunicate_67046_Content_5 = {
    Text = "Ahah, scherzavo! È pericoloso credere a tutto quello che dicono gli altri."
  },
  AvgCommunicate_67046_Content_6 = {
    Text = "S-starò più attenta la prossima volta! Ma per quanto riguarda voi, mio signore, non potrei mai dubitare delle vostre parole!"
  },
  AvgCommunicate_67046_Content_7 = {
    Text = "Ugh, che luce abbagliante..."
  },
  AvgCommunicate_67046_Content_8 = {
    Text = "Cos'è questo senso di colpa..."
  },
  AvgCommunicate_67046_Content_9 = {
    Text = "Hmm? A proposito, mio signore, sto imparando e ho intenzione di far nascere il puledro da sola!"
  },
