  AvgCommunicate_67047_Content_1 = {
    Text = "Custode, vorrei chiederti un favore."
  },
  AvgCommunicate_67047_Content_10 = {
    Text = "Con te al suo fianco, si sentirà sicuramente più a suo agio e si Rilasserà."
  },
  AvgCommunicate_67047_Content_11 = {
    Text = "Vado con lei… capisco."
  },
  AvgCommunicate_67047_Content_12 = {
    Text = "Allora ti disturbo con questo. Grazie mille, Custode."
  },
  AvgCommunicate_67047_Content_2 = {
    Text = "Che succede?"
  },
  AvgCommunicate_67047_Content_3 = {
    Text = "Potresti portare Tintura a qualche ritrovo così da farle fare nuove amicizie?"
  },
  AvgCommunicate_67047_Content_4 = {
    Text = "Da quando ci siamo Riuniti, mi sta appiccicata addosso ogni giorno, completamente isolata dal mondo esterno."
  },
  AvgCommunicate_67047_Content_5 = {
    Text = "Anche se anch'io tengo molto alla nostra Riunione, non voglio tenerla completamente legata al mio fianco."
  },
  AvgCommunicate_67047_Content_6 = {
    Text = "Non è difficile, ma hai considerato come si sente Tintura a riguardo?"
  },
  AvgCommunicate_67047_Content_7 = {
    Text = "La conosco… ma non può continuare a rifiutarsi di avvicinarsi a Tutti solo per amor mio."
  },
  AvgCommunicate_67047_Content_8 = {
    Text = "Forse non hai bisogno nemmeno tu di allontanarla in modo così deciso."
  },
  AvgCommunicate_67047_Content_9 = {
    Text = "Che ne dici se porto sia te che Tintura a un ritrovo insieme? Mi assicurerò che vengano prese le dovute precauzioni."
  },
  AvgCommunicate_67047_Option_2 = {
    Text = "Che succede?"
  },
  AvgCommunicate_67047_Option_6 = {
    Text = "Non è difficile, ma hai considerato come si sente Tintura a riguardo?"
  },
  AvgCommunicate_67047_Option_8 = {
