  },
  AvgCommunicate_67048_Content_1 = {
    Text = "Custode, grazie per il tuo suggerimento l'ultima volta."
  },
  AvgCommunicate_67048_Content_10 = {
    Text = "Sembra che quella che deve migliorare sia in realtà io, la sorella maggiore."
  },
  AvgCommunicate_67048_Content_2 = {
    Text = "Da quando Tintura e io siamo andati a quel raduno insieme, Tintura si è innamorata del chiacchierare con le sue nuove amiche."
  },
  AvgCommunicate_67048_Content_3 = {
    Text = "Di niente. Vedere voi due felici mi rende felice."
  },
  AvgCommunicate_67048_Content_4 = {
    Text = "Mm... È stata la prima volta che ho capito che quando è completamente libera da ogni peso, Tintura è una bambina così socievole."
  },
  AvgCommunicate_67048_Content_5 = {
    Text = "Resta comunque sempre vicina a me, trascinandomi nelle conversazioni di tanto in tanto."
  },
  AvgCommunicate_67048_Content_6 = {
    Text = "Ma era da così tanto tempo che non la vedevo sorridere così felicemente in mezzo ad altre persone."
  },
  AvgCommunicate_67048_Content_7 = {
    Text = "È meraviglioso."
  },
  AvgCommunicate_67048_Content_8 = {
    Text = "Sigh, è solo che rispetto alla sua Euforia, io trovo ancora queste frequenti occasioni sociali un po' estenuanti."
  },
  AvgCommunicate_67048_Content_9 = {
    Text = "Dopo ogni incontro, ho bisogno di un adeguato Riposo nel mio guscio per un po' prima di riprendermi."
