  AvgCommunicate_67049_Content_10 = {
    Text = "Stai chiaramente cercando di ingannare la gente per i sacrifici in mare, di nuovo!!"
  },
  AvgCommunicate_67049_Content_11 = {
    Text = "Ma certo che no! Quelli erano solo incidenti. Riposando per sempre nella loro terra natale, le loro anime troveranno la salvezza."
  },
  AvgCommunicate_67049_Content_12 = {
    Text = "Hai completamente gettato la maschera! Sospensione! Sospendetelo immediatamente!!"
