  AvgCommunicate_67050_Content_1 = {
    Text = "Custode, cos'è questo avviso che mi proibisce di uscire di notte? Non credo di aver fatto nulla che violi le regole."
  },
  AvgCommunicate_67050_Content_10 = {
    Text = "Calmati. In ogni caso, cerca di farti un buon Riposo stanotte."
  },
  AvgCommunicate_67050_Content_11 = {
    Text = "Se vuoi, posso suggerire alla scuola in seguito di affidarti la gestione del traffico sui Sentieri scolastici."
  },
  AvgCommunicate_67050_Content_2 = {
    Text = "Ecco, la questione è questa…"
  },
  AvgCommunicate_67050_Content_3 = {
    Text = "Diverse volte in passato, quando vagavi per il campus nel cuore della notte, da lontano sembravi un occhio fluttuante. Hai spaventato gli studenti che percorrevano il sentiero notturno."
  },
  AvgCommunicate_67050_Content_4 = {
    Text = "Assurdo. La mia radiosità è sempre stata una luce guida per i perduti. Come potrebbe mai essere spaventosa?"
  },
  AvgCommunicate_67050_Content_5 = {
    Text = "Gli studenti che hanno segnalato la cosa hanno detto che quando ti accorgevi di loro, ti avvicinavi improvvisamente verso di loro."
  },
  AvgCommunicate_67050_Content_6 = {
    Text = "Li hai spaventati così tanto che hanno continuato a correre, eppure tu continuavi a inseguirli."
  },
  AvgCommunicate_67050_Content_7 = {
    Text = "La notte era buia pesta. Speravo solo di guidarli sul Sentiero giusto."
  },
  AvgCommunicate_67050_Content_8 = {
    Text = "Bella guida. Per favore, non farlo di nuovo."
  },
  AvgCommunicate_67050_Content_9 = {
    Text = "Loro... persino loro... nessuno di voi, nessuno, capisce il mio dovere..."
  },
  AvgCommunicate_67050_Option_10 = {
