  },
  AvgCommunicate_67051_Content_1 = {
    Text = "Ho improvvisamente perso interesse per i semplici combattimenti."
  },
  AvgCommunicate_67051_Content_10 = {
    Text = "Così in fretta? Allora devi davvero avere un Talento naturale. Hai già giocato contro qualcuno?"
  },
  AvgCommunicate_67051_Content_11 = {
    Text = "Sì, ho bussato al Portale di ogni Risvegliatore. Anche se non tutti hanno accettato di giocare."
  },
  AvgCommunicate_67051_Content_12 = {
    Text = "Quindi hai solo trovato un nuovo modo per infastidire tutti!!"
  },
  AvgCommunicate_67051_Content_13 = {
    Text = "Lasciamo perdere... Allora com'è il tuo bilancio?"
  },
  AvgCommunicate_67051_Content_14 = {
    Text = "Finora ho battuto solo Aurita, ma sono sicura che continuando ad allenarmi diventerò sempre più forte!"
  },
  AvgCommunicate_67051_Content_2 = {
    Text = "?? Chiunque tu sia, scendi subito da Lotan!"
  },
  AvgCommunicate_67051_Content_3 = {
    Text = "Ma che stai dicendo? Ho semplicemente scoperto di recente un tipo di battaglia più interessante."
  },
  AvgCommunicate_67051_Content_4 = {Text = "Quale?"},
  AvgCommunicate_67051_Content_5 = {
    Text = "Gli scacchi! Me ne ha parlato Dexter. Ha detto che tutti i veri maestri di arti marziali sono abili negli scacchi."
  },
  AvgCommunicate_67051_Content_6 = {
    Text = "Solo percependo le intenzioni dell'avversario e anticipando le sue mosse si può ottenere la vittoria sulla scacchiera."
  },
  AvgCommunicate_67051_Content_7 = {
    Text = "Non appena avrò imparato gli scacchi, raggiungerò sicuramente il livello successivo in combattimento!"
  },
  AvgCommunicate_67051_Content_8 = {
    Text = "Qualcosa non torna in tutto questo... ma almeno il risultato è buono."
  },
  AvgCommunicate_67051_Content_9 = {
    Text = "Studio scacchi da una settimana ormai, e sento di averli completamente padroneggiati!"
  },
  AvgCommunicate_67051_Option_10 = {
    Text = "Così in fretta?"
  },
  AvgCommunicate_67051_Option_12 = {
