  AvgCommunicate_67052_Content_1 = {Text = "Fame."},
  AvgCommunicate_67052_Content_10 = {
    Text = "Karen, ha detto che c'è un tipo di, salsiccia, fatta con il Sangue, buona."
  },
  AvgCommunicate_67052_Content_11 = {
    Text = "Voglio mangiarla."
  },
  AvgCommunicate_67052_Content_12 = {
    Text = "Allora chiedi a Lei di preparartela."
  },
  AvgCommunicate_67052_Content_13 = {
    Text = "Non sa farla. Falla tu per me."
  },
  AvgCommunicate_67052_Content_14 = {
    Text = "? Non sa farla nemmeno Lei, e perché dovrei saperlo io?"
  },
  AvgCommunicate_67052_Content_15 = {
    Text = "Il tuo Sangue, buono, Versane una goccia."
  },
  AvgCommunicate_67052_Content_16 = {
    Text = "Per favore."
  },
  AvgCommunicate_67052_Content_17 = {
    Text = "...Fai davvero di tutto per il cibo."
  },
  AvgCommunicate_67052_Content_18 = {
    Text = "Va bene, visto che mi stai supplicando, ci darò un'occhiata."
  },
  AvgCommunicate_67052_Content_2 = {
    Text = "Lo sapevo. Non è che sei diventata dipendente dal bere il mio Sangue, vero?"
  },
  AvgCommunicate_67052_Content_3 = {
    Text = "Mm, ma se ne bevo troppo, morirai."
  },
  AvgCommunicate_67052_Content_4 = {
    Text = "Grazie per preoccuparti così tanto del fatto che io viva o muoia. Chi era che si è fatta prendere la mano bevendo il mio Sangue al punto da finire per combattere contro di me l'ultima volta?"
  },
  AvgCommunicate_67052_Content_5 = {
    Text = "È delizioso, davvero."
  },
  AvgCommunicate_67052_Content_6 = {
    Text = "Lascia perdere. Comunque, non bere il mio stavolta. Sono già sull'orlo dell'anemia."
  },
  AvgCommunicate_67052_Content_7 = {
    Text = "Ma l'ospedale ultimamente dice che le scorte della banca del Sangue sono basse, quindi non possono darcene di extra. Che seccatura."
  },
  AvgCommunicate_67052_Content_8 = {
