  AvgCommunicate_67052_Option_14 = {
    Text = "? Non sa farla nemmeno Lei, e perché dovrei saperlo io?"
  },
  AvgCommunicate_67052_Option_17 = {
    Text = "...Fai davvero di tutto per il cibo."
  },
  AvgCommunicate_67052_Option_2 = {
    Text = "Lo sapevo. Non è che sei diventata dipendente dal bere il mio Sangue, vero?"
  },
  AvgCommunicate_67052_Option_4 = {
    Text = "Grazie per preoccuparti così tanto del fatto che io viva o muoia."
  },
  AvgCommunicate_67052_Option_6 = {
    Text = "Lascia perdere. Comunque, non bere il mio stavolta. Sono già sull'orlo dell'anemia."
  },
  AvgCommunicate_67052_Option_9 = {Text = "Cosa?"},
  AvgCommunicate_67053_Content_1 = {
    Text = "Oh cielo, cucciolotto, ti ho visto consegnare una torta a Tawil poco fa."
  },
  AvgCommunicate_67053_Content_10 = {
    Text = "Dopotutto, quando mi sento sola, questi Cancelli Sigillati tendono sempre ad allentarsi un po'…"
  },
  AvgCommunicate_67053_Content_11 = {
    Text = "Tu! Io— va bene, arrivo subito!"
  },
  AvgCommunicate_67053_Content_2 = {
    Text = "Fai favoritismi adesso, senza portarne neanche una alla tua cara mentore. Che strazio."
