  AvgCommunicate_67053_Content_3 = {
    Text = "Come se tu potessi mangiarla?"
  },
  AvgCommunicate_67053_Content_4 = {
    Text = "E allora soffri pure."
  },
  AvgCommunicate_67053_Content_5 = {
    Text = "Anche se il mio corpo non ha bisogno di mangiare, il mio spirito ha ancora molto bisogno delle attenzioni del mio cucciolotto."
  },
  AvgCommunicate_67053_Content_6 = {
    Text = "Se lasciarla qui sarebbe uno spreco, guardarti mangiare davanti a me non sarebbe male."
  },
  AvgCommunicate_67053_Content_7 = {
    Text = "Posso immaginare la consistenza e il sapore di quella dolce panna, come scivola dalla punta della tua lingua giù per la gola…"
  },
  AvgCommunicate_67053_Content_8 = {
    Text = "? Sembra che tu abbia già pianificato tutto, ma quando avrei acconsentito?"
  },
  AvgCommunicate_67053_Content_9 = {
