  AvgCommunicate_67055_Content_1 = {
    Text = "Custode, perché l'amico che abbiamo portato dalla spiaggia non si muove..."
  },
  AvgCommunicate_67055_Content_2 = {
    Text = "Il mio amico è malato o triste...?"
