  AvgCommunicate_67055_Content_4 = {
    Text = "Mm... Forse il tuo amico sente la mancanza del mare?"
  },
  AvgCommunicate_67055_Content_5 = {
    Text = "Visto che viene dal mare, forse dovremmo riportarlo a casa?"
  },
  AvgCommunicate_67055_Content_6 = {
    Text = "Capisco... il mio amico ha nostalgia di casa..."
  },
  AvgCommunicate_67055_Content_7 = {
