  },
  AvgCommunicate_67055_Content_8 = {
    Text = "OK, andiamo! Riportiamo il nostro amico a casa! Poi possiamo tornare insieme, a casa nostra!"
  },
  AvgCommunicate_67055_Option_4 = {
    Text = "Mm... Forse il tuo amico sente la mancanza del mare?"
  },
  AvgCommunicate_67056_Content_1 = {
    Text = "Scusami, ci ho pensato a lungo e vorrei chiederti una cosa..."
