  AvgCommunicate_67056_Content_10 = {
    Text = "È così...? Che bello."
  },
  AvgCommunicate_67056_Content_11 = {
    Text = "Sono felice di essere stato d'aiuto."
  },
  AvgCommunicate_67056_Content_12 = {
    Text = "Non devi scappare via ogni volta. Sarei felice di fare due Chiacchiere con te e bere una tazza di tè."
  },
  AvgCommunicate_67056_Content_13 = {
    Text = "No... Non è il mio posto. Non voglio creare alcun legame. Sarebbe dannoso per te, per me; persino per il tempo e lo spazio."
  },
  AvgCommunicate_67056_Content_14 = {
    Text = "Almeno concedimi il tempo di dirti addio prima che tu parta."
  },
  AvgCommunicate_67056_Content_15 = {
    Text = "...D'accordo."
  },
  AvgCommunicate_67056_Content_2 = {
    Text = "Che succede?"
  },
  AvgCommunicate_67056_Content_3 = {
    Text = "Pensi che io risponda alle tue evocazioni abbastanza velocemente?"
  },
  AvgCommunicate_67056_Content_4 = {
    Text = "Anche se rispondo sempre alla tua chiamata e parto il più velocemente possibile..."
  },
  AvgCommunicate_67056_Content_5 = {
