  AvgCommunicate_67057_Content_10 = {
    Text = "Mi dispiace, non mi è possibile cercare i compiti di altre persone per te. Tale comportamento costituisce plagio e viola il regolamento scolastico e l'etica sociale."
  },
  AvgCommunicate_67057_Content_11 = {
