  AvgCommunicate_67057_Content_12 = {
    Text = "Oh, ma dai... Allora puoi almeno cercare nel database le risposte alle domande dei compiti, o qualche materiale correlato?"
  },
  AvgCommunicate_67057_Content_13 = {
    Text = "Mi dispiace, non mi è possibile cercare le risposte ai compiti per te. Tale comportamento costituisce un atto di frode e viola il regolamento scolastico e l'etica sociale."
  },
  AvgCommunicate_67057_Content_14 = {
    Text = "Se hai altre domande o hai bisogno di assistenza, non esitare a farmelo sapere. Ti fornirò informazioni positive e costruttive."
  },
  AvgCommunicate_67057_Content_15 = {
    Text = "Che sistema inutile, è fin troppo ligio alle regole! Spegnetelo! Spegnetelo! Lascio una recensione negativa!"
  },
  AvgCommunicate_67057_Content_16 = {
    Text = "Il tuo feedback è stato ricevuto. Non vediamo l'ora di rivederti dopo che saranno stati apportati dei miglioramenti."
  },
  AvgCommunicate_67057_Content_2 = {
    Text = "Sei invitato/a a provare il nuovo sistema di interrogazione intelligente. Ti preghiamo di condividere il tuo feedback e i tuoi suggerimenti dopo la prova."
