  AvgCommunicate_70486_Content_13 = {
    Text = "La prego, comprenda i sentimenti di un padre."
  },
  AvgCommunicate_70486_Content_14 = {
    Text = "Spero che potrai perdonare le cose che farò in futuro."
  },
  AvgCommunicate_70486_Content_15 = {
    Text = "La Pozza nera è estremamente pericolosa ora; la tua forza spirituale non può sopravvivere nella Pozza nera!"
