  AvgCommunicate_70486_Content_4 = {
    Text = "Non è colpa tua. Non c'è bisogno di incolparti, Custode."
  },
  AvgCommunicate_70486_Content_5 = {
    Text = "Mentre scortava il Decano Czort, si è imbattuta in Herbert..."
