  AvgCommunicate_70486_Content_6 = {
    Text = "Non si è \"imbattuta\" in lui, Custode."
  },
  AvgCommunicate_70486_Content_7 = {
    Text = "Herbert è venuto qui appositamente per Ramona."
  },
  AvgCommunicate_70486_Content_8 = {
    Text = "Voglio solo sapere, adesso, se è stata portata alla Pozza nera."
  },
  AvgCommunicate_70486_Content_9 = {
    Text = "Non voglio nascondere nulla, Professor Dexter."
  },
  AvgCommunicate_70486_Option_15 = {
    Text = "La prego, non sia impulsivo!"
  },
  AvgCommunicate_70486_Option_3 = {
    Text = "È colpa mia. Non sono riuscito a proteggerla..."
  },
  AvgCommunicate_70486_Option_5 = {
    Text = "Mentre scortava il Decano Czort, si è imbattuta in Herbert..."
  },
  AvgCommunicate_70486_Option_9 = {Text = "Sì..."},
  AvgCommunicate_70487_Content_1 = {
    Text = "Come procede la guarigione di quella debole?"
  },
  AvgCommunicate_70487_Content_10 = {Text = "..."},
  AvgCommunicate_70487_Content_11 = {
    Text = "Non mi piace lei, e non mi piaci tu. Ma detesto ancora di più quella presuntuosa Montagna di Neve, e coloro che desiderano usarmi o tradirmi."
  },
  AvgCommunicate_70487_Content_12 = {
    Text = "Questo è tutto."
  },
  AvgCommunicate_70487_Content_2 = {
    Text = "Dopo essere tornata dalla Montagna di Neve, ha ricevuto cure e le sue ferite sono guarite molto bene."
  },
  AvgCommunicate_70487_Content_3 = {
    Text = "Ho saputo della Montagna di Neve dall'altra versione di te."
  },
  AvgCommunicate_70487_Content_4 = {
    Text = "Grazie, Helot. Sei tu che ci hai aiutato."
  },
  AvgCommunicate_70487_Content_5 = {
    Text = "Grazie?\" Che parola insignificante."
  },
  AvgCommunicate_70487_Content_6 = {
    Text = "Volevo solo ottenere il potere della Montagna di Neve. Non ha nulla a che fare con l'aiutare voi."
  },
  AvgCommunicate_70487_Content_7 = {
    Text = "Le vite di un branco di formiche non mi riguardano."
  },
  AvgCommunicate_70487_Content_8 = {
    Text = "Nella Montagna di Neve, hai avuto la possibilità di uccidere l'altra versione di te stessa, divorando il potere da sola o lasciando che la montagna divorasse tutti noi."
  },
  AvgCommunicate_70487_Content_9 = {
    Text = "Ma non l'hai fatto, vero?"
  },
  AvgCommunicate_70487_Option_3 = {
    Text = "Grazie per quello che hai fatto riguardo alla Montagna di Neve."
  },
  AvgCommunicate_70487_Option_8 = {
    Text = "Eppure hai scelto di non uccidere l'altra versione di te stessa."
  },
  AvgCommunicate_70488_Content_1 = {
    Text = "La salute del Capitano sta peggiorando..."
  },
  AvgCommunicate_70488_Content_10 = {
    Text = "Custode, farò del mio meglio per assistervi."
  },
  AvgCommunicate_70488_Content_11 = {
    Text = "Se è possibile, la prego, salvi il capitano."
  },
  AvgCommunicate_70488_Content_12 = {
    Text = "Questo... è il mio desiderio."
  },
  AvgCommunicate_70488_Content_2 = {
    Text = "Posso chiedere, c'è un modo per aiutarlo?"
  },
  AvgCommunicate_70488_Content_3 = {
    Text = "Non sarà facile, Celeste."
  },
  AvgCommunicate_70488_Content_4 = {
    Text = "Stabilire un Legame con un Risvegliatore è un peso enorme per il corpo, anche per un investigatore addestrato."
  },
  AvgCommunicate_70488_Content_5 = {
    Text = "Per un profano come il Capitano Elton, lo sforzo è ancora maggiore."
  },
  AvgCommunicate_70488_Content_6 = {
    Text = "Il fatto che sia riuscito a mantenere un Legame con te per così tanto tempo è già un miracolo."
  },
  AvgCommunicate_70488_Content_7 = {
    Text = "Ma non preoccuparti, troverò sicuramente un modo per aiutare entrambi."
  },
  AvgCommunicate_70488_Content_8 = {
    Text = "Se Miryam può farcela, Mythag può sicuramente farcela anche lui."
  },
  AvgCommunicate_70488_Content_9 = {
    Text = "Le persone esprimono desideri a me, eppure io sono impotente nell'aiutare chi mi sta accanto..."
  },
  AvgCommunicate_70488_Option_3 = {
    Text = "Potrebbe essere difficile, ma Mythag troverà sicuramente un modo."
  },
  AvgCommunicate_70489_Content_1 = {
    Text = "Scusa per il disturbo, Occhio Pallido Senza Pupilla."
  },
  AvgCommunicate_70489_Content_10 = {
    Text = "Il mio contattarti è puramente per interesse personale."
  },
  AvgCommunicate_70489_Content_11 = {
    Text = "Una volta che avrò sbrigato le questioni in corso, spero di avere l'opportunità di incontrarti in privato."
  },
  AvgCommunicate_70489_Content_12 = {
    Text = "Riguardo al tuo passato e al tuo futuro."
  },
  AvgCommunicate_70489_Content_13 = {
    Text = "Beh, ammesso che tu riesca a sopravvivere a questi eventi."
  },
  AvgCommunicate_70489_Content_14 = {
    Text = "Ti auguro il meglio, {Male=Mr.,Female=Miss} Custode."
  },
  AvgCommunicate_70489_Content_15 = {
    Text = "Il mio futuro?"
  },
  AvgCommunicate_70489_Content_16 = {
    Text = "Cosa intendi?"
  },
  AvgCommunicate_70489_Content_17 = {Text = "..."},
  AvgCommunicate_70489_Content_18 = {
    Text = "Clementine?"
  },
  AvgCommunicate_70489_Content_2 = {
    Text = "Sei tu... Arrivi al momento giusto. Ho ancora molte cose che voglio chiederti."
  },
  AvgCommunicate_70489_Content_3 = {
    Text = "Cosa ci hai fatto nell'Ospizio dei Poveri?"
  },
  AvgCommunicate_70489_Content_4 = {
    Text = "Come ho detto, è solo un trucco che rientra nel mio campo professionale."
  },
  AvgCommunicate_70489_Content_5 = {
    Text = "Mi ha permesso di andarmene lasciando che tutti voi vi godeste una bella notte di riposo."
  },
  AvgCommunicate_70489_Content_6 = {
    Text = "Mi hai chiamato \"Occhio senza pupilla\" diverse volte ormai. Cosa significa davvero?"
  },
  AvgCommunicate_70489_Content_7 = {
    Text = "Shh, questo non è qualcosa che dovresti sapere adesso."
  },
  AvgCommunicate_70489_Content_8 = {
    Text = "Fidati, lo scoprirai... quando sarà il momento giusto."
  },
  AvgCommunicate_70489_Content_9 = {
    Text = "In ogni caso, non ho cattive intenzioni, {Male=Mr.,Female=Miss} Custode."
  },
  AvgCommunicate_70489_Option_15 = {
    Text = "Il mio futuro?"
  },
  AvgCommunicate_70489_Option_2 = {
    Text = "La psicologa?!"
  },
  AvgCommunicate_70489_Option_3 = {
    Text = "Cosa ci hai fatto nell'Ospizio dei Poveri?"
  },
  AvgCommunicate_70489_Option_6 = {
    Text = "Cosa significa esattamente \"Occhio senza pupilla\"?"
  },
  AvgCommunicate_70490_Content_1 = {
    Text = "Quando il corpo artificiale si è autodistrutto, ho lasciato a Herbert un piccolo frammento di Argento dotato di capacità di registrazione e trasmissione dati."
  },
  AvgCommunicate_70490_Content_10 = {
    Text = "Esattamente identico al simbolo che hai disegnato nel tuo sogno."
  },
  AvgCommunicate_70490_Content_11 = {
    Text = "Cos'è esattamente quel simbolo?"
  },
  AvgCommunicate_70490_Content_12 = {
    Text = "La Chiesa della luce del tempio."
  },
  AvgCommunicate_70490_Content_13 = {
    Text = "Quindi sono davvero loro..."
  },
  AvgCommunicate_70490_Content_14 = {
    Text = "Gli scultori, Elworth... La Chiesa della luce del tempio ha tirato i fili da dietro le quinte."
  },
  AvgCommunicate_70490_Content_15 = {
    Text = "I veri nemici di Mythag si stanno avvicinando."
  },
  AvgCommunicate_70490_Content_16 = {
    Text = "Preparati, %player%."
  },
  AvgCommunicate_70490_Content_2 = {
    Text = "Grazie alla bramosia di Herbert, questo piccolo dispositivo è comunque riuscito a raccogliere una discreta quantità di informazioni."
  },
  AvgCommunicate_70490_Content_3 = {
    Text = "Che possanza, Professoressa Doll!"
  },
  AvgCommunicate_70490_Content_4 = {
    Text = "È solo che non è stato abbastanza cauto."
  },
  AvgCommunicate_70490_Content_5 = {
    Text = "Un sedicente genio la cui arroganza lo porterà ad abbassare la guardia."
  },
  AvgCommunicate_70490_Content_6 = {
    Text = "Avevi pianificato questa mossa da tempo?!"
  },
  AvgCommunicate_70490_Content_7 = {
    Text = "Anche manipolando corpi artificiali, uscire è piuttosto problematico."
  },
  AvgCommunicate_70490_Content_8 = {
    Text = "Se non riesco a ottenere qualcosa, tanto vale godermi il tè pomeridiano in sala."
  },
  AvgCommunicate_70490_Content_9 = {
    Text = "In sintesi, l'informazione più cruciale tra i dati raccolti è un simbolo."
  },
  AvgCommunicate_70490_Option_11 = {
    Text = "Cos'è esattamente quel simbolo?"
  },
  AvgCommunicate_70490_Option_3 = {
    Text = "Che possanza, Professoressa Doll!"
  },
  AvgCommunicate_70490_Option_6 = {
    Text = "Avevi pianificato questa mossa da tempo?!"
  },
  AvgCommunicate_70491_Content_1 = {
    Text = "Il primo Compito sul campo dopo aver assunto il ruolo di Custode è terminato."
  },
  AvgCommunicate_70491_Content_10 = {
    Text = "Non avrei mai immaginato che la mia prima missione ufficiale sul campo avrebbe comportato tutto questo."
  },
  AvgCommunicate_70491_Content_11 = {
    Text = "Perché tu sei il Custode."
  },
  AvgCommunicate_70491_Content_12 = {
    Text = "Molti se ne sono andati, ma molti di più si sono salvati grazie a te."
  },
  AvgCommunicate_70491_Content_13 = {
    Text = "Siamo sulla strada giusta."
  },
  AvgCommunicate_70491_Content_14 = {
    Text = "Hai ragione, Ramona."
  },
  AvgCommunicate_70491_Content_15 = {
    Text = "Più persone sono state salvate grazie a noi."
  },
  AvgCommunicate_70491_Content_16 = {
    Text = "Percorreremo questa strada fino in fondo."
  },
  AvgCommunicate_70491_Content_17 = {
    Text = "Certamente!"
  },
  AvgCommunicate_70491_Content_2 = {
    Text = "Congratulazioni."
  },
  AvgCommunicate_70491_Content_3 = {
    Text = "Non avrei mai immaginato che la mia prima missione ufficiale sul campo avrebbe comportato tutto questo."
  },
  AvgCommunicate_70491_Content_4 = {
    Text = "Ma in ogni caso, ci siamo riusciti."
  },
  AvgCommunicate_70491_Content_5 = {
    Text = "Siamo sulla strada giusta."
  },
  AvgCommunicate_70491_Content_6 = {
    Text = "Esatto, {Male=Mr.,Female=Miss} Custode."
  },
  AvgCommunicate_70491_Content_7 = {
    Text = "Percorreremo questa strada fino in fondo."
  },
  AvgCommunicate_70491_Content_8 = {
    Text = "Non ho la sensazione di aver portato a termine alcunché, Ramona."
  },
  AvgCommunicate_70491_Content_9 = {
    Text = "Anders senior, Sarah, Aigis..."
  },
  AvgCommunicate_70491_Option_14 = {
    Text = "Hai perfettamente ragione..."
  },
  AvgCommunicate_70491_Option_3 = {
    Text = "Ci sono molti rimpianti, ma siamo sul sentiero giusto."
  },
  AvgCommunicate_70491_Option_8 = {
    Text = "La questione è temporaneamente risolta, ma alcuni rimpianti non potranno mai essere sanati."
  },
  AvgCommunicate_70492_Content_1 = {
    Text = "Ho intenzione di tenere una cerimonia commemorativa a breve, ma mi mancano un po' di pesci vivi e barche."
  },
  AvgCommunicate_70492_Content_10 = {
    Text = "Dal momento che conosci il mio passato, dovresti già sapere la mia risposta."
  },
  AvgCommunicate_70492_Content_11 = {
    Text = "Se dovessi rifarlo, farei ancora ciò che ho fatto un tempo."
  },
  AvgCommunicate_70492_Content_12 = {
    Text = "Il passato, il presente e il futuro. La Gran Sacerdotessa di Lemuria non ha rimpianti."
  },
  AvgCommunicate_70492_Content_13 = {
    Text = "Io... non ho mai avuto altra scelta, Custode."
  },
  AvgCommunicate_70492_Content_2 = {
    Text = "Mythag potrebbe prestarcene alcuni per un po'? In qualità di Somma Sacerdotessa di Lemuria, garantisco che verranno restituiti puntualmente."
  },
  AvgCommunicate_70492_Content_3 = {
    Text = "Nessun problema. Comunicherò io con la scuola per te; il comitato scolastico dovrebbe approvare la richiesta."
  },
  AvgCommunicate_70492_Content_4 = {
    Text = "Questi oggetti... sono per la tua famiglia o per Deborah?"
  },
  AvgCommunicate_70492_Content_5 = {
    Text = "...Sai tutto?"
  },
  AvgCommunicate_70492_Content_6 = {
    Text = "Secondo le usanze lemuriane, si usano pesci vivi e barche per porgere i propri omaggi a coloro che si amano di più tra i defunti."
  },
  AvgCommunicate_70492_Content_7 = {
    Text = "Non riesci ancora a dimenticarli. Li ami ancora profondamente."
  },
  AvgCommunicate_70492_Content_8 = {
    Text = "Quindi... te ne penti, Miryam?"
  },
  AvgCommunicate_70492_Content_9 = {Text = "..."},
  AvgCommunicate_70492_Option_3 = {
    Text = "Nessun problema."
  },
  AvgCommunicate_70492_Option_4 = {
    Text = "Sono per la tua famiglia o per Deborah?"
  },
  AvgCommunicate_70492_Option_8 = {
    Text = "Te ne penti?"
  },
  AvgCommunicate_70493_Content_1 = {
    Text = "Ho finito di leggere il tuo testamento."
  },
  AvgCommunicate_70493_Content_10 = {
    Text = "Narrerò con orgoglio le tue gesta agli altri fino a... il giorno in cui la mia Memoria subirà la Dissoluzione."
  },
  AvgCommunicate_70493_Content_11 = {
    Text = "Ma mentre recito il tuo testamento, in questo momento, il rimpianto consuma ogni mio pensiero."
  },
  AvgCommunicate_70493_Content_12 = {
    Text = "Dicevi di essere un codardo. Dicevi che non avresti mai voluto abbandonarci."
  },
  AvgCommunicate_70493_Content_13 = {
    Text = "Ma alla fine, hai comunque percorso questo sentiero."
  },
  AvgCommunicate_70493_Content_14 = {
    Text = "Padre non c'è più. Anche tu non ci sei più."
  },
  AvgCommunicate_70493_Content_15 = {
    Text = "Non mi importa delle bugie che hai detto. Avrei voluto che continuassi a ingannarmi ancora un po'. Un anno, un mese..."
  },
  AvgCommunicate_70493_Content_16 = {
    Text = "Anche se fosse solo per un giorno, le parole rimaste non dette avrebbero almeno la possibilità di essere pronunciate..."
  },
  AvgCommunicate_70493_Content_17 = {
    Text = "Ho davvero paura, %player%."
  },
  AvgCommunicate_70493_Content_18 = {
    Text = "Ho paura che un giorno dimenticherò il tuo volto e il tuo nome."
  },
  AvgCommunicate_70493_Content_19 = {
    Text = "Ho paura che un giorno tu scomparirai completamente dalla mia memoria..."
  },
  AvgCommunicate_70493_Content_2 = {
    Text = "Ho provato a recitare quelle parole con tono rassicurante, come desideravate."
  },
  AvgCommunicate_70493_Content_20 = {
    Text = "Ma sai, io non sono il tipo di persona che si arrende."
  },
  AvgCommunicate_70493_Content_21 = {
    Text = "Non riesco a credere che tu sia svanito così."
  },
  AvgCommunicate_70493_Content_22 = {
    Text = "Non importa quanto dovrò aspettare, sarò qui, a ricordare. Fino al giorno in cui ti risveglierai dalla Pozza nera, aprirai quella porta e tornerai in questo campus."
  },
  AvgCommunicate_70493_Content_23 = {
    Text = "Quando quel momento arriverà, ti racconterò tutto ciò che è accaduto mentre non c'eri, e anche quelle parole mai dette, una per una..."
  },
  AvgCommunicate_70493_Content_24 = {
    Text = "So che ora devi essere molto stanco, troppo stanco per rispondere... Va bene così, riposa pure."
  },
  AvgCommunicate_70493_Content_25 = {
    Text = "Ti sto aspettando... %player%."
  },
  AvgCommunicate_70493_Content_3 = {
    Text = "Ho fatto del mio meglio. Ma non ce la faccio, %player%..."
  },
  AvgCommunicate_70493_Content_4 = {
    Text = "Il Cimitero delle Chiavi è pieno di gente; non riesco a vedere nessuno."
  },
  AvgCommunicate_70493_Content_5 = {
    Text = "Il mondo intero è ammutolito. Resta solo il suono della pioggia, solo tu e io."
  },
  AvgCommunicate_70493_Content_6 = {
    Text = "Quando quella porta si è chiusa davanti a me e quelle parole sono scorte riga dopo riga davanti ai miei Occhi, tutto ciò che ho provato è stato rimpianto."
  },
  AvgCommunicate_70493_Content_7 = {
    Text = "Mi pento di averti inculcato quegli ideali da Investigatore, mi pento di averti insegnato tutto quel Sapere sulle Operazioni, mi pento di averti portato qui da Akut..."
  },
  AvgCommunicate_70493_Content_8 = {
    Text = "So che non dovrei pensarla così."
  },
  AvgCommunicate_70493_Content_9 = {
    Text = "Sono un Investigatore. Hai salvato il nostro mondo dalla Dissoluzione. Dovrei essere fiero di te."
  },
  AvgCommunicate_70494_Content_1 = {
    Text = "Buongiorno, Custode di Mythag."
  },
  AvgCommunicate_70494_Content_10 = {
    Text = "Ho sentito dire che Mythag ha prodotto un Custode eccezionale."
  },
  AvgCommunicate_70494_Content_11 = {
    Text = "Non dovrei intromettermi così bruscamente, ma semplicemente non riesco a contenere la mia curiosità e desideravo vederti di persona."
  },
  AvgCommunicate_70494_Content_12 = {
    Text = "Non mi hai deluso, %player%."
  },
  AvgCommunicate_70494_Content_13 = {
    Text = "Cosa intendi fare esattamente?"
  },
  AvgCommunicate_70494_Content_14 = {
    Text = "Se ne avrò l'occasione, mi piacerebbe invitarvi nel mio laboratorio come Ospite."
  },
  AvgCommunicate_70494_Content_15 = {
    Text = "Un Custode capace di creare un Legame con innumerevoli Risvegliati... I segreti che vi riguardano mi incuriosiscono enormemente."
  },
  AvgCommunicate_70494_Content_16 = {
    Text = "Se tu e tutti i membri de Gli scultori vi consegnaste a Mythag, una cooperazione potrebbe essere presa in considerazione."
  },
  AvgCommunicate_70494_Content_17 = {
    Text = "Heh... Pensavo che mi avresti rimproverato duramente."
  },
  AvgCommunicate_70494_Content_18 = {
    Text = "Sei più interessante di quanto immaginassi."
  },
  AvgCommunicate_70494_Content_19 = {
    Text = "I giorni a venire sono lunghi, e in futuro avremo molte occasioni per comunicare."
  },
  AvgCommunicate_70494_Content_2 = {
    Text = "Sei tu... Herbert Rosenthal..."
  },
  AvgCommunicate_70494_Content_20 = {
    Text = "Non vedo l'ora, %player%."
  },
  AvgCommunicate_70494_Content_3 = {
    Text = "Oh, sembra che qualcuno mi abbia già presentato a voi."
  },
  AvgCommunicate_70494_Content_4 = {
    Text = "In realtà mi ha risparmiato un bel po' di problemi."
  },
  AvgCommunicate_70494_Content_5 = {
    Text = "Le comunicazioni Argento richiedono un Legame bidirezionale. Come avete fatto a contattarmi?"
  },
  AvgCommunicate_70494_Content_6 = {Text = "Hmm..."},
  AvgCommunicate_70494_Content_7 = {
    Text = "Per chi ha avuto la fortuna di partecipare allo sviluppo, la tecnologia di comunicazione Argento non ha segreti."
  },
  AvgCommunicate_70494_Content_8 = {
    Text = "Sei tu lo sviluppatore di Silver Communication?"
  },
  AvgCommunicate_70494_Content_9 = {
    Text = "Le vecchie storie possono essere discusse con calma quando avremo tempo."
  },
  AvgCommunicate_70494_Option_13 = {
    Text = "Cosa intendi fare esattamente?"
  },
  AvgCommunicate_70494_Option_16 = {
    Text = "A meno che non vi costituiate."
  },
  AvgCommunicate_70494_Option_2 = {
    Text = "Herbert Rosenthal..."
  },
  AvgCommunicate_70494_Option_5 = {
    Text = "Come sei riuscito a metterti in contatto con me?"
  },
  AvgCommunicate_70495_Content_1 = {
    Text = "I resti di Anderson sono stati distrutti dai membri de Gli scultori, rendendo impossibile ricomporre una figura umana completa."
  },
  AvgCommunicate_70495_Content_10 = {
    Text = "Forse, un giorno lo faremo..."
  },
  AvgCommunicate_70495_Content_11 = {
    Text = "Proverai terrore, Senior William?"
  },
  AvgCommunicate_70495_Content_12 = {Text = "..."},
  AvgCommunicate_70495_Content_13 = {
    Text = "Forse alcune persone riescono a guardare oltre la vita e la morte, ma non io."
  },
  AvgCommunicate_70495_Content_14 = {
    Text = "Ho paura in ogni istante, %player%."
  },
  AvgCommunicate_70495_Content_15 = {
    Text = "Ma non ho mai scorto alcuna traccia di terrore in te."
  },
  AvgCommunicate_70495_Content_16 = {
    Text = "Perché non ho tempo. Perché la Dissoluzione è proprio davanti a me."
  },
  AvgCommunicate_70495_Content_17 = {
    Text = "Molti sono periti, eppure io vivo ancora."
  },
  AvgCommunicate_70495_Content_18 = {
    Text = "Che si tratti di paura o di ricordo, un Investigatore di Mythag non ha il diritto di fermarsi per questo."
  },
  AvgCommunicate_70495_Content_19 = {Text = "..."},
  AvgCommunicate_70495_Content_2 = {
    Text = "Anche gli Argenti estratti con la forza sono stati quasi completamente distrutti."
  },
  AvgCommunicate_70495_Content_20 = {
    Text = "È arrivato un nuovo compito."
  },
  AvgCommunicate_70495_Content_21 = {
    Text = "Sopravviveremo, %player%. Fino al giorno in cui la Dissoluzione sarà risolta."
  },
  AvgCommunicate_70495_Content_3 = {
    Text = "Abbiamo perquisito il laboratorio nel ricovero e abbiamo trovato solo questo."
  },
  AvgCommunicate_70495_Content_4 = {
    Text = "Chiave d'argento, ID L-1463, appartenente all'Investigatore Anderson... un tempo apparteneva a lui."
  },
  AvgCommunicate_70495_Content_5 = {
    Text = "Cosa farà la scuola con questa Chiave d'argento...?"
  },
  AvgCommunicate_70495_Content_6 = {
    Text = "La riciclerà, la collocherà nella Pozza Nera per essere riforgiata, e poi la distribuirà ai nuovi Investigatori alla Cerimonia di Consegna delle Chiavi dell'anno successivo."
  },
  AvgCommunicate_70495_Content_7 = {
    Text = "Accompagnerà il nuovo Investigatore, dirigendosi costantemente verso i luoghi più pericolosi."
  },
  AvgCommunicate_70495_Content_8 = {
    Text = "Finché quell'Investigatore non si dimette o muore."
  },
  AvgCommunicate_70495_Content_9 = {
    Text = "Forse, un giorno lo faremo..."
  },
  AvgCommunicate_70495_Option_10 = {
    Text = "Proverai terrore?"
  },
  AvgCommunicate_70495_Option_15 = {
    Text = "Non ho mai provato il tuo terrore."
  },
  AvgCommunicate_70495_Option_5 = {
    Text = "Cosa farà la scuola con questa Chiave d'argento...?"
  },
  AvgCommunicate_70495_Option_9 = {
    Text = "Finiremo come Anderson?"
  },
  AvgCommunicate_70496_Content_1 = {
    Text = "Il rito di questi Aram... è davvero sconvolgente."
  },
  AvgCommunicate_70496_Content_10 = {
    Text = "Sono forse quel tipo di persona?"
  },
  AvgCommunicate_70496_Content_11 = {
    Text = "Stavo solo chiedendo così, perché sei così in tensione?"
  },
  AvgCommunicate_70496_Content_12 = {
    Text = "Comportandoti così sarai un libro aperto al tavolo da gioco. La tua forza mentale ha bisogno di migliorare, {Male=Mr.,Female=Miss} Custode."
  },
  AvgCommunicate_70496_Content_13 = {
    Text = "In breve, i Segreti di questo deserto sono probabilmente ben più complessi di quanto avessimo previsto."
  },
  AvgCommunicate_70496_Content_14 = {
    Text = "L'Indagine che seguirà richiede estrema cautela."
  },
  AvgCommunicate_70496_Content_2 = {
    Text = "Pensavo avresti accettato l'invito di quella Donna Aram."
  },
  AvgCommunicate_70496_Content_3 = {Text = "..."},
  AvgCommunicate_70496_Content_4 = {
    Text = "Che immagine ho davvero nel tuo cuore..."
  },
  AvgCommunicate_70496_Content_5 = {
    Text = "Non avrei mai immaginato che persino Ryker, solitamente così affascinante, avesse cose che non riesce ad accettare."
  },
  AvgCommunicate_70496_Content_6 = {
    Text = "Non ci sono storie di fiori e vino, solo i Desideri più primitivi e selvaggi."
  },
  AvgCommunicate_70496_Content_7 = {
    Text = "Questo genere di rito non è davvero di mio gradimento."
  },
  AvgCommunicate_70496_Content_8 = {
    Text = "A proposito, non hai accettato qualche strano invito, vero?"
  },
  AvgCommunicate_70496_Content_9 = {
    Text = "C-certo che no... come potrei mai!"
  },
  AvgCommunicate_70496_Option_2 = {
    Text = "Pensavo avresti accettato l'invito di quella donna Aram."
  },
  AvgCommunicate_70496_Option_5 = {
    Text = "Non mi aspettavo che ci fossero cose inaccettabili anche per te."
  },
  AvgCommunicate_70496_Option_9 = {
    Text = "C-certo che no... come potrei mai!"
  },
  AvgCommunicate_70497_Content_1 = {
    Text = "Salve, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgCommunicate_70497_Content_2 = {
    Text = "Ti sei divertito a giocare con i giocattoli di Juliette?"
  },
  AvgCommunicate_70497_Content_3 = {
    Text = "Sei tu... la talpa?!"
  },
  AvgCommunicate_70497_Content_4 = {
    Text = "Pensavo che avresti capito chi sono prima. Che peccato."
  },
  AvgCommunicate_70497_Content_5 = {
    Text = "Ma non importa; dopotutto, non è che l'ultimo gioco."
  },
  AvgCommunicate_70497_Content_6 = {
    Text = "Ora, il gioco sta per volgere alla Fine."
  },
  AvgCommunicate_70497_Content_7 = {
    Text = "Prima che la Distruzione predestinata giunga, c'è una sola cosa che mi incuriosisce."
  },
  AvgCommunicate_70497_Content_8 = {
    Text = "Potrà la verità eterna del Caos—l'audace Custode di cui parliamo senza vergogna, il coraggioso Salvatore di Mythag—affrontarla davvero con coraggio?"
  },
  AvgCommunicate_70497_Option_3 = {
    Text = "Sei tu... la talpa?!"
  },
  AvgCommunicate_70498_Content_1 = {
    Text = "Non sono un Mercante sciocco, ma a ben pensarci, sembra che abbia concluso un pessimo affare..."
  },
  AvgCommunicate_70498_Content_10 = {
    Text = "Diffidare sempre delle menzogne è una qualità fondamentale di una donna d'affari qualificata."
  },
  AvgCommunicate_70498_Content_11 = {
    Text = "Quindi... quello è davvero il vero volto di Lady Daffodil?"
  },
  AvgCommunicate_70498_Content_12 = {
    Text = "Non esiste costo più caro della realtà, piccolo {Male=Mr.,Female=Miss} Custode."
  },
  AvgCommunicate_70498_Content_13 = {
    Text = "Grazie, Lady Daffodil."
  },
  AvgCommunicate_70498_Content_14 = {
    Text = "Quello che ho appena detto era uno scherzo. So cosa significhi per qualcuno come te rivelare il proprio vero sé."
  },
  AvgCommunicate_70498_Content_15 = {
    Text = "Questo è un dono prezioso, e ne avrò gran cura."
  },
  AvgCommunicate_70498_Content_16 = {
    Text = "Non pensare di potermi liquidare con poche parole, piccolo."
  },
  AvgCommunicate_70498_Content_17 = {
    Text = "In cambio, non dovresti farmi anche tu un dono?"
  },
  AvgCommunicate_70498_Content_18 = {
    Text = "Sono forse stato smascherato...?"
  },
  AvgCommunicate_70498_Content_19 = {
    Text = "Lady Daffodil, cosa desiderate?"
  },
  AvgCommunicate_70498_Content_2 = {Text = "?"},
  AvgCommunicate_70498_Content_20 = {
    Text = "Dato che hai già visto la mia vera forma, quando sarai pronto a mostrarmi il tuo vero sé?"
  },
  AvgCommunicate_70498_Content_21 = {
    Text = "Il mio vero sé? Cosa significa... Non capisco bene, Lady Daffodil."
  },
  AvgCommunicate_70498_Content_22 = {
    Text = "A quanto pare Mythag non ti ha ancora detto nulla..."
  },
  AvgCommunicate_70498_Content_23 = {
    Text = "Il momento non è ancora giunto. Non temere."
  },
  AvgCommunicate_70498_Content_24 = {
    Text = "Ricorda il nostro patto di oggi, piccolo."
  },
  AvgCommunicate_70498_Content_25 = {
    Text = "Non vedo l'ora che arrivi il giorno in cui rivelerai la tua vera forma."
  },
  AvgCommunicate_70498_Content_3 = {
    Text = "Non hai forse già ottenuto la testa che desideravi?"
  },
  AvgCommunicate_70498_Content_4 = {
    Text = "Quel vibrante mare di materia grigia è divenuto un altro pezzo prezioso nella tua collezione."
  },
  AvgCommunicate_70498_Content_5 = {
    Text = "In effetti, era una bella testa; questo scambio non può essere considerato una perdita totale."
  },
  AvgCommunicate_70498_Content_6 = {
    Text = "Tuttavia, il prezzo che ho pagato è ancora un po' troppo alto."
  },
  AvgCommunicate_70498_Content_7 = {
    Text = "Mi hai concesso solo un'occhiata alla tua vera forma..."
  },
  AvgCommunicate_70498_Content_8 = {
    Text = "E se quello sia davvero il tuo aspetto, è difficile dirlo."
  },
  AvgCommunicate_70498_Content_9 = {
    Text = "Heh heh... Niente male, piccolo."
  },
  AvgCommunicate_70498_Option_11 = {
    Text = "Quindi... quello è davvero il vero volto di Lady Daffodil?"
  },
  AvgCommunicate_70498_Option_13 = {
    Text = "Grazie, Lady Daffodil."
  },
  AvgCommunicate_70498_Option_18 = {
    Text = "Sono forse stato smascherato...?"
  },
  AvgCommunicate_70498_Option_2 = {
    Text = "Non hai già ottenuto la testa?"
  },
  AvgCommunicate_70498_Option_21 = {
    Text = "Il mio vero io? Cosa significa..."
  },
  AvgCommunicate_70498_Option_7 = {
    Text = "Ho appena intravisto la tua vera forma..."
  },
  AvgCommunicate_70499_Content_1 = {
    Text = "Eliminando i dissidenti, si è liberata dai vincoli di Longbel e del Contratto. Senza questi ostacoli, in poche settimane è diventata la cacciatrice più feroce nel mondo degli affari di Londinium."
  },
  AvgCommunicate_70499_Content_10 = {
    Text = "Non si preoccupi, Professor Dexter. La prossima volta non le faremo fare cose così pericolose... Voglio dire, cercheremo di non farlo."
  },
  AvgCommunicate_70499_Content_11 = {
    Text = "L'esistenza celata nella coscienza di Sorel sembra chiamarsi \"N\". Sa qualcosa di lui?"
  },
  AvgCommunicate_70499_Content_12 = {
    Text = "Non molto. Sembra o un impostore o un folle, molto probabilmente entrambe le cose."
  },
  AvgCommunicate_70499_Content_13 = {
    Text = "Ma per quanto abominevole, almeno quel tipo ha gusto. Lo si capisce dal suo canto."
  },
  AvgCommunicate_70499_Content_14 = {
    Text = "La prossima volta che se ne presenterà l'occasione, dovremo conoscerci meglio. Magari potremmo persino condividere un bicchiere o due."
  },
  AvgCommunicate_70499_Content_15 = {
    Text = "...Ovviamente, in un ambiente sicuro. Le mie vecchie ossa non possono più sopportare alcuno spavento."
  },
  AvgCommunicate_70499_Content_2 = {
    Text = "Credo che non passerà molto prima che l'intera terra di Londinium porti il suo cognome."
  },
  AvgCommunicate_70499_Content_3 = {
    Text = "Lady Sorel, che persona affascinante. Per fortuna, Mythag è dalla sua parte."
  },
  AvgCommunicate_70499_Content_4 = {
    Text = "Devo questa faccenda al vostro aiuto, Professor Dexter."
  },
  AvgCommunicate_70499_Content_5 = {
    Text = "Grazie per aver aiutato a stanare il sospetto; altrimenti ci sarebbe voluto molto più tempo per risolvere questa faccenda."
  },
  AvgCommunicate_70499_Content_6 = {
    Text = "Sto semplicemente adempiendo ai doveri di un gentiluomo."
  },
  AvgCommunicate_70499_Content_7 = {
    Text = "È stata una proposta avanzata da Ramona. Come padre, come avrei potuto rifiutare?"
  },
  AvgCommunicate_70499_Content_8 = {
    Text = "Tuttavia, se dovesse accadere di nuovo qualcosa del genere, spero che possiate agire un po' più in fretta."
  },
  AvgCommunicate_70499_Content_9 = {
    Text = "Non aspettate che il coltello di quel tizio sia a soli cinque centimetri dal mio collo per intervenire; è davvero spaventoso."
  },
  AvgCommunicate_70499_Option_10 = {
    Text = "Non ci sarà una prossima volta... Farò del mio meglio."
  },
  AvgCommunicate_70499_Option_11 = {
    Text = "Sai qualcosa riguardo \"N\"?"
  },
  AvgCommunicate_70499_Option_4 = {
    Text = "Grazie per aver aiutato ad attirare fuori il sospetto."
  },
  AvgCommunicate_70500_Content_1 = {
    Text = "La conversazione al caffè è stata piuttosto piacevole, {Male=Mr.,Female=Miss} Custode."
  },
  AvgCommunicate_70500_Content_10 = {
    Text = "Se questa situazione si ripresentasse, e dovessi sparare alla vera me per far uscire tutti gli altri, lo faresti?"
  },
  AvgCommunicate_70500_Content_11 = {
    Text = "Hmm... naturalmente."
  },
  AvgCommunicate_70500_Content_12 = {
    Text = "Stai tranquillo/a, {Male=Mr.,Female=Miss} Custode. La fortuna continuerà a sorridermi."
  },
  AvgCommunicate_70500_Content_13 = {
    Text = "In quel momento, la mia pistola sarebbe sicuramente senza proiettili."
  },
  AvgCommunicate_70500_Content_14 = {Text = "70% no."},
  AvgCommunicate_70500_Content_2 = {
    Text = "È stato un onore assistere alla nascita di un giocatore d'azzardo."
  },
  AvgCommunicate_70500_Content_3 = {
    Text = "La mia parte preferita è quando il giocatore ha perso tutto e gli è stata rubata l'anima."
  },
  AvgCommunicate_70500_Content_4 = {
    Text = "Ah... ci sono vittorie e sconfitte; questa è la vita."
  },
  AvgCommunicate_70500_Content_5 = {
    Text = "Vedi? Questa volta abbiamo già recuperato una mano."
  },
  AvgCommunicate_70500_Content_6 = {
    Text = "Quindi, anche quel colpo che mi hai sparato era una scommessa?"
  },
  AvgCommunicate_70500_Content_7 = {
    Text = "Com'è possibile? Ero sicura al 70% del mio giudizio."
  },
  AvgCommunicate_70500_Content_8 = {
    Text = "E il restante 30%?"
  },
  AvgCommunicate_70500_Content_9 = {
    Text = "Non c'è nessun restante 30%. Il 70% è il 100%."
  },
  AvgCommunicate_70500_Option_2 = {
    Text = "È stato un onore assistere alla nascita di un giocatore d'azzardo."
  },
  AvgCommunicate_70500_Option_6 = {
    Text = "Quindi, anche quello sparo che mi hai rivolto era una scommessa?"
  },
  AvgCommunicate_70500_Option_8 = {
    Text = "E il restante 30%?"
  },
  AvgCommunicate_70501_Content_1 = {
    Text = "Ti piace quello che vedi?"
  },
  AvgCommunicate_70501_Content_10 = {
    Text = "Ma... la storia raccontata da quella serie di sculture è fin troppo crudele."
  },
  AvgCommunicate_70501_Content_11 = {
    Text = "L'hai capito, Custode..."
  },
  AvgCommunicate_70501_Content_12 = {
    Text = "Ogni creazione è crudele."
  },
  AvgCommunicate_70501_Content_13 = {
    Text = "È proprio attraverso questa crudeltà che l'arte immobile ottiene una vita vibrante."
  },
  AvgCommunicate_70501_Content_14 = {
    Text = "Se fossi al tuo posto, credo che troverei il processo di una tale creazione incredibilmente arduo..."
  },
  AvgCommunicate_70501_Content_15 = {
    Text = "Ma tu sei diversa, Sanga. Comprendo la tua scelta."
  },
  AvgCommunicate_70501_Content_16 = {
    Text = "Un'opera come \"Morte della Sig.ra Coral\" è il significato che persegui."
  },
  AvgCommunicate_70501_Content_17 = {
    Text = "Non vedo l'ora di vedere quella \"crudeltà\" sbocciare ancora una volta nelle linee che scolpisci."
  },
  AvgCommunicate_70501_Content_18 = {Text = "..."},
  AvgCommunicate_70501_Content_19 = {
    Text = "Pensavo che saresti stato come quei filistei e mi avresti suggerito di rendere la mia arte più \"normale\"."
  },
  AvgCommunicate_70501_Content_2 = {
    Text = "Cosa... la tua faccia?"
  },
  AvgCommunicate_70501_Content_20 = {
    Text = "Queste parole significano molto per me... Grazie, {Male=Mr.,Female=Miss} Custode."
  },
  AvgCommunicate_70501_Content_21 = {
    Text = "Come ricompensa, lascia che ti sveli un piccolo segreto: quando sei entrato in Morpheus, ero in piedi proprio accanto a te."
  },
  AvgCommunicate_70501_Content_22 = {
    Text = "Tutte quelle tue espressioni incustodite... le ho scolpite una per una. Fedelmente · al · vero."
  },
  AvgCommunicate_70501_Content_23 = {
    Text = "Quando hai tempo, vieni a visitare la mia piccola sala espositiva~"
  },
  AvgCommunicate_70501_Content_24 = {
    Text = "Sanga! Ti darò cinquanta Fang, quindi per favore butta via quelle Sculture..."
  },
  AvgCommunicate_70501_Content_25 = {
    Text = "Quella che hai definito arte vivida eppure \"crudele\". Non è così, Custode?"
  },
  AvgCommunicate_70501_Content_3 = {
    Text = "La scultura che hai visto nel Sogno, ovviamente."
  },
  AvgCommunicate_70501_Content_4 = {
    Text = "Le linee della carne sono naturalmente armoniose, eppure mancano dell'eterna bellezza della quiete, e sono prive di tema e visione creativa... difficilmente paragonabili alle opere scultoree."
  },
  AvgCommunicate_70501_Content_5 = {
    Text = "Pochissime persone hanno visto quella serie di sculture ormai. Vorrei conoscere il tuo giudizio..."
  },
  AvgCommunicate_70501_Content_6 = {
    Text = "Cosa... le tue sculture?"
  },
  AvgCommunicate_70501_Content_7 = {
    Text = "Naturalmente. Pochissime persone hanno visto quella serie di sculture finora. Mi piacerebbe conoscere il tuo giudizio..."
  },
  AvgCommunicate_70501_Content_8 = {
    Text = "Quella è la serie di sculture più bella che abbia mai visto."
  },
  AvgCommunicate_70501_Content_9 = {
    Text = "Sebbene le linee siano immobili, catturano un dinamismo e una vitalità che nemmeno gli esseri viventi possiedono."
  },
  AvgCommunicate_70501_Option_14 = {
    Text = "Comprendo la tua scelta"
  },
  AvgCommunicate_70501_Option_2 = {
    Text = "La tua faccia?"
  },
  AvgCommunicate_70501_Option_24 = {
    Text = "Non se ne parla!!!"
  },
  AvgCommunicate_70501_Option_6 = {
    Text = "Le tue sculture?"
  },
  AvgCommunicate_70501_Option_8 = {
    Text = "Belle... e crudeli."
  },
  AvgCommunicate_70502_Content_1 = {
    Text = "Che noia. Noia, noia!"
  },
  AvgCommunicate_70502_Content_10 = {
    Text = "Come mi hai ricordato molte volte, gli schiavi non sono ammessi a Londinium. Questa terra barbarica..."
  },
  AvgCommunicate_70502_Content_11 = {
    Text = "Non ho altra scelta che ascoltarti e comandarli a bacchetta dentro il labirinto."
  },
  AvgCommunicate_70502_Content_12 = {
    Text = "Il modo in cui combattono nell'arena è esattamente come lo ricordavo!"
  },
  AvgCommunicate_70502_Content_13 = {
    Text = "Quindi è a questo che serve il Labirinto..."
  },
  AvgCommunicate_70502_Content_14 = {
    Text = "Esatto, esatto! È davvero emozionante!"
  },
  AvgCommunicate_70502_Content_15 = {
    Text = "Andiamo, vieni a guardare! Questo è il massimo onore che posso concederti!"
  },
  AvgCommunicate_70502_Content_16 = {
    Text = "Certo, perché no? Imparare di più sulla storia non può che far bene..."
  },
  AvgCommunicate_70502_Content_17 = {
    Text = "A Uvhash probabilmente piacerebbe molto la tua arena. Perché non invitare anche lui?"
  },
  AvgCommunicate_70502_Content_18 = {
    Text = "No! Tieni quel demonio alla larga!!!"
  },
  AvgCommunicate_70502_Content_2 = {
    Text = "Bloccata in questo posto dimenticato da Dio ogni giorno, non ne posso più!"
  },
  AvgCommunicate_70502_Content_3 = {
    Text = "Ho ricostruito il mio Labirinto! Un'intera arena costruita secondo i miei ricordi!"
  },
  AvgCommunicate_70502_Content_4 = {
    Text = "Andiamo a divertirci insieme! Subito!"
  },
  AvgCommunicate_70502_Content_5 = {
    Text = "Riuscirai mai a chiedere invece di ordinare...?"
  },
  AvgCommunicate_70502_Content_6 = {
    Text = "Hmph, perché dovrei cambiare il mio modo di parlare?"
  },
  AvgCommunicate_70502_Content_7 = {
    Text = "Ho già fatto diecimila concessioni! Le uniche persone a cui posso dare ordini sono gli schiavi nel mio labirinto!"
  },
  AvgCommunicate_70502_Content_8 = {
    Text = "Quindi ora va tutto bene per te?"
  },
  AvgCommunicate_70502_Content_9 = {
    Text = "Certo. Di cosa dovrei avere paura?"
  },
  AvgCommunicate_70502_Option_16 = {
    Text = "Allora porterò anche Uvhash."
  },
  AvgCommunicate_70502_Option_5 = {
    Text = "Sarai mai capace di chiedere invece di ordinare...?"
  },
  AvgCommunicate_70502_Option_8 = {
    Text = "Quindi ora va tutto bene per te?"
  },
  AvgCommunicate_70503_Content_1 = {
    Text = "L'incidente avvenuto nella chiesa... Se non foste stato presente, altre persone innocenti sarebbero state ferite..."
  },
  AvgCommunicate_70503_Content_10 = {
    Text = "Ma ora è l'attuale capo della Chiesa della luce del tempio."
  },
  AvgCommunicate_70503_Content_11 = {
    Text = "Cosa?! La leader della Chiesa della luce del tempio?!!"
  },
  AvgCommunicate_70503_Content_12 = {
    Text = "Ma è il più grande nemico della vostra chiesa... Come ha potuto la vostra studentessa diventare..."
  },
  AvgCommunicate_70503_Content_13 = {
    Text = "Una lunga storia, Messaggero."
  },
  AvgCommunicate_70503_Content_14 = {
    Text = "Un tempo lavorava al mio fianco per la causa dell'Onnipotente, dedicando tutto ciò che avevamo al popolo dell'Onnipotente."
  },
  AvgCommunicate_70503_Content_15 = {
    Text = "Ma, come puoi vedere, non è così facile per chi si è smarrito allontanarsi dall'Onnipotente. Quelle atrocità e quei pregiudizi non possono essere dissipati con qualche Benedizione."
  },
  AvgCommunicate_70503_Content_16 = {
    Text = "A causa delle tribolazioni che ho sopportato, lei ha intrapreso un cammino divergente dal quale sarebbe stato difficile tornare indietro."
  },
  AvgCommunicate_70503_Content_17 = {
    Text = "Dunque è così..."
  },
  AvgCommunicate_70503_Content_18 = {
    Text = "Capisco. Proprio come accadde prima nella chiesa, coloro che non cambiarono grazie alle tue buone azioni fecero sì che lei cambiasse..."
  },
  AvgCommunicate_70503_Content_19 = {
    Text = "Il Padre Supremo ci ha insegnato che le questioni di questo mondo non sono sempre bianche o nere. Le buone azioni a volte possono anche essere un errore."
  },
  AvgCommunicate_70503_Content_2 = {
    Text = "A nome del Santuario della Vita e dei sopravvissuti innocenti, ti esprimo la mia più sincera gratitudine, Pallido Messaggero."
  },
  AvgCommunicate_70503_Content_20 = {
    Text = "Ho dedicato tutto alle vittime, ma ho dimenticato che anche la mia allieva era una vittima."
  },
  AvgCommunicate_70503_Content_21 = {
    Text = "La chiesa e la mia fede avranno forse salvato molte persone, ma non sono riuscite a salvare lei."
  },
  AvgCommunicate_70503_Content_22 = {
    Text = "Non sono stato un maestro all'altezza, Pallido Messaggero."
  },
  AvgCommunicate_70503_Content_23 = {
    Text = "Continuerò a percorrere il cammino del Padre Supremo. Ma mi chiedo se avrò mai la possibilità di rimediare a questo rimpianto riguardo a quell'allieva..."
  },
  AvgCommunicate_70503_Content_3 = {
    Text = "Non c'è di che, Vescovo Salvador. Rientra tutto nei miei doveri."
  },
  AvgCommunicate_70503_Content_4 = {
    Text = "Vescovo, riguardo al vostro passato, c'è una domanda che vorrei porvi..."
  },
  AvgCommunicate_70503_Content_5 = {
    Text = "Chiedi pure, Messaggero."
  },
  AvgCommunicate_70503_Content_6 = {
    Text = "Il mio passato sarà aperto a ogni persona sotto la protezione dell'Onnipotente."
  },
  AvgCommunicate_70503_Content_7 = {
    Text = "Quando mi sono collegato a voi, oltre a Sophia, ho visto una donna conversare con voi."
  },
  AvgCommunicate_70503_Content_8 = {
    Text = "Quel ricordo occupa gran parte del vostro Spirito... Vi conoscevate bene?"
  },
  AvgCommunicate_70503_Content_9 = {
    Text = "In effetti, molto bene. Fu un tempo la mia studentessa più brillante."
  },
  AvgCommunicate_70503_Option_11 = {
    Text = "La Chiesa della luce del tempio?!"
  },
  AvgCommunicate_70503_Option_17 = {
    Text = "Dunque è così..."
  },
  AvgCommunicate_70503_Option_3 = {
    Text = "È semplicemente il mio dovere."
  },
  AvgCommunicate_70503_Option_7 = {
    Text = "Chi è l'ultima donna apparsa nella vostra memoria?"
  },
  AvgCommunicate_70504_Content_1 = {
    Text = "Avete trascorso una notte piacevole, caro Ospite?"
  },
  AvgCommunicate_70504_Content_10 = {
    Text = "State tranquilli, ho raggiunto un accordo con un certo gentiluomo e non intraprenderò alcuna azione sconsiderata."
  },
  AvgCommunicate_70504_Content_11 = {
    Text = "L'integrità è molto importante per un mercante."
  },
  AvgCommunicate_70504_Content_12 = {
    Text = "Del resto, voi non avete meno segreti di me, non è vero?"
  },
  AvgCommunicate_70504_Content_13 = {
    Text = "Il mio segreto? A cosa ti riferisci?"
  },
  AvgCommunicate_70504_Content_14 = {
    Text = "Non è ancora il momento. Ma stai tranquillo/a, lo scambio riguardante il nuovo segreto avrà inizio presto."
  },
  AvgCommunicate_70504_Content_15 = {
    Text = "Il vento e la neve lungo la strada sono più feroci di quanto possiate immaginare."
  },
  AvgCommunicate_70504_Content_16 = {
    Text = "Finché c'è tempo, godetevi il calore del camino, piccola."
  },
  AvgCommunicate_70504_Content_2 = {
    Text = "Un negozietto così accogliente è raro in un giorno di neve. Grazie per la sua ospitalità, Lady Daffodil."
  },
  AvgCommunicate_70504_Content_3 = {
    Text = "Tuttavia, il suo negozio sembra celare molti segreti."
  },
  AvgCommunicate_70504_Content_4 = {
    Text = "Quegli oggetti da collezione probabilmente non sono così semplici come appaiono."
  },
  AvgCommunicate_70504_Content_5 = {
    Text = "Osservazione molto acuta. Tuttavia, ficcare il naso nei segreti altrui non è un comportamento da gentiluomo!"
  },
  AvgCommunicate_70504_Content_6 = {
    Text = "Mi dispiace, Lady Daffodil."
  },
  AvgCommunicate_70504_Content_7 = {
    Text = "Siamo venuti in questo luogo sconosciuto per un'indagine e dobbiamo prima di tutto garantire la nostra sicurezza."
  },
  AvgCommunicate_70504_Content_8 = {
    Text = "Spero che tu possa comprendere."
  },
  AvgCommunicate_70504_Content_9 = {
    Text = "Naturalmente. Se ci si potesse addormentare con noncuranza nella casa di uno sconosciuto, allora l'addestramento di Mythag per i Custodi è evidentemente inadeguato."
  },
  AvgCommunicate_70504_Option_13 = {
    Text = "Il mio segreto?"
  },
  AvgCommunicate_70504_Option_2 = {
    Text = "Sembra che qui si celino molti segreti."
  },
  AvgCommunicate_70504_Option_6 = {
    Text = "Mi dispiace, ma devo garantire la sicurezza dell'operazione."
  },
  AvgCommunicate_70505_Content_1 = {
    Text = "Miryam era la Somma Sacerdotessa di cui un tempo mi fidavo di più."
  },
  AvgCommunicate_70505_Content_10 = {
    Text = "Porto la responsabilità dei Navigatori."
  },
  AvgCommunicate_70505_Content_11 = {
    Text = "Nessuno avrebbe potuto prevedere come si sarebbero sviluppate le cose; non si può chiamare una colpa."
  },
  AvgCommunicate_70505_Content_12 = {
    Text = "Ciò che hai fatto era la scelta migliore in quel momento."
  },
  AvgCommunicate_70505_Content_13 = {
    Text = "Non è colpa tua, Tulu."
  },
  AvgCommunicate_70505_Content_14 = {
    Text = "Forse. Ma hai risolto personalmente questa faccenda."
  },
  AvgCommunicate_70505_Content_15 = {
    Text = "Nessuno avrebbe potuto prevedere il corso degli eventi."
  },
  AvgCommunicate_70505_Content_16 = {
    Text = "Anche se ci fossero stati errori, li hai corretti."
  },
  AvgCommunicate_70505_Content_17 = {
    Text = "Hai adempiuto al tuo dovere come Re di Lemuria, Tulu."
  },
  AvgCommunicate_70505_Content_18 = {Text = "..."},
  AvgCommunicate_70505_Content_19 = {
    Text = "Le tue parole di conforto sono un po' goffe, ma le accetto."
  },
  AvgCommunicate_70505_Content_2 = {
    Text = "Lei e io portammo un breve periodo di prosperità a Lemuria."
  },
  AvgCommunicate_70505_Content_20 = {
    Text = "Ora ho bisogno di riposare."
  },
  AvgCommunicate_70505_Content_21 = {
    Text = "Quando sarà il momento, mi risveglierò."
  },
  AvgCommunicate_70505_Content_22 = {
    Text = "Il mio dovere non risiede solo a Lemuria, ma anche nel Mythag."
  },
  AvgCommunicate_70505_Content_3 = {
    Text = "Lei e il popolo di Lemuria credevano tutti che avrei riportato Lemuria alla gloria del Regno divino."
  },
  AvgCommunicate_70505_Content_4 = {
    Text = "Ma... è una bugia, vero?"
  },
  AvgCommunicate_70505_Content_5 = {
    Text = "Nel sogno, ricevetti un'illuminazione."
  },
  AvgCommunicate_70505_Content_6 = {
    Text = "La fine di Lemuria è inevitabile."
  },
  AvgCommunicate_70505_Content_7 = {
    Text = "Fin dall'inizio, Lemuria ha vissuto nelle menzogne."
  },
  AvgCommunicate_70505_Content_8 = {
    Text = "Ho legato Lemuria e Miryam con una menzogna."
  },
  AvgCommunicate_70505_Content_9 = {
    Text = "Non avrei mai immaginato che questa menzogna avrebbe portato a tali conseguenze tanti anni dopo."
  },
  AvgCommunicate_70505_Option_11 = {
    Text = "Nessuno avrebbe potuto prevederlo; questo non dovrebbe essere chiamato un peccato."
  },
  AvgCommunicate_70505_Option_14 = {
    Text = "La questione è stata risolta con le tue stesse mani."
  },
  AvgCommunicate_70505_Option_4 = {
    Text = "Ma... è una bugia, vero?"
  },
  AvgCommunicate_70506_Content_1 = {
    Text = "La tua corda non è legata saldamente."
  },
  AvgCommunicate_70506_Content_10 = {
    Text = "E poi, uccidere è solo un mezzo, non il fine."
  },
  AvgCommunicate_70506_Content_11 = {
    Text = "Dovresti pensare di più ai fatti tuoi."
  },
  AvgCommunicate_70506_Content_12 = {
    Text = "Ciò che voglio fare non ti riguarda."
  },
  AvgCommunicate_70506_Content_13 = {
    Text = "Hai un asso nella manica."
  },
  AvgCommunicate_70506_Content_14 = {
    Text = "Quel mezzuomo... farà sicuramente impazzire Miryam, ah!"
  },
  AvgCommunicate_70506_Content_15 = {
    Text = "Fai del tuo meglio, Custode di Mythag."
  },
  AvgCommunicate_70506_Content_16 = {
    Text = "Sono molto curioso di vedere fino a che punto riuscirai a spingere la mia cara Alta Sacerdotessa."
  },
  AvgCommunicate_70506_Content_2 = {
    Text = "Stai attento. Non farti notare."
  },
  AvgCommunicate_70506_Content_3 = {
    Text = "Per ora mi sei ancora utile; non voglio che tu muoia troppo presto."
  },
  AvgCommunicate_70506_Content_4 = {
    Text = "Vuoi salvare Murphy?"
  },
  AvgCommunicate_70506_Content_5 = {
    Text = "Ti sembro forse una persona dal cuore gentile?"
  },
  AvgCommunicate_70506_Content_6 = {
    Text = "Dovresti pensare di più ai fatti tuoi."
  },
  AvgCommunicate_70506_Content_7 = {
    Text = "Ciò che voglio fare non ti riguarda."
  },
  AvgCommunicate_70506_Content_8 = {
    Text = "Vuoi uccidere Miryam?"
  },
  AvgCommunicate_70506_Content_9 = {
    Text = "Quella folle non è così facile da uccidere."
  },
  AvgCommunicate_70506_Option_4 = {
    Text = "Vuoi salvare Murphy?"
  },
  AvgCommunicate_70506_Option_8 = {
    Text = "Vuoi uccidere Miryam?"
  },
  AvgCommunicate_70507_Content_1 = {
    Text = "Io... mi sento un po' stanca..."
  },
  AvgCommunicate_70507_Content_10 = {
    Text = "Il dolore dentro di te... da questo momento in poi svanirà."
  },
  AvgCommunicate_70507_Content_11 = {
    Text = "Mythag sembra un posto così bello..."
  },
  AvgCommunicate_70507_Content_12 = {
    Text = "Sì, non voglio pensare. Non penserò più a niente."
  },
