  },
  AvgCommunicate_70509_Content_16 = {Text = "!!!"},
  AvgCommunicate_70509_Content_17 = {
    Text = "Avevo detto che l'avrei sconfitta."
  },
  AvgCommunicate_70509_Content_18 = {
    Text = "Una guerriera non viene mai meno alla parola data. Sei una vera guerriera, Helot!"
  },
  AvgCommunicate_70509_Content_19 = {
    Text = "Tornerò presto. Per favore, tieni pronta Lotan, {Male=Mr.,Female=Miss} Custode."
  },
  AvgCommunicate_70509_Content_2 = {Text = "Helot?!"},
  AvgCommunicate_70509_Content_20 = {
    Text = "Ho trovato la vera radice del potere di una guerriera. Ho trovato la mia convinzione."
  },
  AvgCommunicate_70509_Content_21 = {
    Text = "Ti sono grata per le parole che mi hai rivolto e per ciò che hai fatto per me."
  },
  AvgCommunicate_70509_Content_22 = {
    Text = "In cambio, le farò assistere al potere proveniente dalla Montagna di Neve."
  },
  AvgCommunicate_70509_Content_23 = {
    Text = "Il tuo modo di mostrare gratitudine è un po' strano... Ma Lotan, d'altra parte, dovrebbe esserne piuttosto contenta."
  },
  AvgCommunicate_70509_Content_24 = {
    Text = "In breve, bentornata, Helot!"
  },
  AvgCommunicate_70509_Content_3 = {
    Text = "Ho visto il ghiaccio e la neve di Elworth sciogliersi, con un dente di leone che spuntava dalla Montagna Innevata..."
