  AvgCommunicate_70510_Content_1 = {
    Text = "Salve, Custode."
  },
  AvgCommunicate_70510_Content_10 = {
    Text = "Raduna coloro che desideri proteggere e unisciti a noi…"
  },
  AvgCommunicate_70510_Content_11 = {
    Text = "Insieme, accogliamo la vera…"
  },
  AvgCommunicate_70510_Content_12 = {Text = "..."},
  AvgCommunicate_70510_Content_13 = {
    Text = "Erica? Stai bene?"
  },
  AvgCommunicate_70510_Content_14 = {Text = "Erica?!"},
  AvgCommunicate_70510_Content_15 = {Text = "..."},
  AvgCommunicate_70510_Content_16 = {
    Text = "Mi dispiace, Custode. Il dispositivo di soppressione psichica ha avuto un malfunzionamento poco fa."
  },
  AvgCommunicate_70510_Content_17 = {
    Text = "Quella personalità è sempre la stessa, completamente folle…"
  },
  AvgCommunicate_70510_Content_18 = {Text = "Stai bene?"},
  AvgCommunicate_70510_Content_19 = {
    Text = "Grazie per la tua preoccupazione, Custode."
  },
  AvgCommunicate_70510_Content_2 = {
    Text = "Erica? C'è un altro invito di prova oggi?"
  },
  AvgCommunicate_70510_Content_20 = {
    Text = "La Professoressa Doll ha installato dentro di me un dispositivo ausiliario di monitoraggio e auto-riparazione. Il malfunzionamento è stato risolto con successo."
  },
  AvgCommunicate_70510_Content_21 = {
    Text = "Sono felice di sapere che stai bene."
  },
  AvgCommunicate_70510_Content_22 = {
    Text = "La teoria dell'evoluzione meccanica di quella personalità è estrema e unilaterale."
  },
  AvgCommunicate_70510_Content_23 = {
    Text = "In un certo senso, potrebbe essere considerata una sorta di fede maligna."
  },
  AvgCommunicate_70510_Content_24 = {
    Text = "La teoria dell'evoluzione meccanica di quella personalità, sebbene alquanto estrema e unilaterale…"
  },
  AvgCommunicate_70510_Content_25 = {
    Text = "In un certo senso, è effettivamente un approccio che potrebbe contrastare la Dissoluzione."
  },
  AvgCommunicate_70510_Content_26 = {
    Text = "Tuttavia, comporterebbe anche numerose questioni tecniche ed etiche…"
  },
  AvgCommunicate_70510_Content_27 = {
    Text = "Non ci sono registrazioni pertinenti nel mio database, quindi non sono in grado di fornire pareri di riferimento efficaci."
  },
  AvgCommunicate_70510_Content_28 = {
    Text = "Se questo approccio sia praticabile, spetta a voi giudicarlo, Custode."
  },
  AvgCommunicate_70510_Content_3 = {
    Text = "Un invito di prova… Suppongo si possa chiamare così."
  },
  AvgCommunicate_70510_Content_4 = {
    Text = "Ma non è uno di quei banali piccoli esperimenti."
  },
  AvgCommunicate_70510_Content_5 = {
    Text = "È una grande invenzione che può davvero cambiare la nostra situazione."
  },
  AvgCommunicate_70510_Content_6 = {
    Text = "Hai combattuto la sostanza nera per tutto questo tempo, ma la soluzione è sempre stata davanti ai tuoi occhi."
  },
  AvgCommunicate_70510_Content_7 = {
    Text = "Di cosa stai parlando..."
  },
  AvgCommunicate_70510_Content_8 = {
    Text = "Sono i macchinari, Custode."
  },
  AvgCommunicate_70510_Content_9 = {
    Text = "Nei macchinari non vi è dolore né morte. Nei macchinari possiamo possedere una vita che trascende la carne!"
  },
  AvgCommunicate_70510_Option_13 = {
    Text = "Erica? Stai bene?"
  },
  AvgCommunicate_70510_Option_17 = {
    Text = "Tutto bene?"
  },
  AvgCommunicate_70510_Option_2 = {
    Text = "C'è un altro invito di prova oggi?"
  },
  AvgCommunicate_70510_Option_22 = {
    Text = "La sua teoria dell'evoluzione meccanica è, in un certo senso, una sorta di fede maligna."
  },
  AvgCommunicate_70510_Option_24 = {
