  AvgCommunicate_70510_Option_7 = {
    Text = "Di cosa stai parlando..."
  },
  AvgCommunicate_70511_Content_1 = {
    Text = "Mio signore… c'è qualcosa che vorrei chiedervi…"
  },
  AvgCommunicate_70511_Content_10 = {
    Text = "Se sia la Principessa che io fossimo in pericolo allo stesso tempo, chi salveresti per primo?"
  },
  AvgCommunicate_70511_Content_11 = {
    Text = "Mio... mio signore... questo... Io..."
  },
  AvgCommunicate_70511_Content_12 = {
    Text = "Va bene, va bene... È colpa mia. Non avrei dovuto stuzzicarti così."
  },
  AvgCommunicate_70511_Content_13 = {
    Text = "Lo so, sei un Cavaliere devoto al dovere. Non importa quale pericolo tu debba affrontare, onorerai sempre Un Giuramento."
  },
  AvgCommunicate_70511_Content_14 = {
    Text = "Questa Esperienza nel Sogno mi ha aiutato a capirti ancora meglio."
  },
  AvgCommunicate_70511_Content_15 = {
    Text = "Grazie... Grazie, mio signore..."
  },
  AvgCommunicate_70511_Content_16 = {
    Text = "Ora mi alleno ogni singolo giorno. Diventerò un Cavaliere qualificato, capace di proteggere il mio signore. Quello che è successo prima... non permetterò mai più che accada!"
  },
  AvgCommunicate_70511_Content_17 = {
    Text = "Quindi, mio signore... davvero non posso praticare equitazione a scuola..."
  },
  AvgCommunicate_70511_Content_18 = {Text = "No!"},
  AvgCommunicate_70511_Content_19 = {
    Text = "Tuttavia, c'è un maneggio appena aperto nel Distretto Ovest... Che ne dici se ti ci porto questo fine settimana per provare?"
  },
  AvgCommunicate_70511_Content_2 = {
    Text = "Ogier, sebbene le tue prestazioni abituali siano state piuttosto buone, le regole del Mythag stabiliscono che andare a cavallo non è consentito all'interno del campus, tanto meno esercitarsi in cariche…"
  },
  AvgCommunicate_70511_Content_20 = {Text = "!!!"},
  AvgCommunicate_70511_Content_21 = {
    Text = "Grazie, mio signore!!!"
  },
  AvgCommunicate_70511_Content_3 = {
    Text = "Vi sbagliate, mio signore! Quello che volevo chiedervi riguarda… la questione dei Sogni…"
  },
  AvgCommunicate_70511_Content_4 = {
    Text = "Riguarda quel \"Sogno\" che ho fatto?"
  },
  AvgCommunicate_70511_Content_5 = {
    Text = "Sì, mio signore!"
  },
  AvgCommunicate_70511_Content_6 = {
    Text = "Voglio sapere, cosa avete visto esattamente in quel Sogno?"
  },
  AvgCommunicate_70511_Content_7 = {
    Text = "Ho visto una catastrofe, una Principessa gentile e un piccolo Cavaliere coraggioso e Risoluto."
  },
  AvgCommunicate_70511_Content_8 = {
    Text = "Anch'io ho una domanda che vorrei farti."
  },
  AvgCommunicate_70511_Content_9 = {
    Text = "Mio signore, prego, proseguite."
  },
  AvgCommunicate_70511_Option_10 = {
    Text = "Tra me e quella Principessa, chi salveresti per primo?"
  },
  AvgCommunicate_70511_Option_13 = {
    Text = "Lo so, sei un Cavaliere devoto al dovere"
  },
  AvgCommunicate_70511_Option_18 = {Text = "No!"},
  AvgCommunicate_70511_Option_2 = {
    Text = "Riguardo al cavalcare nel campo?"
  },
  AvgCommunicate_70511_Option_4 = {
    Text = "Riguardo ai \"Sogni\"?"
  },
  AvgCommunicate_70512_Content_1 = {
    Text = "È passato molto tempo da quando ci siamo separati a Remouahe, {Male=Mr.,Female=Miss} Custode."
  },
  AvgCommunicate_70512_Content_10 = {
    Text = "La decomposizione che sgretola questo mondo è qualcosa che voi, gente viziata, non comprenderete mai."
  },
  AvgCommunicate_70512_Content_11 = {
    Text = "La Volontà suprema, il Creatore Originale, porterà la purificazione definitiva al mondo."
  },
  AvgCommunicate_70512_Content_12 = {
    Text = "Non ho Intenzione di prendere di mira i Mythag, ma i Mythag ostacolano il Sentiero verso l'Avvento del Nuovo Mondo."
  },
  AvgCommunicate_70512_Content_13 = {
    Text = "Stai tranquillo/a, {Male=Mr.,Female=Miss} Custode, il mio Signore non ti abbandonerà per questo."
  },
  AvgCommunicate_70512_Content_14 = {
    Text = "Anche tu diventerai un membro del nuovo mondo."
  },
  AvgCommunicate_70512_Content_15 = {
    Text = "Lui vi mostrerà quel futuro completamente nuovo."
  },
  AvgCommunicate_70512_Content_16 = {
    Text = "In quel momento, Egli ascolterà le vostre sincere confessioni."
  },
  AvgCommunicate_70512_Content_17 = {
    Text = "Puoi stare tranquilla anche tu, Juliette."
  },
  AvgCommunicate_70512_Content_18 = {
    Text = "Il tuo padrone non avrà la possibilità di arrivare."
  },
  AvgCommunicate_70512_Content_19 = {
    Text = "Ti fermerò. Senza alcun dubbio!"
  },
  AvgCommunicate_70512_Content_2 = {
    Text = "Juliette... cosa intendi fare esattamente irrompendo nel Mythag?!"
  },
  AvgCommunicate_70512_Content_3 = {
    Text = "A Remouahe, una volta ti ho parlato."
  },
  AvgCommunicate_70512_Content_4 = {
    Text = "Il nostro Dio creerà un futuro migliore per il mondo."
  },
  AvgCommunicate_70512_Content_5 = {
    Text = "Ricordi, Custode?"
  },
  AvgCommunicate_70512_Content_6 = {
    Text = "Naturalmente, non dimenticherò un'informazione così importante."
  },
  AvgCommunicate_70512_Content_7 = {
    Text = "Cosa c'entra questo con Mythag?"
  },
  AvgCommunicate_70512_Content_8 = {
    Text = "Non spreco il mio tempo a ricordare le tue parole manipolatorie."
  },
  AvgCommunicate_70512_Content_9 = {
    Text = "Ho visto molte persone irrimediabilmente ostinate, e non ne sono sorpreso."
  },
  AvgCommunicate_70512_Option_17 = {
    Text = "Ti fermerò."
  },
  AvgCommunicate_70512_Option_2 = {
    Text = "Cosa intendi fare?!"
  },
  AvgCommunicate_70512_Option_6 = {
    Text = "Me lo ricordo."
  },
  AvgCommunicate_70512_Option_8 = {
    Text = "Non perdo tempo a ricordare le tue parole manipolatorie."
  },
  AvgCommunicate_70513_Content_1 = {
    Text = "Riguardo al suono del flauto che hai sentito mentre eri privo di sensi, sono andato a indagare."
  },
  AvgCommunicate_70513_Content_10 = {
    Text = "Non so se lodare il tuo ottimismo o criticare la tua ignoranza."
  },
  AvgCommunicate_70513_Content_11 = {
    Text = "Ciò che Tawil menziona specificamente è di solito una catastrofe."
  },
  AvgCommunicate_70513_Content_12 = {
    Text = "Del peggior genere."
  },
  AvgCommunicate_70513_Content_13 = {
    Text = "Dato che è già successo... prendiamoci un momento per consolarci."
  },
  AvgCommunicate_70513_Content_14 = {
    Text = "In breve, continuerò a indagare sulla faccenda."
  },
  AvgCommunicate_70513_Content_15 = {
    Text = "Al momento non ha alcun effetto sostanziale su di te, quindi non c'è bisogno di preoccuparsene per ora."
  },
  AvgCommunicate_70513_Content_16 = {
    Text = "Prima occupiamoci del problema che abbiamo tra le mani."
  },
  AvgCommunicate_70513_Content_2 = {
    Text = "C'è qualche risultato?"
  },
  AvgCommunicate_70513_Content_3 = {
    Text = "Poco. Ma qualche scoperta c'è stata."
  },
  AvgCommunicate_70513_Content_4 = {
    Text = "È stata solo la mia immaginazione?"
  },
  AvgCommunicate_70513_Content_5 = {
    Text = "Si può affermare con certezza: no."
  },
  AvgCommunicate_70513_Content_6 = {
    Text = "Ho consultato il Professor Alistair."
  },
  AvgCommunicate_70513_Content_7 = {
    Text = "Sebbene al momento non esistano registrazioni di questo suono di flauto, Tawil gli ha menzionato qualcosa al riguardo."
  },
  AvgCommunicate_70513_Content_8 = {Text = "Tawil?!"},
  AvgCommunicate_70513_Content_9 = {
    Text = "Solo un sogno, e già coinvolge una figura di quel calibro..."
  },
  AvgCommunicate_70513_Option_13 = {
    Text = "Consideralo una forma di autoconsolazione."
  },
  AvgCommunicate_70513_Option_2 = {
    Text = "C'è qualche risultato?"
  },
  AvgCommunicate_70513_Option_4 = {
    Text = "È stata solo la mia immaginazione?"
  },
  AvgCommunicate_70513_Option_8 = {Text = "Tawil?!"},
  AvgCommunicate_70514_Content_1 = {
    Text = "{Male=Mr.,Female=Miss} Custode, l'editore mi ha inviato una lettera."
  },
  AvgCommunicate_70514_Content_10 = {
    Text = "È stata la sua protezione a permettermi di vagare spensierato nel mondo dei fiori e della poesia."
  },
  AvgCommunicate_70514_Content_11 = {
    Text = "Tutte quelle cose—la protezione e il dolore—appartengono ormai al passato..."
  },
  AvgCommunicate_70514_Content_12 = {
    Text = "{Male=Mr.,Female=Miss} Custode, grazie per avermi portato alla Cité questa volta... Questo viaggio è stato molto importante per me."
  },
  AvgCommunicate_70514_Content_13 = {
    Text = "Esatto. Tutto ciò che appartiene al tuo passato con Colette è ormai alle tue spalle."
  },
  AvgCommunicate_70514_Content_14 = {
    Text = "Guarda avanti, Horla."
  },
  AvgCommunicate_70514_Content_15 = {
    Text = "Va bene, {Male=Mr.,Female=Miss} Custode."
  },
  AvgCommunicate_70514_Content_16 = {
    Text = "Questa raccolta poetica è il mio addio al passato."
  },
  AvgCommunicate_70514_Content_17 = {
    Text = "Ricorderò Colette nella sua giovinezza. Ricorderò Colette nella sua vecchiaia. E ora, la lascerò andare..."
  },
  AvgCommunicate_70514_Content_18 = {
    Text = "C'è una nuova vita, e nuove poesie, che mi attendono."
  },
  AvgCommunicate_70514_Content_2 = {
    Text = "Si sono congratulati con me: questa raccolta ha ottenuto risultati eccellenti."
  },
  AvgCommunicate_70514_Content_3 = {
    Text = "Congratulazioni, Horla!"
  },
  AvgCommunicate_70514_Content_4 = {
    Text = "Grazie, Custode."
  },
  AvgCommunicate_70514_Content_5 = {
    Text = "In passato, era Colette a occuparsi di tutte queste faccende."
  },
  AvgCommunicate_70514_Content_6 = {
    Text = "Per tutto questo tempo, è stata lei a farsi carico di questa parte."
  },
  AvgCommunicate_70514_Content_7 = {
    Text = "Per quanto ne so, è la prima volta in assoluto che ti vedo mostrare interesse per le vendite."
  },
  AvgCommunicate_70514_Content_8 = {
    Text = "Perché l'autore di questa raccolta di poesie è l'Horla Corlet..."
  },
  AvgCommunicate_70514_Content_9 = {
