  AvgCommunicate_70517_Content_13 = {
    Text = "Perché il consiglio scolastico del Mythag ha rifiutato di vendermela."
  },
  AvgCommunicate_70517_Content_14 = {
    Text = "Sembra che tu abbia frainteso la mia domanda..."
  },
  AvgCommunicate_70517_Content_15 = {
    Text = "Non importa. Domani sera, sarò l'Ospite di un Banchetto nella sala."
  },
  AvgCommunicate_70517_Content_16 = {
    Text = "Un banchetto appassionato, originale e davvero vibrante, traboccante della vitalità della vita — proprio come quelli nel mio castello."
  },
  AvgCommunicate_70517_Content_17 = {
    Text = "I preparativi e gli accessori necessari sono ora completamente pronti."
  },
  AvgCommunicate_70517_Content_18 = {
    Text = "Ho già aggirato in anticipo gli ostacoli posti dalle regole. Nessuno ci disturberà."
  },
  AvgCommunicate_70517_Content_19 = {
    Text = "Confido che saprai trovare la strada, {Male=Mr.,Female=Miss} Custode?"
  },
  AvgCommunicate_70517_Content_2 = {
    Text = "Di cosa stai parlando..."
  },
  AvgCommunicate_70517_Content_3 = {
    Text = "Intendo dire che non organizziamo un vero banchetto da molto tempo."
  },
  AvgCommunicate_70517_Content_4 = {
    Text = "Non c'è stata una cena nella sala lo scorso fine settimana?"
  },
  AvgCommunicate_70517_Content_5 = {
    Text = "Un gruppo di individui in abiti eleganti seduti insieme, che mantengono una cortese distanza sociale, si comportano con garbo, eppure sempre attenti a Occultare i pensieri sordidi nei loro cuori..."
  },
  AvgCommunicate_70517_Content_6 = {
