  AvgCommunicate_70518_Content_15 = {
    Text = "Complottare contro Mythag proprio davanti a me... non è un po' inopportuno?"
  },
  AvgCommunicate_70518_Content_16 = {
    Text = "È cooperazione. Dopotutto, se i poteri del Navigatore e dei Perishita potessero essere sfruttati, la tua indagine procederebbe molto più agevolmente, non credi?"
  },
  AvgCommunicate_70518_Content_17 = {
    Text = "Sembra che... ci possa essere del vero in questo..."
  },
  AvgCommunicate_70518_Content_18 = {
    Text = "Molto bene, molto sveglio/a, Custode {Male=Mr.,Female=Miss}."
  },
  AvgCommunicate_70518_Content_19 = {
