  },
  AvgCommunicate_70522_Content_1 = {
    Text = "Diverse operazioni di consolidamento fondiario a Londinium procedono senza intoppi, e quei contratti problematici sono stati risolti."
  },
  AvgCommunicate_70522_Content_10 = {
    Text = "Come? Il {Male=Mr.,Female=Miss} Custode di Mythag, possibile che tu sia una persona che non mantiene la parola data?"
  },
  AvgCommunicate_70522_Content_11 = {
    Text = "Assolutamente no! È solo che..."
  },
  AvgCommunicate_70522_Content_12 = {
    Text = "Eh... Che infantile. Anche se non posso vederlo, scommetto che in questo momento il tuo viso è arrossato fino al collo mentre cerchi di inventare una scusa, vero?"
  },
  AvgCommunicate_70522_Content_13 = {
    Text = "Ecco la questione. L'oggetto che ho promesso di consegnare a Mythag deve essere recapitato da te. È una ragione sufficiente?"
  },
  AvgCommunicate_70522_Content_14 = {Text = "Ma..."},
  AvgCommunicate_70522_Content_15 = {
    Text = "Bene, niente più \"ma\"; è deciso."
  },
  AvgCommunicate_70522_Content_16 = {
    Text = "Va bene, te lo prometto... È un onore per me, Lady Sorel."
  },
  AvgCommunicate_70522_Content_17 = {
    Text = "Così va meglio."
  },
  AvgCommunicate_70522_Content_18 = {
    Text = "Tra di noi non c'è più bisogno di quelle formalità e di quei reciproci sondaggi."
  },
  AvgCommunicate_70522_Content_19 = {
    Text = "Stasera alle 8, nella cantina della mia tenuta. Nessuno ti fermerà."
  },
  AvgCommunicate_70522_Content_2 = {
    Text = "Tutto questo è merito del tuo aiuto, {Male=Mr.,Female=Miss} Custode."
  },
  AvgCommunicate_70522_Content_20 = {
    Text = "Ti aspetto, mio piccolo cavaliere."
  },
  AvgCommunicate_70522_Content_3 = {
    Text = "Quei tediosi salotti d'affari stanno finalmente giungendo al termine."
  },
  AvgCommunicate_70522_Content_4 = {
    Text = "Già che hai un po' di tempo libero, vieni a bere qualcosa con me?"
  },
  AvgCommunicate_70522_Content_5 = {
    Text = "Agli studenti del Mythag è proibito bere alcolici..."
  },
  AvgCommunicate_70522_Content_6 = {
    Text = "Davvero? Il Professor Dexter non me l'ha detto."
  },
  AvgCommunicate_70522_Content_7 = {
    Text = "Chi ha stabilito questa regola? Va cambiata."
  },
  AvgCommunicate_70522_Content_8 = {
    Text = "Ah, questo..."
  },
  AvgCommunicate_70522_Content_9 = {
    Text = "Mi devi ancora da bere. Ricordi?"
  },
  AvgCommunicate_70522_Option_11 = {
    Text = "Assolutamente no! È solo che..."
  },
  AvgCommunicate_70522_Option_16 = {
    Text = "È un onore per me, Lady Sorel."
  },
  AvgCommunicate_70522_Option_5 = {
    Text = "Agli studenti del Mythag è proibito bere alcolici..."
  },
  AvgCommunicate_70523_Content_1 = {
    Text = "Nella fretta, non ho avuto modo di presentarvi gli usi e la cultura Locale."
  },
  AvgCommunicate_70523_Content_10 = {
    Text = "Come ho già detto, non sono che un messaggero che proclama gli insegnamenti del mio Signore."
  },
  AvgCommunicate_70523_Content_11 = {
    Text = "Il nostro Dio creerà un futuro migliore per il mondo."
  },
  AvgCommunicate_70523_Content_12 = {
    Text = "Gruppi primitivi come gli Aram fanno anch'essi parte di questo futuro e restano i nostri amici più leali."
  },
  AvgCommunicate_70523_Content_13 = {
    Text = "Naturalmente, comprendo anche i dubbi del {Male=Mr.,Female=Miss} Custode."
  },
  AvgCommunicate_70523_Content_14 = {
    Text = "Credo che basterà trascorrere un po' più di tempo insieme perché questi dubbi svaniscano da soli."
  },
  AvgCommunicate_70523_Content_15 = {
    Text = "Avete percorso un lungo cammino; riposatevi bene."
  },
  AvgCommunicate_70523_Content_16 = {
    Text = "A nome di Remouahe, do il più sincero benvenuto al vostro arrivo, {Male=Mr.,Female=Miss} Custode."
  },
  AvgCommunicate_70523_Content_2 = {
    Text = "Mi chiedo se il {Male=Mr.,Female=Miss} Custode abbia qualche domanda per me."
  },
  AvgCommunicate_70523_Content_3 = {
    Text = "Sono un po' curioso riguardo alle usanze di questo luogo."
  },
  AvgCommunicate_70523_Content_4 = {
    Text = "Sebbene il popolo degli Aram viva di pastorizia da generazioni, lontano dalla società industriale, vi prego di non considerarli tribù barbare e incivili."
  },
  AvgCommunicate_70523_Content_5 = {
    Text = "Qui non ci sono Regole; sentitevi liberi di interagire con loro."
  },
  AvgCommunicate_70523_Content_6 = {
    Text = "Sono certo che tutti voi percepirete presto l'entusiasmo del popolo Aram."
  },
  AvgCommunicate_70523_Content_7 = {
    Text = "È piuttosto strano che qualcuno come te si trovi in una tribù del genere, non credi?"
  },
  AvgCommunicate_70523_Content_8 = {
    Text = "Rispondere al richiamo di un sogno per guidare gli Aram... come motivazione sembra alquanto forzata."
  },
  AvgCommunicate_70523_Content_9 = {
    Text = "{Male=Mr.,Female=Miss} Custode, la prego di non pensarci troppo."
