  AvgCommunicate_70526_Content_10 = {
    Text = "In breve, voglio vedere un mondo più vasto."
  },
  AvgCommunicate_70526_Content_11 = {
    Text = "Lotan mi ha sconfitto tre volte. Mi chiedo, cos'altro, oltre all'odio, possa conferire a qualcuno un potere così immenso."
  },
  AvgCommunicate_70526_Content_12 = {
    Text = "Dopo aver trovato la risposta, farò ritorno."
