  AvgCommunicate_70532_Content_1 = {Text = "Custode!"},
  AvgCommunicate_70532_Content_2 = {
    Text = "Quando andremo a filmare di nuovo!"
  },
  AvgCommunicate_70532_Content_3 = {
    Text = "Cosa, sei diventato dipendente dagli applausi?"
  },
  AvgCommunicate_70532_Content_4 = {
    Text = "Non è che ne sia dipendente; è che questa città ha bisogno di noi!"
  },
  AvgCommunicate_70532_Content_5 = {
    Text = "Questa città è piena di malvagità, ha bisogno del Ranger della Notte e del suo assitente!"
  },
  AvgCommunicate_70532_Content_6 = {
    Text = "Chiederò a Doll se posso prendere in prestito la cinepresa di nuovo."
  },
  AvgCommunicate_70532_Content_7 = {
    Text = "A proposito, hai frequentato le lezioni di alfabetizzazione come si deve? Quanti errori di ortografia hai fatto!"
  },
  AvgCommunicate_70532_Content_8 = {
    Text = "Fatti gli affari tuoi, West Welp!"
  },
  AvgCommunicate_70532_Content_9 = {
