  AvgCommunicate_70533_Content_1 = {
    Text = "Custode, Custode!"
  },
  AvgCommunicate_70533_Content_10 = {
    Text = "Ma perché non riesco a ricordarli?"
  },
  AvgCommunicate_70533_Content_11 = {
    Text = "Cucciolo, Pony, Piccola Medusa... Erano tutti amici di Aurita, un tempo."
  },
  AvgCommunicate_70533_Content_12 = {
    Text = "Ma un giorno, dovettero andare in un posto molto lontano."
  },
  AvgCommunicate_70533_Content_13 = {
    Text = "Avevano paura che Aurita sarebbe stata triste, così portarono via i ricordi che Aurita aveva di loro."
  },
  AvgCommunicate_70533_Content_14 = {
    Text = "Eppure desideravano ancora restare al fianco di Aurita, così lasciarono i loro corpi."
  },
  AvgCommunicate_70533_Content_15 = {
    Text = "Questi corpi si trasformarono in piccole bambole d'argilla e furono lasciati nel Palazzo d'Acqua di Aurita."
  },
  AvgCommunicate_70533_Content_16 = {
    Text = "...Si sono sempre presi cura di te e ti hanno accompagnata. Questo non è mai cambiato."
  },
  AvgCommunicate_70533_Content_17 = {
    Text = "Credo di capire... ma allo stesso tempo, forse no..."
  },
  AvgCommunicate_70533_Content_18 = {
    Text = "Ma Aurita lo sa! Le cose nel Palazzo d'Acqua sono tutte buone amiche di Aurita."
  },
  AvgCommunicate_70533_Content_19 = {
    Text = "Quindi Aurita se ne prenderà cura e giocherà con loro ogni giorno!"
  },
  AvgCommunicate_70533_Content_2 = {
    Text = "Sai cosa c'è dentro il Palazzo d'Acqua di Aurita?"
  },
  AvgCommunicate_70533_Content_3 = {
    Text = "Aurita, cosa pensi che siano?"
  },
  AvgCommunicate_70533_Content_4 = {
    Text = "Umm... Aurita non riesce a ricordare..."
  },
  AvgCommunicate_70533_Content_5 = {
    Text = "Sembra familiare, come... come..."
  },
  AvgCommunicate_70533_Content_6 = {Text = "Amici..."},
  AvgCommunicate_70533_Content_7 = {
    Text = "Aurita adora gli amici più di tutto! Ma perché Aurita non riesce a ricordarli?"
  },
  AvgCommunicate_70533_Content_8 = {
    Text = "Sono tutti amici di Aurita."
  },
  AvgCommunicate_70533_Content_9 = {
    Text = "Amici? Adoro gli amici!"
  },
  AvgCommunicate_70533_Option_11 = {
    Text = "Racconta ad Aurita la sua storia."
  },
  AvgCommunicate_70533_Option_3 = {
    Text = "Beh, tu cosa ne pensi?"
  },
  AvgCommunicate_70533_Option_8 = {
    Text = "Sono tutti amici di Aurita."
  },
  AvgCommunicate_72037_Content_1 = {
    Text = "Ieri, Questa qui ha sognato l'infanzia... molti volti dal passato di Lemuria."
  },
  AvgCommunicate_72037_Content_10 = {
    Text = "Nulla sfugge alla tua attenzione."
  },
  AvgCommunicate_72037_Content_11 = {
    Text = "Ciò che aleggiava nel sogno era una sensazione eccezionalmente calda e familiare. Inizialmente pensavo fosse portata da Noah."
  },
  AvgCommunicate_72037_Content_12 = {
    Text = "In seguito, mi resi conto che nel corso dei lunghi anni, la cosa a me più familiare non era più una persona, ma un oggetto freddo e privo di vita."
  },
  AvgCommunicate_72037_Content_13 = {Text = "Tulu..."},
  AvgCommunicate_72037_Content_14 = {
    Text = "Metti via la tua compassione. Dal momento in cui ho indossato la corona, tutto era già deciso."
  },
  AvgCommunicate_72037_Content_15 = {
    Text = "Il Re di Lemuria non ha bisogno che qualcuno versi lacrime per lui."
  },
  AvgCommunicate_72037_Content_16 = {
    Text = "Quindi... Grande Re di Lemuria, ti interesserebbe assaggiare di nuovo quelle caramelle di riso? Credo che lo chef di Mythag dovrebbe essere in grado di ricrearle in una certa misura."
  },
  AvgCommunicate_72037_Content_17 = {Text = "..."},
  AvgCommunicate_72037_Content_18 = {
    Text = "Hmph. È premuroso da parte tua."
  },
  AvgCommunicate_72037_Content_19 = {
    Text = "Molto bene, allora. Lo accetterò come tua offerta."
  },
  AvgCommunicate_72037_Content_2 = {
    Text = "Sono ricordi di cui non ho mai amato parlare, ma... nel sogno di ieri, tu eri lì, non è vero?"
  },
  AvgCommunicate_72037_Content_3 = {
    Text = "?! Come fai a saperlo?"
  },
  AvgCommunicate_72037_Content_4 = {
    Text = "Il tempo che ho trascorso nei sogni supera di gran lunga quello nel mondo ordinario. Stai mettendo in dubbio la percezione di qualcuno che vive in un sogno?"
  },
  AvgCommunicate_72037_Content_5 = {
    Text = "Oltre alle profezie, a volte faccio sogni come le persone comuni, ma nessuno di quei sogni è mai stato vivido e continuo come quello di ieri..."
  },
  AvgCommunicate_72037_Content_6 = {
    Text = "Era come se qualcuno fosse seduto accanto a me, a rivivere il passato fin dall'inizio."
  },
  AvgCommunicate_72037_Content_7 = {
    Text = "Questa sensazione di non essere sola... è piuttosto piacevole."
  },
  AvgCommunicate_72037_Content_8 = {
    Text = "In effetti sono sempre stata al tuo fianco."
  },
  AvgCommunicate_72037_Content_9 = {
    Text = "Lascia che indovini: devi aver posseduto la corona, giusto?"
  },
  AvgCommunicate_72037_Option_10 = {Text = "Sì"},
  AvgCommunicate_72037_Option_13 = {Text = "Tulu..."},
  AvgCommunicate_72037_Option_16 = {
    Text = "Allora... perché tu..."
  },
  AvgCommunicate_72037_Option_3 = {Text = "?!"},
  AvgCommunicate_72037_Option_8 = {
    Text = "In effetti sono sempre stata al tuo fianco."
  },
  AvgCommunicate_80100_Content_1 = {
    Text = "%player%, se non è un problema, potresti venire a fare un test psicologico?"
  },
  AvgCommunicate_80100_Content_10 = {
    Text = "Ramona, Lotan, Ogier... quando sono solo/a, le loro figure mi tornano sempre in mente."
  },
  AvgCommunicate_80100_Content_11 = {
    Text = "Ecco, non tenere tutti quei sentimenti dentro di te. Se ti senti turbato/a o confuso/a, puoi sempre parlarne con me."
  },
  AvgCommunicate_80100_Content_12 = {
    Text = "Ho persino preparato del tè caldo e degli spuntini per te, così possiamo chiacchierare quanto vuoi."
  },
  AvgCommunicate_80100_Content_13 = {
    Text = "...va bene, sto arrivando."
  },
  AvgCommunicate_80100_Content_2 = {
    Text = "…Un test psicologico?"
  },
  AvgCommunicate_80100_Content_3 = {
    Text = "È molto semplice. Devi solo disegnare una casa, un albero e una persona su un foglio bianco."
  },
  AvgCommunicate_80100_Content_4 = {
    Text = "Fidati, non ti porterà via troppo tempo."
  },
  AvgCommunicate_80100_Content_5 = {
    Text = "…Ma credo che la mia salute mentale sia perfettamente a posto."
  },
  AvgCommunicate_80100_Content_6 = {
    Text = "Lo scopo ultimo del test non è giudicare la salute, ma osservare potenziali problemi psicologici."
  },
  AvgCommunicate_80100_Content_7 = {
    Text = "%player%, da quando sei arrivato/a qui, ti senti solo/a? Ti mancano gli amici di quel mondo?"
  },
  AvgCommunicate_80100_Content_8 = {
    Text = "Questa solitudine e questo isolamento verranno sepolti nel profondo del tuo cuore, fermentando col tempo e producendo effetti imprevedibili."
  },
  AvgCommunicate_80100_Content_9 = {
    Text = "Suppongo che mi manchino davvero..."
  },
  AvgCommunicate_80100_Option_13 = {
    Text = "...va bene, sto arrivando."
  },
  AvgCommunicate_80100_Option_2 = {
    Text = "…Un test psicologico?"
  },
  AvgCommunicate_80100_Option_5 = {
    Text = "…Ma credo che la mia salute mentale sia perfettamente a posto."
  },
  AvgCommunicate_80100_Option_9 = {Text = "..."},
  AvgCommunicate_80101_Content_1 = {
    Text = "Ho sentito che ultimamente sei giù di morale. Se non ti dispiace, puoi venire da me per un consulto."
  },
  AvgCommunicate_80101_Content_10 = {
    Text = "Ah~, il solo descriverli fa tremare senza sosta il mio cuore d'argento..."
  },
  AvgCommunicate_80101_Content_11 = {
    Text = "%player%, non vedo l'ora di addentrarmi nel tuo cuore e assaporare le tue memorie."
  },
  AvgCommunicate_80101_Content_12 = {
    Text = "Allora rimarrai deluso, dato che me ne sono già andato."
  },
  AvgCommunicate_80101_Content_13 = {
    Text = "Lo so. Una delle mie pazienti me lo ha già comunicato."
  },
  AvgCommunicate_80101_Content_14 = {
    Text = "È stata persino così premurosa da inviarmi la tua posizione, quindi..."
  },
  AvgCommunicate_80101_Content_15 = {
    Text = "Sarò lì a breve."
  },
  AvgCommunicate_80101_Content_2 = {
    Text = "Non c'è bisogno di fare il duro, Custode. Un professionista può aiutarti ad alleviare lo stress più rapidamente."
  },
  AvgCommunicate_80101_Content_3 = {
    Text = "Come facevi a saperlo...?"
  },
  AvgCommunicate_80101_Content_4 = {Text = "Segreto~"},
  AvgCommunicate_80101_Content_5 = {
    Text = "Allora, qual è la tua risposta?"
  },
  AvgCommunicate_80101_Content_6 = {
    Text = "Prometto che questa volta non farò nient'altro."
  },
  AvgCommunicate_80101_Content_7 = {
    Text = "Hai detto la stessa cosa l'ultima volta... e quella prima ancora..."
  },
  AvgCommunicate_80101_Content_8 = {
    Text = "Non è colpa mia; è piuttosto la tua coscienza, colma di ricordi così deliziosi..."
  },
  AvgCommunicate_80101_Content_9 = {
    Text = "Quei ricordi che superano di gran lunga il dolore sopportabile da una persona comune, pervasi dall'aura di quella grande esistenza, la dolcezza più suprema..."
  },
  AvgCommunicate_80101_Option_12 = {
    Text = "...Allora resterai deluso/a."
  },
  AvgCommunicate_80101_Option_3 = {
    Text = "Come facevi a saperlo...?"
  },
  AvgCommunicate_80101_Option_7 = {
    Text = "Hai detto la stessa cosa l'ultima volta... e quella prima ancora..."
  },
  AvgCommunicate_80102_Content_1 = {
    Text = "%player%, se non ti dispiace, potrei occuparmi delle tue esigenze psicologiche?"
  },
  AvgCommunicate_80102_Content_10 = {
    Text = "Ma non farò nulla di estremo. Fidati di me."
  },
  AvgCommunicate_80102_Content_11 = {
    Text = "...Davvero?"
  },
  AvgCommunicate_80102_Content_12 = {
    Text = "Certo. Dopotutto, sono solo una psicologa."
  },
  AvgCommunicate_80102_Content_2 = {
    Text = "Credo tu abbia bisogno di uno psichiatra personale."
  },
  AvgCommunicate_80102_Content_3 = {
    Text = "...Sento che non è necessario."
  },
  AvgCommunicate_80102_Content_4 = {
    Text = "No, in quanto unico Custode, la tua stessa esistenza merita di essere valorizzata."
  },
  AvgCommunicate_80102_Content_5 = {
    Text = "Desidero solo mettere le mie competenze professionali al tuo servizio."
  },
  AvgCommunicate_80102_Content_6 = {
    Text = "Davvero? Perché ho la sensazione che tu abbia secondi fini..."
  },
  AvgCommunicate_80102_Content_7 = {
    Text = "Per esempio, usare la scusa dello psicologo personale per sbirciare nei miei ricordi?"
  },
  AvgCommunicate_80102_Content_8 = {
    Text = "Oh cielo, era così ovvio? Beh, pazienza, non posso farci nulla."
  },
  AvgCommunicate_80102_Content_9 = {
    Text = "Sono davvero molto, molto interessata alle tue memorie, specialmente dopo che hai parlato di quel mondo."
  },
  AvgCommunicate_80102_Option_11 = {
    Text = "...Davvero?"
  },
  AvgCommunicate_80102_Option_3 = {
    Text = "...Sento che non è necessario."
  },
  AvgCommunicate_80102_Option_6 = {
    Text = "...Davvero?"
  },
  AvgCommunicate_80104_Content_1 = {
    Text = "Grazie per avermi inviato quel rapporto."
  },
  AvgCommunicate_80104_Content_10 = {
    Text = "Per quanto riguarda la possibilità di tornare in quel mondo, affidarsi unicamente al potere di Doll: Inferno e al mio chiaramente non è sufficiente."
  },
  AvgCommunicate_80104_Content_11 = {
    Text = "Quindi hai bisogno del mio potere...? Capisco."
  },
  AvgCommunicate_80104_Content_12 = {
    Text = "Accetterò questo dono. In cambio, ti offrirò una consulenza psicologica gratuita."
  },
  AvgCommunicate_80104_Content_13 = {
    Text = "%player%, quando hai del tempo libero?"
  },
  AvgCommunicate_80104_Content_14 = {
    Text = "Sia come medico che come amica, sento la responsabilità di comprendere a fondo il tuo io interiore."
  },
  AvgCommunicate_80104_Content_15 = {
    Text = "Sono in missione sul campo... segnale scarso... continueremo dopo..."
  },
  AvgCommunicate_80104_Content_16 = {Text = "%player%?"},
  AvgCommunicate_80104_Content_17 = {Text = "%player%?"},
  AvgCommunicate_80104_Content_18 = {
    Text = "Heh, so che sei ancora lì. Ma va bene, abbiamo ancora tutto il tempo che serve."
  },
  AvgCommunicate_80104_Content_2 = {
    Text = "Quella è una versione sintetica del mio rapporto sulle specie di insetti. Non contiene nulla di classificato, quindi sentiti libero di tenerla."
  },
  AvgCommunicate_80104_Content_3 = {
    Text = "Questa è la \"ricompensa\" pagata in anticipo?"
  },
  AvgCommunicate_80104_Content_4 = {
    Text = "Ma scusa, non ho informazioni riservate dal Comitato da condividere di recente."
  },
  AvgCommunicate_80104_Content_5 = {
    Text = "È un regalo, non una ricompensa."
  },
  AvgCommunicate_80104_Content_6 = {
    Text = "Congratulazioni per la tua Rinascita dalla Terra, e grazie per aver scelto me."
  },
  AvgCommunicate_80104_Content_7 = {
    Text = "Perché non mi oppongo a te come \"lei\" dall'altro mondo?"
  },
  AvgCommunicate_80104_Content_8 = {
    Text = "Puoi vederla in quel modo."
  },
  AvgCommunicate_80104_Content_9 = {
    Text = "In qualità di Custode, mi piacerebbe credere che i Risvegliatori e io siamo alleati, non nemici."
  },
  AvgCommunicate_80104_Option_15 = {
    Text = "...segnale in caduta..."
  },
  AvgCommunicate_80104_Option_2 = {
    Text = "Immagino tu abbia ricevuto la posta allora."
  },
  AvgCommunicate_80104_Option_5 = {
    Text = "No, questo è un regalo."
  },
  AvgCommunicate_80104_Option_8 = {
    Text = "Puoi vederla in quel modo."
  },
  AvgCommunicate_81323_Content_1 = {
    Text = "Benefattore, quando mi consegnerai un nuovo quaderno di esercizi?"
  },
  AvgCommunicate_81323_Content_10 = {
    Text = "Capisco. In tal caso, ci sono altri insegnanti che puoi raccomandarmi?"
  },
  AvgCommunicate_81323_Content_11 = {
    Text = "Se non ce ne sono, posso studiare da sola e fare del mio meglio."
  },
  AvgCommunicate_81323_Content_12 = {
    Text = "C'è, ma... non è esattamente la persona più stabile..."
  },
  AvgCommunicate_81323_Content_13 = {
    Text = "Non fa niente. Non ho paura."
  },
  AvgCommunicate_81323_Content_14 = {
    Text = "Sono io quella che ha paura! Beh, se andassi a cercare Winkle... mmm, probabilmente impazzirebbe per prima."
  },
  AvgCommunicate_81323_Content_15 = {
    Text = "Impazzire? Questa Maestra Winkle ha qualche tipo di malattia?"
  },
  AvgCommunicate_81323_Content_16 = {
    Text = "Beh no... beh, non posso dire che NON ce l'abbia, ma... Ah, lascia perdere! Prima lascia che ti insegni un principio fondamentale dell'apprendimento!"
  },
  AvgCommunicate_81323_Content_17 = {
    Text = "D'accordo, benefattore, sono tutt'orecchi."
  },
  AvgCommunicate_81323_Content_18 = {
    Text = "In poche parole... non mettere in discussione letteralmente ogni cosa!!!"
  },
  AvgCommunicate_81323_Content_19 = {
    Text = "Come sarebbe, benefattrice? Non capisco... se non faccio abbastanza domande, come posso davvero imparare una materia..?"
  },
  AvgCommunicate_81323_Content_2 = {
    Text = "Per quanto riguarda gli ultimi due libri, li ho letti approfonditamente e ho annotato un totale di 107 domande; spero che tu possa darmi qualche indicazione nel tuo tempo libero."
  },
  AvgCommunicate_81323_Content_20 = {
    Text = "Non sei stanca di tutto questo?! Con la tua determinazione, riusciresti sicuramente in qualsiasi cosa ti prefiggi di fare..."
  },
  AvgCommunicate_81323_Content_21 = {
    Text = "Grazie, benefattrice. Sono davvero fortunata ad avere l'opportunità di imparare cose che mi interessano."
  },
  AvgCommunicate_81323_Content_22 = {
    Text = "Stanca? Se sono stanca, mi riposo un po' e sto bene."
  },
  AvgCommunicate_81323_Content_23 = {
    Text = "Allora, quando puoi presentarmi la nuova insegnante? Cercherò di non fare troppe domande."
  },
  AvgCommunicate_81323_Content_24 = {
    Text = "Ehm... che ne dici se faccio solo 97 domande?"
  },
  AvgCommunicate_81323_Content_3 = {
    Text = "Mi dispiace."
  },
  AvgCommunicate_81323_Content_4 = {
    Text = "Mi dispiace davvero."
  },
  AvgCommunicate_81323_Content_6 = {
    Text = "Non avrei dovuto darti i miei compiti. Ognuno dovrebbe occuparsi delle proprie faccende..."
  },
  AvgCommunicate_81323_Content_7 = {
    Text = "Per favore, non chiedermi altro! Se continua così, avrò incubi ogni notte!!"
  },
  AvgCommunicate_81323_Content_8 = {
    Text = "Ah... mi dispiace. Non mi rendevo conto di causare tanti problemi al mio benefattore. Sono stata troppo disattenta."
  },
  AvgCommunicate_81323_Content_9 = {
    Text = "Non scusarti, non è colpa tua. Non credo di essere adatto a fare l'insegnante..."
  },
  AvgCommunicate_81323_Option_12 = {
    Text = "C'è, ma..."
  },
  AvgCommunicate_81323_Option_14 = {
    Text = "Sono io quella che ha paura!"
  },
  AvgCommunicate_81323_Option_16 = {
    Text = "Beh no... beh, non posso dire che NON ce l'abbia, ma..."
  },
  AvgCommunicate_81323_Option_18 = {
    Text = "In poche parole... non mettere in discussione letteralmente ogni cosa!!!"
  },
  AvgCommunicate_81323_Option_20 = {
    Text = "Non sei stanca di tutto questo?!"
  },
  AvgCommunicate_81323_Option_3 = {
    Text = "Mi dispiace."
  },
  AvgCommunicate_81323_Option_4 = {
    Text = "Mi dispiace davvero."
  },
  AvgCommunicate_81323_Option_9 = {
    Text = "Non scusarti, non è colpa tua. Non credo di essere adatto a fare l'insegnante..."
  },
  AvgCommunicate_81324_Content_1 = {
    Text = "Benefattrice, ho letto e ho nuove domande da fare."
  },
  AvgCommunicate_81324_Content_10 = {
    Text = "Quindi stai dicendo... che dipende da cosa stavi pensando mentre lo facevi?"
  },
  AvgCommunicate_81324_Content_11 = {
    Text = "Esatto! Pensaci. Quando ti ho chiesto di scrivere quei due compiti per te, ti stavo sfruttando come manodopera gratuita, o ti stavo dando l'opportunità di imparare qualcosa di nuovo?"
  },
  AvgCommunicate_81324_Content_12 = {Text = "Non lo so."},
  AvgCommunicate_81324_Content_13 = {
    Text = "Come sarebbe a dire che non lo sai?! Ovviamente l'ho fatto per insegnarti!"
  },
  AvgCommunicate_81324_Content_14 = {
    Text = "Ah, ecco com'è. A quanto pare avevo frainteso; pensavo volessi solo che ti aiutassi con i compiti."
  },
  AvgCommunicate_81324_Content_16 = {
    Text = "Ahaha... Beh, riflettiamoci. Quando compiamo un'azione con l'obiettivo di aiutare qualcuno, aiutarlo sinceramente, quella può essere considerata un'azione etica."
  },
  AvgCommunicate_81324_Content_17 = {
    Text = "Trattare qualcuno puramente come uno strumento, d'altra parte, sarebbe certamente non etico."
  },
  AvgCommunicate_81324_Content_18 = {
    Text = "Credo di capire ora. È come quando la Lanterna ha usato me e Pollux come strumenti per il sacrificio, senza considerare i nostri sentimenti. Quello che hanno fatto non era etico."
  },
  AvgCommunicate_81324_Content_19 = {
    Text = "Esatto, esatto! Hai capito perfettamente!"
  },
  AvgCommunicate_81324_Content_2 = {
    Text = "Hai detto prima che i compiti servono a verificare e perfezionare le proprie conoscenze. Se la materia è padroneggiata, non c'è bisogno di preoccuparsi di chi li fa davvero."
  },
  AvgCommunicate_81324_Content_20 = {
    Text = "Capisco, benefattore, sei davvero una persona etica! Allora, per favore dammi qualche altro compito. Li completerò diligentemente e tornerò a consultarti!"
  },
  AvgCommunicate_81324_Content_21 = {
    Text = "Benefattore?"
  },
  AvgCommunicate_81324_Content_22 = {
    Text = "Ehm, all'improvviso ho una cosa da fare... Per i compiti dovresti rivolgerti direttamente a Doll!"
  },
  AvgCommunicate_81324_Content_3 = {
    Text = "Ehm... potrei aver detto qualcosa del genere..."
  },
  AvgCommunicate_81324_Content_4 = {
    Text = "Ma i libri che ho letto affermano che far fare il proprio lavoro ad altri non è etico."
  },
  AvgCommunicate_81324_Content_6 = {
    Text = "Quindi come possiamo stabilire se questa questione è etica?"
  },
  AvgCommunicate_81324_Content_7 = {
    Text = "Eh... riguardo a questa questione, dovresti considerarla in modo dialettico."
  },
  AvgCommunicate_81324_Content_8 = {
    Text = "Non possiamo dire con certezza né sì né no."
  },
  AvgCommunicate_81324_Content_9 = {
    Text = "Quando si giudica qualcosa, non si può considerare solo il risultato. Bisogna anche considerare lo scopo dietro l'azione."
  },
  AvgCommunicate_81324_Option_11 = {
    Text = "Sì. Esatto!"
  },
  AvgCommunicate_81324_Option_13 = {
    Text = "Come sarebbe a dire che non lo sai?!"
  },
  AvgCommunicate_81324_Option_19 = {
    Text = "Esatto, esatto! Hai capito perfettamente!"
  },
  AvgCommunicate_81324_Option_22 = {
    Text = "Ehm, all'improvviso ho una cosa da fare..."
  },
  AvgCommunicate_81324_Option_3 = {
