  },
  AvgCommunicate_81324_Option_7 = {
    Text = "Eh... riguardo a questa questione, dovresti considerarla in modo dialettico."
  },
  AvgCommunicate_81324_Option_8 = {
    Text = "Non possiamo dire con certezza né sì né no."
  },
  AvgCommunicate_81325_Content_1 = {
    Text = "Che scatola magica, benefattore. Davvero non è alimentata da qualche tipo di magia o cerchio rituale?"
  },
  AvgCommunicate_81325_Content_10 = {
    Text = "Non esattamente... È solo che queste due discipline sono attualmente in continua evoluzione, e molti studiosi ampliano e approfondiscono queste ricerche, creando nuove conoscenze."
  },
  AvgCommunicate_81325_Content_11 = {
    Text = "Se scegli un campo così fiorente come obiettivo di studio, allora ovviamente dovrai continuare a studiare per tutta la vita."
  },
  AvgCommunicate_81325_Content_12 = {
    Text = "Capisco. Una conoscenza che continua a svilupparsi... davvero magnifica."
  },
  AvgCommunicate_81325_Content_13 = {
    Text = "Quando studiamo le scritture della lanterna, non possiamo cambiare una sola parola; il contenuto deve rimanere costante, ripetuto e immutabile per sempre."
  },
  AvgCommunicate_81325_Content_14 = {
    Text = "Ma ogni volta che studio le scritture, mi sento intrappolata in una scatola... con la fine già davanti a me."
  },
  AvgCommunicate_81325_Content_15 = {
    Text = "In effetti, continuare ad accrescere la propria conoscenza è il vero significato della vita!"
  },
  AvgCommunicate_81325_Content_16 = {
    Text = "È... davvero ispirante..."
  },
  AvgCommunicate_81325_Content_17 = {
    Text = "A proposito, ho un'eccellente opportunità di apprendimento che posso generosamente offrirvi gratuitamente."
  },
  AvgCommunicate_81325_Content_18 = {
    Text = "Davvero, benefattore!? La mia gratitudine è al di là delle parole."
  },
  AvgCommunicate_81325_Content_19 = {
    Text = "Certo che è vero! Guarda! Ecco questo manuale di Esercizi e Principi di Manutenzione della Tecnologia di chip d'argento, insieme a questo Manuale Obbligatorio di Strategie Psicologiche per Investigatori, su quale vorresti lavorare per primo..."
  },
  AvgCommunicate_81325_Content_2 = {
    Text = "No, questa è pura Tecnologia di chip d'argento. E te lo ricordo, il comunicatore è stato costoso, quindi per favore non smontarlo."
  },
  AvgCommunicate_81325_Content_20 = {
    Text = "Ehm, intendo, quale vorresti studiare per primo?"
  },
  AvgCommunicate_81325_Content_3 = {
    Text = "Ah, che peccato... Come facevi a sapere che l'avrei smontato, benefattore? Mi hai letto nel pensiero?"
  },
  AvgCommunicate_81325_Content_4 = {
    Text = "Non proprio... Non mi serve nemmeno la psicologia per indovinare la tua prossima mossa!"
  },
  AvgCommunicate_81325_Content_5 = {
    Text = "La psicologia dev'essere una materia molto profonda. Purtroppo, le mie conoscenze in questo campo sono davvero carenti..."
  },
  AvgCommunicate_81325_Content_6 = {
    Text = "Benefattore, quanto tempo ci vuole per padroneggiare questa Tecnologia di chip d'argento e la psicologia?"
  },
  AvgCommunicate_81325_Content_7 = {
    Text = "Padroneggiare? Hmm..."
  },
  AvgCommunicate_81325_Content_8 = {
    Text = "Ci vogliono quattro o cinque anni per imparare le basi, e per padroneggiarle potrebbe volerci una vita intera."
  },
  AvgCommunicate_81325_Content_9 = {
    Text = "Una vita intera! Ci sono migliaia di volumi da leggere?"
  },
  AvgCommunicate_81325_Option_10 = {
    Text = "Non esattamente..."
  },
  AvgCommunicate_81325_Option_16 = {
    Text = "È... davvero ispirante..."
  },
  AvgCommunicate_81325_Option_19 = {
    Text = "Certo che è vero."
