  AvgCommunicate_81325_Option_4 = {
    Text = "Non proprio..."
  },
  AvgCommunicate_81325_Option_7 = {
    Text = "Padroneggiare? Hmm..."
  },
  AvgCommunicate_84107_Content_1 = {
    Text = "Quando finisce questa vacanza?"
  },
  AvgCommunicate_84107_Content_10 = {
    Text = "Tutti questi fattori combinati devono essere soppesati per pianificare il percorso più efficiente e razionale."
  },
  AvgCommunicate_84107_Content_11 = {
    Text = "...Capisco. Sembra che ogni compito sia importante."
  },
  AvgCommunicate_84107_Content_12 = {
    Text = "Sì. Dal momento che ho fatto questa scelta, devo assumermi le mie responsabilità."
  },
  AvgCommunicate_84107_Content_13 = {
    Text = "D'ora in poi, farò la ronda ogni notte per assicurarmi che non si verifichino incidenti all'accademia durante questa pausa."
  },
  AvgCommunicate_84107_Content_14 = {
    Text = "Custode, fermiamoci qui per ora. Devo tornare al lavoro."
  },
  AvgCommunicate_84107_Content_2 = {
    Text = "...Non sono appena iniziate?"
  },
  AvgCommunicate_84107_Content_4 = {
    Text = "Mi sto solo preparando per ciò che verrà."
  },
  AvgCommunicate_84107_Content_5 = {
    Text = "La mappa dell'accademia è stata aggiornata, l'orologio è stato calibrato, e le bandiere e le aste sono state riordinate."
  },
  AvgCommunicate_84107_Content_6 = {
    Text = "Continuerò a occuparmi di queste cose ogni giorno per assicurarmi che possiamo riprendere il lavoro in qualsiasi momento."
  },
  AvgCommunicate_84107_Content_7 = {
    Text = "...Serve davvero tutta questa preparazione per organizzare la pausa pranzo?"
  },
  AvgCommunicate_84107_Content_8 = {
    Text = "Certo. Quale mensa è la più frequentata, quale accademia ha più studenti e quali studenti vogliono andare in mensa per primi: tutto questo influisce sulla pianificazione dell'intero percorso."
  },
  AvgCommunicate_84107_Content_9 = {
    Text = "Quale aiuola ha scelto come casa il nuovo gatto randagio, in quale zona gli studenti hanno calpestato il terreno creando un nuovo sentiero, quale strada necessita di manutenzione..."
  },
  AvgCommunicate_84107_Option_11 = {
    Text = "...Capisco."
  },
  AvgCommunicate_84107_Option_2 = {
    Text = "...Non sono appena iniziate?"
  },
  AvgCommunicate_84107_Option_7 = {
    Text = "Serve davvero tutta questa preparazione?"
  },
  AvgCommunicate_84108_Content_1 = {
    Text = "Custode, mi scuso profondamente per l'incidente dell'ultima volta."
  },
  AvgCommunicate_84108_Content_10 = {
    Text = "Ma dato che non siamo in mare, ho apportato alcuni adattamenti in base alle circostanze."
  },
  AvgCommunicate_84108_Content_11 = {
    Text = "Questi adattamenti non saranno mica... ammanettarti a me, vero..."
  },
  AvgCommunicate_84108_Content_12 = {
    Text = "Sì. In questo modo, se qualcosa dovesse andare storto con me, potrai accorgertene e intervenire immediatamente."
  },
  AvgCommunicate_84108_Content_13 = {
    Text = "...Posso rifiutare?"
  },
  AvgCommunicate_84108_Content_14 = {
    Text = "Sei ovviamente libero/a di rifiutare."
  },
  AvgCommunicate_84108_Content_15 = {
    Text = "Ma sono già fuori dalla tua porta."
  },
  AvgCommunicate_84108_Content_2 = {
    Text = "…Ti riferisci a quando la tua insonnia ha fatto perdere il controllo al Fuoco di Sant'Elmo?"
  },
  AvgCommunicate_84108_Content_3 = {
    Text = "Anche se Doll: Inferno mi ha messo fuori combattimento in tempo, provo comunque un senso di colpa."
  },
  AvgCommunicate_84108_Content_4 = {
    Text = "Ci ho riflettuto a lungo e sono giunta alla conclusione che merito una punizione."
  },
  AvgCommunicate_84108_Content_5 = {
    Text = "Non ce n'è davvero bisogno. L'ultimo incidente non ha causato conseguenze gravi."
  },
  AvgCommunicate_84108_Content_6 = {
    Text = "No, gli errori devono essere puniti. Queste sono le regole."
  },
  AvgCommunicate_84108_Content_7 = {
    Text = "Ho già agganciato un'estremità delle manette a me stessa. L'altra estremità richiede la tua collaborazione."
  },
  AvgCommunicate_84108_Content_8 = {
    Text = "La mia collaborazione?"
  },
  AvgCommunicate_84108_Content_9 = {
    Text = "Normalmente, chi commette errori su una nave viene incatenato per le gambe e lasciato a cuocere sul ponte per diverse ore."
  },
  AvgCommunicate_84108_Option_11 = {
    Text = "Questi adattamenti non saranno mica..."
  },
  AvgCommunicate_84108_Option_13 = {
    Text = "...Posso rifiutare?"
  },
  AvgCommunicate_84108_Option_2 = {
    Text = "Vuoi dire..."
  },
  AvgCommunicate_84108_Option_5 = {
    Text = "Non ce n'è davvero bisogno."
  },
  AvgCommunicate_84108_Option_8 = {
    Text = "La mia collaborazione?"
  },
  AvgCommunicate_84109_Content_1 = {
    Text = "Custode, grazie."
  },
  AvgCommunicate_84109_Content_10 = {Text = "..."},
  AvgCommunicate_84109_Content_11 = {
    Text = "In realtà..."
  },
  AvgCommunicate_84109_Content_12 = {
    Text = "In realtà? Perché improvvisamente parli con tanta esitazione? Non è da te."
  },
  AvgCommunicate_84109_Content_13 = {
    Text = "In realtà, non è necessario visitare musei marittimi. Anche solo avere un momento di \"relax\" va bene."
  },
  AvgCommunicate_84109_Content_14 = {
    Text = "Non riesco a capire bene cosa intendi per \"relax\" nel senso comune, ma provo una profonda sensazione di calma quando sono con te."
  },
  AvgCommunicate_84109_Content_15 = {
    Text = "È come trovarsi su un mare tranquillo: nessuna tempesta, e nessuna possibilità di incontrarne. Devo solo seguire la rotta per raggiungere la destinazione in sicurezza."
  },
  AvgCommunicate_84109_Content_16 = {
    Text = "...Anche se quella metafora è un po' difficile da seguire, credo di capire più o meno cosa intendi."
  },
  AvgCommunicate_84109_Content_17 = {
    Text = "In futuro potremo esplorare tanti posti diversi. Il mondo è vasto; ci sono molti panorami meravigliosi oltre l'oceano."
  },
  AvgCommunicate_84109_Content_18 = {
    Text = "...Capisco. Ci proverò."
  },
  AvgCommunicate_84109_Content_19 = {
    Text = "Andrò a vedere... i bei paesaggi che sono diversi dall'oceano."
  },
  AvgCommunicate_84109_Content_2 = {
    Text = "Perché questa gratitudine improvvisa?"
  },
  AvgCommunicate_84109_Content_3 = {
    Text = "Ho imparato moltissimo durante questa visita al Museo Marittimo di Londra."
  },
  AvgCommunicate_84109_Content_4 = {
    Text = "Gli orologi nautici esposti, le carte nautiche disegnate a mano e i frammenti dei giornali di bordo mi aiuteranno a migliorare le mie abilità di navigazione."
  },
  AvgCommunicate_84109_Content_5 = {
    Text = "Metterò tutto questo a frutto nella prossima Navigazione, assicurandomi che Tutti facciano Ritorno sani e salvi al porto."
  },
  AvgCommunicate_84109_Content_6 = {
    Text = "Se ricordo bene, lo scopo di andare al Museo Marittimo di Londra quel giorno doveva essere per \"rilassarsi\"..."
  },
  AvgCommunicate_84109_Content_7 = {
    Text = "Lascia perdere. L'importante è che tu sia felice."
  },
  AvgCommunicate_84109_Content_8 = {
    Text = "Sì, sono molto felice, e spero che in futuro potremo uscire spesso insieme per rilassarci."
  },
  AvgCommunicate_84109_Content_9 = {
    Text = "Nessun problema. Controllerò quali altri musei marittimi a Londra possiamo visitare."
  },
  AvgCommunicate_84109_Option_12 = {Text = "Davvero?"},
  AvgCommunicate_84109_Option_16 = {
    Text = "...Che metafora complicata."
  },
  AvgCommunicate_84109_Option_2 = {
    Text = "Perché questa gratitudine improvvisa?"
  },
  AvgCommunicate_84109_Option_6 = {Text = "...?"},
  AvgCommunicate_84109_Option_9 = {
    Text = "Nessun problema."
  },
  AvgCommunicate_84110_Content_1 = {
    Text = "Potresti inviarmi in anticipo il prossimo lotto di scorte di caffeina, {Male=Mr.,Female=Miss} Custode?"
  },
  AvgCommunicate_84110_Content_10 = {
    Text = "Aspetta, come può diventare ancora più assurdo!"
  },
  AvgCommunicate_84110_Content_11 = {
    Text = "Dov'è Winkle adesso?"
  },
  AvgCommunicate_84110_Content_12 = {
    Text = "Proprio qui, a condurre esperimenti sul dispositivo di conduzione, verificando se l'energia di @2<AvgCommunicateConfuseColor.Light> possa essere trasformata in energia luminosa."
  },
  AvgCommunicate_84110_Content_13 = {
    Text = "Perché non rifiuti?"
  },
  AvgCommunicate_84110_Content_14 = {
    Text = "Perché rifiutare? Servire i passeggeri è uno dei miei doveri."
  },
  AvgCommunicate_84110_Content_15 = {Text = "..."},
  AvgCommunicate_84110_Content_16 = {
    Text = "Sto andando. Trattieni Winkle per me."
  },
  AvgCommunicate_84110_Content_17 = {
    Text = "Compreso. Eseguirò il tuo comando, anche a costo della vita."
  },
  AvgCommunicate_84110_Content_2 = {
    Text = "Winkle ha preso di nuovo la tua porzione?"
  },
  AvgCommunicate_84110_Content_3 = {
    Text = "Per essere precisi, non è stata \"presa\", piuttosto l'ho data a quel passeggero."
  },
  AvgCommunicate_84110_Content_4 = {
    Text = "...Ancora con la scusa del \"mi unirò al viaggio la prossima volta\"?"
  },
  AvgCommunicate_84110_Content_5 = {
    Text = "Sto semplicemente adempiendo ai miei doveri. Servire i passeggeri è anch'essa una delle mie responsabilità."
  },
  AvgCommunicate_84110_Content_6 = {
    Text = "...La richiesta di rifornimento è stata approvata. Questa è l'ultima volta."
  },
  AvgCommunicate_84110_Content_7 = {
    Text = "A proposito, Winkle sta ancora cercando di estrarre l'@2 dal tuo petto, ultimamente?"
  },
  AvgCommunicate_84110_Content_8 = {
    Text = "Non più; questo passeggero ha cambiato i suoi metodi di ricerca."
  },
  AvgCommunicate_84110_Content_9 = {
    Text = "Ad esempio, testare l'intensità di @2<AvgCommunicateConfuseColor.Light> con un misuratore di corrente d'impatto, analizzare le linee spettrali di @2<AvgCommunicateConfuseColor.Light> con un prisma, utilizzare una piattaforma di test umana per verificare la connessione di @2<AvgCommunicateConfuseColor.Light> con le fibre nervose..."
  },
  AvgCommunicate_84110_Option_10 = {
    Text = "Aspetta, come può diventare ancora più assurdo!"
  },
  AvgCommunicate_84110_Option_13 = {
    Text = "Perché non rifiuti?"
  },
  AvgCommunicate_84110_Option_15 = {Text = "..."},
  AvgCommunicate_84110_Option_2 = {
    Text = "Winkle ha preso di nuovo la tua porzione?"
  },
  AvgCommunicate_84110_Option_4 = {
    Text = "Ancora una volta, il motivo è..."
  },
  AvgCommunicate_84110_Option_6 = {
    Text = "La richiesta di rifornimenti è stata approvata..."
  },
  AvgCommunicate_94500_Content_1 = {
    Text = "Grazie alla vostra presentazione, dopo aver incontrato Lord Ogier, lui ci ha fatto conoscere ancora più amici."
  },
  AvgCommunicate_94500_Content_10 = {
    Text = "Lord Ogier ha anche detto che l'addestramento di un cavaliere è ancora più complesso e tedioso di questo. Sembra che, come raccontano le storie, ogni cavaliere sia una persona davvero rispettabile."
  },
  AvgCommunicate_94500_Content_11 = {
    Text = "Esatto, Ogier è il più diligente nell'addestramento tra tutti i Risvegliatori!"
  },
  AvgCommunicate_94500_Content_12 = {
    Text = "Abbiamo anche notato che l'Istruttrice Alva, nonostante la sua disabilità, svolge esattamente lo stesso addestramento nostro."
  },
  AvgCommunicate_94500_Content_13 = {
    Text = "Inizialmente pensavamo che anche l'Istruttrice Alva fosse una cavaliera, ma ha detto che era una soldatessa. Non so che tipo di professione sia, ma dev'essere rispettabile quanto quella di un cavaliere."
  },
  AvgCommunicate_94500_Content_14 = {
    Text = "I soldati sono persone che combattono per il proprio paese, quindi si potrebbero considerare un tipo di cavaliere. Tuttavia, rispetto al rigido codice morale dei cavalieri, le azioni di un soldato non sempre rappresentano la giustizia."
  },
  AvgCommunicate_94500_Content_15 = {
    Text = "Alva se ne è resa conto solo dopo aver lasciato l'esercito. Forse la vita che ha adesso è più serena per lei."
  },
  AvgCommunicate_94500_Content_16 = {
    Text = "Capisco. Vuoi dire che un cavaliere non rappresenta il potere, ma uno spirito di giustizia. Persone giuste come l'Istruttrice Alva e persino tu, possedete tutti l'anima di un cavaliere."
  },
  AvgCommunicate_94500_Content_18 = {
    Text = "Anche se è stato detto molto bene, perché mi fa sentire così in imbarazzo...?"
  },
  AvgCommunicate_94500_Content_2 = {
    Text = "Che splendida notizia! Sono davvero felice per voi."
  },
  AvgCommunicate_94500_Content_3 = {
    Text = "Abbiamo già incontrato molti Risvegliatori e, in effetti, come avevate detto, la maggior parte di loro sono persone amichevoli."
  },
  AvgCommunicate_94500_Content_4 = {
    Text = "Mi vergogno un po' ripensando a quanto ero diffidente e sospettoso verso gli altri quando sono arrivato qui."
  },
  AvgCommunicate_94500_Content_5 = {
    Text = "In realtà, va bene così. Dopotutto, ci sono ancora parecchie persone da cui è meglio guardarsi..."
  },
  AvgCommunicate_94500_Content_6 = {
    Text = "Castor e io stiamo frequentando il corso di addestramento dell'Istruttrice Alva, insieme a Lord Ogier."
  },
  AvgCommunicate_94500_Content_7 = {
    Text = "La postura di combattimento di Lord Ogier è davvero straordinaria, ma lui stesso sembra non essere abituato a ricevere complimenti. Che persona umile."
  },
  AvgCommunicate_94500_Content_8 = {
    Text = "Ah ah, Ogier è semplicemente timido. Parlagli normalmente."
  },
  AvgCommunicate_94500_Content_9 = {
    Text = "Capisco. Castor e io non abbiamo mai ricevuto addestramento al combattimento nella chiesa; un esercizio così intenso è davvero faticoso. Eppure Lord Ogier dice che lo fa ogni giorno. Che perseveranza incredibile."
  },
  AvgCommunicate_94500_Option_11 = {
    Text = "Esatto, Ogier è il più diligente nell'addestramento tra tutti i Risvegliatori!"
  },
  AvgCommunicate_94500_Option_14 = {
    Text = "Suppongo di sì..."
  },
  AvgCommunicate_94500_Option_2 = {
    Text = "Che splendida notizia! Sono davvero felice per voi."
  },
  AvgCommunicate_94500_Option_5 = {
    Text = "In realtà, va bene così. Dopotutto, ci sono ancora parecchie persone da cui è meglio guardarsi..."
  },
  AvgCommunicate_94500_Option_8 = {
    Text = "Ogier è solo facilmente timido."
  },
  AvgCommunicate_94501_Content_1 = {
    Text = "Stimato Benefattore, grazie per aver preparato con tanta cura questa dimora per me e Castor."
  },
  AvgCommunicate_94501_Content_10 = {
    Text = "Castor ne era così entusiasta che si lavava il viso cinque volte al giorno, ma dopo il mio intervento, siamo scesi a tre."
  },
  AvgCommunicate_94501_Content_12 = {
    Text = "Lavarsi il viso troppe volte rovina la pelle!"
  },
  AvgCommunicate_94501_Content_13 = {
    Text = "Ma aspetta, non avevate mai usato queste cose prima? Non immaginavo che la Chiesa della luce del tempio fosse così austera."
  },
  AvgCommunicate_94501_Content_14 = {
    Text = "In effetti no, ma non è per l'austerità della Chiesa. In quanto Divi Gemelli, ci veniva sempre richiesto di frenare i nostri desideri e concentrarci sulla pratica spirituale."
  },
  AvgCommunicate_94501_Content_15 = {
    Text = "Non abbiamo avuto praticamente alcun contatto con questo tipo di prodotti tecnologici. Le nostre routine quotidiane e i pasti erano regolati da molte regole rigide."
  },
  AvgCommunicate_94501_Content_16 = {
    Text = "Sebbene i nostri abiti e i pasti fossero generalmente lussuosi, non potevamo mangiare al di fuori degli orari dei pasti, e dovevamo lasciare la stanza non appena era ora di alzarsi."
  },
  AvgCommunicate_94501_Content_17 = {
    Text = "Da bambino, sognavo spesso un giorno in cui non avrei dovuto svegliarmi presto e avrei potuto mangiare quello che volevo per tutto il giorno."
  },
  AvgCommunicate_94501_Content_18 = {
    Text = "In questi ultimi giorni, ho visto più volte una ragazzina che portava del cibo passare per il corridoio nel pomeriggio. Sembra che la vita che sognavo sia già la normalità qui."
  },
  AvgCommunicate_94501_Content_19 = {
    Text = "Ah, quella dev'essere Murphy che va a prendere le sue tortine... La vostra vita passata sembra davvero estenuante."
  },
  AvgCommunicate_94501_Content_2 = {
    Text = "Quando Castor ha detto che un letto era stato aggiunto appositamente alla casa, ho capito subito che era un tuo gesto premuroso."
  },
  AvgCommunicate_94501_Content_20 = {
    Text = "Ormai è tutto alle nostre spalle. Quegli errori e quelle distorsioni resteranno nel passato. Intraprenderemo il cammino giusto con un nuovo inizio, e ti chiediamo di esserne testimone."
  },
  AvgCommunicate_94501_Content_21 = {
    Text = "Sei troppo gentile. Se hai qualche domanda, non esitare a chiedere. Il tuo atteggiamento da solo è infinitamente più rassicurante di quello di certi altri Risvegliatori!"
  },
  AvgCommunicate_94501_Content_3 = {
    Text = "Siamo cresciuti abituati a condividere una stanza nel palazzo della Chiesa, e ci siamo preoccupati molto quando abbiamo saputo che qui la regola era una stanza per persona."
  },
  AvgCommunicate_94501_Content_4 = {
    Text = "Vedendo ora come ti prendi cura delle nostre esigenze con tanta meticolosità, mi rendo davvero conto di quanto avesse ragione Lady Thais a suggerirci di cercare rifugio da te."
  },
  AvgCommunicate_94501_Content_5 = {
    Text = "Ahah, non è niente, davvero. Vi state ambientando bene da quando siete arrivati?"
  },
  AvgCommunicate_94501_Content_6 = {
    Text = "Grazie alle tue attenzioni, tutto bene. Sebbene gli alloggi qui siano piccoli come la stanza di una cameriera, sono completamente arredati, e dopo esserci adattati, risultano piuttosto accoglienti e confortevoli."
  },
  AvgCommunicate_94501_Content_7 = {
    Text = "Ahaha, davvero? Beh, che bello, che bello..."
  },
  AvgCommunicate_94501_Content_8 = {
    Text = "Abbiamo imparato lentamente a vivere senza essere serviti; non preoccuparti per noi. In realtà, è qualcosa che entrambi sognavamo da anni."
  },
  AvgCommunicate_94501_Content_9 = {
    Text = "Il detergente per il viso fornito nella stanza è davvero prodigioso: usandolo come indicato produce tante bollicine soffici come nuvole. E il gusto del dentifricio è così fresco!"
  },
  AvgCommunicate_94501_Option_19 = {
    Text = "Ah, quella dev'essere Murphy che va a prendere le sue tortine..."
  },
  AvgCommunicate_94501_Option_21 = {
    Text = "Sei troppo gentile."
  },
  AvgCommunicate_94501_Option_5 = {
    Text = "Oh, non è stato niente."
  },
  AvgCommunicate_94501_Option_7 = {
    Text = "Ahaha, davvero? Beh, che bello, che bello..."
  },
  AvgCommunicate_94502_Content_1 = {
    Text = "Mi scuso per il disturbo, ma potrei chiedervi un piccolo favore per una presentazione?"
  },
  AvgCommunicate_94502_Content_10 = {
    Text = "Oh! Devono essere Ogier e Lotan."
  },
  AvgCommunicate_94502_Content_11 = {
    Text = "Ogier... Ho preso nota del nome. Il portamento di quel giovane era così onorevole ed eroico che ci ha davvero conquistati. Castor e io volevamo avvicinarci, ma sono passati rapidamente e se ne sono andati."
  },
  AvgCommunicate_94502_Content_12 = {
    Text = "Dopo essere tornati al dormitorio, non riuscivamo a smettere di pensare a quel cavaliere, ma non sapevamo come avviare un contatto. Così siamo venuti a chiederti una presentazione, sperando che tu possa dedicarci il tempo e lo sforzo per facilitare il nostro incontro."
  },
  AvgCommunicate_94502_Content_13 = {
    Text = "Capisco. Sinceramente, non c'è bisogno di essere così formali. Ogier è una persona molto gentile. Se glielo chiedeste semplicemente, sarebbe felicissimo di diventare vostro amico."
  },
  AvgCommunicate_94502_Content_14 = {
    Text = "Davvero ammirevole per un vero cavaliere: una tale apertura mentale è encomiabile, essere disposto ad accettare persone come noi che un tempo erano nemici."
  },
  AvgCommunicate_94502_Content_15 = {
    Text = "No, no, non ha niente a che fare con la magnanimità! È semplicemente il modo in cui le persone normali fanno amicizia!"
  },
  AvgCommunicate_94502_Content_16 = {
    Text = "Anche se non tutti i Risvegliatori sono persone normali... la maggior parte delle persone qui è piuttosto amichevole. Dovreste semplicemente interagire con loro in modo libero e naturale."
  },
  AvgCommunicate_94502_Content_17 = {
    Text = "Mi scuso. Potresti illuminarmi: cos'è esattamente... una comunicazione normale?"
  },
  AvgCommunicate_94502_Content_19 = {
    Text = "Capisco. Lascia che ti sveli il segreto per fare amicizia!"
  },
  AvgCommunicate_94502_Content_2 = {
    Text = "Da quando ci hai suggerito di provare a fare più amicizie, Castor e io ci siamo spesso soffermati nelle zone più frequentate."
  },
  AvgCommunicate_94502_Content_20 = {
    Text = "È l'iniziativa! La sincerità e l'iniziativa sono ciò che crea un vero legame con le persone!"
  },
  AvgCommunicate_94502_Content_21 = {
    Text = "Ricorda, potresti essere rifiutato o ingannato, ma la colpa è di chi ti ha fatto del male. Non dubitare mai che la sincerità sia l'approccio giusto."
  },
  AvgCommunicate_94502_Content_22 = {
    Text = "Sviluppa un cuore resiliente, e poi vai coraggiosamente là fuori a vivere l'amicizia!"
  },
  AvgCommunicate_94502_Content_23 = {
    Text = "La vostra saggezza ispira sempre in me la più profonda reverenza e ammirazione. Farò davvero tesoro dei vostri insegnamenti. Vi ringrazio sinceramente, mia luce guida."
  },
  AvgCommunicate_94502_Content_3 = {
    Text = "Soffermati?"
  },
  AvgCommunicate_94502_Content_4 = {
    Text = "Sì. Spesso ci sediamo in silenzio al ristorante o in piazza, osservando la gente che passa, cercando di non disturbare nessuno."
  },
  AvgCommunicate_94502_Content_6 = {
    Text = "Ehm, le vostre intenzioni sono buone, ma non farete amicizia semplicemente standovene seduti lì!"
  },
  AvgCommunicate_94502_Content_7 = {
    Text = "Davvero? Eravamo così vincolati dalle nostre vecchie regole. Ma non mi aspettavo che ci fosse un vero cavaliere qui!"
  },
  AvgCommunicate_94502_Content_8 = {
    Text = "Forse Castor te ne ha parlato: entrambi ammiriamo profondamente le storie dei cavalieri."
  },
  AvgCommunicate_94502_Content_9 = {
    Text = "Quel giorno nella piazza, abbiamo visto un giovane uomo che impugnava una lunga lancia, intento a discutere la tecnica della lancia del Cavaliere con una dama."
  },
  AvgCommunicate_94502_Option_10 = {
    Text = "Oh! Devono essere Ogier e Lotan."
  },
  AvgCommunicate_94502_Option_13 = {
    Text = "Sinceramente, non c'è bisogno di essere così formali."
  },
  AvgCommunicate_94502_Option_15 = {
    Text = "Non ha niente a che fare con l'apertura mentale!"
  },
  AvgCommunicate_94502_Option_3 = {
    Text = "Soffermati?"
  },
  AvgCommunicate_95003_Content_1 = {
    Text = "Ehi, piccola, hai un minuto?"
  },
  AvgCommunicate_95003_Content_10 = {
    Text = "\"...Quando le stelle si allineeranno, il Feto Divino nascerà dal Suo grembo.\""
  },
  AvgCommunicate_95003_Content_11 = {
    Text = "\"...Sebbene non celebriamo più alcun rituale o sacrificio, spero che queste informazioni possano fornirvi qualche spunto.\""
  },
  AvgCommunicate_95003_Content_12 = {
    Text = "\"...Se avete tempo, mi piacerebbe discutere con voi del nostro Giovane Re e Salvatore...\""
  },
  AvgCommunicate_95003_Content_13 = {
    Text = "...Ora so chi è."
  },
  AvgCommunicate_95003_Content_14 = {
    Text = "...Avrei dovuto immaginarlo."
  },
  AvgCommunicate_95003_Content_15 = {
    Text = "Quindi conosci questa persona, piccola?"
  },
  AvgCommunicate_95003_Content_16 = {
    Text = "Esatto... lascia fare a me."
  },
  AvgCommunicate_95003_Content_17 = {
    Text = "La prossima volta che vedi una lettera del genere, mi raccomando, non rispondere e avvisami immediatamente!"
  },
  AvgCommunicate_95003_Content_2 = {
    Text = "C'è qualche problema?"
  },
  AvgCommunicate_95003_Content_3 = {
    Text = "Non mi aspettavo che dopo il nostro piccolo scambio sarebbero arrivate davvero delle lettere."
  },
  AvgCommunicate_95003_Content_4 = {
    Text = "Filtrando quelle palesemente false, ce n'erano sorprendentemente alcune autentiche."
  },
  AvgCommunicate_95003_Content_5 = {
    Text = "Non posso credere che qualcuno ci sia cascato davvero!"
  },
  AvgCommunicate_95003_Content_6 = {
    Text = "Tuttavia, una lettera è piuttosto strana; la posizione del mittente è all'interno di Mythag stesso."
  },
  AvgCommunicate_95003_Content_7 = {
    Text = "Cosa! Dobbiamo avvisare immediatamente l'Ufficio Sicurezza!"
  },
  AvgCommunicate_95003_Content_8 = {
    Text = "Niente panico. Per sicurezza, lascia che ti dica prima i punti chiave."
  },
  AvgCommunicate_95003_Content_9 = {
    Text = "\"...In passato, selezionavamo neonati idonei a portare le responsabilità della Madre Divina.\""
  },
  AvgCommunicate_95003_Option_13 = {
    Text = "...Ora so chi è."
  },
  AvgCommunicate_95003_Option_14 = {
    Text = "...Avrei dovuto immaginarlo."
  },
  AvgCommunicate_95004_Content_1 = {
    Text = "È da tanto che non ci vediamo, mia piccola Custode."
  },
  AvgCommunicate_95004_Content_10 = {
    Text = "Certo, una cosa del genere è molto strana!!!"
  },
  AvgCommunicate_95004_Content_11 = {
    Text = "Haha, proprio come sospettavo."
  },
  AvgCommunicate_95004_Content_12 = {
    Text = "C-cosa sospettavi?"
  },
  AvgCommunicate_95004_Content_13 = {
    Text = "Ho scommesso con Ismael che la piccola sarebbe rimasta sicuramente scioccata vedendo quel messaggio."
  },
  AvgCommunicate_95004_Content_14 = {
    Text = "A quanto pare ho vinto."
  },
  AvgCommunicate_95004_Content_15 = {
    Text = "...Puoi dirmi chi ha scritto quel messaggio?"
  },
  AvgCommunicate_95004_Content_16 = {
    Text = "Anche se sarei capace di scrivere qualcosa di simile."
  },
  AvgCommunicate_95004_Content_17 = {
    Text = "Quel passaggio è stato effettivamente scritto da Ismael, su mia richiesta."
  },
  AvgCommunicate_95004_Content_18 = {
    Text = "...Meraviglioso. A quanto pare siete entrambi i colpevoli."
  },
  AvgCommunicate_95004_Content_19 = {Text = "Uh, ah..."},
  AvgCommunicate_95004_Content_2 = {
    Text = "È passato un po' dall'ultima volta che ci siamo incontrati. Confido che la tua salute sia buona."
  },
  AvgCommunicate_95004_Content_20 = {Text = "Piccola?"},
  AvgCommunicate_95004_Content_21 = {
    Text = "Piccola? Sei ancora lì?"
  },
  AvgCommunicate_95004_Content_22 = {
    Text = "Non ci sono. Puoi lasciarmi un messaggio vocale."
  },
  AvgCommunicate_95004_Content_23 = {
    Text = "Scusa, scusa, piccola. Non arrabbiarti."
  },
  AvgCommunicate_95004_Content_24 = {
    Text = "Come compenso, tutto il bottino di questa caccia ti verrà dato in regalo."
  },
  AvgCommunicate_95004_Content_25 = {
    Text = "Sbrigati e vieni! È passato troppo tempo; ci manchi terribilmente."
  },
  AvgCommunicate_95004_Content_26 = {
    Text = "...Hmph, va bene. Per via del regalo, ti perdono questa volta!"
  },
  AvgCommunicate_95004_Content_27 = {
    Text = "Arrivo subito. Ma non ci sarà una prossima volta!"
  },
  AvgCommunicate_95004_Content_28 = {
    Text = "(Allora suppongo che userò un metodo diverso per stuzzicare la piccola.)"
  },
  AvgCommunicate_95004_Content_29 = {
